# ─────────────────────────────────────────────
# 路径模板（变量）解析
# 目标：把所有“输出路径/存放位置”入口统一到同一套解析逻辑
# - 支持环境变量：${HOME} / %USERPROFILE% 等（os.path.expandvars）
# - 支持 ~：用户目录（os.path.expanduser）
# - 支持内置变量：
#   {date}/{yyyy-MM-dd}、{yyyyMMdd}、{yyyyMM}、{time}/{hhmmss}、{cwd}、{home}
# - 支持上下文变量：通过 variables 传入，例如 {project}、{src_dir} 等
# 注意：该函数只在“真正执行写入/导出”时做解析；配置里仍保存用户输入的模板原文。
# ─────────────────────────────────────────────
def render_path_template(path_template, variables=None, project_name=""):
    raw = str(path_template or "").strip().strip('"').strip("'")
    if not raw:
        return ""

    # 1) 先展开环境变量与 ~
    try:
        raw = os.path.expandvars(os.path.expanduser(raw))
    except Exception:
        pass

    # 2) 内置变量
    try:
        now = datetime.now()
    except Exception:
        now = None

    mapping = {}
    if now is not None:
        mapping.update({
            "{date}": now.strftime("%Y-%m-%d"),
            "{yyyy-MM-dd}": now.strftime("%Y-%m-%d"),
            "{yyyyMMdd}": now.strftime("%Y%m%d"),
            "{yyyyMM}": now.strftime("%Y%m"),
            "{time}": now.strftime("%H-%M-%S"),
            "{hhmmss}": now.strftime("%H%M%S"),
        })

    # 常用系统变量
    try:
        mapping["{cwd}"] = os.getcwd()
    except Exception:
        mapping["{cwd}"] = ""
    try:
        mapping["{home}"] = os.path.expanduser("~")
    except Exception:
        mapping["{home}"] = ""

    # project_name 快捷注入（仅在相关模块传入时生效）
    if project_name:
        try:
            safe_project = clean_long_filename(str(project_name or ""), 120)
        except Exception:
            safe_project = str(project_name or "")
        mapping["{project}"] = safe_project

    # 3) 自定义上下文变量（允许传入 "project" 或 "{project}" 两种写法）
    if isinstance(variables, dict):
        for k, v in variables.items():
            key = str(k or "")
            if not key:
                continue
            token = key if key.startswith("{") and key.endswith("}") else ("{" + key + "}")
            mapping[token] = "" if v is None else str(v)

    # 4) 替换（仅做简单替换，保持兼容现有 {yyyy-MM-dd} 这种带符号 token）
    for token, value in mapping.items():
        if token and token in raw:
            raw = raw.replace(token, value)

    # 5) 规范化路径
    try:
        return os.path.normpath(raw)
    except Exception:
        return raw

def normalize_api_base(api_base, default=""):
    return (api_base or default or "").strip().rstrip("/")

def is_google_native_api(api_base):
    base = normalize_api_base(api_base).lower()
    return "generativelanguage.googleapis.com" in base or "googleapis.com" in base

def pick_google_model(model_name, default_model="gemini-1.5-flash"):
    name = (model_name or "").strip()
    return name if "gemini" in name.lower() else default_model

def get_effective_api_interval(api_base, ai_config=None, fallback=0):
    interval = max(0, int(fallback or 0))
    if isinstance(ai_config, dict):
        try:
            interval = max(interval, int(ai_config.get("api_interval", fallback) or 0))
        except Exception:
            pass
    return max(0, interval)

def get_api_pool_strategy(ai_config=None, default="ordered"):
    strategy = default
    if isinstance(ai_config, dict):
        if ai_config.get("api_random_enabled"):
            return "random"
        strategy = ai_config.get("api_pool_strategy", default)
    strategy = str(strategy or default).strip().lower()
    if strategy in {"random", "shuffle", "rand", "随机"}:
        return "random"
    return "ordered"

def order_api_keys(api_keys, ai_config=None, strategy=None):
    keys = [str(k).strip() for k in (api_keys or []) if str(k).strip()]
    if len(keys) <= 1:
        return keys
    resolved = get_api_pool_strategy({"api_pool_strategy": strategy} if strategy is not None else ai_config)
    ordered = list(keys)
    if resolved == "random":
        random.shuffle(ordered)
    return ordered

def fix_mojibake_text(text):
    raw = str(text or "")
    if not raw:
        return raw
    suspicious = ("Ã", "Â", "â", "æ", "å", "ä", "ç", "é")
    if any(token in raw for token in suspicious):
        try:
            repaired = raw.encode("latin-1").decode("utf-8")
            if repaired:
                return repaired
        except Exception:
            pass
    return raw

def sanitize_api_keys(api_keys):
    seen = set()
    cleaned = []
    for key in api_keys or []:
        k = str(key or "").strip()
        if not k or k in seen:
            continue
        seen.add(k)
        cleaned.append(k)
    return cleaned

def normalize_api_base_for_profile(api_base, default="https://api.openai.com/v1"):
    base = normalize_api_base(api_base, default)
    if "/chat/completions" in base:
        base = base.replace("/chat/completions", "")
    lower = base.lower()
    if "googleapis.com" in lower:
        return "https://generativelanguage.googleapis.com"
    if any(x in lower for x in ["openrouter.ai", "openai.com", "groq.com"]) and not base.endswith("/v1"):
        if "openrouter.ai" in lower and not base.endswith("/api/v1"):
            return base.rstrip("/") + "/api/v1"
        return base.rstrip("/") + "/v1"
    return base

def normalize_api_pool_entry(entry, idx=0):
    if not isinstance(entry, dict):
        entry = {}
    keys = sanitize_api_keys(entry.get("api_keys", []))
    if not keys:
        raw_text = str(entry.get("api_keys_text", "") or "")
        keys = sanitize_api_keys(raw_text.splitlines())
    profile = {
        "name": str(entry.get("name") or f"API-{idx + 1}").strip() or f"API-{idx + 1}",
        "api_base": normalize_api_base_for_profile(entry.get("api_base") or entry.get("base") or ""),
        "api_model": str(entry.get("api_model") or entry.get("model") or "gpt-4o-mini").strip() or "gpt-4o-mini",
        "api_keys": keys,
        "enabled": bool(entry.get("enabled", True)),
    }
    return profile

def build_legacy_api_profile(ai_config=None):
    ai_config = ai_config or {}
    api_keys = ai_config.get("api_keys", [])
    if not api_keys and ai_config.get("api_key"):
        api_keys = [ai_config.get("api_key", "")]
    api_keys = sanitize_api_keys(api_keys)
    return {
        "name": "传统单接口",
        "api_base": normalize_api_base_for_profile(ai_config.get("api_base", "")),
        "api_model": str(ai_config.get("api_model", "gpt-4o-mini") or "gpt-4o-mini").strip(),
        "api_keys": order_api_keys(api_keys, ai_config),
        "enabled": True,
        "source": "legacy",
    }

def normalize_api_pool(ai_config=None):
    ai_config = ai_config or {}
    raw_pool = ai_config.get("api_pool", [])
    pool = []
    seen_names = set()
    for idx, item in enumerate(raw_pool or []):
        profile = normalize_api_pool_entry(item, idx)
        base_name = profile["name"]
        name = base_name
        seq = 2
        while name in seen_names:
            name = f"{base_name}_{seq}"
            seq += 1
        profile["name"] = name
        profile["source"] = "pool"
        pool.append(profile)
        seen_names.add(name)
    if pool:
        return pool

    legacy = build_legacy_api_profile(ai_config)
    legacy_keys = sanitize_api_keys(legacy.get("api_keys", []))
    if not legacy_keys:
        fallback_key = str(ai_config.get("api_key", "") or os.environ.get("OPENAI_API_KEY", "") or "").strip()
        if fallback_key:
            legacy_keys = [fallback_key]
    if not legacy_keys:
        return []
    return [{
        "name": str(legacy.get("name") or "默认节点").strip() or "默认节点",
        "api_base": normalize_api_base_for_profile(legacy.get("api_base") or ai_config.get("api_base") or ""),
        "api_model": str(legacy.get("api_model") or ai_config.get("api_model") or "gpt-4o-mini").strip() or "gpt-4o-mini",
        "api_keys": order_api_keys(legacy_keys, ai_config),
        "enabled": True,
        "source": "pool_migrated",
    }]

def get_api_source_mode(ai_config=None, default="pool"):
    ai_config = ai_config or {}
    mode = str(ai_config.get("api_source_mode", default) or default).strip().lower()
    if mode == "legacy":
        return "pool"
    if mode in {"single", "pool"}:
        return mode
    return default

def get_api_provider_strategy(ai_config=None, default="ordered"):
    ai_config = ai_config or {}
    if ai_config.get("api_random_enabled"):
        return "random"
    strategy = str(ai_config.get("api_provider_strategy", default) or default).strip().lower()
    if strategy in {"random", "shuffle", "rand", "随机"}:
        return "random"
    return "ordered"

def resolve_api_profiles(ai_config=None):
    ai_config = ai_config or {}
    pool = normalize_api_pool(ai_config)
    mode = get_api_source_mode(ai_config, "pool")
    active_name = str(ai_config.get("active_api_name", "") or "").strip()
    if not pool:
        return []

    enabled_pool = [dict(p) for p in pool if p.get("enabled", True)]
    candidate_pool = enabled_pool or [dict(p) for p in pool]
    if not candidate_pool:
        return []

    if mode == "single":
        selected = next((dict(p) for p in candidate_pool if p.get("name") == active_name), None)
        if not selected:
            selected = dict(candidate_pool[0])
        selected["api_keys"] = order_api_keys(selected.get("api_keys", []), ai_config)
        return [selected]

    strategy = get_api_provider_strategy(ai_config, "ordered")
    ordered_pool = [dict(p) for p in candidate_pool]
    if strategy == "random":
        random.shuffle(ordered_pool)
    elif active_name:
        for idx, item in enumerate(ordered_pool):
            if item.get("name") == active_name:
                ordered_pool = ordered_pool[idx:] + ordered_pool[:idx]
                break
    for item in ordered_pool:
        item["api_keys"] = order_api_keys(item.get("api_keys", []), ai_config)
    return ordered_pool

def get_runtime_api_profiles(ai_config=None, fallback_env=True):
    ai_config = ai_config or {}
    profiles = []
    for idx, profile in enumerate(resolve_api_profiles(ai_config)):
        item = dict(profile)
        keys = sanitize_api_keys(item.get("api_keys", []))
        if not keys and idx == 0 and fallback_env:
            fallback_key = str(ai_config.get("api_key", "") or os.environ.get("OPENAI_API_KEY", "") or "").strip()
            if fallback_key:
                keys = [fallback_key]
        if not keys:
            continue
        item["api_keys"] = order_api_keys(keys, ai_config)
        profiles.append(item)
    return profiles


def get_primary_api_profile(ai_config=None):
    profiles = get_runtime_api_profiles(ai_config)
    if profiles:
        return profiles[0]
    pool = normalize_api_pool(ai_config)
    if pool:
        return dict(pool[0])
    return build_legacy_api_profile(ai_config)

