def get_review_json_schema_text():
    return (
        "{\"violation\": true/false, "
        "\"category\": \"pass|copy_mismatch|visual_violation|manual_review\", "
        "\"hit_rules\": [\"触发的视觉规则关键词，可为空数组\"], "
        "\"reason\": \"一句话说明结论\", "
        "\"analysis\": \"用 2-4 句说明判定依据，重点写主题、意境、情绪、氛围、主体动作、镜头感是否匹配\", "
        "\"suggestion\": \"若有优化建议请给出，可为空\", "
        "\"confidence\": 0~1}"
    )

def get_default_review_prompt_template():
    return (
        "你是一名专业、谨慎的图片审核员，负责判断图片是否适合当前中文文案与视觉规则。\n\n"
        "请不要只做机械的“元素对元素”比对，而要综合判断图片与中文文案在以下维度是否贴切：\n"
        "1. 主题与主体是否一致\n"
        "2. 场景、动作、叙事方向是否一致\n"
        "3. 情绪、氛围、意境、审美气质是否一致\n"
        "4. 镜头语言、构图感觉、风格调性是否和文案想表达的感觉相符\n"
        "5. 画面本身是否存在明显视觉问题，或违反了给定视觉规则\n\n"
        "请优先以中文文案为主进行判断；若同时给了英文文案，英文只作为辅助参考。\n"
        "如果图片虽然出现了相似元素，但整体气质、意境、情绪、故事感与中文文案不符，也应判定为 `copy_mismatch`。\n"
        "如果主要问题是画面质量、违规元素、构图缺陷、文字水印、模糊、遮挡、低质感或不符合视觉规则，应判定为 `visual_violation`。\n"
        "如果你无法稳定判断，或图文之间存在边界情况、歧义、信息不足，请判定为 `manual_review`，不要勉强给通过。\n\n"
        "{{审核重点}}\n\n"
        "{{视觉规则}}\n\n"
        "{{文案信息}}\n\n"
        "请只返回 JSON，不要返回额外解释。JSON 格式如下：\n"
        "{{JSON格式}}"
    )

def build_review_focus_text():
    return (
        "审核重点：\n"
        "- 重点判断“中文文案是否贴切”，不要只按图片里出现了哪些物体来机械匹配。\n"
        "- 要特别关注文案的意境、氛围、情绪、气质、审美风格、故事感、镜头感。\n"
        "- 若图片与文案只是表面元素相关，但深层表达不一致，也属于不贴切。"
    )

def build_effective_review_system_prompt(ai_config=None, rules_str="", combined_copy=""):
    ai_config = ai_config or {}
    template = str(ai_config.get("review_prompt_template", "") or "").strip() or get_default_review_prompt_template()
    visual_text = f"视觉规则：\n{rules_str.strip()}" if str(rules_str or "").strip() else "视觉规则：\n未设置视觉规则。"
    copy_text = f"文案信息：\n{combined_copy.strip()}" if str(combined_copy or "").strip() else "文案信息：\n未提供中文/英文文案。"
    rendered = template
    replacements = {
        "{{审核重点}}": build_review_focus_text(),
        "{{视觉规则}}": visual_text,
        "{{文案信息}}": copy_text,
        "{{JSON格式}}": get_review_json_schema_text(),
    }
    for token, value in replacements.items():
        rendered = rendered.replace(token, value)
    # 关键加固：强制模型“逐条执行”视觉规则，而不是只参考。
    # 说明：不改变既有字段解析逻辑；即使模型额外返回 hit_rules，也不会影响解析。
    extra = (
        "\n\n【规则执行要求】\n"
        "1) 你必须逐条检查上面的每一条“视觉规则”，不要遗漏。\n"
        "2) 若命中任意视觉规则：必须设置 violation=true 且 category=\"visual_violation\"。\n"
        "3) 若未命中任何视觉规则：hit_rules 设为空数组 []。\n"
        "4) 发现命中的规则时：请在 hit_rules 中列出命中的规则关键词（例如：\"黑色十字架\"）。\n"
    )
    return (rendered.strip() + extra).strip()

def normalize_review_category(value):
    raw = str(value or "").strip().lower()
    if raw in {"pass", "ok", "passed", "通过", "已通过"}:
        return "pass"
    if raw in {"copy_mismatch", "copy", "text_mismatch", "semantic_mismatch", "文案不贴切", "图文不符", "图文不贴切"}:
        return "copy_mismatch"
    if raw in {"visual_violation", "visual", "image_issue", "视觉违规", "画面违规", "画面问题"}:
        return "visual_violation"
    if raw in {"manual_review", "manual", "review", "uncertain", "需人工复核", "人工复核", "不确定"}:
        return "manual_review"
    return ""

def infer_review_category(data):
    data = data or {}
    explicit = normalize_review_category(data.get("category") or data.get("status") or data.get("result"))
    if explicit:
        return explicit
    reason = str(data.get("reason", "") or "")
    analysis = str(data.get("analysis", "") or "")
    suggestion = str(data.get("suggestion", "") or "")
    text = f"{reason}\n{analysis}\n{suggestion}".lower()
    conf = data.get("confidence", "")
    try:
        if conf != "" and conf is not None and float(conf) < 0.55:
            return "manual_review"
    except Exception:
        pass
    manual_keys = ["人工复核", "需复核", "不确定", "难以判断", "无法判断", "边界", "歧义", "信息不足", "uncertain", "manual"]
    copy_keys = ["文案不贴切", "图文不符", "图文不贴切", "不匹配", "不一致", "意境不符", "氛围不符", "情绪不符", "语义不符", "主题不符", "气质不符"]
    visual_keys = ["视觉违规", "画面问题", "模糊", "糊", "水印", "logo", "文字", "遮挡", "低质", "噪点", "曝光", "过曝", "欠曝", "拉伸", "变形", "裁切", "黑边", "规则不符"]
    if any(k.lower() in text for k in manual_keys):
        return "manual_review"
    visual_hit = any(k.lower() in text for k in visual_keys)
    copy_hit = any(k.lower() in text for k in copy_keys)
    if visual_hit and copy_hit:
        return "manual_review"
    if copy_hit:
        return "copy_mismatch"
    if visual_hit:
        return "visual_violation"
    if data.get("violation"):
        return "manual_review"
    return "pass"

def parse_json_loose(text):
    """
    宽松 JSON 解析器：尽最大可能从模型输出中提取一个 dict。
    支持：
    - ```json 代码块
    - JSON 前后夹杂自然语言
    - JSON 数组（取第一个 dict）
    - 类 Python dict（单引号/True/False/None）兜底
    """
    import json as _json
    import re as _re
    import ast as _ast

    t = str(text or "").strip()
    if not t:
        return None

    # 去掉 ``` / ```json 包裹
    if t.startswith("```"):
        lines = t.splitlines()
        if lines and lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].startswith("```"):
            lines = lines[:-1]
        t = "\n".join(lines).strip()

    # 1) 直接 JSON
    try:
        obj = _json.loads(t)
        if isinstance(obj, list) and obj and isinstance(obj[0], dict):
            return obj[0]
        return obj if isinstance(obj, dict) else None
    except Exception:
        pass

    # 2) JSONDecoder.raw_decode：允许前后夹杂文本（例如“结果如下：{...}”）
    try:
        decoder = _json.JSONDecoder()
        for m in _re.finditer(r"[\{\[]", t):
            start = m.start()
            try:
                obj, _end = decoder.raw_decode(t[start:])
                if isinstance(obj, list) and obj and isinstance(obj[0], dict):
                    return obj[0]
                if isinstance(obj, dict):
                    return obj
            except Exception:
                continue
    except Exception:
        pass

    # 3) 兜底：抽取一个 {...}，尝试按 Python dict 解析（兼容单引号 / True / None）
    m = _re.search(r"\{[\s\S]*\}", t)
    if not m:
        return None
    s = m.group(0).strip()
    # 清理常见尾逗号
    s = _re.sub(r",\s*}", "}", s)
    s = _re.sub(r",\s*]", "]", s)
    try:
        obj = _ast.literal_eval(s)
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None

def review_state_label_from_category(category):
    category = normalize_review_category(category) or infer_review_category({"category": category})
    if category == "copy_mismatch":
        return REVIEW_STATE_COPY_MISMATCH
    if category == "visual_violation":
        return REVIEW_STATE_VISUAL_ISSUE
    if category == "manual_review":
        return REVIEW_STATE_MANUAL
    return REVIEW_STATE_PASS

def normalize_review_state_label(state):
    state = str(state or "").strip()
    if state in {REVIEW_STATE_PENDING, REVIEW_STATE_PASS, REVIEW_STATE_COPY_MISMATCH, REVIEW_STATE_VISUAL_ISSUE, REVIEW_STATE_MANUAL}:
        return state
    if state == "🟡 待审核":
        return REVIEW_STATE_PENDING
    if state == "⚠️ 有问题":
        return REVIEW_STATE_MANUAL
    return REVIEW_STATE_PENDING

def build_review_note(category, reason="", ai_note=""):
    category = normalize_review_category(category) or "pass"
    reason = str(reason or "").strip()
    ai_note = str(ai_note or "").strip()
    brief = reason or ai_note or "未说明原因"
    if category == "copy_mismatch":
        return f"文案不贴切：{brief}"
    if category == "visual_violation":
        return f"视觉违规：{brief}"
    if category == "manual_review":
        return f"需人工复核：{brief}"
    return f"AI审核通过：{ai_note[:80]}" if ai_note else "AI审核通过"

def _api_throttle_token(api_base, api_key):
    # Google 原生接口的配额/限流往往是“项目/账号级”而不是“Key 级”，
    # 多 Key 并发反而更容易整体触发 429/503。
    # 因此对 Google 原生接口：忽略 api_key，让所有请求共用同一个节流桶。
    if is_google_native_api(api_base):
        raw = f"{normalize_api_base(api_base)}"
    else:
        raw = f"{normalize_api_base(api_base)}|{api_key or ''}"
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()

def wait_for_api_slot(api_base, api_key, min_interval=0, stop_check=None, log_fn=None, prefix=""):
    token = _api_throttle_token(api_base, api_key)
    while True:
        with _API_THROTTLE_LOCK:
            now = time.time()
            next_allowed = _API_NEXT_ALLOWED_TS.get(token, 0.0)
            wait_seconds = max(0.0, next_allowed - now)
            if wait_seconds <= 0:
                return
        if log_fn and wait_seconds >= 0.5:
            log_fn(f"{prefix}检测到限流冷却，等待 {wait_seconds:.1f}s 后重试...", "gray")
        steps = max(1, int(wait_seconds * 10))
        for _ in range(steps):
            if stop_check and stop_check():
                return
            time.sleep(0.1)

def apply_api_cooldown(api_base, api_key, cooldown_seconds):
    cooldown_seconds = max(0.0, float(cooldown_seconds or 0))
    if cooldown_seconds <= 0:
        return
    token = _api_throttle_token(api_base, api_key)
    with _API_THROTTLE_LOCK:
        _API_NEXT_ALLOWED_TS[token] = max(_API_NEXT_ALLOWED_TS.get(token, 0.0), time.time() + cooldown_seconds)

def parse_retry_after_seconds(response, default_seconds):
    try:
        retry_after = response.headers.get("Retry-After", "")
        if retry_after:
            return max(float(retry_after), float(default_seconds or 0))
    except Exception:
        pass
    return float(default_seconds or 0)

def extract_api_error_message(response):
    try:
        data = response.json()
        if isinstance(data, dict):
            err = data.get("error")
            if isinstance(err, dict):
                msg = err.get("message") or err.get("status") or ""
                details = err.get("details")
                if isinstance(details, list) and details:
                    detail_text = []
                    for item in details[:2]:
                        if isinstance(item, dict):
                            part = item.get("reason") or item.get("detail") or item.get("@type") or ""
                            if part:
                                detail_text.append(str(part))
                    if detail_text:
                        msg = f"{msg} ({'; '.join(detail_text)})".strip()
                if msg:
                    return str(msg)
        text = response.text.strip()
        if text:
            return text[:200]
    except Exception:
        try:
            text = response.text.strip()
            if text:
                return text[:200]
        except Exception:
            pass
    return f"HTTP {getattr(response, 'status_code', 'ERROR')}"


_in_debug = False
def write_debug(msg, color="black"):
    global _in_debug
    if _in_debug: return
    _in_debug = True
    try:
        ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with open(DEBUG_LOG, "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {msg}\n")
        print(f"[DEBUG] {msg}")
        # 核心：通过信号将日志发射到 UI 界面
        GLOBAL_LOG.log_signal.emit(str(msg), color)
    except: pass
    finally: _in_debug = False

