_VLC_RUNTIME_INFO = {"root": "", "libvlc_dll": "", "plugins_dir": ""}
_VLC_DLL_DIR_HANDLES = []

def _get_python_bitness():
    try:
        import struct
        return struct.calcsize("P") * 8
    except Exception:
        return 64 if "64" in platform.architecture()[0] else 32

def _get_windows_pe_bitness(pe_path):
    try:
        with open(pe_path, "rb") as f:
            if f.read(2) != b"MZ":
                return 0
            f.seek(0x3C)
            pe_offset = int.from_bytes(f.read(4), "little", signed=False)
            f.seek(pe_offset)
            if f.read(4) != b"PE\x00\x00":
                return 0
            machine = int.from_bytes(f.read(2), "little", signed=False)
        if machine == 0x8664:
            return 64
        if machine == 0x014C:
            return 32
        if machine == 0xAA64:
            return 64
    except Exception:
        pass
    return 0

def _iter_vlc_runtime_candidates():
    seen = set()

    def _push(path):
        p = os.path.abspath(str(path or "").strip().strip('"'))
        if not p or p in seen:
            return
        seen.add(p)
        yield p

    env_candidates = [
        os.environ.get("VLC_ROOT", ""),
        os.environ.get("VLC_HOME", ""),
        os.environ.get("VLC_INSTALL_DIR", ""),
        os.environ.get("VLC_DIR", ""),
    ]
    for item in env_candidates:
        for out in _push(item):
            yield out

    plugin_env = os.environ.get("VLC_PLUGIN_PATH", "")
    if plugin_env:
        for out in _push(os.path.dirname(plugin_env)):
            yield out

    if sys.platform == "win32":
        for item in [
            os.environ.get("ProgramFiles", ""),
            os.environ.get("ProgramFiles(x86)", ""),
            os.environ.get("LOCALAPPDATA", ""),
        ]:
            if not item:
                continue
            for out in _push(os.path.join(item, "VideoLAN", "VLC")):
                yield out
            for out in _push(os.path.join(item, "Programs", "VideoLAN", "VLC")):
                yield out
        try:
            import winreg
            reg_keys = [
                (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\VideoLAN\VLC"),
                (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\VideoLAN\VLC"),
                (winreg.HKEY_CURRENT_USER, r"SOFTWARE\VideoLAN\VLC"),
            ]
            for hive, subkey in reg_keys:
                try:
                    with winreg.OpenKey(hive, subkey) as key:
                        for value_name in ["InstallDir", "InstallPath", ""]:
                            try:
                                val, _ = winreg.QueryValueEx(key, value_name)
                                for out in _push(val):
                                    yield out
                            except Exception:
                                continue
                except Exception:
                    continue
        except Exception:
            pass

    local_candidates = [
        os.path.join(base_dir, "VLC"),
        os.path.join(base_dir, "vlc"),
        base_dir,
        os.path.dirname(sys.executable) if getattr(sys, "frozen", False) else "",
    ]
    for item in local_candidates:
        for out in _push(item):
            yield out

def _probe_vlc_runtime():
    global _VLC_RUNTIME_INFO
    fallback = None
    preferred = None
    py_bits = _get_python_bitness() if sys.platform == "win32" else 0
    for root in _iter_vlc_runtime_candidates():
        libvlc_dll = os.path.join(root, "libvlc.dll") if sys.platform == "win32" else os.path.join(root, "libvlc.so")
        if sys.platform == "darwin":
            libvlc_dll = os.path.join(root, "libvlc.dylib")
        plugins_dir = os.path.join(root, "plugins")
        if os.path.isfile(libvlc_dll):
            dll_bits = _get_windows_pe_bitness(libvlc_dll) if sys.platform == "win32" else 0
            candidate = {
                "root": root,
                "libvlc_dll": libvlc_dll,
                "plugins_dir": plugins_dir if os.path.isdir(plugins_dir) else "",
                "dll_bitness": dll_bits,
                "python_bitness": py_bits,
            }
            if sys.platform == "win32" and py_bits and dll_bits and py_bits != dll_bits:
                if fallback is None:
                    fallback = candidate
                continue
            if candidate["plugins_dir"]:
                preferred = candidate
                break
            if fallback is None:
                fallback = candidate
    if preferred:
        _VLC_RUNTIME_INFO = preferred
        return dict(_VLC_RUNTIME_INFO)
    if fallback:
        _VLC_RUNTIME_INFO = fallback
        return dict(_VLC_RUNTIME_INFO)
    _VLC_RUNTIME_INFO = {"root": "", "libvlc_dll": "", "plugins_dir": "", "dll_bitness": 0, "python_bitness": py_bits}
    return dict(_VLC_RUNTIME_INFO)

def _prepare_vlc_runtime(log_if_missing=True):
    info = _probe_vlc_runtime()
    root = info.get("root", "")
    libvlc_dll = info.get("libvlc_dll", "")
    plugins_dir = info.get("plugins_dir", "")
    dll_bits = int(info.get("dll_bitness", 0) or 0)
    py_bits = int(info.get("python_bitness", 0) or 0)
    if not root or not libvlc_dll:
        if log_if_missing:
            write_debug("[VLC] 未找到 VLC Runtime（libvlc.dll / libvlc.so / libvlc.dylib）")
        return False, info
    if sys.platform == "win32" and py_bits and dll_bits and py_bits != dll_bits:
        if log_if_missing:
            write_debug(f"[VLC] 已找到 VLC Runtime，但位数不匹配：Python={py_bits} 位，libvlc.dll={dll_bits} 位，路径={root}")
        return False, info

    try:
        if sys.platform == "win32":
            path_parts = [p for p in os.environ.get("PATH", "").split(os.pathsep) if p]
            if root not in path_parts:
                os.environ["PATH"] = root + os.pathsep + os.environ.get("PATH", "")
            if hasattr(os, "add_dll_directory"):
                try:
                    _VLC_DLL_DIR_HANDLES.append(os.add_dll_directory(root))
                except Exception:
                    pass
        if plugins_dir:
            os.environ["VLC_PLUGIN_PATH"] = plugins_dir
        return True, info
    except Exception as e:
        write_debug(f"[VLC] 注入 VLC Runtime 路径失败: {e}")
        return False, info

