class KeyManagerDialog(QDialog):
    def __init__(self, parent=None, initial_keys=None):
        super().__init__(parent)
        self.setWindowTitle("🔑 API Key 大池管理器 (支持批量操作)")
        self.setMinimumSize(700, 500)
        self.keys = initial_keys or []
        self._init_ui()

    def _init_ui(self):
        layout = QVBoxLayout(self)
        
        tip = QLabel("💡 提示：你可以直接点击『批量导入』一次性粘贴多个 Key，或双击表格编辑。")
        tip.setStyleSheet("color: #0369a1; background: #f0f9ff; padding: 10px; border-radius: 5px;")
        layout.addWidget(tip)

        self.table = QTableWidget(0, 1)
        self.table.setHorizontalHeaderLabels(["API Key 内容"])
        self.table.horizontalHeader().setSectionResizeMode(QHeaderView.ResizeMode.Stretch if PYQT_VERSION == 6 else QHeaderView.Stretch)
        self.table.setAlternatingRowColors(True)
        layout.addWidget(self.table)

        # 底部按钮区
        btn_layout = QHBoxLayout()
        
        btn_add = QPushButton("➕ 添加单行")
        btn_batch = QPushButton("📋 批量导入/粘贴")
        btn_del = QPushButton("➖ 删除选中")
        btn_clear = QPushButton("🗑️ 全部清空")
        btn_dedup = QPushButton("🧹 自动去重")
        
        for b in [btn_add, btn_batch, btn_del, btn_dedup, btn_clear]:
            btn_layout.addWidget(b)
        layout.addLayout(btn_layout)

        # 确认取消区
        bottom_layout = QHBoxLayout()
        bottom_layout.addStretch()
        btn_save = QPushButton("✅ 保存并同步")
        btn_save.setMinimumWidth(120)
        btn_save.setStyleSheet("background-color: #059669; color: white; font-weight: bold; padding: 8px;")
        btn_cancel = QPushButton("取消")
        bottom_layout.addWidget(btn_save)
        bottom_layout.addWidget(btn_cancel)
        layout.addLayout(bottom_layout)

        # 绑定事件
        btn_add.clicked.connect(lambda: self._add_row(""))
        btn_batch.clicked.connect(self._batch_import)
        btn_del.clicked.connect(self._delete_row)
        btn_clear.clicked.connect(lambda: self.table.setRowCount(0))
        btn_dedup.clicked.connect(self._deduplicate)
        btn_save.clicked.connect(self.accept)
        btn_cancel.clicked.connect(self.reject)

        # 填充初始数据
        for k in self.keys:
            self._add_row(k)

    def _add_row(self, val):
        row = self.table.rowCount()
        self.table.insertRow(row)
        self.table.setItem(row, 0, QTableWidgetItem(val))

    def _delete_row(self):
        curr = self.table.currentRow()
        if curr >= 0: self.table.removeRow(curr)

    def _deduplicate(self):
        seen = set()
        unique_keys = []
        for i in range(self.table.rowCount()):
            k = self.table.item(i, 0).text().strip()
            if k and k not in seen:
                seen.add(k)
                unique_keys.append(k)
        
        self.table.setRowCount(0)
        for k in unique_keys: self._add_row(k)
        QMessageBox.information(self, "去重完成", f"已剔除重复项，当前剩余 {len(unique_keys)} 个唯一 Key。")

    def _batch_import(self):
        text, ok = QInputDialog.getMultiLineText(self, "批量导入", "请在下方粘贴你的 API Key 列表 (一行一个):")
        if ok and text:
            new_keys = [k.strip() for k in text.split("\n") if k.strip()]
            for k in new_keys:
                self._add_row(k)

    def get_keys(self):
        res = []
        for i in range(self.table.rowCount()):
            item = self.table.item(i, 0)
            if item and item.text().strip():
                res.append(item.text().strip())
        return res

class ApiPoolManagerDialog(QDialog):
    def __init__(self, parent=None, initial_pool=None):
        super().__init__(parent)
        self.setWindowTitle("🌐 API 节点池管理器")
        self.setMinimumSize(980, 620)
        self.pool = [normalize_api_pool_entry(item, idx) for idx, item in enumerate(initial_pool or [])]
        self._current_index = -1
        self._init_ui()
        self._reload_list()

    def _init_ui(self):
        layout = QVBoxLayout(self)
        tip = QLabel("💡 每个 API 节点都可以拥有独立的接口地址、模型和 Key 池。你可以把 OpenAI、OpenRouter、Gemini、OneAPI、Ollama 分开保存。")
        tip.setWordWrap(True)
        tip.setStyleSheet("color: #0369a1; background: #f0f9ff; padding: 10px; border-radius: 5px;")
        layout.addWidget(tip)

        body = QHBoxLayout()
        layout.addLayout(body, 1)

        left = QVBoxLayout()
        body.addLayout(left, 2)
        left.addWidget(QLabel("API 节点列表"))
        self.api_list = QListWidget()
        self.api_list.currentRowChanged.connect(self._on_row_changed)
        left.addWidget(self.api_list, 1)

        left_btns = QHBoxLayout()
        btn_add = QPushButton("➕ 新建")
        btn_copy = QPushButton("📄 复制")
        btn_del = QPushButton("🗑️ 删除")
        left_btns.addWidget(btn_add)
        left_btns.addWidget(btn_copy)
        left_btns.addWidget(btn_del)
        left.addLayout(left_btns)
        btn_add.clicked.connect(self._add_profile)
        btn_copy.clicked.connect(self._copy_profile)
        btn_del.clicked.connect(self._delete_profile)

        right = QVBoxLayout()
        body.addLayout(right, 3)

        form = QGridLayout()
        right.addLayout(form)
        form.addWidget(QLabel("节点名称:"), 0, 0)
        self.name_edit = QLineEdit()
        form.addWidget(self.name_edit, 0, 1)
        form.addWidget(QLabel("接口地址:"), 1, 0)
        self.base_edit = QLineEdit()
        self.base_edit.setPlaceholderText("https://api.openai.com/v1")
        form.addWidget(self.base_edit, 1, 1)
        form.addWidget(QLabel("默认模型:"), 2, 0)
        self.model_edit = QLineEdit()
        self.model_edit.setPlaceholderText("gpt-4o-mini")
        form.addWidget(self.model_edit, 2, 1)
        self.enabled_check = QCheckBox("启用该 API 节点")
        self.enabled_check.setChecked(True)
        form.addWidget(self.enabled_check, 3, 1)

        right.addWidget(QLabel("该节点的 Key 池（每行一个）"))
        self.keys_edit = QTextEdit()
        self.keys_edit.setPlaceholderText("sk-xxx\nsk-yyy\n...")
        self.keys_edit.setMinimumHeight(220)
        right.addWidget(self.keys_edit, 1)

        helper = QLabel("说明：\n1. 这里的 Key 池只属于当前节点。\n2. 如果是 Gemini 原生接口，接口地址填 `https://generativelanguage.googleapis.com`。\n3. OpenAI / OpenRouter / OneAPI / Groq 这类兼容接口请填到 `/v1`。")
        helper.setStyleSheet("color:#475569; background:#f8fafc; padding:8px; border:1px solid #e2e8f0; border-radius:6px;")
        helper.setWordWrap(True)
        right.addWidget(helper)

        bottom = QHBoxLayout()
        layout.addLayout(bottom)
        bottom.addStretch()
        btn_ok = QPushButton("✅ 保存 API 池")
        btn_cancel = QPushButton("取消")
        bottom.addWidget(btn_ok)
        bottom.addWidget(btn_cancel)
        btn_ok.clicked.connect(self.accept)
        btn_cancel.clicked.connect(self.reject)

    def _reload_list(self):
        self.api_list.blockSignals(True)
        self.api_list.clear()
        for item in self.pool:
            tag = "启用" if item.get("enabled", True) else "停用"
            self.api_list.addItem(f"{item.get('name', '未命名')} [{tag}]")
        self.api_list.blockSignals(False)
        if self.pool:
            target = min(max(self._current_index, 0), len(self.pool) - 1)
            self.api_list.setCurrentRow(target)
        else:
            self._current_index = -1
            self._load_form(None)

    def _load_form(self, item):
        self.name_edit.setText("" if not item else item.get("name", ""))
        self.base_edit.setText("" if not item else item.get("api_base", ""))
        self.model_edit.setText("" if not item else item.get("api_model", ""))
        self.enabled_check.setChecked(True if not item else bool(item.get("enabled", True)))
        self.keys_edit.setPlainText("" if not item else "\n".join(item.get("api_keys", [])))

    def _save_current_form(self):
        if self._current_index < 0 or self._current_index >= len(self.pool):
            return
        item = self.pool[self._current_index]
        item["name"] = self.name_edit.text().strip() or f"API-{self._current_index + 1}"
        item["api_base"] = normalize_api_base_for_profile(self.base_edit.text().strip())
        item["api_model"] = self.model_edit.text().strip() or "gpt-4o-mini"
        item["enabled"] = self.enabled_check.isChecked()
        item["api_keys"] = sanitize_api_keys(self.keys_edit.toPlainText().splitlines())

    def _on_row_changed(self, row):
        if row == self._current_index:
            return
        self._save_current_form()
        self._current_index = row
        if 0 <= row < len(self.pool):
            self._load_form(self.pool[row])
        else:
            self._load_form(None)
        self._reload_list()

    def _add_profile(self):
        self._save_current_form()
        idx = len(self.pool)
        self.pool.append(normalize_api_pool_entry({}, idx))
        self._current_index = idx
        self._reload_list()

    def _copy_profile(self):
        if not self.pool:
            self._add_profile()
            return
        self._save_current_form()
        row = self.api_list.currentRow()
        if row < 0 or row >= len(self.pool):
            return
        item = dict(self.pool[row])
        item["name"] = f"{item.get('name', 'API')}_副本"
        item["api_keys"] = list(item.get("api_keys", []))
        self.pool.insert(row + 1, item)
        self._current_index = row + 1
        self._reload_list()

    def _delete_profile(self):
        row = self.api_list.currentRow()
        if row < 0 or row >= len(self.pool):
            return
        del self.pool[row]
        if not self.pool:
            self._current_index = -1
        else:
            self._current_index = max(0, row - 1)
        self._reload_list()

    def accept(self):
        self._save_current_form()
        self.pool = [normalize_api_pool_entry(item, idx) for idx, item in enumerate(self.pool)]
        super().accept()

    def get_pool(self):
        return [dict(item) for item in self.pool]


class ApiWorker(QThread):
    finished_signal = pyqtSignal(bool, str, object)  # success, message, data
    log_signal = pyqtSignal(str, str)

    def __init__(self, task_type, params):
        super().__init__()
        self.task_type = task_type
        self.params = params
        self.profiles = [dict(p) for p in (params.get("api_profiles", []) or [])]
        if not self.profiles:
            keys = params.get("keys", [])
            if not keys and params.get("key"):
                keys = [params.get("key")]
            base = params.get("base", "")
            model = params.get("model", "gpt-4o-mini")
            self.profiles = [{
                "name": "传统单接口",
                "api_base": normalize_api_base_for_profile(base),
                "api_model": str(model or "gpt-4o-mini").strip() or "gpt-4o-mini",
                "api_keys": order_api_keys(keys, strategy=params.get("pool_strategy", "ordered")),
            }]
        for item in self.profiles:
            item["api_keys"] = order_api_keys(item.get("api_keys", []), strategy=params.get("pool_strategy", "ordered"))
        if get_api_provider_strategy({"api_provider_strategy": params.get("provider_strategy", "ordered")}) == "random":
            random.shuffle(self.profiles)
        self.current_profile_index = 0
        self.current_key_index = 0

    def run(self):
        try:
            if self.task_type == "refresh_models":
                self.do_refresh_models()
            elif self.task_type == "test_api":
                self.do_test_api()
        except Exception as e:
            self.finished_signal.emit(False, str(e), None)

    def get_current_profile(self):
        if not self.profiles:
            return None
        return self.profiles[self.current_profile_index % len(self.profiles)]

    def get_current_key(self):
        profile = self.get_current_profile()
        if not profile:
            return None
        keys = profile.get("api_keys", [])
        if not keys:
            return None
        return keys[self.current_key_index % len(keys)]

    def switch_to_next_key(self):
        profile = self.get_current_profile()
        keys = profile.get("api_keys", []) if profile else []
        if len(keys) <= 1: return False
        self.current_key_index += 1
        display_idx = (self.current_key_index % len(keys)) + 1
        self.log_signal.emit(f"🔄 当前节点的 Key 受限，正在切换到第 {display_idx} 个 Key...", "orange")
        return True

    def switch_to_next_profile(self):
        if len(self.profiles) <= 1:
            return False
        self.current_profile_index += 1
        self.current_key_index = 0
        profile = self.get_current_profile() or {}
        self.log_signal.emit(f"🔀 当前 API 节点不可用，切换到 [{profile.get('name', '未命名节点')}] ...", "orange")
        return True

    def do_refresh_models(self):
        if not self.profiles:
            self.finished_signal.emit(False, "错误：没有可用的 API 节点。", None)
            return
        errors = []
        for _ in range(len(self.profiles)):
            profile = self.get_current_profile() or {}
            base = profile.get("api_base", "")
            key = self.get_current_key()
            if not key:
                errors.append(f"{profile.get('name', '未命名节点')}: 未配置 Key")
                if not self.switch_to_next_profile():
                    break
                continue
            is_google_direct = "googleapis.com" in base.lower()
            self.log_signal.emit(f"🔄 [2/5] 正在连接节点 [{profile.get('name', '未命名节点')}] ...", "blue")
            try:
                if is_google_direct:
                    target_url = f"https://generativelanguage.googleapis.com/v1beta/models?key={key}"
                    r = requests.get(target_url, timeout=10, verify=HTTP_VERIFY)
                else:
                    headers = {"Authorization": f"Bearer {key}"}
                    r = requests.get(f"{base}/models", headers=headers, timeout=15, verify=HTTP_VERIFY)
                r.raise_for_status()
                data = r.json()
                raw_list = data.get("data", []) if isinstance(data, dict) else data
                if isinstance(data, dict) and not raw_list and "models" in data:
                    raw_list = data["models"]
                keywords = ["gemini", "gpt", "claude", "qwen", "deepseek", "llama", "mistral"]
                exclude_keywords = ["robotics", "tuning", "metadata", "embedding", "er-", "computer-use"]
                id_key = "id" if "id" in (raw_list[0] if raw_list else {}) else "name"
                models = []
                for m in raw_list:
                    if isinstance(m, dict) and id_key in m:
                        mid = str(m[id_key])
                        if mid.startswith("models/"):
                            mid = mid.replace("models/", "")
                        mid_lower = mid.lower()
                        if any(k in mid_lower for k in keywords) and not any(ex in mid_lower for ex in exclude_keywords):
                            models.append(mid)
                if is_google_direct and "gemini-2.5-flash" not in models:
                    models.append("gemini-2.5-flash")
                models = sorted(list(set(models)))
                self.finished_signal.emit(True, f"✅ 节点 [{profile.get('name', '未命名节点')}] 成功获取 {len(models)} 个模型", models)
                return
            except Exception as e:
                errors.append(f"{profile.get('name', '未命名节点')}: {e}")
                if not self.switch_to_next_profile():
                    break
        self.finished_signal.emit(False, "；".join(errors) if errors else "获取模型失败", None)

    def do_test_api(self):
        if not self.profiles:
            self.finished_signal.emit(False, "错误：没有可用的 API 节点。", None)
            return
        errors = []
        for _profile_round in range(len(self.profiles)):
            profile = self.get_current_profile() or {}
            base = profile.get("api_base", "")
            mdl = profile.get("api_model") or self.params.get("model") or "gpt-4o-mini"
            keys = profile.get("api_keys", [])
            is_google_direct = is_google_native_api(base)
            if not keys:
                errors.append(f"{profile.get('name', '未命名节点')}: API Key 列表为空")
                if not self.switch_to_next_profile():
                    break
                continue

            max_retries_per_key = 2
            total_keys = len(keys)
            min_interval = get_effective_api_interval(base, {"api_interval": 2, "google_min_interval": 20}, 2)

            for _key_attempt in range(total_keys):
                key = self.get_current_key()
                masked = f"{key[:6]}***{key[-4:]}" if key and len(key) > 10 else "******"
                self.log_signal.emit(f"⚡ 正在使用节点 [{profile.get('name', '未命名节点')}] 的 Key ({masked}) 进行测试...", "blue")
                for attempt in range(max_retries_per_key + 1):
                    import time
                    wait_for_api_slot(base, key, min_interval, log_fn=self.log_signal.emit, prefix="⏳ ")
                    try:
                        if is_google_direct:
                            g_mdl = pick_google_model(mdl, "gemini-2.5-flash")
                            g_url = f"https://generativelanguage.googleapis.com/v1beta/models/{g_mdl}:generateContent?key={key}"
                            g_payload = {
                                "contents": [{"parts": [{"text": "Hello, this is an API connectivity test."}]}],
                                "generationConfig": {"maxOutputTokens": 5},
                                "safetySettings": [
                                    {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                                    {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                                    {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                                    {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"}
                                ]
                            }
                            r = requests.post(g_url, json=g_payload, timeout=15, verify=HTTP_VERIFY)
                        else:
                            headers = {"Content-Type": "application/json", "Authorization": f"Bearer {key}"}
                            payload = {"model": mdl, "messages": [{"role": "user", "content": "hi"}], "max_tokens": 5}
                            r = requests.post(f"{base}/chat/completions", json=payload, headers=headers, timeout=15, verify=HTTP_VERIFY)
                        if r.status_code == 429:
                            err_detail = extract_api_error_message(r)
                            cooldown = parse_retry_after_seconds(r, (2 ** attempt) * (8 if is_google_direct else 3))
                            apply_api_cooldown(base, key, cooldown)
                            if attempt < max_retries_per_key:
                                self.log_signal.emit(f"⚠️ 当前 Key 触发 429，等待 {cooldown:.0f}s 后重试...", "orange")
                                continue
                            if self.switch_to_next_key():
                                break
                            raise RuntimeError(f"429: 当前 Key 频率受限。{err_detail[:160]}")
                        r.raise_for_status()
                        self.finished_signal.emit(True, f"✅ 测试成功！节点 [{profile.get('name', '未命名节点')}] 可用。", r.text)
                        return
                    except Exception as e:
                        if attempt == max_retries_per_key:
                            errors.append(f"{profile.get('name', '未命名节点')}: {e}")
                            if self.switch_to_next_key():
                                break
                            break
            if not self.switch_to_next_profile():
                break
        self.finished_signal.emit(False, "；".join(errors) if errors else "API 测试失败", None)


