class PathDropTextEdit(QTextEdit):
    """支持把多个文件夹/文件直接拖入的多行文本框。"""
    def __init__(self, parent=None, accept_dirs=True, accept_files=False):
        super().__init__(parent)
        self.accept_dirs = accept_dirs
        self.accept_files = accept_files
        self.setAcceptDrops(True)
        self.setFixedHeight(60) # 默认高度，显示约2-3行

    def _extract_local_path(self, url):
        path = url.toLocalFile()
        if not path:
            raw = url.toString()
            if raw.startswith("file:///"):
                path = urllib.parse.unquote(raw[8:])
                if sys.platform == 'win32' and path.startswith('/'):
                    path = path[1:]
        return os.path.normpath(path) if path else ""

    def _is_acceptable_path(self, path):
        if not path: return False
        return (self.accept_dirs and os.path.isdir(path)) or (self.accept_files and os.path.isfile(path))

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            for url in event.mimeData().urls():
                if self._is_acceptable_path(self._extract_local_path(url)):
                    event.acceptProposedAction()
                    return
        event.ignore()

    def dragMoveEvent(self, event):
        self.dragEnterEvent(event)

    def dropEvent(self, event):
        if not event.mimeData().hasUrls():
            event.ignore(); return
        paths = []
        for url in event.mimeData().urls():
            path = self._extract_local_path(url)
            if self._is_acceptable_path(path):
                paths.append(path)
        if paths:
            self.setPlainText("\n".join(paths))
            event.acceptProposedAction()
        else:
            event.ignore()

    # 兼容 QLineEdit 的常用方法
    def text(self): return self.toPlainText()
    def setText(self, t): self.setPlainText(t)

class PathDropLineEdit(QLineEdit):
    """支持把文件夹/文件拖入的单行输入框（用于路径）。"""
    def __init__(self, parent=None, accept_dirs=True, accept_files=False):
        super().__init__(parent)
        self.accept_dirs = accept_dirs
        self.accept_files = accept_files
        self.setAcceptDrops(True)

    def _extract_local_path(self, url):
        path = ""
        try:
            path = url.toLocalFile()
        except Exception:
            path = ""
        if not path:
            raw = ""
            try:
                raw = url.toString()
            except Exception:
                raw = ""
            if raw.startswith("file:///"):
                path = urllib.parse.unquote(raw[8:])
                if sys.platform == 'win32' and path.startswith('/'):
                    path = path[1:]
        return os.path.normpath(path) if path else ""

    def _is_acceptable_path(self, path):
        if not path:
            return False
        return (self.accept_dirs and os.path.isdir(path)) or (self.accept_files and os.path.isfile(path))

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            for url in event.mimeData().urls():
                if self._is_acceptable_path(self._extract_local_path(url)):
                    event.acceptProposedAction()
                    return
        event.ignore()

    def dragMoveEvent(self, event):
        self.dragEnterEvent(event)

    def dropEvent(self, event):
        if not event.mimeData().hasUrls():
            event.ignore()
            return
        for url in event.mimeData().urls():
            path = self._extract_local_path(url)
            if self._is_acceptable_path(path):
                self.setText(path)
                event.acceptProposedAction()
                return
        event.ignore()

class ChatInputTextEdit(QTextEdit):
    """聊天输入框：支持拖入文件/文件夹作为附件。"""
    attachments_dropped = pyqtSignal(list)
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragEnterEvent(event)
    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragMoveEvent(event)
    def dropEvent(self, event):
        urls = event.mimeData().urls() if event.mimeData() and event.mimeData().hasUrls() else []
        paths = []
        for url in urls:
            try:
                p = url.toLocalFile()
            except Exception:
                p = ""
            if p:
                p = os.path.normpath(p)
                if os.path.exists(p):
                    paths.append(p)
        if paths:
            self.attachments_dropped.emit(paths)
            event.acceptProposedAction()
            return
        super().dropEvent(event)

def is_image_path(path):
    ext = os.path.splitext(str(path or ""))[1].lower()
    return ext in (".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif")

def safe_read_text_file(path, max_chars=5000):
    encodings = ["utf-8", "utf-8-sig", "gbk", "gb18030", "latin-1"]
    for enc in encodings:
        try:
            with open(path, "r", encoding=enc) as f:
                return f.read(max_chars)
        except Exception:
            continue
    return ""

def summarize_folder_for_ai(folder_path, max_items=40):
    try:
        folders = 0
        files = 0
        samples = []
        for root, dirnames, filenames in os.walk(folder_path):
            folders += len(dirnames)
            files += len(filenames)
            for name in filenames[:max(0, max_items - len(samples))]:
                rel = os.path.relpath(os.path.join(root, name), folder_path)
                samples.append(rel)
            if len(samples) >= max_items:
                break
        lines = [
            f"文件夹路径: {folder_path}",
            f"共发现 {folders} 个子文件夹，{files} 个文件。"
        ]
        if samples:
            lines.append("样例文件:")
            lines.extend([f"- {item}" for item in samples[:max_items]])
        return "\n".join(lines)
    except Exception as e:
        return f"文件夹路径: {folder_path}\n读取失败: {e}"

def summarize_attachment_for_ai(att):
    path = str(att.get("path", "") or "").strip()
    if not path:
        return ""
    name = att.get("name") or os.path.basename(path) or path
    kind = att.get("kind") or ("folder" if os.path.isdir(path) else "file")
    if not os.path.exists(path):
        return f"[附件] {name}\n路径: {path}\n状态: 文件不存在"
    if kind == "folder" or os.path.isdir(path):
        return f"[文件夹附件] {name}\n{summarize_folder_for_ai(path)}"
    mime, _ = mimetypes.guess_type(path)
    if is_image_path(path):
        return f"[图片附件] {name}\n路径: {path}\n说明: 这是用户附带的图片，可结合路径和文件名理解上下文。"
    text_exts = {".txt", ".md", ".markdown", ".csv", ".json", ".py", ".log", ".ini", ".yaml", ".yml", ".toml"}
    ext = os.path.splitext(path)[1].lower()
    if ext in text_exts or (mime and mime.startswith("text/")):
        content = safe_read_text_file(path, 5000)
        if content:
            return f"[文本附件] {name}\n路径: {path}\n内容摘录:\n{content}"
    try:
        size_kb = os.path.getsize(path) / 1024.0
    except Exception:
        size_kb = 0
    return f"[文件附件] {name}\n路径: {path}\n大小: {size_kb:.1f} KB"

def render_markdown_html(text):
    raw = str(text or "")
    try:
        import markdown as _markdown
        html_body = _markdown.markdown(
            raw,
            extensions=["fenced_code", "tables", "sane_lists", "nl2br"]
        )
    except Exception:
        html_body = html.escape(raw).replace("\n", "<br>")
    return html_body

def parse_plan_items_from_text(text, fallback_source="AI"):
    lines = str(text or "").splitlines()
    items = []
    priority_keywords = [
        ("高", ["p0", "p1", "高优先级", "紧急", "重要", "urgent", "high"]),
        ("中", ["p2", "中优先级", "一般", "normal", "medium"]),
        ("低", ["p3", "低优先级", "稍后", "low", "later"])
    ]
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        line = re.sub(r"^\s*(?:[-*•]|\d+[.)]|`)\s*", "", line).strip()
        if not line or len(line) < 2:
            continue
        if len(items) >= 50:
            break
        priority = "中"
        lower = line.lower()
        for label, keys in priority_keywords:
            if any(k in lower for k in keys):
                priority = label
                line = re.sub("|".join(re.escape(k) for k in keys[:3]), "", line, flags=re.I).strip(" :：-")
                break
        items.append({
            "done": False,
            "priority": priority,
            "content": line[:200],
            "deadline": "",
            "source": fallback_source
        })
    return items

