def build_subtitle_style_layer(style=None):
    style = normalize_subtitle_style(style)
    return {
        "font_size": style.get("font_size", 54),
        "font_size_mode": style.get("font_size_mode", "percent_width"),
        "font_size_ratio": style.get("font_size_ratio", 4.6),
        "font_family": style.get("font_family", ""),
        "color": style.get("color", "#ffffff"),
        "stroke_color": style.get("stroke_color", "#000000"),
        "stroke_width": style.get("stroke_width", 3.2),
    }


def _coerce_ass_bool(value):
    text = str(value or "").strip().lower()
    if text in {"-1", "1", "true", "yes", "on"}:
        return True
    if text in {"0", "false", "no", "off", ""}:
        return False
    try:
        return int(float(text)) != 0
    except Exception:
        return False


def _parse_ass_color(value, default_hex="#ffffff", default_opacity=100):
    text = str(value or "").strip()
    if not text:
        return default_hex, int(default_opacity)
    try:
        if text.lower().startswith("&h"):
            raw = re.sub(r"[^0-9a-fA-F]", "", text[2:])
        else:
            dec = int(float(text))
            if dec < 0:
                dec &= 0xFFFFFFFF
            raw = f"{dec:X}"
        raw = raw[-8:].rjust(8, "0")
        alpha = int(raw[0:2], 16)
        blue = int(raw[2:4], 16)
        green = int(raw[4:6], 16)
        red = int(raw[6:8], 16)
        color_hex = f"#{red:02x}{green:02x}{blue:02x}"
        opacity = int(round((255 - alpha) * 100 / 255))
        return color_hex, max(0, min(100, opacity))
    except Exception:
        return default_hex, int(default_opacity)


def _ass_alignment_to_position(value):
    try:
        align = int(float(value))
    except Exception:
        align = 2
    if align in {7, 8, 9}:
        return "top"
    if align in {4, 5, 6}:
        return "middle"
    return "bottom"


def parse_ass_style_presets(text, source_name=""):
    section = ""
    format_fields = []
    presets = {}
    if not text:
        return presets
    for raw_line in str(text).splitlines():
        line = raw_line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line.strip().lower()
            format_fields = []
            continue
        if section not in {"[v4+ styles]", "[v4 styles]"}:
            continue
        if line.lower().startswith("format:"):
            format_fields = [part.strip().lower() for part in line.split(":", 1)[1].split(",")]
            continue
        if not line.lower().startswith("style:") or not format_fields:
            continue
        parts = [part.strip() for part in line.split(":", 1)[1].split(",", len(format_fields) - 1)]
        if len(parts) != len(format_fields):
            continue
        row = dict(zip(format_fields, parts))
        style_name = str(row.get("name", "") or "").strip() or "ASS样式"
        primary_color, primary_opacity = _parse_ass_color(row.get("primarycolour"), "#ffffff", 100)
        outline_color, outline_opacity = _parse_ass_color(row.get("outlinecolour"), "#000000", 100)
        back_color, back_opacity = _parse_ass_color(row.get("backcolour"), "#000000", 55)
        margin_l = int(round(float(row.get("marginl", 36) or 36)))
        margin_r = int(round(float(row.get("marginr", 36) or 36)))
        style = normalize_subtitle_style({
            "font_family": str(row.get("fontname", "") or ""),
            "font_size_mode": "fixed",
            "font_size": int(round(float(row.get("fontsize", 54) or 54))),
            "color": primary_color,
            "text_opacity": primary_opacity,
            "stroke_color": outline_color,
            "stroke_opacity": outline_opacity,
            "stroke_width": float(row.get("outline", 3.2) or 0.0),
            "shadow": float(row.get("shadow", 0.8) or 0.0),
            "bold": _coerce_ass_bool(row.get("bold")),
            "italic": _coerce_ass_bool(row.get("italic")),
            "underline": _coerce_ass_bool(row.get("underline")),
            "strikeout": _coerce_ass_bool(row.get("strikeout")),
            "letter_spacing": float(row.get("spacing", 0.0) or 0.0),
            "scale_x": int(round(float(row.get("scalex", 100) or 100))),
            "scale_y": int(round(float(row.get("scaley", 100) or 100))),
            "angle": float(row.get("angle", 0.0) or 0.0),
            "position": _ass_alignment_to_position(row.get("alignment")),
            "margin_v": int(round(float(row.get("marginv", 58) or 58))),
            "margin_h": max(margin_l, margin_r),
            "background_box": str(row.get("borderstyle", "1") or "1").strip() == "3",
            "background_color": back_color,
            "background_opacity": back_opacity,
        })
        key = style_name
        if source_name:
            key = f"{source_name} · {style_name}"
        unique_key = key
        suffix = 2
        while unique_key in presets:
            unique_key = f"{key} ({suffix})"
            suffix += 1
        presets[unique_key] = style
    return presets


class SubtitleStylePreviewWidget(QLabel):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.subtitle_style = normalize_subtitle_style()
        self.preview_width = 1080
        self.preview_height = 1920
        self.preview_text = "这里输入一段真实字幕预览文本，右侧效果会尽量贴近最终成片。"
        self.setStyleSheet("border: 1px solid #94a3b8; background: #0f172a; border-radius: 12px;")
        self.setMinimumWidth(160)
        self.setMaximumWidth(320)
        self.setMinimumHeight(200)
        self.setSizePolicy(_Preferred, _Expanding)
        self.update_preview(self.subtitle_style, self.preview_width, self.preview_height)

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        width = max(self.minimumWidth(), min(width, self.maximumWidth() if self.maximumWidth() > 0 else width))
        return max(self.minimumHeight(), int(width * self.preview_height / max(1, self.preview_width)))

    def sizeHint(self):
        base_w = min(250, self.maximumWidth() if self.maximumWidth() > 0 else 250)
        return QSize(base_w, self.heightForWidth(base_w))

    def update_preview(self, subtitle_style=None, width=1080, height=1920, preview_text=None):
        self.subtitle_style = normalize_subtitle_style(subtitle_style)
        self.preview_width = max(1, int(width or 1080))
        self.preview_height = max(1, int(height or 1920))
        if preview_text is not None:
            self.preview_text = str(preview_text or "").strip() or "这里输入一段真实字幕预览文本，右侧效果会尽量贴近最终成片。"
        self.updateGeometry()
        self.update()

    def _calc_anchor_y(self, position, screen_h, block_h, margin_v):
        if position == "top":
            return margin_v
        if position == "middle":
            return max(0, int((screen_h - block_h) / 2))
        return max(0, screen_h - block_h - margin_v)

    def _build_preview_font(self, style, font_px):
        font = QFont(style.get("font_family", "") or "")
        font.setBold(bool(style.get("bold", False)))
        font.setItalic(bool(style.get("italic", False)))
        font.setUnderline(bool(style.get("underline", False)))
        font.setStrikeOut(bool(style.get("strikeout", False)))
        try:
            font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing if PYQT_VERSION == 6 else QFont.AbsoluteSpacing, float(style.get("letter_spacing", 0.0) or 0.0))
        except Exception:
            pass
        try:
            font.setPixelSize(font_px)
        except Exception:
            font.setPointSize(max(8, font_px))
        return font

    def _mix_qcolor(self, c1, c2, t):
        t = max(0.0, min(1.0, float(t or 0.0)))
        mixed = QColor(
            int(round(c1.red() + (c2.red() - c1.red()) * t)),
            int(round(c1.green() + (c2.green() - c1.green()) * t)),
            int(round(c1.blue() + (c2.blue() - c1.blue()) * t)),
            int(round(c1.alpha() + (c2.alpha() - c1.alpha()) * t)),
        )
        return mixed

    def _draw_text_fill(self, painter, text_path, style, fill_color):
        if not style.get("gradient_fill", False):
            painter.fillPath(text_path, QBrush(fill_color))
            return
        end_color = QColor(style.get("gradient_color_end", "#67e8f9"))
        end_color.setAlpha(fill_color.alpha())
        rect = text_path.boundingRect()
        if rect.height() <= 1:
            painter.fillPath(text_path, QBrush(fill_color))
            return
        steps = 6
        for idx in range(steps):
            t = idx / max(1, steps - 1)
            color = self._mix_qcolor(fill_color, end_color, t)
            y1 = rect.top() + rect.height() * idx / steps
            y2 = rect.top() + rect.height() * (idx + 1) / steps
            painter.save()
            painter.setClipRect(QRectF(rect.left() - 4, y1, rect.width() + 8, max(1.0, y2 - y1)))
            painter.fillPath(text_path, QBrush(color))
            painter.restore()

    def _draw_shadow(self, painter, text_path, style, scale):
        shadow_opacity = int(style.get("shadow_opacity", 0) or 0)
        dx = float(style.get("shadow_x", 0.0) or 0.0) * max(0.5, scale)
        dy = float(style.get("shadow_y", 0.0) or 0.0) * max(0.5, scale)
        blur = float(style.get("shadow_blur", 0.0) or 0.0) * max(0.5, scale)
        if shadow_opacity <= 0 or (abs(dx) < 0.01 and abs(dy) < 0.01 and blur <= 0.01):
            return
        shadow_color = QColor(style.get("shadow_color", "#000000"))
        base_alpha = max(0.0, min(1.0, shadow_opacity / 100.0))
        passes = max(1, int(round(blur)) + 1)
        for idx in range(passes):
            alpha = base_alpha * (0.7 if idx == 0 else max(0.12, 0.35 / (idx + 1)))
            shadow_color.setAlphaF(alpha)
            painter.save()
            painter.translate(dx + idx * 0.35, dy + idx * 0.35)
            painter.fillPath(text_path, QBrush(shadow_color))
            painter.restore()

    def _draw_glow(self, painter, text_path, style, scale):
        if not style.get("glow_enabled", False):
            return
        glow_size = float(style.get("glow_size", 0.0) or 0.0) * max(0.6, scale)
        glow_blur = float(style.get("glow_blur", 0.0) or 0.0) * max(0.6, scale)
        glow_opacity = int(style.get("glow_opacity", 0) or 0)
        if glow_size <= 0.01 and glow_blur <= 0.01:
            return
        glow_color = QColor(style.get("glow_color", "#67e8f9"))
        base_alpha = max(0.0, min(1.0, glow_opacity / 100.0))
        for factor, alpha_factor in [(1.55, 0.18), (1.10, 0.30), (0.72, 0.44)]:
            c = QColor(glow_color)
            c.setAlphaF(base_alpha * alpha_factor)
            pen = QPen(c, max(1.0, glow_size * factor + glow_blur), Qt.PenStyle.SolidLine if PYQT_VERSION == 6 else Qt.SolidLine)
            pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin if PYQT_VERSION == 6 else Qt.RoundJoin)
            painter.strokePath(text_path, pen)

    def _draw_center_panel(self, painter, canvas_w, y, width_px, height_px, radius, color):
        rect = QRectF(max(8.0, (canvas_w - width_px) / 2.0), y, max(12.0, width_px), max(6.0, height_px))
        painter.setPen(Qt.PenStyle.NoPen if PYQT_VERSION == 6 else Qt.NoPen)
        painter.setBrush(color)
        painter.drawRoundedRect(rect, radius, radius)
        return rect

    def _wrap_preview_text(self, text, fm, max_width):
        raw_lines = str(text or "").replace("\r\n", "\n").split("\n")
        wrapped = []
        max_width = max(40, int(max_width or 40))
        for raw in raw_lines:
            raw = str(raw or "").strip()
            if not raw:
                if wrapped:
                    wrapped.append("")
                continue
            current = ""
            for ch in raw:
                test = current + ch
                test_w = fm.horizontalAdvance(test) if PYQT_VERSION == 6 else fm.width(test)
                if current and test_w > max_width:
                    wrapped.append(current)
                    current = ch
                else:
                    current = test
            if current:
                wrapped.append(current)
        return [line for line in wrapped if str(line).strip()] or ["这是字幕预览效果"]

    def paintEvent(self, event):
        super().paintEvent(event)
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing if PYQT_VERSION == 6 else QPainter.Antialiasing)
        painter.fillRect(self.rect(), QColor("#0f172a"))

        outer = self.rect().adjusted(8, 8, -8, -8)
        painter.setPen(QPen(QColor("#334155"), 2))
        painter.setBrush(QColor("#111827"))
        painter.drawRoundedRect(outer, 18, 18)

        screen = outer.adjusted(12, 18, -12, -18)
        painter.setPen(QPen(QColor("#1e293b"), 1))
        painter.setBrush(QColor("#111827"))
        painter.drawRoundedRect(screen, 12, 12)

        style = normalize_subtitle_style(self.subtitle_style)

        painter.save()
        painter.setClipRect(screen)
        painter.translate(screen.left(), screen.top())
        canvas_w, canvas_h = screen.width(), screen.height()
        scale_x = canvas_w / max(1, float(self.preview_width))
        scale_y = canvas_h / max(1, float(self.preview_height))
        scale = min(scale_x, scale_y)

        font_px = resolve_text_font_size_px(build_subtitle_style_layer(style), self.preview_width, minimum=12)
        font_px = max(8, int(round(font_px * scale)))
        font = self._build_preview_font(style, font_px)
        fm = QFontMetrics(font)
        scale_x_ratio = max(0.3, float(style.get("scale_x", 100) or 100) / 100.0)
        scale_y_ratio = max(0.3, float(style.get("scale_y", 100) or 100) / 100.0)
        angle = float(style.get("angle", 0.0) or 0.0)
        line_gap = max(6, int(round(font_px * 0.25 * scale_y_ratio)))
        line_height = max(1, int(round(fm.height() * scale_y_ratio)))
        margin_v = max(8, int(round(style.get("margin_v", 58) * scale_y)))
        margin_h = max(10, int(round(style.get("margin_h", 36) * scale_x)))
        offset_x = int(round(float(style.get("offset_x", 0) or 0) * scale_x))
        offset_y = int(round(float(style.get("offset_y", 0) or 0) * scale_y))
        pad_x = max(0, int(round(style.get("background_pad_x", 28) * scale_x)))
        text_max_w = canvas_w - margin_h * 2
        if style.get("background_box", False):
            preview_box_w = min(canvas_w - 16, max(text_max_w, int(round(canvas_w * float(style.get("background_width_ratio", 78.0) or 78.0) / 100.0))))
            text_max_w = max(40, preview_box_w - pad_x * 2)
        sample_lines = self._wrap_preview_text(self.preview_text, fm, text_max_w)
        base_line_widths = [(fm.horizontalAdvance(line) if PYQT_VERSION == 6 else fm.width(line)) for line in sample_lines]
        block_h = len(sample_lines) * line_height + max(0, len(sample_lines) - 1) * line_gap
        block_w = max(1, int(round(max(base_line_widths) * scale_x_ratio)))
        anchor_y = self._calc_anchor_y(style.get("position", "bottom"), canvas_h, block_h, margin_v) + offset_y
        anchor_y = max(8, min(canvas_h - block_h - 8, anchor_y))
        center_x = int(canvas_w / 2) + offset_x

        fill_color = QColor(style.get("color", "#ffffff"))
        fill_color.setAlphaF(max(0.0, min(1.0, style.get("text_opacity", 100) / 100.0)))
        stroke_color = QColor(style.get("stroke_color", "#000000"))
        stroke_color.setAlphaF(max(0.0, min(1.0, style.get("stroke_opacity", 100) / 100.0)))
        outer_stroke_color = QColor(style.get("secondary_stroke_color", "#1f2937"))
        outer_stroke_color.setAlphaF(max(0.0, min(1.0, style.get("secondary_stroke_opacity", 100) / 100.0)))
        box_color = QColor(style.get("background_color", "#000000"))
        box_color.setAlphaF(max(0.0, min(1.0, style.get("background_opacity", 55) / 100.0)))

        box_rect = None
        if style.get("background_box", False):
            pad_y = max(0, int(round(style.get("background_pad_y", 16) * scale_y)))
            box_w = min(canvas_w - 16, max(block_w + pad_x * 2, int(round(canvas_w * float(style.get("background_width_ratio", 78.0) or 78.0) / 100.0))))
            box_h = min(canvas_h - 16, max(block_h + pad_y * 2, int(round(font_px * 1.9))))
            box_y = max(8.0, min(canvas_h - box_h - 8.0, anchor_y - pad_y))
            radius = min(float(style.get("background_radius", 18) or 18) * scale, box_h / 2.0)
            box_rect = self._draw_center_panel(painter, canvas_w, box_y, box_w, box_h, radius, box_color)

        if style.get("highlight_bar_enabled", False):
            hl_color = QColor(style.get("highlight_color", "#f59e0b"))
            hl_color.setAlphaF(max(0.0, min(1.0, style.get("highlight_opacity", 90) / 100.0)))
            bar_h = max(4.0, float(style.get("highlight_height", 10) or 10) * scale_y)
            bar_w = min(canvas_w - 16, max(font_px * 3.0, canvas_w * float(style.get("highlight_width_ratio", 36.0) or 36.0) / 100.0))
            bar_gap = max(2.0, float(style.get("highlight_gap", 10) or 10) * scale_y)
            if style.get("position", "bottom") == "top":
                base_y = (box_rect.bottom() if box_rect else (anchor_y + font_px * 0.45)) + bar_gap
            else:
                top_y = box_rect.top() if box_rect else (anchor_y - block_h)
                base_y = max(8.0, top_y - bar_gap - bar_h)
            self._draw_center_panel(painter, canvas_w, base_y, bar_w, bar_h, min(bar_h / 2.0, 999.0), hl_color)

        for idx, line in enumerate(sample_lines):
            baseline_y = anchor_y + idx * (line_height + line_gap) + fm.ascent()
            line_w = max(1, int(round(base_line_widths[idx] * scale_x_ratio)))
            line_x = int(round(center_x - line_w / 2.0))
            min_line_x = min(margin_h, max(0, canvas_w - line_w))
            max_line_x = max(min_line_x, canvas_w - line_w - margin_h)
            line_x = max(min_line_x, min(max_line_x, line_x))
            text_path = QPainterPath()
            text_path.addText(0, 0, font, line)
            transform = QTransform()
            transform.translate(line_x, baseline_y)
            if abs(angle) > 0.01:
                transform.rotate(angle)
            if abs(scale_x_ratio - 1.0) > 0.001 or abs(scale_y_ratio - 1.0) > 0.001:
                transform.scale(scale_x_ratio, scale_y_ratio)
            text_path = transform.map(text_path)
            self._draw_shadow(painter, text_path, style, scale)
            self._draw_glow(painter, text_path, style, scale)
            if style.get("double_stroke_enabled", False):
                outer_width = max(0.0, float(style.get("secondary_stroke_width", 0.0) or 0.0) * scale)
                if outer_width > 0:
                    pen = QPen(outer_stroke_color, max(1.0, outer_width), Qt.PenStyle.SolidLine if PYQT_VERSION == 6 else Qt.SolidLine)
                    pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin if PYQT_VERSION == 6 else Qt.RoundJoin)
                    painter.strokePath(text_path, pen)
            stroke_width = max(0.0, float(style.get("stroke_width", 0.0) or 0.0) * scale)
            if stroke_width > 0:
                pen = QPen(stroke_color, max(1.0, stroke_width), Qt.PenStyle.SolidLine if PYQT_VERSION == 6 else Qt.SolidLine)
                pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin if PYQT_VERSION == 6 else Qt.RoundJoin)
                painter.strokePath(text_path, pen)
            self._draw_text_fill(painter, text_path, style, fill_color)

        painter.restore()
        ratio_text = f"{self.preview_width}:{self.preview_height}"
        ratio_align = (Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignBottom) if PYQT_VERSION == 6 else (Qt.AlignRight | Qt.AlignBottom)
        painter.setPen(QColor("#cbd5e1"))
        painter.drawText(self.rect().adjusted(0, 0, -12, -10), ratio_align, ratio_text)
        painter.end()


class VideoFormatAudioBatchThread(QThread):
    progress = pyqtSignal(int)
    log = pyqtSignal(str, str)
    finished_all = pyqtSignal()
    VIDEO_EXTS = VideoConcatBatchThread.VIDEO_EXTS
    AUDIO_EXTS = ('.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg', '.wma', '.opus')
    SUBTITLE_EXTS = ('.srt', '.ass', '.ssa', '.vtt')
    TEXT_SOURCE_EXTS = ('.txt', '.md', '.srt', '.vtt', '.lrc')

    def __init__(self, video_paths, out_dir, config=None):
        super().__init__()
        self.video_paths = video_paths or []
        self.out_dir = out_dir
        self.config = config if isinstance(config, dict) else {}

    def _run_process(self, cmd, timeout=None):
        return subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout, **_subprocess_no_window_kwargs())

    def _ffprobe_has_audio(self, file_path):
        try:
            cmd = ["ffprobe", "-v", "error", "-select_streams", "a", "-show_entries", "stream=index", "-of", "csv=p=0", file_path]
            out = subprocess.check_output(cmd, stderr=subprocess.DEVNULL, **_subprocess_no_window_kwargs()).decode(errors="replace").strip()
            return bool(out)
        except Exception:
            return False

    def _get_asr_helper(self):
        helper = getattr(self, "_subtitle_asr_helper", None)
        if helper is None:
            helper = VideoCopyMatchThread(
                "",
                copy_items=[],
                clip_use_gpu=bool(self.config.get("subtitle_use_gpu", True)),
                ai_config=dict(self.config.get("subtitle_ai_config", {}) or {})
            )
            self._subtitle_asr_helper = helper
        return helper

    def _escape_subtitle_path_for_filter(self, subtitle_path):
        norm = os.path.abspath(subtitle_path).replace("\\", "/")
        for src, dst in [
            ("\\", "\\\\"),
            (":", r"\:"),
            ("'", r"\'"),
            (",", r"\,"),
            ("[", r"\["),
            ("]", r"\]"),
            (";", r"\;"),
        ]:
            norm = norm.replace(src, dst)
        return norm

    def _find_sidecar_subtitle(self, src_path):
        base_no_ext = os.path.splitext(src_path)[0]
        for ext in self.SUBTITLE_EXTS:
            p = base_no_ext + ext
            if os.path.isfile(p):
                return p
        return ""

    def _find_sidecar_text_source(self, src_path):
        base_no_ext = os.path.splitext(src_path)[0]
        for ext in self.TEXT_SOURCE_EXTS:
            p = base_no_ext + ext
            if os.path.isfile(p):
                return p
        return ""

    def _write_generated_subtitle(self, src_path, out_path):
        helper = self._get_asr_helper()
        temp_audio = helper._extract_audio_wav(src_path)
        if not temp_audio:
            raise RuntimeError("无法提取音轨，不能自动生成字幕")
        try:
            transcribed = helper._transcribe_audio(temp_audio)
            transcript = str(transcribed.get("text", "") or "").strip()
            segments = helper._ensure_timed_segments(src_path, transcript, transcribed.get("segments") or [])
            srt_text = build_srt_text(segments)
            if not srt_text.strip():
                raise RuntimeError("转写成功但字幕内容为空")
            with open(out_path, "w", encoding="utf-8-sig") as f:
                f.write(srt_text)
            return out_path, str(transcribed.get("engine", "") or "ASR")
        finally:
            try:
                if temp_audio and os.path.exists(temp_audio):
                    os.remove(temp_audio)
            except Exception:
                pass

    def _get_subtitle_compose_helper(self):
        helper = getattr(self, "_subtitle_compose_helper", None)
        if helper is None:
            helper = AudioSubtitleComposeThread(
                "",
                text_source=str(self.config.get("subtitle_text_source", "") or ""),
                manual_text=str(self.config.get("subtitle_manual_text", "") or ""),
                subtitle_mode=str(self.config.get("subtitle_align_mode", "script_blocks") or "script_blocks"),
                clip_use_gpu=bool(self.config.get("subtitle_use_gpu", True)),
                ai_config=dict(self.config.get("subtitle_ai_config", {}) or {})
            )
            self._subtitle_compose_helper = helper
        return helper

    def _select_script_items_for_video(self, src_path):
        text_source = str(self.config.get("subtitle_text_source", "") or "").strip()
        manual_text = str(self.config.get("subtitle_manual_text", "") or "").strip()
        subtitle_mode = str(self.config.get("subtitle_align_mode", "script_blocks") or "script_blocks")
        item_mode = "files" if subtitle_mode == "script_files" else "blocks"
        video_stem = os.path.splitext(os.path.basename(str(src_path or "")))[0].strip().lower()

        fallback_sidecar = ""
        if not text_source:
            fallback_sidecar = self._find_sidecar_text_source(src_path)
            if fallback_sidecar:
                text_source = fallback_sidecar

        items = build_subtitle_items_from_sources(text_source, manual_text, mode=item_mode)
        if not items:
            return [], fallback_sidecar, {"status": "no_text", "message": "没有提供可对齐文本"}

        manual_items = [it for it in items if str(it.get("source_stem", "") or "").strip().lower() == "manual"]
        file_items = [it for it in items if str(it.get("source_path", "") or "").strip()]
        if not file_items:
            return items, fallback_sidecar, {"status": "manual_only", "message": "仅使用手填文本"}

        file_stems = sorted({
            str(it.get("source_stem", "") or os.path.splitext(os.path.basename(str(it.get("source_path", "") or "")))[0]).strip().lower()
            for it in file_items
            if str(it.get("source_path", "") or "").strip()
        })
        if len(file_stems) <= 1:
            source_name = os.path.basename(str(file_items[0].get("source_path", "") or "")) if file_items else ""
            return items, fallback_sidecar, {"status": "global_text", "message": f"使用统一文本：{source_name}" if source_name else "使用统一文本"}

        matched_file_items = [
            it for it in file_items
            if str(it.get("source_stem", "") or os.path.splitext(os.path.basename(str(it.get("source_path", "") or "")))[0]).strip().lower() == video_stem
        ]
        if not matched_file_items and video_stem:
            matched_file_items = [
                it for it in file_items
                if video_stem in str(it.get("source_stem", "") or "").strip().lower()
                or str(it.get("source_stem", "") or "").strip().lower() in video_stem
            ]
        if matched_file_items:
            source_name = os.path.basename(str(matched_file_items[0].get("source_path", "") or "")) if matched_file_items else ""
            return manual_items + matched_file_items, fallback_sidecar, {"status": "same_name_text", "message": f"按同名文本对齐：{source_name}" if source_name else "按同名文本对齐"}

        if manual_items:
            return manual_items, fallback_sidecar, {"status": "manual_fallback", "message": "未找到同名文本，改用手填文本"}
        return [], fallback_sidecar, {"status": "no_same_name_text", "message": "多视频模式下未找到同名文本，已回退纯转写"}

    def _write_aligned_subtitle(self, src_path, out_path):
        helper = self._get_asr_helper()
        compose_helper = self._get_subtitle_compose_helper()
        script_items, matched_sidecar, match_meta = self._select_script_items_for_video(src_path)
        if not script_items:
            raise RuntimeError(str((match_meta or {}).get("message", "") or "没有找到可用于对齐的文本"))

        temp_audio = helper._extract_audio_wav(src_path)
        if not temp_audio:
            raise RuntimeError("无法提取音轨，不能生成对齐字幕")
        try:
            transcribed = helper._transcribe_audio(temp_audio)
            transcript = str(transcribed.get("text", "") or "").strip()
            asr_segments = helper._ensure_timed_segments(src_path, transcript, transcribed.get("segments") or [])
            aligned_segments = compose_helper._align_script_items(src_path, script_items, asr_segments)
            srt_text = build_srt_text(aligned_segments)
            if not srt_text.strip():
                raise RuntimeError("文本对齐完成但字幕内容为空")
            with open(out_path, "w", encoding="utf-8-sig") as f:
                f.write(srt_text)
            status = str((match_meta or {}).get("status", "") or "").strip()
            if status == "same_name_text":
                label = f"文本对齐（同名文本）"
            elif status == "manual_only":
                label = f"文本对齐（手填文本）"
            elif status == "manual_fallback":
                label = f"文本对齐（手填文本回退）"
            else:
                label = f"文本对齐（统一文本）"
            if matched_sidecar and status != "same_name_text":
                label += f" - {os.path.basename(matched_sidecar)}"
            return out_path, label
        finally:
            try:
                if temp_audio and os.path.exists(temp_audio):
                    os.remove(temp_audio)
            except Exception:
                pass

    def _resolve_subtitle_for_video(self, src_path, out_path):
        mode = str(self.config.get("subtitle_mode", "none") or "none")
        keep_srt = bool(self.config.get("subtitle_keep_srt", False))
        if mode == "none":
            return "", "", False
        if mode == "sidecar_burn":
            sidecar = self._find_sidecar_subtitle(src_path)
            return sidecar, ("同名字幕" if sidecar else ""), False
        if mode == "asr_burn":
            if keep_srt:
                target = os.path.splitext(out_path)[0] + ".srt"
            else:
                temp_name = hashlib.md5(f"{src_path}|{time.time()}".encode("utf-8", errors="replace")).hexdigest()
                target = os.path.join(tempfile.gettempdir(), f"auto_subtitle_{temp_name}.srt")
            srt_path, engine = self._write_generated_subtitle(src_path, target)
            return srt_path, engine, (not keep_srt)
        if mode == "align_burn":
            if keep_srt:
                target = os.path.splitext(out_path)[0] + ".srt"
            else:
                temp_name = hashlib.md5(f"{src_path}|{time.time()}|align".encode("utf-8", errors="replace")).hexdigest()
                target = os.path.join(tempfile.gettempdir(), f"aligned_subtitle_{temp_name}.srt")
            try:
                srt_path, engine = self._write_aligned_subtitle(src_path, target)
                return srt_path, engine, (not keep_srt)
            except Exception as e:
                self.log.emit(f"⚠️ 文本对齐失败，改用纯转写：{os.path.basename(src_path)}：{e}", "orange")
                srt_path, engine = self._write_generated_subtitle(src_path, target)
                return srt_path, f"纯转写回退（{str(e)[:60]}）", (not keep_srt)
        return "", "", False

    def _ass_color(self, color, opacity=100):
        color = str(color or "#ffffff")
        if color.startswith("#") and len(color) >= 7:
            r = int(color[1:3], 16)
            g = int(color[3:5], 16)
            b = int(color[5:7], 16)
        else:
            r, g, b = 255, 255, 255
        alpha = int(round(255 * (100 - max(0.0, min(100.0, float(opacity or 0.0)))) / 100.0))
        return f"&H{alpha:02X}{b:02X}{g:02X}{r:02X}"

    def _ass_bgr(self, color):
        color = str(color or "#ffffff")
        if color.startswith("#") and len(color) >= 7:
            r = int(color[1:3], 16)
            g = int(color[3:5], 16)
            b = int(color[5:7], 16)
        else:
            r, g, b = 255, 255, 255
        return f"&H{b:02X}{g:02X}{r:02X}&"

    def _ass_alpha(self, opacity=100):
        alpha = int(round(255 * (100 - max(0.0, min(100.0, float(opacity or 0.0)))) / 100.0))
        return f"&H{alpha:02X}&"

    def _subtitle_style_needs_custom_ass(self, style=None):
        style = normalize_subtitle_style(style or self.config.get("subtitle_style", {}) or {})
        return any([
            bool(style.get("gradient_fill", False)),
            bool(style.get("double_stroke_enabled", False) and float(style.get("secondary_stroke_width", 0.0) or 0.0) > 0.01),
            bool(style.get("glow_enabled", False) and (
                float(style.get("glow_size", 0.0) or 0.0) > 0.01 or
                float(style.get("glow_blur", 0.0) or 0.0) > 0.01
            )),
            bool(style.get("background_box", False)),
            bool(style.get("highlight_bar_enabled", False)),
            abs(float(style.get("offset_x", 0.0) or 0.0)) > 0.01,
            abs(float(style.get("offset_y", 0.0) or 0.0)) > 0.01,
            abs(float(style.get("shadow_x", 0.0) or 0.0)) > 0.01,
            abs(float(style.get("shadow_y", 0.0) or 0.0)) > 0.01,
            float(style.get("shadow_blur", 0.0) or 0.0) > 0.01,
        ])

    def _subtitle_ass_time(self, seconds):
        total = max(0.0, float(seconds or 0.0))
        hours = int(total // 3600)
        total -= hours * 3600
        minutes = int(total // 60)
        total -= minutes * 60
        secs = int(total)
        cs = int(round((total - secs) * 100))
        if cs >= 100:
            secs += 1
            cs = 0
        if secs >= 60:
            minutes += 1
            secs -= 60
        if minutes >= 60:
            hours += 1
            minutes -= 60
        return f"{hours}:{minutes:02d}:{secs:02d}.{cs:02d}"

    def _subtitle_parse_srt_ts(self, value):
        text = str(value or "").strip().replace(",", ".")
        parts = text.split(":")
        if len(parts) != 3:
            raise ValueError(f"无效字幕时间戳: {value}")
        hours = int(parts[0])
        minutes = int(parts[1])
        sec_part = parts[2].split(".")
        seconds = int(sec_part[0])
        millis = int((sec_part[1] if len(sec_part) > 1 else "0").ljust(3, "0")[:3])
        return hours * 3600 + minutes * 60 + seconds + millis / 1000.0

    def _parse_srt_subtitle_events(self, srt_path):
        with open(srt_path, "r", encoding="utf-8-sig", errors="replace") as f:
            raw_text = f.read()
        blocks = re.split(r"\n\s*\n", raw_text.replace("\r\n", "\n").replace("\r", "\n").strip())
        events = []
        for block in blocks:
            lines = [line.rstrip() for line in block.split("\n")]
            lines = [line for line in lines if line.strip()]
            if not lines:
                continue
            if "-->" in lines[0]:
                ts_line = lines[0]
                text_lines = lines[1:]
            elif len(lines) >= 2 and "-->" in lines[1]:
                ts_line = lines[1]
                text_lines = lines[2:]
            else:
                continue
            start_raw, end_raw = [seg.strip() for seg in ts_line.split("-->", 1)]
            try:
                start_sec = self._subtitle_parse_srt_ts(start_raw.split(" ", 1)[0].strip())
                end_sec = self._subtitle_parse_srt_ts(end_raw.split(" ", 1)[0].strip())
            except Exception:
                continue
            text_lines = [html.unescape(re.sub(r"<[^>]+>", "", str(line or ""))).strip() for line in text_lines]
            text_lines = [line for line in text_lines if line]
            if not text_lines:
                continue
            events.append({
                "start": start_sec,
                "end": max(start_sec + 0.05, end_sec),
                "text": "\n".join(text_lines),
            })
        return events

    def _subtitle_escape_ass_text(self, text):
        txt = str(text or "")
        txt = txt.replace("\\", "＼").replace("{", "｛").replace("}", "｝")
        return txt.replace("\r\n", "\n").replace("\r", "\n").replace("\n", r"\N")

    def _build_ass_tag_text(self, tags):
        tags = [str(tag) for tag in tags if str(tag)]
        return "{" + "".join(tags) + "}"

    def _build_ass_round_rect_path(self, x, y, w, h, r):
        x = float(x); y = float(y); w = max(2.0, float(w)); h = max(2.0, float(h))
        r = max(0.0, min(float(r or 0.0), min(w, h) / 2.0))
        if r <= 0.01:
            return f"m {x:.1f} {y:.1f} l {x + w:.1f} {y:.1f} {x + w:.1f} {y + h:.1f} {x:.1f} {y + h:.1f}"
        c = r * 0.55228475
        x0, y0 = x, y
        x1, y1 = x + w, y + h
        return (
            f"m {x0 + r:.1f} {y0:.1f} "
            f"l {x1 - r:.1f} {y0:.1f} "
            f"b {x1 - r + c:.1f} {y0:.1f} {x1:.1f} {y0 + r - c:.1f} {x1:.1f} {y0 + r:.1f} "
            f"l {x1:.1f} {y1 - r:.1f} "
            f"b {x1:.1f} {y1 - r + c:.1f} {x1 - r + c:.1f} {y1:.1f} {x1 - r:.1f} {y1:.1f} "
            f"l {x0 + r:.1f} {y1:.1f} "
            f"b {x0 + r - c:.1f} {y1:.1f} {x0:.1f} {y1 - r + c:.1f} {x0:.1f} {y1 - r:.1f} "
            f"l {x0:.1f} {y0 + r:.1f} "
            f"b {x0:.1f} {y0 + r - c:.1f} {x0 + r - c:.1f} {y0:.1f} {x0 + r:.1f} {y0:.1f}"
        )

    def _convert_subtitle_to_srt(self, subtitle_path):
        ext = os.path.splitext(str(subtitle_path or ""))[1].lower()
        if ext == ".srt":
            return subtitle_path, False
        temp_name = hashlib.md5(f"{subtitle_path}|{time.time()}|srt".encode("utf-8", errors="replace")).hexdigest()
        temp_srt = os.path.join(tempfile.gettempdir(), f"styled_subtitle_src_{temp_name}.srt")
        r = self._run_process(["ffmpeg", "-y", "-hide_banner", "-i", subtitle_path, temp_srt], timeout=120)
        if r.returncode != 0 or not os.path.isfile(temp_srt):
            raise RuntimeError((r.stderr or r.stdout or "字幕转 SRT 失败").strip()[-400:])
        return temp_srt, True

    def _build_styled_ass_subtitle(self, subtitle_path, width, height):
        style = normalize_subtitle_style(self.config.get("subtitle_style", {}) or {})
        srt_path, need_cleanup_srt = self._convert_subtitle_to_srt(subtitle_path)
        cleanup_paths = [srt_path] if need_cleanup_srt else []
        font_name = str(style.get("font_family", "") or "Arial").replace(",", " ").replace("'", "")
        font_px = resolve_text_font_size_px(build_subtitle_style_layer(style), width, minimum=12)
        align = {"bottom": 2, "middle": 5, "top": 8}.get(style.get("position", "bottom"), 2)
        offset_x = int(style.get("offset_x", 0) or 0)
        offset_y = int(style.get("offset_y", 0) or 0)
        center_x = int(width / 2) + offset_x
        scale_y_ratio = max(0.3, float(style.get("scale_y", 100) or 100) / 100.0)
        margin_v = int(style.get("margin_v", 58) or 58)
        margin_h = int(style.get("margin_h", 36) or 36)
        default_line_height = max(font_px, int(round(font_px * scale_y_ratio * 1.18)))

        events = self._parse_srt_subtitle_events(srt_path)
        ass_lines = [
            "[Script Info]",
            "ScriptType: v4.00+",
            "WrapStyle: 2",
            "ScaledBorderAndShadow: yes",
            f"PlayResX: {int(width)}",
            f"PlayResY: {int(height)}",
            "",
            "[V4+ Styles]",
            "Format: Name,Fontname,Fontsize,PrimaryColour,SecondaryColour,OutlineColour,BackColour,Bold,Italic,Underline,StrikeOut,ScaleX,ScaleY,Spacing,Angle,BorderStyle,Outline,Shadow,Alignment,MarginL,MarginR,MarginV,Encoding",
            f"Style: Default,{font_name},{int(font_px)},&H00FFFFFF,&H00FFFFFF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,0,0,{align},{margin_h},{margin_h},{margin_v},1",
            "",
            "[Events]",
            "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text",
        ]

        for ev in events:
            text = self._subtitle_escape_ass_text(ev.get("text", ""))
            if not text:
                continue
            line_count = max(1, text.count(r"\N") + 1)
            block_h = max(default_line_height, int(round(default_line_height * line_count)))
            if style.get("position", "bottom") == "bottom":
                anchor_y = int(height - margin_v + offset_y)
                region_top = max(0, anchor_y - block_h)
            elif style.get("position", "bottom") == "top":
                anchor_y = int(margin_v + font_px * 0.95 + offset_y)
                region_top = max(0, anchor_y - int(font_px * 0.9))
            else:
                anchor_y = int(height / 2 + offset_y)
                region_top = max(0, anchor_y - int(block_h / 2))
            region_h = max(block_h, int(round(font_px * (1.6 + 0.55 * max(0, line_count - 1)))))
            region_bottom = min(height, region_top + region_h)
            start_ts = self._subtitle_ass_time(ev.get("start", 0.0))
            end_ts = self._subtitle_ass_time(ev.get("end", 0.0))

            base_tags = [
                f"\\an{align}",
                f"\\pos({center_x},{anchor_y})",
                "\\q2",
                f"\\fn{font_name}",
                f"\\fs{int(font_px)}",
                f"\\fscx{int(style.get('scale_x', 100) or 100)}",
                f"\\fscy{int(style.get('scale_y', 100) or 100)}",
                f"\\fsp{float(style.get('letter_spacing', 0.0) or 0.0):.1f}",
                f"\\frz{float(style.get('angle', 0.0) or 0.0):.1f}",
                "\\b1" if style.get("bold", False) else "\\b0",
                "\\i1" if style.get("italic", False) else "\\i0",
                "\\u1" if style.get("underline", False) else "\\u0",
                "\\s1" if style.get("strikeout", False) else "\\s0",
            ]

            if style.get("background_box", False):
                pad_x = int(style.get("background_pad_x", 28) or 28)
                pad_y = int(style.get("background_pad_y", 16) or 16)
                box_w = min(max(180, width - margin_h * 2), max(int(width * float(style.get("background_width_ratio", 78.0) or 78.0) / 100.0), int(font_px * 5.2) + pad_x * 2))
                box_h = max(int(font_px * (1.25 + 0.72 * max(0, line_count - 1))) + pad_y * 2, int(font_px * 1.7))
                box_y = max(6, min(height - box_h - 6, int(region_top - pad_y)))
                box_x = int((width - box_w) / 2)
                box_path = self._build_ass_round_rect_path(box_x, box_y, box_w, box_h, int(style.get("background_radius", 18) or 18))
                box_tags = self._build_ass_tag_text([
                    "\\p1\\bord0\\shad0",
                    f"\\1c{self._ass_bgr(style.get('background_color', '#000000'))}",
                    f"\\1a{self._ass_alpha(style.get('background_opacity', 55))}",
                ])
                ass_lines.append(
                    f"Dialogue: 0,{start_ts},{end_ts},Default,,0,0,0,,"
                    f"{box_tags}{box_path}"
                )
            else:
                box_y = region_top

            if style.get("highlight_bar_enabled", False):
                bar_h = max(2, int(style.get("highlight_height", 10) or 10))
                bar_w = min(max(80, width - margin_h * 2), max(int(width * float(style.get("highlight_width_ratio", 36.0) or 36.0) / 100.0), int(font_px * 2.8)))
                bar_x = int((width - bar_w) / 2)
                if style.get("position", "bottom") == "top":
                    bar_y = min(height - bar_h - 4, int(box_y + max(bar_h + 4, font_px * 1.45)))
                else:
                    bar_y = max(4, int(box_y - int(style.get("highlight_gap", 10) or 10) - bar_h))
                bar_path = self._build_ass_round_rect_path(bar_x, bar_y, bar_w, bar_h, int(bar_h / 2))
                bar_tags = self._build_ass_tag_text([
                    "\\p1\\bord0\\shad0",
                    f"\\1c{self._ass_bgr(style.get('highlight_color', '#f59e0b'))}",
                    f"\\1a{self._ass_alpha(style.get('highlight_opacity', 90))}",
                ])
                ass_lines.append(
                    f"Dialogue: 1,{start_ts},{end_ts},Default,,0,0,0,,"
                    f"{bar_tags}{bar_path}"
                )

            shadow_opacity = int(style.get("shadow_opacity", 0) or 0)
            shadow_x = float(style.get("shadow_x", 0.0) or 0.0)
            shadow_y = float(style.get("shadow_y", 0.0) or 0.0)
            shadow_blur = float(style.get("shadow_blur", 0.0) or 0.0)
            if shadow_opacity > 0 and (abs(shadow_x) > 0.01 or abs(shadow_y) > 0.01 or shadow_blur > 0.01):
                shadow_tags = list(base_tags) + [
                    f"\\pos({int(round(center_x + shadow_x))},{int(round(anchor_y + shadow_y))})",
                    "\\bord0",
                    "\\shad0",
                    f"\\blur{shadow_blur:.1f}",
                    f"\\1c{self._ass_bgr(style.get('shadow_color', '#000000'))}",
                    f"\\1a{self._ass_alpha(shadow_opacity)}",
                ]
                ass_lines.append(f"Dialogue: 2,{start_ts},{end_ts},Default,,0,0,0,,{self._build_ass_tag_text(shadow_tags)}{text}")

            if style.get("glow_enabled", False) and (
                float(style.get("glow_size", 0.0) or 0.0) > 0.01 or float(style.get("glow_blur", 0.0) or 0.0) > 0.01
            ):
                glow_tags = list(base_tags) + [
                    f"\\bord{float(style.get('glow_size', 5.0) or 0.0):.1f}",
                    "\\shad0",
                    f"\\blur{float(style.get('glow_blur', 3.0) or 0.0):.1f}",
                    "\\1a&HFF&",
                    f"\\3c{self._ass_bgr(style.get('glow_color', '#67e8f9'))}",
                    f"\\3a{self._ass_alpha(style.get('glow_opacity', 70))}",
                ]
                ass_lines.append(f"Dialogue: 3,{start_ts},{end_ts},Default,,0,0,0,,{self._build_ass_tag_text(glow_tags)}{text}")

            if style.get("double_stroke_enabled", False) and float(style.get("secondary_stroke_width", 0.0) or 0.0) > 0.01:
                outer_tags = list(base_tags) + [
                    f"\\bord{float(style.get('secondary_stroke_width', 6.0) or 0.0):.1f}",
                    "\\shad0",
                    "\\1a&HFF&",
                    f"\\3c{self._ass_bgr(style.get('secondary_stroke_color', '#1f2937'))}",
                    f"\\3a{self._ass_alpha(style.get('secondary_stroke_opacity', 100))}",
                ]
                ass_lines.append(f"Dialogue: 4,{start_ts},{end_ts},Default,,0,0,0,,{self._build_ass_tag_text(outer_tags)}{text}")

            if float(style.get("stroke_width", 0.0) or 0.0) > 0.01:
                stroke_tags = list(base_tags) + [
                    f"\\bord{float(style.get('stroke_width', 3.2) or 0.0):.1f}",
                    "\\shad0",
                    "\\1a&HFF&",
                    f"\\3c{self._ass_bgr(style.get('stroke_color', '#000000'))}",
                    f"\\3a{self._ass_alpha(style.get('stroke_opacity', 100))}",
                ]
                ass_lines.append(f"Dialogue: 5,{start_ts},{end_ts},Default,,0,0,0,,{self._build_ass_tag_text(stroke_tags)}{text}")

            if style.get("gradient_fill", False):
                grad_end = style.get("gradient_color_end", "#67e8f9")
                steps = 6
                base_color = QColor(style.get("color", "#ffffff"))
                end_color = QColor(grad_end)
                for grad_idx in range(steps):
                    t = grad_idx / max(1, steps - 1)
                    c = QColor(
                        int(round(base_color.red() + (end_color.red() - base_color.red()) * t)),
                        int(round(base_color.green() + (end_color.green() - base_color.green()) * t)),
                        int(round(base_color.blue() + (end_color.blue() - base_color.blue()) * t)),
                    )
                    y1 = int(region_top + (region_bottom - region_top) * grad_idx / steps)
                    y2 = int(region_top + (region_bottom - region_top) * (grad_idx + 1) / steps)
                    fill_tags = list(base_tags) + [
                        "\\bord0",
                        "\\shad0",
                        f"\\clip(0,{y1},{width},{max(y1 + 1, y2)})",
                        f"\\1c{self._ass_bgr(c.name())}",
                        f"\\1a{self._ass_alpha(style.get('text_opacity', 100))}",
                    ]
                    ass_lines.append(f"Dialogue: {6 + grad_idx},{start_ts},{end_ts},Default,,0,0,0,,{self._build_ass_tag_text(fill_tags)}{text}")
            else:
                fill_tags = list(base_tags) + [
                    "\\bord0",
                    "\\shad0",
                    f"\\1c{self._ass_bgr(style.get('color', '#ffffff'))}",
                    f"\\1a{self._ass_alpha(style.get('text_opacity', 100))}",
                ]
                ass_lines.append(f"Dialogue: 6,{start_ts},{end_ts},Default,,0,0,0,,{self._build_ass_tag_text(fill_tags)}{text}")

        ass_name = hashlib.md5(f"{subtitle_path}|{width}|{height}|{time.time()}|styled".encode("utf-8", errors="replace")).hexdigest()
        ass_path = os.path.join(tempfile.gettempdir(), f"styled_subtitle_{ass_name}.ass")
        with open(ass_path, "w", encoding="utf-8-sig") as f:
            f.write("\n".join(ass_lines))
        cleanup_paths.append(ass_path)
        return ass_path, cleanup_paths

    def _prepare_subtitle_render_path(self, subtitle_path, width, height):
        style = normalize_subtitle_style(self.config.get("subtitle_style", {}) or {})
        if not subtitle_path or not os.path.isfile(subtitle_path):
            return subtitle_path, []
        if not self._subtitle_style_needs_custom_ass(style):
            return subtitle_path, []
        return self._build_styled_ass_subtitle(subtitle_path, width, height)

    def _build_subtitle_force_style(self, ref_width):
        style = normalize_subtitle_style(self.config.get("subtitle_style", {}) or {})
        font_name = str(style.get("font_family", "") or "").replace("'", "").replace(",", " ")
        font_px = resolve_text_font_size_px(build_subtitle_style_layer(style), ref_width, minimum=12)
        align_map = {"bottom": 2, "middle": 5, "top": 8}
        border_style = 3 if style.get("background_box", False) else 1
        outline_width = max(0.0, float(style.get("stroke_width", 0.0) or 0.0))
        shadow = max(
            0.0,
            float(style.get("shadow", 0.0) or 0.0),
            abs(float(style.get("shadow_x", 0.0) or 0.0)),
            abs(float(style.get("shadow_y", 0.0) or 0.0)),
            float(style.get("shadow_blur", 0.0) or 0.0)
        )
        box_opacity = style.get("background_opacity", 55) if style.get("background_box", False) else 0
        values = [
            f"FontSize={font_px}",
            f"PrimaryColour={self._ass_color(style.get('color', '#ffffff'), style.get('text_opacity', 100))}",
            f"OutlineColour={self._ass_color(style.get('stroke_color', '#000000'), style.get('stroke_opacity', 100))}",
            f"BackColour={self._ass_color(style.get('background_color', '#000000'), box_opacity)}",
            f"Bold={-1 if style.get('bold', False) else 0}",
            f"Italic={-1 if style.get('italic', False) else 0}",
            f"Underline={-1 if style.get('underline', False) else 0}",
            f"StrikeOut={-1 if style.get('strikeout', False) else 0}",
            f"BorderStyle={border_style}",
            f"Outline={outline_width:.1f}",
            f"Shadow={shadow:.1f}",
            f"Spacing={float(style.get('letter_spacing', 0.0) or 0.0):.1f}",
            f"ScaleX={int(style.get('scale_x', 100) or 100)}",
            f"ScaleY={int(style.get('scale_y', 100) or 100)}",
            f"Angle={float(style.get('angle', 0.0) or 0.0):.1f}",
            f"Alignment={align_map.get(style.get('position', 'bottom'), 2)}",
            f"MarginV={int(style.get('margin_v', 58) or 58)}",
            f"MarginL={int(style.get('margin_h', 36) or 36)}",
            f"MarginR={int(style.get('margin_h', 36) or 36)}",
        ]
        if font_name:
            values.insert(0, f"FontName={font_name}")
        return ",".join(values).replace(":", r"\:")

    def _build_video_filter(self, aspect_mode, width, height, subtitle_path=""):
        base_filter = ""
        if aspect_mode == "crop916":
            base_filter = f"[0:v]scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},format=yuv420p[vpre]"
        elif aspect_mode == "pad916_black":
            base_filter = f"[0:v]scale={width}:{height}:force_original_aspect_ratio=decrease,pad={width}:{height}:(ow-iw)/2:(oh-ih)/2:black,format=yuv420p[vpre]"
        elif aspect_mode == "pad916_blur":
            base_filter = (
                f"[0:v]scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},boxblur=20:10[bg];"
                f"[0:v]scale={width}:{height}:force_original_aspect_ratio=decrease[fg];"
                f"[bg][fg]overlay=(W-w)/2:(H-h)/2,format=yuv420p[vpre]"
            )
        if subtitle_path:
            escaped = self._escape_subtitle_path_for_filter(subtitle_path)
            if os.path.splitext(subtitle_path)[1].lower() == ".ass":
                subtitle_filter = f"subtitles='{escaped}':charenc=UTF-8"
            else:
                force_style = self._build_subtitle_force_style(width)
                subtitle_filter = f"subtitles='{escaped}':charenc=UTF-8:force_style='{force_style}'"
            if base_filter:
                return base_filter + ";" + f"[vpre]{subtitle_filter},format=yuv420p[vout]"
            return f"[0:v]{subtitle_filter},format=yuv420p[vout]"
        if base_filter:
            return base_filter.replace("[vpre]", "[vout]")
        return ""

    def _build_encode_args(self):
        preset = str(self.config.get("preset", "veryfast") or "veryfast").strip()
        crf = int(self.config.get("crf", 23) or 23)
        args = ["-c:v", "libx264", "-preset", preset, "-crf", str(crf)]
        if str(self.config.get("output_ext", ".mp4")).lower() == ".mp4":
            args.extend(["-movflags", "+faststart"])
        return args

    def _build_audio_filter(self, has_audio, bgm_mode, normalize_audio, origin_volume, bgm_volume):
        filters = []
        has_output = False
        if bgm_mode == "mix":
            if has_audio:
                filters.append(f"[0:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo,volume={origin_volume:.4f}[amain]")
                filters.append(f"[1:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo,volume={bgm_volume:.4f}[abgm]")
                chain = "[amain][abgm]amix=inputs=2:duration=first:dropout_transition=2"
                if normalize_audio:
                    chain += ",loudnorm=I=-16:TP=-1.5:LRA=11"
                filters.append(chain + "[aout]")
                has_output = True
            else:
                chain = f"[1:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo,volume={bgm_volume:.4f}"
                if normalize_audio:
                    chain += ",loudnorm=I=-16:TP=-1.5:LRA=11"
                filters.append(chain + "[aout]")
                has_output = True
        elif bgm_mode == "replace":
            chain = f"[1:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo,volume={bgm_volume:.4f}"
            if normalize_audio:
                chain += ",loudnorm=I=-16:TP=-1.5:LRA=11"
            filters.append(chain + "[aout]")
            has_output = True
        elif has_audio:
            chain = f"[0:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo,volume={origin_volume:.4f}"
            if normalize_audio:
                chain += ",loudnorm=I=-16:TP=-1.5:LRA=11"
            filters.append(chain + "[aout]")
            has_output = True
        return filters, has_output

    def run(self):
        try:
            if not self.video_paths:
                self.log.emit("⚠️ 没有可处理的视频", "orange")
                return
            os.makedirs(self.out_dir, exist_ok=True)
            self._run_process(["ffmpeg", "-version"], timeout=30).check_returncode()
            self._run_process(["ffprobe", "-version"], timeout=30).check_returncode()

            total = len(self.video_paths)
            aspect_mode = str(self.config.get("aspect_mode", "none") or "none")
            width = int(self.config.get("target_width", 1080) or 1080)
            height = int(self.config.get("target_height", 1920) or 1920)
            bgm_mode = str(self.config.get("bgm_mode", "none") or "none")
            bgm_paths = [p for p in self.config.get("bgm_paths", []) if os.path.isfile(p)]
            normalize_audio = bool(self.config.get("normalize_audio", True))
            output_ext = str(self.config.get("output_ext", ".mp4") or ".mp4").strip()
            output_ext = output_ext if output_ext.startswith(".") else f".{output_ext}"
            origin_volume = max(0.0, float(self.config.get("origin_volume", 100.0) or 100.0) / 100.0)
            bgm_volume = max(0.0, float(self.config.get("bgm_volume", 25.0) or 25.0) / 100.0)
            subtitle_mode = str(self.config.get("subtitle_mode", "none") or "none")
            subtitle_style = normalize_subtitle_style(self.config.get("subtitle_style", {}) or {})

            for idx, src in enumerate(self.video_paths, 1):
                if not os.path.isfile(src):
                    self.progress.emit(int(idx / total * 100))
                    continue
                stem = clean_long_filename(os.path.splitext(os.path.basename(src))[0], 120) or f"video_{idx:03d}"
                out_path = os.path.join(self.out_dir, f"{stem}_processed{output_ext}")
                has_audio = self._ffprobe_has_audio(src)
                bgm_path = ""
                if bgm_mode != "none" and bgm_paths:
                    bgm_path = bgm_paths[(idx - 1) % len(bgm_paths)]
                subtitle_path = ""
                subtitle_render_path = ""
                subtitle_label = ""
                delete_subtitle_after_use = False
                subtitle_temp_cleanup = []
                if subtitle_mode != "none":
                    try:
                        subtitle_path, subtitle_label, delete_subtitle_after_use = self._resolve_subtitle_for_video(src, out_path)
                        if subtitle_mode == "sidecar_burn" and not subtitle_path:
                            self.log.emit(f"⚠️ 未找到同名字幕，已按无字幕继续：{os.path.basename(src)}", "orange")
                    except Exception as e:
                        self.log.emit(f"⚠️ 字幕处理失败，已按无字幕继续：{os.path.basename(src)}：{e}", "orange")
                        subtitle_path = ""
                        subtitle_render_path = ""
                        subtitle_label = ""
                        delete_subtitle_after_use = False
                        subtitle_temp_cleanup = []

                if subtitle_path:
                    try:
                        subtitle_render_path, subtitle_temp_cleanup = self._prepare_subtitle_render_path(subtitle_path, width, height)
                    except Exception as e:
                        self.log.emit(f"⚠️ 高级字幕样式生成失败，回退普通烧录：{os.path.basename(src)}：{e}", "orange")
                        subtitle_render_path = subtitle_path
                        subtitle_temp_cleanup = []

                cmd = ["ffmpeg", "-y", "-hide_banner", "-i", src]
                if bgm_path:
                    cmd.extend(["-stream_loop", "-1", "-i", bgm_path])

                filter_parts = []
                video_filter = self._build_video_filter(aspect_mode, width, height, subtitle_path=subtitle_render_path)
                video_reencode = bool(video_filter)
                if video_filter:
                    filter_parts.append(video_filter)

                audio_filters, has_audio_output = self._build_audio_filter(
                    has_audio=has_audio,
                    bgm_mode=bgm_mode if bgm_path or bgm_mode == "none" else "none",
                    normalize_audio=normalize_audio,
                    origin_volume=origin_volume,
                    bgm_volume=bgm_volume
                )
                filter_parts.extend(audio_filters)

                if filter_parts:
                    cmd.extend(["-filter_complex", ";".join(filter_parts)])

                if video_reencode:
                    cmd.extend(["-map", "[vout]"])
                    cmd.extend(self._build_encode_args())
                else:
                    cmd.extend(["-map", "0:v:0", "-c:v", "copy"])

                if has_audio_output:
                    cmd.extend(["-map", "[aout]", "-c:a", "aac", "-b:a", "192k"])
                else:
                    if has_audio and bgm_mode == "none":
                        cmd.extend(["-map", "0:a?", "-c:a", "copy"])
                    else:
                        cmd.extend(["-an"])

                if bgm_path:
                    cmd.append("-shortest")
                cmd.append(out_path)

                msg = f"🎬 处理视频：{os.path.basename(src)}"
                if aspect_mode != "none":
                    msg += f" | 画幅={aspect_mode}"
                if bgm_mode != "none" and bgm_path:
                    msg += f" | BGM={os.path.basename(bgm_path)}"
                if subtitle_path:
                    msg += f" | 字幕={subtitle_label or os.path.basename(subtitle_path)}"
                    msg += f" | 样式={subtitle_style.get('font_family') or '系统字体'}"
                if normalize_audio:
                    msg += " | 响度标准化"
                if subtitle_render_path and subtitle_render_path != subtitle_path:
                    msg += " | 高级字效"
                self.log.emit(msg, "blue")

                r = self._run_process(cmd, timeout=int(self.config.get("timeout", 7200) or 7200))
                if r.returncode == 0 and os.path.exists(out_path):
                    self.log.emit(f"✅ 处理完成：{out_path}", "green")
                    if subtitle_path and (not delete_subtitle_after_use) and os.path.isfile(subtitle_path) and os.path.splitext(out_path)[0] + ".srt" == subtitle_path:
                        self.log.emit(f"📝 已保留字幕文件：{subtitle_path}", "gray")
                else:
                    err = (r.stderr or r.stdout or "未知错误").strip()
                    self.log.emit(f"❌ 处理失败：{os.path.basename(src)}：{err[-500:]}", "red")
                if delete_subtitle_after_use:
                    try:
                        if subtitle_path and os.path.isfile(subtitle_path):
                            os.remove(subtitle_path)
                    except Exception:
                        pass
                for temp_path in subtitle_temp_cleanup:
                    try:
                        if temp_path and os.path.isfile(temp_path):
                            os.remove(temp_path)
                    except Exception:
                        pass
                self.progress.emit(int(idx / total * 100))
        except Exception as e:
            err_msg = traceback.format_exc()
            self.log.emit(f"❌ VideoFormatAudioBatchThread 发生严重错误: {e}\n{err_msg}", "red")
        finally:
            self.finished_all.emit()


class VideoSubtitleOnlyBatchThread(QThread):
    progress = pyqtSignal(int)
    log = pyqtSignal(str, str)
    result = pyqtSignal(list)
    error = pyqtSignal(str)
    finished_all = pyqtSignal()

    def __init__(self, video_paths, config=None):
        super().__init__()
        self.video_paths = list(video_paths or [])
        self.config = dict(config or {})

    def run(self):
        try:
            if not self.video_paths:
                self.error.emit("没有可用于生成字幕的视频")
                return
            worker = VideoFormatAudioBatchThread(self.video_paths, "", dict(self.config))
            results = []
            total = len(self.video_paths)
            for idx, src in enumerate(self.video_paths, 1):
                if not os.path.isfile(src):
                    self.progress.emit(int(idx / max(1, total) * 100))
                    continue
                target = os.path.splitext(src)[0] + ".mp4"
                try:
                    srt_path, label, delete_after = worker._resolve_subtitle_for_video(src, target)
                    status = "纯转写回退" if str(label or "").startswith("纯转写回退") else "文本对齐"
                    if srt_path and os.path.isfile(srt_path):
                        self.log.emit(f"📝 已生成字幕：{os.path.basename(src)} -> {os.path.basename(srt_path)} | 状态={label or status}", "green")
                        results.append({
                            "src_label": label or status,
                            "rename_name": os.path.splitext(os.path.basename(src))[0],
                            "res": src,
                            "score": status,
                            "srt_path": srt_path,
                            "tooltip": f"状态：{label or status}\n源文件：{src}\n字幕：{srt_path}",
                        })
                    else:
                        self.log.emit(f"⚠️ 未生成字幕：{os.path.basename(src)}", "orange")
                    if delete_after and srt_path and os.path.isfile(srt_path):
                        os.remove(srt_path)
                except Exception as e:
                    self.log.emit(f"❌ 字幕生成失败：{os.path.basename(src)}：{e}", "red")
                self.progress.emit(int(idx / max(1, total) * 100))
            self.result.emit(results)
        except Exception as e:
            self.error.emit(f"只生成字幕线程异常：{e}\n{traceback.format_exc()}")
        finally:
            self.finished_all.emit()


class VideoTrimBatchThread(QThread):
    progress = pyqtSignal(int)
    log = pyqtSignal(str, str)
    finished_all = pyqtSignal()
    VIDEO_EXTS = VideoConcatBatchThread.VIDEO_EXTS

    def __init__(self, tasks, out_dir, config=None):
        super().__init__()
        self.tasks = tasks or []
        self.out_dir = out_dir
        self.config = config if isinstance(config, dict) else {}

    def _run_process(self, cmd, timeout=None):
        return subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout, **_subprocess_no_window_kwargs())

    def _build_encode_args(self):
        preset = str(self.config.get("preset", "veryfast") or "veryfast").strip()
        crf = int(self.config.get("crf", 23) or 23)
        args = ["-c:v", "libx264", "-preset", preset, "-crf", str(crf), "-c:a", "aac", "-b:a", "192k"]
        if str(self.config.get("output_ext", ".mp4")).lower() == ".mp4":
            args.extend(["-movflags", "+faststart"])
        return args

    def run(self):
        try:
            if not self.tasks:
                self.log.emit("⚠️ 没有可执行的裁剪任务", "orange")
                return
            os.makedirs(self.out_dir, exist_ok=True)
            self._run_process(["ffmpeg", "-version"], timeout=30).check_returncode()
            total = len(self.tasks)
            output_ext = str(self.config.get("output_ext", ".mp4") or ".mp4").strip()
            output_ext = output_ext if output_ext.startswith(".") else f".{output_ext}"
            reencode = bool(self.config.get("reencode", True))
            for idx, task in enumerate(self.tasks, 1):
                src = task.get("src", "")
                start = max(0.0, float(task.get("start", 0.0) or 0.0))
                end = max(start, float(task.get("end", start) or start))
                if not os.path.isfile(src):
                    self.log.emit(f"⚠️ 找不到视频，已跳过：{src}", "orange")
                    self.progress.emit(int(idx / total * 100))
                    continue
                if end - start <= 0.02:
                    self.log.emit(f"⚠️ 裁剪区间无效，已跳过：{os.path.basename(src)}", "orange")
                    self.progress.emit(int(idx / total * 100))
                    continue
                stem = clean_long_filename(task.get("output_name") or os.path.splitext(os.path.basename(src))[0], 120) or f"trim_{idx:03d}"
                out_path = os.path.join(self.out_dir, f"{stem}{output_ext}")
                cmd = ["ffmpeg", "-y", "-hide_banner", "-ss", f"{start:.3f}", "-to", f"{end:.3f}", "-i", src]
                if reencode:
                    cmd.extend(self._build_encode_args())
                else:
                    cmd.extend(["-c", "copy"])
                cmd.append(out_path)
                self.log.emit(f"✂️ 开始裁剪：{os.path.basename(src)} [{start:.3f}s ~ {end:.3f}s]", "blue")
                r = self._run_process(cmd, timeout=int(self.config.get("timeout", 7200) or 7200))
                if r.returncode == 0 and os.path.exists(out_path):
                    self.log.emit(f"✅ 裁剪完成：{out_path}", "green")
                else:
                    err = (r.stderr or r.stdout or "未知错误").strip()
                    self.log.emit(f"❌ 裁剪失败：{os.path.basename(src)}：{err[-500:]}", "red")
                self.progress.emit(int(idx / total * 100))
        except Exception as e:
            err_msg = traceback.format_exc()
            self.log.emit(f"❌ VideoTrimBatchThread 发生严重错误: {e}\n{err_msg}", "red")
        finally:
            self.finished_all.emit()


class VideoConcatTab(QWidget):
    GLOBAL_VIDEO_CONCAT_SYNC_SIGNAL = pyqtSignal()
    vlc_install_finished = pyqtSignal(bool, str)
    VIDEO_EXTS = VideoConcatBatchThread.VIDEO_EXTS
    AUDIO_EXTS = VideoFormatAudioBatchThread.AUDIO_EXTS

    def __init__(self, parent=None):
        super().__init__(parent)
        self.concat_thread = None
        self.scene_thread = None
        self.speed_thread = None
        self.format_thread = None
        self.format_srt_thread = None
        self.trim_thread = None
        self.trim_preview_cache = {}
        self.trim_player = None
        self.trim_vlc_instance = None
        self.trim_vlc_media = None
        self.trim_player_backend = "none"
        self._vlc_install_attempted = False
        self.trim_is_playing = False
        self.trim_play_output_path = ""
        self.trim_pending_output_path = ""
        self.trim_pending_output_paths = []
        self.trim_seek_dragging = False
        self.trim_pending_seek_seconds = 0.0
        self.trim_last_timeline_update_ts = 0.0
        self.trim_last_position_ui_sync_ts = 0.0
        self.concat_auto_rule_config = self._default_concat_auto_rule_config()
        self.concat_auto_rule_presets = {}
        self.concat_auto_rule_active_preset = "严格成片"
        self._loading_subtitle_style = False
        self.subtitle_custom_presets = {}
        self.trim_play_timer = QTimer(self)
        self.trim_play_timer.setInterval(250)
        self.trim_play_timer.timeout.connect(self._on_trim_play_tick)
        self.trim_seek_apply_timer = QTimer(self)
        self.trim_seek_apply_timer.setSingleShot(True)
        self.trim_seek_apply_timer.setInterval(80)
        self.trim_seek_apply_timer.timeout.connect(self._apply_pending_trim_seek)
        self.trim_preview_refresh_timer = QTimer(self)
        self.trim_preview_refresh_timer.setSingleShot(True)
        self.trim_preview_refresh_timer.setInterval(120)
        self.trim_preview_refresh_timer.timeout.connect(lambda: self.refresh_trim_previews(refresh_current_only=True))
        self.vlc_install_finished.connect(self._on_vlc_install_finished)
        self.setup_ui()
        QTimer.singleShot(0, self._start_background_vlc_check)

    def _set_subtitle_color_button(self, btn, color):
        btn.setStyleSheet(f"background: {color}; border: 1px solid #94a3b8; border-radius: 4px;")

    def _default_concat_auto_rule_config(self):
        return {
            "filename_mode": "numeric_only",
            "custom_regex": "",
            "require_same_name_txt": True,
            "require_nonempty_txt": False,
            "sequence_rule": "from_1",
            "sequence_gap_action": "skip_group",
            "duplicate_rule": "keep_all",
            "include_keywords": "",
            "exclude_keywords": "",
            "ignore_hidden_temp": True,
            "sort_mode": "number",
        }

    def _concat_builtin_rule_presets(self):
        return {
            "严格成片": self._normalize_concat_auto_rule_config({
                "filename_mode": "numeric_only",
                "require_same_name_txt": True,
                "require_nonempty_txt": False,
                "sequence_rule": "from_1",
                "sequence_gap_action": "skip_group",
                "duplicate_rule": "keep_all",
                "sort_mode": "number",
            }),
            "数字开头+TXT": self._normalize_concat_auto_rule_config({
                "filename_mode": "starts_with_number",
                "require_same_name_txt": True,
                "sequence_rule": "consecutive",
                "sequence_gap_action": "skip_group",
                "duplicate_rule": "keep_all",
                "sort_mode": "number",
            }),
            "宽松整理": self._normalize_concat_auto_rule_config({
                "filename_mode": "numeric_only",
                "require_same_name_txt": False,
                "sequence_rule": "any",
                "sequence_gap_action": "keep_existing",
                "duplicate_rule": "keep_all",
                "sort_mode": "number",
            }),
            "去重优先": self._normalize_concat_auto_rule_config({
                "filename_mode": "numeric_only",
                "require_same_name_txt": True,
                "sequence_rule": "from_1",
                "sequence_gap_action": "skip_group",
                "duplicate_rule": "keep_first",
                "sort_mode": "number",
            }),
        }

    def _normalize_concat_auto_rule_config(self, cfg=None):
        base = dict(self._default_concat_auto_rule_config())
        if isinstance(cfg, dict):
            base.update(cfg)
        base["filename_mode"] = str(base.get("filename_mode", "numeric_only") or "numeric_only").strip() or "numeric_only"
        base["custom_regex"] = str(base.get("custom_regex", "") or "").strip()
        base["require_same_name_txt"] = bool(base.get("require_same_name_txt", True))
        base["require_nonempty_txt"] = bool(base.get("require_nonempty_txt", False))
        base["sequence_rule"] = str(base.get("sequence_rule", "from_1") or "from_1").strip() or "from_1"
        base["sequence_gap_action"] = str(base.get("sequence_gap_action", "skip_group") or "skip_group").strip() or "skip_group"
        base["duplicate_rule"] = str(base.get("duplicate_rule", "keep_all") or "keep_all").strip() or "keep_all"
        base["include_keywords"] = str(base.get("include_keywords", "") or "").strip()
        base["exclude_keywords"] = str(base.get("exclude_keywords", "") or "").strip()
        base["ignore_hidden_temp"] = bool(base.get("ignore_hidden_temp", True))
        base["sort_mode"] = str(base.get("sort_mode", "number") or "number").strip() or "number"
        return base

    def _normalize_concat_auto_rule_presets(self, presets=None):
        normalized = {}
        if not isinstance(presets, dict):
            return normalized
        for name, cfg in presets.items():
            preset_name = str(name or "").strip()
            if not preset_name:
                continue
            normalized[preset_name] = self._normalize_concat_auto_rule_config(cfg)
        return normalized

    def _all_concat_rule_presets(self):
        presets = dict(self._concat_builtin_rule_presets())
        presets.update(self._normalize_concat_auto_rule_presets(getattr(self, "concat_auto_rule_presets", {})))
        return presets

    def _split_concat_rule_keywords(self, raw_text):
        return [kw.strip().lower() for kw in re.split(r"[\n,，;；|]+", str(raw_text or "")) if kw.strip()]

    def _get_concat_rule_summary(self):
        cfg = self._normalize_concat_auto_rule_config(getattr(self, "concat_auto_rule_config", {}))
        active_preset = str(getattr(self, "concat_auto_rule_active_preset", "") or "").strip()
        filename_map = {
            "any": "文件名不限",
            "numeric_only": "仅纯数字文件名",
            "starts_with_number": "仅数字开头文件名",
            "regex": f"自定义正则：{cfg.get('custom_regex') or '未填写'}",
        }
        seq_map = {
            "any": "序号不限",
            "consecutive": "序号必须连续",
            "from_1": "必须从 1 开始连续",
        }
        gap_map = {
            "skip_group": "缺号整组跳过",
            "keep_existing": "缺号保留现有项",
            "keep_prefix": "缺号只保留前面连续段",
        }
        dup_map = {
            "keep_all": "重复素材全部保留",
            "keep_first": "重复素材只保留首个",
            "skip_group": "发现重复整组跳过",
        }
        parts = []
        if active_preset:
            parts.append(f"预设：{active_preset}")
        parts.append(filename_map.get(cfg.get("filename_mode"), "文件名不限"))
        parts.append("必须有同名TXT" if cfg.get("require_same_name_txt") else "TXT可选")
        if cfg.get("require_nonempty_txt"):
            parts.append("TXT不能为空")
        parts.append(seq_map.get(cfg.get("sequence_rule"), "序号不限"))
        if cfg.get("sequence_rule") != "any":
            parts.append(gap_map.get(cfg.get("sequence_gap_action"), "缺号整组跳过"))
        parts.append(dup_map.get(cfg.get("duplicate_rule"), "重复素材全部保留"))
        include_keywords = self._split_concat_rule_keywords(cfg.get("include_keywords", ""))
        exclude_keywords = self._split_concat_rule_keywords(cfg.get("exclude_keywords", ""))
        if include_keywords:
            parts.append(f"包含关键词：{' / '.join(include_keywords[:3])}" + (" ..." if len(include_keywords) > 3 else ""))
        if exclude_keywords:
            parts.append(f"排除关键词：{' / '.join(exclude_keywords[:3])}" + (" ..." if len(exclude_keywords) > 3 else ""))
        if cfg.get("ignore_hidden_temp"):
            parts.append("忽略隐藏/临时文件")
        return "当前智能组合规则：" + "；".join(parts)

    def _refresh_concat_rule_summary_label(self):
        if hasattr(self, "concat_rule_summary_label"):
            self.concat_rule_summary_label.setText(self._get_concat_rule_summary())

    def _subtitle_offset_slider_to_value(self, slider_value):
        try:
            slider_value = float(slider_value or 0)
        except Exception:
            slider_value = 0.0
        sign = -1 if slider_value < 0 else 1
        ratio = min(1.0, abs(slider_value) / 1000.0)
        return int(round(sign * (ratio ** 2) * 2000))

    def _subtitle_offset_value_to_slider(self, value):
        try:
            value = float(value or 0)
        except Exception:
            value = 0.0
        sign = -1 if value < 0 else 1
        ratio = min(1.0, (abs(value) / 2000.0) ** 0.5 if abs(value) > 0 else 0.0)
        return int(round(sign * ratio * 1000))

    def _sync_subtitle_offset_from_slider(self, spin, slider, value):
        value = self._subtitle_offset_slider_to_value(value)
        spin.blockSignals(True)
        spin.setValue(value)
        spin.blockSignals(False)
        slider_target = self._subtitle_offset_value_to_slider(value)
        if slider.value() != slider_target:
            slider.blockSignals(True)
            slider.setValue(slider_target)
            slider.blockSignals(False)
        self.on_subtitle_style_changed()

    def _sync_subtitle_offset_from_spin(self, spin, slider, value):
        value = int(value or 0)
        slider_target = self._subtitle_offset_value_to_slider(value)
        slider.blockSignals(True)
        slider.setValue(slider_target)
        slider.blockSignals(False)
        if spin.value() != value:
            spin.blockSignals(True)
            spin.setValue(value)
            spin.blockSignals(False)
        self.on_subtitle_style_changed()

    def _reset_subtitle_style_fields(self, *keys):
        if not keys:
            return
        style = self._collect_subtitle_style_from_controls()
        defaults = normalize_subtitle_style()
        changed = False
        for key in keys:
            if key in defaults:
                style[key] = defaults[key]
                changed = True
        if not changed:
            return
        self._apply_subtitle_style_to_controls(style, preferred_data="__manual__")
        self.GLOBAL_VIDEO_CONCAT_SYNC_SIGNAL.emit()

    def _subtitle_builtin_presets(self):
        return get_builtin_subtitle_style_presets()

    def _all_subtitle_presets(self):
        presets = dict(self._subtitle_builtin_presets())
        for name, cfg in (self.subtitle_custom_presets or {}).items():
            presets[name] = normalize_subtitle_style(cfg)
        return presets

    def _subtitle_selected_preset_name(self):
        data = self.subtitle_preset_combo.currentData() if hasattr(self, "subtitle_preset_combo") else "__manual__"
        if not data or data == "__manual__" or ":" not in str(data):
            return ""
        return str(data).split(":", 1)[1]

    def _refresh_subtitle_preset_combo(self, selected_data=None):
        if not hasattr(self, "subtitle_preset_combo"):
            return
        if selected_data is None:
            selected_data = self.subtitle_preset_combo.currentData()
        self.subtitle_preset_combo.blockSignals(True)
        self.subtitle_preset_combo.clear()
        self.subtitle_preset_combo.addItem("当前样式（手动）", "__manual__")
        for name in self._subtitle_builtin_presets().keys():
            self.subtitle_preset_combo.addItem(f"内置 · {name}", f"builtin:{name}")
        for name in sorted(self.subtitle_custom_presets.keys()):
            self.subtitle_preset_combo.addItem(f"自定义 · {name}", f"custom:{name}")
        idx = self.subtitle_preset_combo.findData(selected_data)
        self.subtitle_preset_combo.setCurrentIndex(idx if idx >= 0 else 0)
        self.subtitle_preset_combo.blockSignals(False)

    def _update_subtitle_font_size_controls(self):
        is_fixed = (self.subtitle_size_mode_combo.currentData() != "percent_width")
        self.subtitle_size_label.setVisible(is_fixed)
        self.subtitle_font_size_spin.setVisible(is_fixed)
        self.subtitle_ratio_label.setVisible(not is_fixed)
        self.subtitle_font_ratio_spin.setVisible(not is_fixed)
        self.subtitle_size_hint.setText("固定像素字号" if is_fixed else "按输出宽度百分比")
        has_box = self.subtitle_box_check.isChecked() if hasattr(self, "subtitle_box_check") else False
        has_gradient = self.subtitle_gradient_check.isChecked() if hasattr(self, "subtitle_gradient_check") else False
        has_double_stroke = self.subtitle_double_stroke_check.isChecked() if hasattr(self, "subtitle_double_stroke_check") else False
        has_glow = self.subtitle_glow_check.isChecked() if hasattr(self, "subtitle_glow_check") else False
        has_highlight = self.subtitle_highlight_check.isChecked() if hasattr(self, "subtitle_highlight_check") else False
        if hasattr(self, "subtitle_bg_color_btn"):
            self.subtitle_bg_color_btn.setEnabled(has_box)
        if hasattr(self, "subtitle_bg_opacity_spin"):
            self.subtitle_bg_opacity_spin.setEnabled(has_box)
        if hasattr(self, "subtitle_bg_radius_spin"):
            self.subtitle_bg_radius_spin.setEnabled(has_box)
        if hasattr(self, "subtitle_bg_width_ratio_spin"):
            self.subtitle_bg_width_ratio_spin.setEnabled(has_box)
        if hasattr(self, "subtitle_bg_pad_x_spin"):
            self.subtitle_bg_pad_x_spin.setEnabled(has_box)
        if hasattr(self, "subtitle_bg_pad_y_spin"):
            self.subtitle_bg_pad_y_spin.setEnabled(has_box)
        if hasattr(self, "subtitle_gradient_end_btn"):
            self.subtitle_gradient_end_btn.setEnabled(has_gradient)
        if hasattr(self, "subtitle_outer_stroke_color_btn"):
            self.subtitle_outer_stroke_color_btn.setEnabled(has_double_stroke)
        if hasattr(self, "subtitle_outer_stroke_width_spin"):
            self.subtitle_outer_stroke_width_spin.setEnabled(has_double_stroke)
        if hasattr(self, "subtitle_glow_color_btn"):
            self.subtitle_glow_color_btn.setEnabled(has_glow)
        if hasattr(self, "subtitle_glow_size_spin"):
            self.subtitle_glow_size_spin.setEnabled(has_glow)
        if hasattr(self, "subtitle_glow_blur_spin"):
            self.subtitle_glow_blur_spin.setEnabled(has_glow)
        if hasattr(self, "subtitle_shadow_color_btn"):
            self.subtitle_shadow_color_btn.setEnabled(True)
        if hasattr(self, "subtitle_highlight_color_btn"):
            self.subtitle_highlight_color_btn.setEnabled(has_highlight)
        if hasattr(self, "subtitle_highlight_height_spin"):
            self.subtitle_highlight_height_spin.setEnabled(has_highlight)
        if hasattr(self, "subtitle_highlight_width_ratio_spin"):
            self.subtitle_highlight_width_ratio_spin.setEnabled(has_highlight)
        if hasattr(self, "subtitle_highlight_gap_spin"):
            self.subtitle_highlight_gap_spin.setEnabled(has_highlight)

    def _collect_subtitle_style_from_controls(self):
        return normalize_subtitle_style({
            "font_family": self.subtitle_font_combo.currentFont().family(),
            "font_size": self.subtitle_font_size_spin.value(),
            "font_size_mode": self.subtitle_size_mode_combo.currentData() or "percent_width",
            "font_size_ratio": self.subtitle_font_ratio_spin.value(),
            "color": getattr(self, "subtitle_color", "#ffffff"),
            "gradient_fill": self.subtitle_gradient_check.isChecked(),
            "gradient_color_end": getattr(self, "subtitle_gradient_end_color", "#67e8f9"),
            "text_opacity": self.subtitle_text_opacity_spin.value(),
            "stroke_color": getattr(self, "subtitle_stroke_color", "#000000"),
            "stroke_opacity": self.subtitle_stroke_opacity_spin.value(),
            "stroke_width": self.subtitle_stroke_width_spin.value(),
            "double_stroke_enabled": self.subtitle_double_stroke_check.isChecked(),
            "secondary_stroke_color": getattr(self, "subtitle_outer_stroke_color", "#1f2937"),
            "secondary_stroke_opacity": self.subtitle_outer_stroke_opacity_spin.value(),
            "secondary_stroke_width": self.subtitle_outer_stroke_width_spin.value(),
            "glow_enabled": self.subtitle_glow_check.isChecked(),
            "glow_color": getattr(self, "subtitle_glow_color", "#67e8f9"),
            "glow_opacity": self.subtitle_glow_opacity_spin.value(),
            "glow_size": self.subtitle_glow_size_spin.value(),
            "glow_blur": self.subtitle_glow_blur_spin.value(),
            "shadow": self.subtitle_shadow_spin.value(),
            "shadow_color": getattr(self, "subtitle_shadow_color", "#000000"),
            "shadow_opacity": self.subtitle_shadow_opacity_spin.value(),
            "shadow_x": self.subtitle_shadow_x_spin.value(),
            "shadow_y": self.subtitle_shadow_y_spin.value(),
            "shadow_blur": self.subtitle_shadow_blur_spin.value(),
            "bold": self.subtitle_bold_check.isChecked(),
            "italic": self.subtitle_italic_check.isChecked(),
            "underline": self.subtitle_underline_check.isChecked(),
            "strikeout": self.subtitle_strikeout_check.isChecked(),
            "letter_spacing": self.subtitle_letter_spacing_spin.value(),
            "scale_x": self.subtitle_scale_x_spin.value(),
            "scale_y": self.subtitle_scale_y_spin.value(),
            "angle": self.subtitle_angle_spin.value(),
            "position": self.subtitle_position_combo.currentData() or "bottom",
            "margin_v": self.subtitle_margin_v_spin.value(),
            "margin_h": self.subtitle_margin_h_spin.value(),
            "offset_x": self.subtitle_offset_x_spin.value(),
            "offset_y": self.subtitle_offset_y_spin.value(),
            "background_box": self.subtitle_box_check.isChecked(),
            "background_color": getattr(self, "subtitle_bg_color", "#000000"),
            "background_opacity": self.subtitle_bg_opacity_spin.value(),
            "background_radius": self.subtitle_bg_radius_spin.value(),
            "background_width_ratio": self.subtitle_bg_width_ratio_spin.value(),
            "background_pad_x": self.subtitle_bg_pad_x_spin.value(),
            "background_pad_y": self.subtitle_bg_pad_y_spin.value(),
            "highlight_bar_enabled": self.subtitle_highlight_check.isChecked(),
            "highlight_color": getattr(self, "subtitle_highlight_color", "#f59e0b"),
            "highlight_opacity": self.subtitle_highlight_opacity_spin.value(),
            "highlight_height": self.subtitle_highlight_height_spin.value(),
            "highlight_width_ratio": self.subtitle_highlight_width_ratio_spin.value(),
            "highlight_gap": self.subtitle_highlight_gap_spin.value(),
        })

    def _apply_subtitle_style_to_controls(self, style, preferred_data=None):
        style = normalize_subtitle_style(style)
        self._loading_subtitle_style = True
        family = style.get("font_family", "") or ""
        if family:
            self.subtitle_font_combo.setCurrentFont(QFont(family))
        else:
            self.subtitle_font_combo.setCurrentFont(QFont())
        self.subtitle_font_size_spin.setValue(int(style.get("font_size", 54) or 54))
        idx = self.subtitle_size_mode_combo.findData(style.get("font_size_mode", "percent_width"))
        self.subtitle_size_mode_combo.setCurrentIndex(idx if idx >= 0 else 0)
        self.subtitle_font_ratio_spin.setValue(float(style.get("font_size_ratio", 4.6) or 4.6))
        self.subtitle_color = style.get("color", "#ffffff")
        self.subtitle_gradient_end_color = style.get("gradient_color_end", "#67e8f9")
        self.subtitle_stroke_color = style.get("stroke_color", "#000000")
        self.subtitle_outer_stroke_color = style.get("secondary_stroke_color", "#1f2937")
        self.subtitle_glow_color = style.get("glow_color", "#67e8f9")
        self.subtitle_shadow_color = style.get("shadow_color", "#000000")
        self.subtitle_bg_color = style.get("background_color", "#000000")
        self.subtitle_highlight_color = style.get("highlight_color", "#f59e0b")
        self._set_subtitle_color_button(self.subtitle_color_btn, self.subtitle_color)
        self._set_subtitle_color_button(self.subtitle_gradient_end_btn, self.subtitle_gradient_end_color)
