    def _trim_duration(self, path=""):
        target = path or self._trim_selected_video()
        return self._ffprobe_duration(target) if target and os.path.isfile(target) else 0.0

    def _update_trim_backend_label(self):
        backend = getattr(self, "trim_player_backend", "none")
        text = "后端: 缩略图"
        color = "#64748b"
        bg = "#f8fafc"
        border = "#e2e8f0"
        if backend == "vlc":
            text = "后端: VLC"
            color = "#166534"
            bg = "#dcfce7"
            border = "#86efac"
        if hasattr(self, "trim_backend_label") and self.trim_backend_label:
            self.trim_backend_label.setText(text)
            self.trim_backend_label.setStyleSheet(
                f"color:{color}; background:{bg}; border:1px solid {border}; "
                "border-radius:10px; padding:2px 10px;"
            )

    def _has_embedded_trim_player(self):
        return bool(self.trim_player and self.trim_player_backend == "vlc" and getattr(self, "trim_video_widget", None))

    def _is_trim_vlc_backend(self):
        return getattr(self, "trim_player_backend", "none") == "vlc"

    def _bind_trim_vlc_output(self):
        if not self._is_trim_vlc_backend() or not self.trim_player or not getattr(self, "trim_video_widget", None):
            return False
        try:
            try:
                self.trim_video_widget.show()
            except Exception:
                pass
            QApplication.processEvents()
            raw_wid = self.trim_video_widget.effectiveWinId() if hasattr(self.trim_video_widget, "effectiveWinId") else self.trim_video_widget.winId()
            wid = int(raw_wid)
            if wid <= 0:
                return False
            if sys.platform.startswith("linux"):
                self.trim_player.set_xwindow(wid)
            elif sys.platform == "win32":
                self.trim_player.set_hwnd(wid)
            elif sys.platform == "darwin":
                self.trim_player.set_nsobject(wid)
            return True
        except Exception:
            return False

    def _schedule_trim_vlc_rebind(self):
        if not self._is_trim_vlc_backend():
            return
        for delay in (0, 80, 180, 320):
            QTimer.singleShot(delay, self._bind_trim_vlc_output)

    def _trim_player_stop(self):
        if not self.trim_player:
            return
        try:
            self.trim_player.stop()
        except Exception:
            pass

    def _trim_player_pause(self):
        if not self.trim_player:
            return
        try:
            self.trim_player.set_pause(1)
        except Exception:
            pass

    def _trim_player_play(self):
        if not self.trim_player:
            return False
        try:
            self._bind_trim_vlc_output()
            if self.trim_player.play() == -1:
                return False
            self._schedule_trim_vlc_rebind()
            return True
        except Exception:
            return False

    def _trim_player_set_position_ms(self, position_ms):
        if not self.trim_player:
            return
        pos = max(0, int(position_ms or 0))
        try:
            self.trim_player.set_time(pos)
        except Exception:
            pass

    def _trim_player_get_position_ms(self):
        if not self.trim_player:
            return 0
        try:
            return max(0, int(self.trim_player.get_time() or 0))
        except Exception:
            return 0

    def _trim_player_set_volume_value(self, vol):
        if not self.trim_player:
            return
        try:
            self.trim_player.audio_set_volume(int(vol))
        except Exception:
            pass

    def _start_background_vlc_check(self):
        if HAS_VLC and vlc is not None:
            write_debug("[VLC] 启动时已检测到 python-vlc，尝试启用 VLC 内嵌播放器")
            self._retry_enable_vlc_backend(reason="startup_available")
            return
        if self._vlc_install_attempted:
            return
        self._vlc_install_attempted = True
        if hasattr(self, "trim_player_status_label"):
            self.trim_player_status_label.setText("未检测到 python-vlc，正在后台静默安装，完成后将自动切到 VLC")
        write_debug("[VLC] 启动时未检测到 python-vlc，开始后台静默安装")

        def _worker():
            ok, detail = ensure_python_vlc()
            try:
                self.vlc_install_finished.emit(bool(ok), str(detail or ""))
            except Exception as e:
                write_debug(f"[VLC] 发送安装完成信号失败: {e}")

        threading.Thread(target=_worker, daemon=True).start()

    def _on_vlc_install_finished(self, ok, detail=""):
        if ok:
            switched = self._retry_enable_vlc_backend(reason="post_install")
            if hasattr(self, "trim_player_status_label"):
                if switched:
                    self.trim_player_status_label.setText("python-vlc 已静默安装完成，已自动切换到 VLC")
                else:
                    self.trim_player_status_label.setText("python-vlc 已安装，但 VLC 初始化失败，继续使用缩略图预览")
        else:
            if hasattr(self, "trim_player_status_label") and not self._has_embedded_trim_player():
                self.trim_player_status_label.setText("python-vlc 静默安装失败，继续使用缩略图预览")
        try:
            write_debug(f"[VLC] 后台安装结果: ok={ok}, detail={detail}")
        except Exception:
            pass

    def _retry_enable_vlc_backend(self, reason="manual"):
        if not (HAS_VLC and vlc is not None):
            self.trim_player_backend = "none"
            self._update_trim_backend_label()
            return False
        _prepare_vlc_runtime(log_if_missing=False)
        write_debug(f"[VLC] 准备启用 VLC 内嵌播放器，触发原因: {reason}")
        current_path = ""
        try:
            current_path = self._trim_selected_video()
        except Exception:
            current_path = ""
        self._init_trim_player()
        if not self._has_embedded_trim_player():
            return False
        if current_path and os.path.isfile(current_path):
            try:
                self._load_trim_player_source(current_path)
                duration = self._trim_duration(current_path)
                if duration > 0:
                    current_sec = self._trim_seek_seconds(duration)
                    self._trim_player_set_position_ms(int(current_sec * 1000))
            except Exception as e:
                write_debug(f"[VLC] 安装后重载当前视频失败: {e}")
        return True

    def _get_splitter_sizes_safe(self, splitter):
        try:
            return [int(x) for x in splitter.sizes()]
        except Exception:
            return []

    def _set_trim_aux_visible(self, visible):
        if hasattr(self, "trim_aux_panel") and self.trim_aux_panel:
            self.trim_aux_panel.setVisible(bool(visible))
        if hasattr(self, "trim_main_splitter") and self.trim_main_splitter and hasattr(self, "trim_bottom_panel") and self.trim_bottom_panel:
            try:
                if visible:
                    self.trim_main_splitter.setSizes([760, 420])
                else:
                    self.trim_main_splitter.setSizes([980, 0])
            except Exception:
                pass
        if hasattr(self, "trim_bottom_splitter") and self.trim_bottom_splitter:
            try:
                if visible:
                    self.trim_bottom_splitter.setSizes([300, 340])
                else:
                    self.trim_bottom_splitter.setSizes([1, 0])
            except Exception:
                pass

    def _init_trim_player(self):
        self.trim_player = None
        self.trim_vlc_instance = None
        self.trim_vlc_media = None
        self.trim_player_backend = "none"
        self._update_trim_backend_label()
        if not (HAS_VLC and vlc is not None and isinstance(getattr(self, "trim_video_widget", None), QFrame)):
            if hasattr(self, "trim_player_status_label"):
                self.trim_player_status_label.setText("未检测到可用的 VLC，使用缩略图预览")
            self._update_trim_backend_label()
            return
        try:
            instance_args = _build_vlc_instance_args()
            write_debug(f"[VLC] 初始化实例参数: {instance_args}")
            self.trim_vlc_instance = vlc.Instance(*instance_args)
            self.trim_player = self.trim_vlc_instance.media_player_new()
            self.trim_player_backend = "vlc"
            self._update_trim_backend_label()
            self._bind_trim_vlc_output()
            self._schedule_trim_vlc_rebind()
            self.on_trim_volume_changed(self.trim_volume_slider.value())
            self.trim_player_status_label.setText("VLC 内嵌播放器已就绪")
        except Exception as e:
            self.trim_player = None
            self.trim_vlc_instance = None
            self.trim_vlc_media = None
            self.trim_player_backend = "none"
            self._update_trim_backend_label()
            self.trim_player_status_label.setText(f"VLC 初始化失败，使用缩略图预览：{e}")

    def _trim_seek_seconds(self, duration=None):
        total = duration if duration is not None else self._trim_duration()
        if total <= 0:
            return 0.0
        ratio = (self.trim_seek_slider.value() / 1000.0) if hasattr(self, "trim_seek_slider") else 0.0
        return max(0.0, min(total, total * ratio))

    def _set_trim_seek_by_seconds(self, seconds, refresh_preview=True, sync_player=True):
        duration = self._trim_duration()
        if duration <= 0 or not hasattr(self, "trim_seek_slider"):
            return
        sec = max(0.0, min(duration, float(seconds or 0.0)))
        ratio = int(round((sec / duration) * 1000)) if duration > 0 else 0
        self.trim_seek_slider.blockSignals(True)
        self.trim_seek_slider.setValue(max(0, min(1000, ratio)))
        self.trim_seek_slider.blockSignals(False)
        self.on_trim_seek_changed()
        should_sync_player = (
            sync_player
            and self._has_embedded_trim_player()
            and (self.trim_is_playing or not self.trim_seek_dragging)
        )
        if should_sync_player:
            self._trim_player_set_position_ms(int(sec * 1000))
        if refresh_preview:
            if self._has_embedded_trim_player() and not self.trim_is_playing and not self.trim_seek_dragging:
                self.trim_preview_refresh_timer.start()
            elif not self._has_embedded_trim_player():
                self.refresh_trim_previews(refresh_current_only=True)

    def _set_trim_playing_state(self, playing):
        self.trim_is_playing = bool(playing)
        if self.trim_is_playing:
            self.btn_trim_play.setText("⏸ 暂停")
            self.trim_play_timer.start()
            if hasattr(self, "trim_player_status_label"):
                self.trim_player_status_label.setText("正在播放裁剪区间" if not self._is_trim_vlc_backend() else "VLC 正在播放裁剪区间")
        else:
            self.trim_play_timer.stop()
            self.btn_trim_play.setText("▶ 播放")
            if hasattr(self, "trim_player_status_label"):
                self.trim_player_status_label.setText("已暂停")

    def toggle_trim_playback(self):
        path = self._trim_selected_video()
        if not path or not os.path.isfile(path):
            QMessageBox.warning(self, "提示", "请先选择一个有效视频")
            return
        if self.trim_is_playing:
            if self._has_embedded_trim_player():
                self._trim_player_pause()
            self._set_trim_playing_state(False)
            return
        duration = self._trim_duration(path)
        if duration <= 0:
            QMessageBox.warning(self, "提示", "当前视频时长读取失败，无法预览")
            return
        start = max(0.0, min(duration, self.trim_start_spin.value()))
        end = max(start, min(duration, self.trim_end_spin.value()))
        current = self._trim_seek_seconds(duration)
        if current < start or current > end:
            self._set_trim_seek_by_seconds(start, refresh_preview=True, sync_player=True)
        if self._has_embedded_trim_player():
            try:
                if not self._trim_player_play():
                    raise RuntimeError("播放器启动失败")
                self._set_trim_playing_state(True)
                return
            except Exception:
                pass
        self._set_trim_playing_state(True)

    def _on_trim_play_tick(self):
        if self._has_embedded_trim_player():
            if not self._is_trim_vlc_backend():
                return
            if not self.trim_is_playing:
                return
            duration = self._trim_duration()
            if duration <= 0:
                self._set_trim_playing_state(False)
                return
            start = max(0.0, min(duration, self.trim_start_spin.value()))
            end = max(start, min(duration, self.trim_end_spin.value()))
            current = max(0.0, self._trim_player_get_position_ms() / 1000.0)
            if current < start:
                current = start
                self._trim_player_set_position_ms(int(start * 1000))
            reached_end = current >= end - 0.02
            if reached_end:
                self._trim_player_pause()
                self._trim_player_set_position_ms(int(end * 1000))
                self._set_trim_playing_state(False)
                current = end
            self._set_trim_seek_by_seconds(min(current, end), refresh_preview=False, sync_player=False)
            return
        if not self.trim_is_playing:
            return
        duration = self._trim_duration()
        if duration <= 0:
            self._set_trim_playing_state(False)
            return
        start = max(0.0, min(duration, self.trim_start_spin.value()))
        end = max(start, min(duration, self.trim_end_spin.value()))
        step = max(0.04, self.trim_play_timer.interval() / 1000.0)
        current = self._trim_seek_seconds(duration)
        if current < start or current > end:
            current = start
        else:
            current += step
        reached_end = current >= end - 1e-6
        self._set_trim_seek_by_seconds(min(current, end), refresh_preview=True, sync_player=False)
        if reached_end:
            self._set_trim_playing_state(False)

    def jump_trim_to_time(self, timestamp):
        self._set_trim_seek_by_seconds(timestamp, refresh_preview=True, sync_player=True)
        self.setFocus()

    def _load_trim_player_source(self, path):
        if not self._has_embedded_trim_player():
            if hasattr(self, "trim_player_status_label"):
                self.trim_player_status_label.setText("播放器不可用，使用缩略图预览")
            return
        self._trim_player_stop()
        try:
            valid_path = path if path and os.path.isfile(path) else ""
            self._bind_trim_vlc_output()
            self.trim_vlc_media = self.trim_vlc_instance.media_new(os.path.abspath(valid_path)) if valid_path else None
            self.trim_player.set_media(self.trim_vlc_media)
            self._schedule_trim_vlc_rebind()
            self.trim_player_status_label.setText("已载入视频（VLC），可直接播放并试听音频" if valid_path else "未选择视频")
        except Exception as e:
            self.trim_player_status_label.setText(f"载入视频失败：{e}")

    def on_trim_volume_changed(self, value):
        vol = max(0, min(100, int(value or 0)))
        if hasattr(self, "btn_trim_mute"):
            self.btn_trim_mute.setText("🔇 静音" if vol <= 0 else "🔊 有声")
        if not self._has_embedded_trim_player():
            return
        self._trim_player_set_volume_value(vol)

    def toggle_trim_mute(self):
        if self.trim_volume_slider.value() > 0:
            self.trim_volume_slider.setProperty("_prev_volume", self.trim_volume_slider.value())
            self.trim_volume_slider.setValue(0)
        else:
            prev = int(self.trim_volume_slider.property("_prev_volume") or 80)
            self.trim_volume_slider.setValue(max(1, min(100, prev)))

    def on_trim_seek_slider_pressed(self):
        self.trim_seek_dragging = True

    def on_trim_seek_slider_moved(self, value):
        self.trim_pending_seek_seconds = self._trim_duration() * (max(0, min(1000, int(value or 0))) / 1000.0)
        if self._has_embedded_trim_player():
            self.on_trim_seek_changed()
        else:
            self.trim_seek_apply_timer.start()

    def on_trim_seek_slider_released(self):
        self.trim_seek_dragging = False
        self.trim_pending_seek_seconds = self._trim_seek_seconds()
        self._apply_pending_trim_seek()
        self.refresh_trim_previews(refresh_current_only=True)

    def _apply_pending_trim_seek(self):
        sec = float(self.trim_pending_seek_seconds or 0.0)
        # 内嵌播放器拖动时，大画面本身就是实时预览，避免重复抽帧导致卡顿。
        self._set_trim_seek_by_seconds(
            sec,
            refresh_preview=not self._has_embedded_trim_player(),
            sync_player=(not self.trim_seek_dragging),
        )

    def _on_trim_player_position_changed(self, position_ms):
        return

    def _on_trim_player_duration_changed(self, duration_ms):
        if duration_ms and duration_ms > 0 and hasattr(self, "trim_player_status_label"):
            self.trim_player_status_label.setText(f"播放器时长: {self._format_seconds(duration_ms / 1000.0)}")

    def _on_trim_player_state_changed(self, state):
        return

    def _update_trim_timeline(self, refresh_images=False):
        labels = getattr(self, "trim_timeline_labels", [])
        if not labels:
            return
        path = self._trim_selected_video()
        duration = self._trim_duration(path)
        if not path or not os.path.isfile(path) or duration <= 0:
            for lbl in labels:
                lbl.timestamp = 0.0
                lbl.setToolTip("")
                self._set_trim_preview_pixmap(lbl, "", "时间点")
                lbl.setStyleSheet("border:1px solid #d1d5db; background:#f8fafc; color:#64748b; padding:2px;")
            return
        start = max(0.0, min(duration, self.trim_start_spin.value()))
        end = max(start, min(duration, self.trim_end_spin.value()))
        current = self._trim_seek_seconds(duration)
        count = max(1, len(labels))
        slot_span = duration / max(1, count - 1)
        current_tol = max(0.2, slot_span / 2.0)
        for idx, lbl in enumerate(labels):
            ts = (duration * idx / max(1, count - 1)) if count > 1 else 0.0
            lbl.timestamp = ts
            if refresh_images:
                self._set_trim_preview_pixmap(lbl, self._extract_trim_frame(path, ts), self._format_seconds(ts))
            in_range = (start - 1e-6) <= ts <= (end + 1e-6)
            is_current = abs(ts - current) <= current_tol
            border = "#2563eb" if is_current else ("#16a34a" if in_range else "#d1d5db")
            bg = "#dbeafe" if is_current else ("#dcfce7" if in_range else "#f8fafc")
            lbl.setStyleSheet(f"border:2px solid {border}; background:{bg}; color:#334155; padding:2px;")
            lbl.setToolTip(f"{self._format_seconds(ts)}\n点击跳转到这里")

    def _append_video_path_once(self, path):
        target = os.path.abspath(path or "")
        if not target or not os.path.isfile(target):
            return False
        current_trim_path = self._trim_selected_video()
        existing = []
        for raw in self.video_list_edit.toPlainText().splitlines():
            norm = self._normalize_video_path(raw)
            if norm:
                existing.append(os.path.abspath(norm))
        if os.path.normcase(target) in {os.path.normcase(p) for p in existing}:
            self.refresh_concat_source_table()
            self.refresh_trim_video_combo(select_path=current_trim_path)
            return False
        merged = [p for p in self.video_list_edit.toPlainText().splitlines() if p.strip()]
        merged.append(target)
        self.video_list_edit.setPlainText("\n".join(merged))
        self.refresh_concat_source_table()
        self.refresh_trim_video_combo(select_path=current_trim_path)
        return True

    def _insert_trim_output_to_concat_table(self, path):
        table = getattr(self, "concat_group_table", None)
        if not table or not path:
            return False
        row = table.currentRow()
        col = table.currentColumn()
        if row < 0 or col < 1:
            row = -1
            col = -1
            for r in range(table.rowCount()):
                for c in range(1, table.columnCount()):
                    it = table.item(r, c)
                    if not it or not it.text().strip():
                        row, col = r, c
                        break
                if row >= 0:
                    break
        if row < 0:
            row = table.rowCount()
            table.insertRow(row)
        if col < 1:
            col = 1
        item = table.item(row, col)
        if not item:
            item = QTableWidgetItem("")
            table.setItem(row, col, item)
        item.setText(path)
        table.setCurrentCell(row, col)
        return True

    def _handle_trim_output_ready(self):
        output_paths = list(self.trim_pending_output_paths or ([self.trim_pending_output_path] if self.trim_pending_output_path else []))
        self.trim_pending_output_path = ""
        self.trim_pending_output_paths = []
        for out_path in output_paths:
            if not out_path or not os.path.isfile(out_path):
                continue
            self._append_video_path_once(out_path)
            if getattr(self, "trim_add_to_concat_check", None) and self.trim_add_to_concat_check.isChecked():
                inserted = self._insert_trim_output_to_concat_table(out_path)
                if inserted:
                    main_win = self.window()
                    if hasattr(main_win, "log"):
                        main_win.log(f"🧩 裁剪结果已加入拼接表：{os.path.basename(out_path)}", "green")

    def _on_concat_option_change(self, *args):
        transition = self.concat_transition_check.isChecked() if hasattr(self, "concat_transition_check") else False
        silence_cut = self.concat_silence_cut_check.isChecked() if hasattr(self, "concat_silence_cut_check") else False
        voice_cut = self.concat_voice_cut_check.isChecked() if hasattr(self, "concat_voice_cut_check") else False
        loudness_match = self.concat_loudness_match_check.isChecked() if hasattr(self, "concat_loudness_match_check") else False
        if transition or silence_cut or voice_cut or loudness_match:
            # 有转场、裁静音、裁无人声或智能匹配音量时强制转码
            self.concat_reencode_check.setChecked(True)
            self.concat_reencode_check.setEnabled(False)
        else:
            self.concat_reencode_check.setEnabled(True)
        enabled = self.concat_reencode_check.isChecked()
        self.concat_crf_spin.setEnabled(enabled)
        self.concat_preset_combo.setEnabled(enabled)
        if hasattr(self, "concat_transition_dur"):
            self.concat_transition_dur.setEnabled(transition)
        if hasattr(self, "concat_transition_audio_check"):
            self.concat_transition_audio_check.setEnabled(transition)
        if hasattr(self, "concat_silence_threshold_spin"):
            self.concat_silence_threshold_spin.setEnabled(silence_cut)
        if hasattr(self, "concat_silence_min_duration_spin"):
            self.concat_silence_min_duration_spin.setEnabled(silence_cut)
        if hasattr(self, "concat_silence_keep_buffer_spin"):
            self.concat_silence_keep_buffer_spin.setEnabled(silence_cut)
        if hasattr(self, "concat_voice_min_duration_spin"):
            self.concat_voice_min_duration_spin.setEnabled(voice_cut)
        if hasattr(self, "concat_voice_keep_buffer_spin"):
            self.concat_voice_keep_buffer_spin.setEnabled(voice_cut)
        if hasattr(self, "concat_loudness_max_gain_spin"):
            self.concat_loudness_max_gain_spin.setEnabled(loudness_match)
        self.GLOBAL_VIDEO_CONCAT_SYNC_SIGNAL.emit()

    def browse_out(self):
        p = QFileDialog.getExistingDirectory(self, "选择输出目录")
        if p:
            self.out_path_edit.setText(p)

    def add_video_files(self):
        paths, _ = QFileDialog.getOpenFileNames(self, "选择视频文件", "", "视频文件 (*.mp4 *.mkv *.avi *.mov *.flv *.wmv *.m4v *.ts *.webm)")
        if paths:
            self._append_video_paths(paths)

    def add_video_folder(self):
        folder = QFileDialog.getExistingDirectory(self, "选择视频文件夹")
        if folder:
            self._append_video_paths([folder])

    def _append_video_paths(self, paths):
        if not paths:
            return
        existing = self.video_list_edit.toPlainText().strip()
        merged = (existing + "\n") if existing else ""
        merged += "\n".join([os.path.normpath(p) for p in paths if p])
        self.video_list_edit.setPlainText(merged.strip())
        self.refresh_concat_source_table()
        self.refresh_trim_video_combo()

    def clear_video_list(self):
        self.video_list_edit.clear()
        self.refresh_concat_source_table()
        self.refresh_trim_video_combo()

