    def keyPressEvent(self, event):
        try:
            active_trim_tab = hasattr(self, "op_tabs") and self.op_tabs.currentIndex() == 3
            focus_w = QApplication.focusWidget()
            if active_trim_tab and not isinstance(focus_w, (QLineEdit, QTextEdit)):
                key = event.key()
                if key == _Key_Space:
                    self.toggle_trim_playback()
                    event.accept()
                    return
                if key == _Key_I:
                    self.set_trim_start_from_seek()
                    event.accept()
                    return
                if key == _Key_O:
                    self.set_trim_end_from_seek()
                    event.accept()
                    return
        except Exception:
            pass
        super().keyPressEvent(event)

