    def run_format_align_srt_export(self):
        subtitle_mode = str(self.format_subtitle_mode_combo.currentData() or "none") if hasattr(self, "format_subtitle_mode_combo") else "none"
        if subtitle_mode != "align_burn":
            QMessageBox.warning(self, "提示", "这个按钮只用于“按提供文本对齐后烧录”模式。请先把字幕处理切换到该模式。")
            return
        videos = self._collect_videos()
        if not videos:
            QMessageBox.warning(self, "提示", "请先添加至少 1 个有效视频素材")
            return
        self.btn_run_format.setEnabled(False)
        self.btn_run_format_srt_only.setEnabled(False)
        self.format_prog.setValue(0)
        cfg = self.get_config()
        main_win = self.window()
        subtitle_ai_cfg = {}
        subtitle_use_gpu = True
        try:
            if hasattr(main_win, "_get_named_ai_config"):
                subtitle_ai_cfg = dict(main_win._get_named_ai_config("pipeline") or {})
                subtitle_use_gpu = bool(subtitle_ai_cfg.get("clip_use_gpu", True))
        except Exception:
            pass
        cfg2 = {
            "subtitle_mode": "align_burn",
            "subtitle_keep_srt": True,
            "subtitle_align_mode": str(cfg.get("format_subtitle_align_mode", "script_blocks") or "script_blocks"),
            "subtitle_text_source": str(cfg.get("format_subtitle_text_source", "") or ""),
            "subtitle_manual_text": str(cfg.get("format_subtitle_manual_text", "") or ""),
            "subtitle_ai_config": subtitle_ai_cfg,
            "subtitle_use_gpu": subtitle_use_gpu,
        }
        self.format_srt_thread = VideoSubtitleOnlyBatchThread(videos, cfg2)
        self.format_srt_thread.progress.connect(self.format_prog.setValue)
        if hasattr(main_win, "log"):
            self.format_srt_thread.log.connect(main_win.log)
            self.format_srt_thread.finished_all.connect(lambda: main_win.log("✅ 已完成“只生成对齐 SRT”任务", "green"))
        self.format_srt_thread.error.connect(lambda msg: (self.log(msg, "red"), QMessageBox.critical(self, "字幕生成失败", msg)))
        self.format_srt_thread.finished_all.connect(lambda: self.btn_run_format.setEnabled(True))
        self.format_srt_thread.finished_all.connect(lambda: self.btn_run_format_srt_only.setEnabled(True))
        self.format_srt_thread.start()

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            event.ignore()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            event.ignore()

    def dropEvent(self, event):
        if not event.mimeData().hasUrls():
            event.ignore()
            return
        new_paths = []
        for url in event.mimeData().urls():
            f = url.toLocalFile()
            if not f:
                raw = url.toString()
                if raw.startswith("file:///"):
                    f = urllib.parse.unquote(raw[8:])
                    if sys.platform == 'win32' and f.startswith('/'):
                        f = f[1:]
            if f:
                new_paths.append(os.path.normpath(f))
        if new_paths:
            self._append_video_paths(new_paths)
            self.refresh_concat_source_table()
            event.acceptProposedAction()
        else:
            event.ignore()

