    def update_rec_btn_styles(self):
        """根据已录制坐标更新按钮样式和文字"""
        btn_map = {
            'upload': (self.btn_rec_u, "录制上传点"),
            'script': (self.btn_rec_s, "录制输入框"),
            'generate': (self.btn_rec_g, "录制生成键"),
            'clear': (self.btn_rec_c, "录制清除键")
        }
        for key, (btn, base_text) in btn_map.items():
            if key in self.auto_coords:
                c = self.auto_coords[key]
                btn.setText(f"✅ {base_text}\n({c['x']}, {c['y']})")
                btn.setStyleSheet("background-color: #dcfce7; color: #166534; font-weight: bold; border: 2px solid #22c55e;")
            else:
                btn.setText(base_text)
                btn.setStyleSheet("")


    def toggle_pause_universal(self):
        if hasattr(self, "engine") and self.engine.isRunning():
            if self.engine._pause:
                self.engine.resume()
                self.btn_pause_universal.setText(" ⏸ 暂停流程 ")
            else:
                self.engine.pause()
                self.btn_pause_universal.setText(" ▶ 恢复流程 ")

    def on_start_universal_flow(self):
        """启动万能自动化流程：支持多窗口并行。"""
        if hasattr(self, "engine") and self.engine.isRunning():
            self.engine.stop()
            self.btn_start_universal.setText(" 🚀 启动并行流程 ")
            self.btn_pause_universal.setEnabled(False)
            return

    def _set_all_tasks_checked(self, checked):
        """全局同步勾选状态：直接操作原生 checkState，避免 QWidget 覆盖鼠标事件。"""
        state = self._win_checked if checked else self._win_unchecked
        for i in range(self.auto_task_table.rowCount()):
            item = self.auto_task_table.item(i, 0)
            if item:
                item.setCheckState(state)

    def _auto_check_flags(self):
        if PYQT_VERSION == 6:
            return (Qt.ItemFlag.ItemIsUserCheckable if PYQT_VERSION == 6 else Qt.ItemIsUserCheckable) | (Qt.ItemFlag.ItemIsEnabled if PYQT_VERSION == 6 else Qt.ItemIsEnabled) | (Qt.ItemFlag.ItemIsSelectable if PYQT_VERSION == 6 else Qt.ItemIsSelectable)
        return (Qt.ItemFlag.ItemIsUserCheckable if PYQT_VERSION == 6 else Qt.ItemIsUserCheckable) | (Qt.ItemFlag.ItemIsEnabled if PYQT_VERSION == 6 else Qt.ItemIsEnabled) | (Qt.ItemFlag.ItemIsSelectable if PYQT_VERSION == 6 else Qt.ItemIsSelectable)

    def _auto_text_flags(self):
        if PYQT_VERSION == 6:
            return (Qt.ItemFlag.ItemIsEnabled if PYQT_VERSION == 6 else Qt.ItemIsEnabled) | (Qt.ItemFlag.ItemIsSelectable if PYQT_VERSION == 6 else Qt.ItemIsSelectable)
        return (Qt.ItemFlag.ItemIsEnabled if PYQT_VERSION == 6 else Qt.ItemIsEnabled) | (Qt.ItemFlag.ItemIsSelectable if PYQT_VERSION == 6 else Qt.ItemIsSelectable)

    def _make_auto_check_item(self, checked=True):
        item = QTableWidgetItem("")
        item.setFlags(self._auto_check_flags())
        item.setCheckState(self._win_checked if checked else self._win_unchecked)
        item.setTextAlignment(_AlignCenter)
        return item

    def _make_auto_code_item(self, code, is_sub=False, expanded=False):
        base_code = self._clean_auto_code(code)
        prefix = "│    ↳" if is_sub else ("▾ ★" if expanded else "▸ ★")
        text = f"{prefix} {base_code}{' (续)' if is_sub and not base_code.endswith('(续)') else ''}"
        item = QTableWidgetItem(text)
        item.setFlags(self._auto_text_flags())
        item.setData(_UserRole, {"base_code": base_code, "is_sub": is_sub})
        if not is_sub:
            font = item.font(); font.setBold(True); item.setFont(font)
        return item

    def _clean_auto_code(self, text):
        text = (text or "").replace("▸", "").replace("▾", "").replace("★", "").replace("│", "").replace("↳", "")
        text = text.replace("(续)", "").strip()
        return text

    def _auto_is_sub_row(self, row):
        item = self.auto_task_table.item(row, 1)
        if not item: return False
        data = item.data(_UserRole)
        if isinstance(data, dict) and "is_sub" in data: return bool(data.get("is_sub"))
        return "↳" in item.text()

    def _auto_is_main_row(self, row):
        item = self.auto_task_table.item(row, 1)
        return bool(item and "★" in item.text())

    def _style_auto_task_row(self, row, is_sub=False):
        main_bg = QColor("#ffffff")
        sub_bg = QColor("#f8fafc")
        main_text = QColor("#111827")
        sub_text = QColor("#64748b")
        path_sub = QColor("#94a3b8")
        bg = sub_bg if is_sub else main_bg
        for col in range(self.auto_task_table.columnCount()):
            item = self.auto_task_table.item(row, col)
            if item:
                item.setBackground(bg)
                item.setForeground(path_sub if (is_sub and col == 3) else (sub_text if is_sub else main_text))
                if col in (1, 4) and not is_sub:
                    font = item.font(); font.setBold(True); item.setFont(font)
        self.auto_task_table.setRowHeight(row, 30 if is_sub else 34)

    def _populate_auto_task_row(self, row, code, img, text, is_sub, titles, checked=True, win="", status="等待执行"):
        self.auto_task_table.setItem(row, 0, self._make_auto_check_item(checked))
        self.auto_task_table.setItem(row, 1, self._make_auto_code_item(code, is_sub=is_sub, expanded=False))
        cb = QComboBox(); cb.setEditable(True); cb.addItem(""); cb.addItems(titles)
        if win: cb.setCurrentText(win)
        self.auto_task_table.setCellWidget(row, 2, cb)
        self.auto_task_table.setItem(row, 3, QTableWidgetItem(img or ""))
        content = ("        " + text.strip()) if is_sub else (text or "")
        self.auto_task_table.setItem(row, 4, QTableWidgetItem(content))
        self.auto_task_table.setItem(row, 5, QTableWidgetItem(status))
        self._style_auto_task_row(row, is_sub=is_sub)
        if is_sub:
            self.auto_task_table.setRowHidden(row, True)

    def _on_auto_table_cell_clicked(self, row, col):
        """将项目代码列中的 ▸/▾ 作为轻量级折叠按钮，避免在执行列使用 setCellWidget。"""
        if col == 1 and self._auto_is_main_row(row):
            self._toggle_row_group(row)
    def refresh_wins(self):
        """刷新目标窗口列表，并同步更新任务表格中的下拉框。"""
        checked_titles = set()
        if hasattr(self, 'win_list'):
            for idx in range(self.win_list.count()):
                item = self.win_list.item(idx)
                if item.checkState() == self._win_checked: checked_titles.add(item.text())
            self.win_list.clear()
            try:
                titles = WinUtils.get_all_windows()
                for title in titles:
                    it = QListWidgetItem(title); it.setFlags(self._win_item_flag)
                    it.setCheckState(self._win_checked if title in checked_titles else self._win_unchecked)
                    self.win_list.addItem(it)
                for i in range(self.auto_task_table.rowCount()):
                    cb = self.auto_task_table.cellWidget(i, 2)
                    if isinstance(cb, QComboBox):
                        curr = cb.currentText(); cb.clear(); cb.addItem(""); cb.addItems(titles); cb.setCurrentText(curr)
            except Exception:
                pass
    def start_record(self, key):
        self.overlay = ScreenOverlay(); self.overlay.clicked.connect(lambda x, y: self.save_coord(key, x, y))

    def save_coord(self, key, x, y):
        self.auto_coords[key] = {'x': x, 'y': y}
        self.log(f"✅ 已录制 {key} 坐标: ({x}, {y})", "green")
        self.update_rec_btn_styles()
        self.save_config(force=True) # 录制后立即保存到 JSON，避免因输入焦点导致延迟保存

    def _show_rec_btn_menu(self, pos, btn):
        """录制按钮右键菜单：支持清除坐标"""
        menu = QMenu()
        clear_act = menu.addAction("❌ 清除此坐标")
        action = menu.exec_(btn.mapToGlobal(pos)) if PYQT_VERSION != 6 else menu.exec(btn.mapToGlobal(pos))
        if action == clear_act:
            key = btn.objectName().replace("rec_", "")
            if key in self.auto_coords:
                del self.auto_coords[key]
                self.log(f"🗑️ 已清除 {key} 坐标录制", "blue")
                self.update_rec_btn_styles()
                self.save_config(force=True)

    def _show_auto_table_menu(self, pos):
        """万能自动化表格右键菜单：支持动态重拆分文案。"""
        menu = QMenu()
        re_wrap_act = menu.addAction("✂️ 重新按字数拆分选中行")
        expand_all_act = menu.addAction("➕ 全部展开")
        collapse_all_act = menu.addAction("➖ 全部折叠")
        del_row_act = menu.addAction("🗑️ 删除选中行任务")
        
        if PYQT_VERSION == 6:
            action = menu.exec(self.auto_task_table.viewport().mapToGlobal(pos))
        else:
            action = menu.exec_(self.auto_task_table.viewport().mapToGlobal(pos))
        if action == expand_all_act:
            self._set_all_rows_visible(True)
        elif action == collapse_all_act:
            self._set_all_rows_visible(False)
        elif action == re_wrap_act:
            self._dynamic_re_wrap_tasks()
        elif action == del_row_act:
            rows = sorted(list(set(i.row() for i in self.auto_task_table.selectedItems())), reverse=True)
            for r in rows: self.auto_task_table.removeRow(r)

    def _set_all_rows_visible(self, visible):
        """批量折叠或展开所有子行，并同步主行项目代码列的 ▸/▾ 状态。"""
        for i in range(self.auto_task_table.rowCount()):
            if self._auto_is_sub_row(i):
                self.auto_task_table.setRowHidden(i, not visible)
            elif self._auto_is_main_row(i):
                item = self.auto_task_table.item(i, 1)
                if item:
                    code = self._clean_auto_code(item.text())
                    item.setText(("▾ ★ " if visible else "▸ ★ ") + code)
    def _toggle_row_group(self, main_row):
        """切换特定任务组展开/折叠；不使用第一列 QWidget，保留原生复选框点击能力。"""
        item = self.auto_task_table.item(main_row, 1)
        if not item: return
        is_expanding = item.text().lstrip().startswith("▸")
        code = self._clean_auto_code(item.text())
        item.setText(("▾ ★ " if is_expanding else "▸ ★ ") + code)
        for i in range(main_row + 1, self.auto_task_table.rowCount()):
            if self._auto_is_main_row(i): break
            if self._auto_is_sub_row(i):
                self.auto_task_table.setRowHidden(i, not is_expanding)
    def _dynamic_re_wrap_tasks(self):
        """对选中行重新拆分文案，并按新版 6 列树形结构重绘。"""
        selected_rows = sorted(list(set(i.row() for i in self.auto_task_table.selectedItems())))
        if not selected_rows: return
        limit, ok = QInputDialog.getInt(self, "动态重拆分", "请输入新的断行字数上限：", 150, 20, 2000, 10)
        if not ok: return

        groups = []
        curr_group = None
        for r in selected_rows:
            code_item = self.auto_task_table.item(r, 1)
            code = self._clean_auto_code(code_item.text() if code_item else "")
            img = self.auto_task_table.item(r, 3).text().strip() if self.auto_task_table.item(r, 3) else ""
            txt = self.auto_task_table.item(r, 4).text().strip() if self.auto_task_table.item(r, 4) else ""
            is_main = self._auto_is_main_row(r)
            win_cb = self.auto_task_table.cellWidget(r, 2)
            win = win_cb.currentText().strip() if isinstance(win_cb, QComboBox) else ""
            checked = self.auto_task_table.item(r, 0).checkState() == self._win_checked if self.auto_task_table.item(r, 0) else True
            
            if is_main or not curr_group or curr_group["code"] != code:
                if curr_group: groups.append(curr_group)
                curr_group = {"code": code, "img": img, "full_text": txt, "win": win, "checked": checked}
            else:
                curr_group["full_text"] += "\n" + txt
        if curr_group: groups.append(curr_group)

        # 记录最上方的行号作为插入起点
        start_insert_pos = selected_rows[0]
        
        self.auto_task_table.blockSignals(True)
        # 逆序删除选中行，避免行号塌陷
        for r in reversed(selected_rows):
            self.auto_task_table.removeRow(r)
        
        titles = WinUtils.get_all_windows()
        current_pos = start_insert_pos
        for group in groups:
            new_lines = smart_wrap_text(group["full_text"], limit).split('\n')
            for idx, line_txt in enumerate(new_lines):
                self.auto_task_table.insertRow(current_pos)
                self._populate_auto_task_row(current_pos, group["code"], group["img"], line_txt, idx > 0, titles, checked=group["checked"], win=group["win"])
                current_pos += 1
        
        self.auto_task_table.blockSignals(False)
        self.auto_task_table.viewport().update()
        self.log(f"✨ 动态重拆分完成，已按 {limit} 字重新整理选中任务并重置树状结构。", "green")
    def import_from_summary_view(self):
        """从汇总预览表导入任务：新增项目代码列，并按主任务/子文案树形层级展示。"""
        options = ["中文文案", "英文文案"]
        choice, ok = QInputDialog.getItem(self, "选择导入文案", "请选择要导入到自动化流程的文案类型：", options, 0, False)
        if not ok: return
        default_limit = 120 if choice == "中文文案" else 150
        wrap_limit, ok2 = QInputDialog.getInt(self, "设置拆分长度", f"请输入【{choice}】自动拆分的字数上限：\n(设置大一些可以减少拆分行数)", default_limit, 20, 2000, 10)
        if not ok2: return
        col_idx = 3 if choice == "中文文案" else 4

        IMG_EXTS = ('.jpg', '.jpeg', '.png', '.webp', '.bmp', '.gif', '.tiff', '.tif')
        global_root = self.heygen_source_input.text().strip() if hasattr(self, "heygen_source_input") and is_alive(self.heygen_source_input) else ""
        extra_dir = getattr(self, "_extra_search_dir", "")
        dir_file_index = {}
        def _get_dir_index(d):
            if not d or not os.path.isdir(d): return {}
            if d in dir_file_index: return dir_file_index[d]
            idx = {}
            try:
                for root, _, files in os.walk(d):
                    for f in files:
                        if f.lower().endswith(IMG_EXTS): idx[f.lower()] = os.path.join(root, f)
            except Exception:
                pass
            dir_file_index[d] = idx
            return idx

        processed_tasks = []
        for proj_name, p in self.project_tabs.items():
            table = p.get("table")
            if not table or not is_alive(table): continue
            src_dir = p["source_input"].text().strip() if is_alive(p["source_input"]) else ""
            out_dir = self._get_heygen_base_output_dir(proj_name, p)
            for i in range(table.rowCount()):
                code = table.item(i, 0).text().strip() if table.item(i, 0) else ""
                if not code: continue
                raw_text = table.item(i, col_idx).text().strip() if table.item(i, col_idx) else ""
                if not raw_text: continue
                orig_img = table.item(i, 1).text().strip() if table.item(i, 1) else ""
                real_img = ""
                if orig_img and os.path.isabs(orig_img) and os.path.isfile(orig_img):
                    real_img = orig_img
                if not real_img:
                    fname_lower = os.path.basename(orig_img).lower() if orig_img else ""
                    code_lower = code.lower()
                    search_dirs = [d for d in [out_dir, src_dir, global_root, extra_dir] if d]
                    for sd in search_dirs:
                        idx = _get_dir_index(sd)
                        found = False
                        for ext in IMG_EXTS:
                            if f"{code_lower}{ext}" in idx:
                                real_img = idx[f"{code_lower}{ext}"]; found = True; break
                        if found: break
                        if fname_lower and fname_lower in idx:
                            real_img = idx[fname_lower]; break
                lines = smart_wrap_text(raw_text, wrap_limit).split('\n')
                for idx, line_txt in enumerate(lines):
                    processed_tasks.append({"code": code, "img": real_img, "text": line_txt, "is_sub": idx > 0})

        if not processed_tasks:
            QMessageBox.warning(self, "提示", "未找到有效数据。"); return

        self.auto_task_table.setRowCount(0)
        self.auto_task_table.blockSignals(True)
        titles = WinUtils.get_all_windows()
        for i, data in enumerate(processed_tasks):
            self.auto_task_table.insertRow(i)
            self._populate_auto_task_row(i, data["code"], data["img"], data["text"], data["is_sub"], titles, checked=True)
        self.auto_task_table.blockSignals(False)
        self.auto_task_table.viewport().update()
        self.log(f"✅ 已成功导入 {len(processed_tasks)} 条任务 (含拆分行)，项目代码列与树形层级已启用", "green")
    def batch_set_task_window(self):
        """批量为选中行设置窗口。"""
        titles = WinUtils.get_all_windows()
        win, ok = QInputDialog.getItem(self, "批量设置窗口", "请选择目标窗口：", [""] + titles, 0, True)
        if ok:
            for item in self.auto_task_table.selectedItems():
                row = item.row()
                cb = self.auto_task_table.cellWidget(row, 2)
                if isinstance(cb, QComboBox): cb.setCurrentText(win)
            self.trigger_save()

    def clear_all_auto_tasks(self):
        """清除万能自动化表格中的所有任务"""
        if QMessageBox.question(self, "确认", "确定要清除所有自动化任务吗？") == QMessageBox.StandardButton.Yes:
            self.auto_task_table.blockSignals(True)
            self.auto_task_table.setRowCount(0)
            self.auto_task_table.blockSignals(False)
            self.trigger_save()

    def get_auto_tasks_data(self):
        """获取万能自动化表格的数据用于保存"""
        data = []
        for i in range(self.auto_task_table.rowCount()):
            chk = self.auto_task_table.item(i, 0)
            win_cb = self.auto_task_table.cellWidget(i, 2)
            data.append({
                "checked": (chk.checkState() == self._win_checked) if chk else False,
                "code": self.auto_task_table.item(i, 1).text() if self.auto_task_table.item(i, 1) else "",
                "win": win_cb.currentText() if (win_cb and isinstance(win_cb, QComboBox)) else "",
                "img": self.auto_task_table.item(i, 3).text() if self.auto_task_table.item(i, 3) else "",
                "script": self.auto_task_table.item(i, 4).text() if self.auto_task_table.item(i, 4) else "",
                "status": self.auto_task_table.item(i, 5).text() if self.auto_task_table.item(i, 5) else ""
            })
        return data

    def load_auto_tasks_data(self, data):
        """加载保存的万能自动化任务"""
        if not data: return
        self.auto_task_table.setRowCount(0)
        self.auto_task_table.blockSignals(True)
        titles = WinUtils.get_all_windows()
        for d in data:
            row = self.auto_task_table.rowCount()
            self.auto_task_table.insertRow(row)
            code = d.get("code", "")
            img = d.get("img", "")
            script = d.get("script", "")
            win = d.get("win", "")
            status = d.get("status", "等待执行")
            checked = d.get("checked", True)
            is_sub = "↳" in code or script.startswith("        ")
            # 清理 code 中的树形前缀，因为 _populate_auto_task_row 会重新生成
            clean_code = self._clean_auto_code(code)
            self._populate_auto_task_row(row, clean_code, img, script.strip(), is_sub, titles, checked=checked, win=win, status=status)
            if status == "✅ 已完成":
                for col in range(self.auto_task_table.columnCount()):
                    it = self.auto_task_table.item(row, col)
                    if it: it.setForeground(QColor("#9ca3af"))
        self.auto_task_table.blockSignals(False)

    def on_task_status_updated(self, row_idx, status):
        """当任务状态更新时（由引擎回传）"""
        if row_idx < self.auto_task_table.rowCount():
            it = self.auto_task_table.item(row_idx, 5)
            if it:
                it.setText(status)
                if status == "✅ 已完成":
                    for col in range(self.auto_task_table.columnCount()):
                        cell = self.auto_task_table.item(row_idx, col)
                        if cell: cell.setForeground(QColor("#9ca3af"))
            self.trigger_save()
    def on_start_universal_flow(self):
        """从表格读取任务并启动；精准识别原生复选框状态。"""
        global_wins = []
        for idx in range(self.win_list.count()):
            it = self.win_list.item(idx)
            if it.checkState() == self._win_checked: global_wins.append(it.text())

        tasks = []
        for i in range(self.auto_task_table.rowCount()):
            chk = self.auto_task_table.item(i, 0)
            if chk and chk.checkState() == self._win_checked:
                win_cb = self.auto_task_table.cellWidget(i, 2)
                win = win_cb.currentText().strip() if isinstance(win_cb, QComboBox) else ""
                code_item = self.auto_task_table.item(i, 1)
                code = self._clean_auto_code(code_item.text() if code_item else "")
                img = self.auto_task_table.item(i, 3).text().strip() if self.auto_task_table.item(i, 3) else ""
                cn = self.auto_task_table.item(i, 4).text().strip() if self.auto_task_table.item(i, 4) else ""
                if cn: tasks.append({'code': code, 'img': img, 'scripts': [cn], 'win': win, 'row_idx': i})
        if not tasks:
            QMessageBox.warning(self, "提示", "请先勾选要执行的任务。"); return
        prefix = self.prefix_edit.toPlainText().strip()
        self.engine = UniversalAutoEngine(tasks, global_wins, self.wait_gen_in.value(), prefix, self.auto_coords)
        self.engine.log_signal.connect(self.log)
        self.engine.finished_signal.connect(lambda: [self.btn_start_universal.setText(" 🚀 启动并行流程 "), self.btn_pause_universal.setEnabled(False)])
        self.engine.start()
        self.btn_pause_universal.setEnabled(True)
        self.btn_pause_universal.setText(" ⏸ 暂停流程 ")
        self.btn_start_universal.setText(" 🛑 停止流程 ")
        self.log(f"🚀 自动化已启动，共 {len(tasks)} 个任务", "blue")
