    def handle_note_mode_change(self, is_floating):
        current_size = self.note_widget.size()
        if is_floating:
            # 记录当前屏幕位置，setParent(None) 后用于恢复
            current_pos = self.note_widget.mapToGlobal(QPoint(0, 0))
            self.sidebar.hide()
            # setParent(None) 使其成为独立顶层窗口，必须在 setWindowFlags 之前调用
            self.note_widget.setParent(None)
            self.note_widget.is_floating = True
            # 设置窗口标志（无边框、置顶）
            flags = _WindowType_Window | _FramelessWindow
            if self.note_widget.btn_pin.isChecked():
                flags |= _WindowStaysOnTop
            self.note_widget.setWindowFlags(flags)
            self.note_widget.resize(current_size)
            self.note_widget.move(current_pos)
            self.note_widget.show()
        else:
            # 从浮动恢复为嵌入式控件
            self.note_widget.hide()
            self.note_widget.setWindowFlags(_WidgetType)
            self.sidebar.layout().addWidget(self.note_widget)
            self.note_widget.is_floating = False
            self.sidebar.show()
            self.note_widget.show()
        self.trigger_save()
    def toggle_note_visibility(self):
        w = self.note_widget if self.note_widget.is_floating else self.sidebar
        w.setVisible(not w.isVisible())
        self.trigger_save()

    def toggle_log_visibility(self):
        """显示/隐藏主界面底部运行日志，释放更多垂直空间。"""
        if not hasattr(self, "log_container"):
            return
        visible = not self.log_container.isVisible()
        self.log_container.setVisible(visible)
        if hasattr(self, "btn_toggle_log") and self.btn_toggle_log:
            self.btn_toggle_log.setText("📜 隐藏日志" if visible else "📜 显示日志")
        self.trigger_save()
