        count_label.setStyleSheet("font-weight: bold; color: #0891b2; font-size: 13px;")
        count_layout.addWidget(count_label)
        count_layout.addStretch()
        count_layout.addWidget(QLabel("✂️ 英文分段字数:"))
        split_limit = QSpinBox(); split_limit.setRange(10, 2000)
        if split_limit_value is None:
            split_limit_value = getattr(self, "_last_heygen_split_limit", 100)
        split_limit_value = max(10, min(2000, int(split_limit_value or 100)))
        split_limit.setValue(split_limit_value)
        split_limit.setFixedWidth(70)
        def _on_split_limit_changed(val):
            self._last_heygen_split_limit = int(val)
            self.trigger_save()
        split_limit.valueChanged.connect(_on_split_limit_changed)
        count_layout.addWidget(split_limit)
        v_layout.addLayout(count_layout)

        table = ExcelTable(10, 6)
        table.setObjectName("heygen_table")
        table.setHorizontalHeaderLabels(["代码", "图片路径 (拖入/AI匹配)", "评分", "中文文案", "英文文案", "备注 (特殊要求)"])
        table.setColumnWidth(0, 80); table.setColumnWidth(1, 200); table.setColumnWidth(2, 120); table.setColumnWidth(3, 250); table.setColumnWidth(4, 250); table.setColumnWidth(5, 200)
        
        # 定义统计逻辑
        def _update_count():
            valid_rows = 0
            for r in range(table.rowCount()):
                # 放宽口径：代码、图片、中文文案，只要有一项有内容即视为有效
                it_code = table.item(r, 0); code = it_code.text().strip() if (it_code and it_code.text()) else ""
                it_img = table.item(r, 1); img = it_img.text().strip() if (it_img and it_img.text()) else ""
                it_cn = table.item(r, 3); cn = it_cn.text().strip() if (it_cn and it_cn.text()) else ""
                if code or img or cn:
                    valid_rows += 1
            count_label.setText(f"📊 已录入有效条数: {valid_rows}")
            # 实时同步全局总计
            self.update_global_total_count()

        table.cellChanged.connect(lambda: (_update_count(), self.trigger_save()))
