            rem_idx, ok4 = QInputDialog.getItem(dlg, "指定备注列", "请选择【备注/特殊要求】所在列：", ["不导入"] + cols, self._detected_remark_col + 1 if self._detected_remark_col != -1 else 0, False)
            if not ok4: return
            
            self._detected_code_col = cols.index(c_idx)
