    def get_universal_match_mode(self):
        if hasattr(self, "uni_match_mode_combo"):
            return str(self.uni_match_mode_combo.currentData() or "general")
        return "general"

    def get_universal_match_name_source_mode(self):
        if hasattr(self, "uni_match_name_source_combo"):
            return str(self.uni_match_name_source_combo.currentData() or "auto")
        return "auto"

    def get_universal_match_skip_existing_pairs(self):
        if hasattr(self, "uni_match_skip_existing_pairs_check"):
            return bool(self.uni_match_skip_existing_pairs_check.isChecked())
        return False

    def _on_universal_match_name_source_changed(self):
        self.trigger_save()
        self.refresh_universal_match_preview_names()

    def _detect_universal_match_name_kind(self, path):
        low_path = str(path or "").strip().lower()
        if not low_path:
            return ""
        if low_path.endswith(UniversalMatchThread.IMAGE_EXTS):
            return "image"
        if low_path.endswith(UniversalMatchThread.VIDEO_EXTS):
            return "video"
        if low_path.endswith(UniversalMatchThread.AUDIO_EXTS):
            return "audio"
        text_exts = (".txt", ".srt", ".vtt", ".lrc", ".md")
        if low_path.endswith(text_exts):
            return "text"
        return ""

    def _build_universal_match_name_candidates(self, src_abs="", res_abs="", rename_name=""):
        candidates = {}

        def _stem(path):
            raw = str(path or "").strip()
            if not raw:
                return ""
            return os.path.splitext(os.path.basename(raw))[0].strip()

        src_stem = _stem(src_abs)
        res_stem = _stem(res_abs)
        src_kind = self._detect_universal_match_name_kind(src_abs)
        res_kind = self._detect_universal_match_name_kind(res_abs)
        text_name = str(rename_name or "").strip()

        if src_stem:
            candidates["source"] = src_stem
            if src_kind and src_kind not in candidates:
                candidates[src_kind] = src_stem
        if res_stem and res_kind and res_kind not in candidates:
            candidates[res_kind] = res_stem
        if text_name:
            candidates["text"] = text_name
        return candidates

    def _choose_universal_match_name(self, src_abs="", res_abs="", rename_name="", mode_override=""):
        candidates = self._build_universal_match_name_candidates(src_abs=src_abs, res_abs=res_abs, rename_name=rename_name)
        mode = str(mode_override or self.get_universal_match_mode() or "general")
        pref = self.get_universal_match_name_source_mode()
        if mode == "audio_text":
            auto_order = ["text", "video", "audio", "image", "source"]
        else:
            auto_order = ["source", "image", "video", "audio", "text"]
        lead_order = {
            "image": ["image"],
            "video": ["video"],
            "text": ["text"],
        }.get(pref, [])
        order = lead_order + [k for k in auto_order if k not in lead_order]
        seen = set()
        for key in order:
            if key in seen:
                continue
            seen.add(key)
            val = str(candidates.get(key, "") or "").strip()
            if val:
                return val
        for val in candidates.values():
            val = str(val or "").strip()
            if val:
                return val
        return ""

    def refresh_universal_match_preview_names(self):
        matches = getattr(self, "_last_universal_match_results", None)
        kind = str(getattr(self, "_last_universal_match_result_kind", "") or "").strip()
        if not matches:
            return
        if kind == "general":
            self.display_universal_match_results(matches)
        elif kind == "audio_text":
            self.display_video_copy_match_results(matches)

