    def install_faster_whisper_for_match(self):
        ok = _silent_install_libs(["faster_whisper"], timeout=1200, log_prefix="[ASR]")
        if ok:
            QMessageBox.information(self, "安装完成", "faster-whisper 已安装完成，现在可以直接执行音频/视频对白对文本匹配。")
            self.log("[音频转写] ✅ faster-whisper 安装完成", "green")
        else:
            QMessageBox.warning(self, "安装失败", "faster-whisper 自动安装失败。请检查网络或权限，或稍后重试。")
            self.log("[音频转写] ❌ faster-whisper 自动安装失败", "red")

    def run_universal_match(self):
        src = self.uni_match_src_input.text().strip(); res = self.uni_match_res_input.text().strip()
        if not src or not res: QMessageBox.warning(self, "提示", "请设置参考文件和待匹配目录"); return
        pipeline_cfg = self._get_named_ai_config("pipeline") if hasattr(self, "_get_named_ai_config") else {}
        clip_model_name = str((pipeline_cfg or {}).get("clip_model", "OFA-Sys/chinese-clip-vit-large-patch14") or "OFA-Sys/chinese-clip-vit-large-patch14")
        clip_use_gpu = bool((pipeline_cfg or {}).get("clip_use_gpu", True))
        self.uni_match_table.setRowCount(0); self.uni_progress_bar.setValue(0)
        self.log(f"[全能对位] ⚡ 启动多模态匹配 (CLIP: {clip_model_name})", "blue")
        self.uni_match_thread = UniversalMatchThread(
            src,
            res,
            clip_model_name=clip_model_name,
            clip_use_gpu=clip_use_gpu,
            name_source_mode=self.get_universal_match_name_source_mode()
        )
        self.uni_match_thread.progress.connect(self.uni_progress_bar.setValue); self.uni_match_thread.log.connect(self.log); self.uni_match_thread.result.connect(self.display_universal_match_results); self.uni_match_thread.start()

    def run_video_copy_match(self):
        src = self.uni_match_src_input.text().strip()
        res = self.uni_match_res_input.text().strip()
        raw_copy = self.uni_match_copy_edit.toPlainText().strip() if hasattr(self, "uni_match_copy_edit") else ""
        media_source = res or src
        text_source = src or res
        if not media_source:
            QMessageBox.warning(self, "提示", "请先设置音频/视频来源；你也可以直接拖一个同时含视频和 txt 的总文件夹")
            return
        separate_by_subfolder = bool(self.uni_match_split_subfolder_check.isChecked()) if hasattr(self, "uni_match_split_subfolder_check") else False
        skip_existing_pairs = self.get_universal_match_skip_existing_pairs()
        raw_copy_items = build_copy_items_from_sources(
            text_source,
            raw_copy,
            dedup_scope=("folder" if separate_by_subfolder else "global")
        )
        copy_items = filter_numeric_named_copy_items(raw_copy_items)
        if not copy_items:
            QMessageBox.warning(self, "提示", "没有找到可比对的数字命名文本。当前模式只会匹配像 1.txt、2.txt 这样的纯数字文件名。")
            return
        skipped_non_numeric = max(0, len(raw_copy_items) - len(copy_items))
        if skipped_non_numeric > 0:
            self.log(f"[音频文案匹配] 已忽略 {skipped_non_numeric} 个非数字命名文本文件；当前只匹配纯数字 txt。", "orange")
        pipeline_cfg = self._get_named_ai_config("pipeline") if hasattr(self, "_get_named_ai_config") else {}
        clip_model_name = str((pipeline_cfg or {}).get("clip_model", "OFA-Sys/chinese-clip-vit-large-patch14") or "OFA-Sys/chinese-clip-vit-large-patch14")
        clip_use_gpu = bool((pipeline_cfg or {}).get("clip_use_gpu", True))
        self.uni_match_table.setRowCount(0); self.uni_progress_bar.setValue(0)
        self.log("[音频文案匹配] ⚡ 启动：将先转写音频/视频，再按文本内容匹配，并使用 txt 文件名命名，不自动生成字幕", "blue")
        ai_cfg = self._get_named_ai_config("pipeline")
        ai_cfg = dict(ai_cfg if isinstance(ai_cfg, dict) else {})
        ai_cfg["audio_transcribe_local_model"] = self.uni_match_asr_model_combo.currentText().strip() or "small"
        self.uni_copy_match_thread = VideoCopyMatchThread(
            media_source,
            copy_items,
            clip_model_name=clip_model_name,
            clip_use_gpu=clip_use_gpu,
            ai_config=ai_cfg,
            separate_by_subfolder=separate_by_subfolder,
            skip_existing_pairs=skip_existing_pairs
        )
        self.uni_copy_match_thread.progress.connect(self.uni_progress_bar.setValue)
        self.uni_copy_match_thread.log.connect(self.log)
        self.uni_copy_match_thread.result.connect(self.display_video_copy_match_results)
        self.uni_copy_match_thread.error.connect(lambda msg: (self.log(msg, "red"), QMessageBox.critical(self, "文案匹配失败", msg)))
        self.uni_copy_match_thread.start()

