        self.uni_srt_export_thread.log.connect(self.log)
        self.uni_srt_export_thread.result.connect(self.display_video_copy_match_results)
        self.uni_srt_export_thread.error.connect(lambda msg: (self.log(msg, "red"), QMessageBox.critical(self, "SRT生成失败", msg)))
        self.uni_srt_export_thread.start()

