    def _append_universal_match_row(self, src_label, res_label, score_value, src_abs="", res_abs="", rename_name="", tooltip="", srt_label="", srt_abs="", txt_label="", txt_abs=""):
        row = self.uni_match_table.rowCount()
        self.uni_match_table.insertRow(row)
        display_name = str(src_label or rename_name or "")
        stored_rename_name = str(rename_name or src_label or "")
        it_src = QTableWidgetItem(display_name)
        it_res = QTableWidgetItem(str(res_label or ""))
        it_score = QTableWidgetItem(str(score_value))
        it_srt = QTableWidgetItem(str(srt_label or ""))
        it_txt = QTableWidgetItem(str(txt_label or ""))
        it_src.setData(_UserRole, src_abs)
        it_src.setData(_UserRole + 1, stored_rename_name)
        it_src.setData(_UserRole + 2, srt_abs or "")
        it_src.setData(_UserRole + 3, txt_abs or "")
        it_res.setData(_UserRole, res_abs)
        if tooltip:
            try:
                it_src.setToolTip(str(tooltip))
            except Exception:
                pass
        if srt_abs:
            try:
                it_srt.setData(_UserRole, srt_abs)
                it_srt.setToolTip(str(srt_abs))
            except Exception:
                pass
        if txt_abs:
            try:
                it_txt.setData(_UserRole, txt_abs)
                it_txt.setToolTip(str(txt_abs))
            except Exception:
                pass
        self.uni_match_table.setItem(row, 0, it_src)
        self.uni_match_table.setItem(row, 1, it_res)
        self.uni_match_table.setItem(row, 2, it_score)
        self.uni_match_table.setItem(row, 3, it_srt)
        self.uni_match_table.setItem(row, 4, it_txt)

    def display_universal_match_results(self, matches):
        self._last_universal_match_results = list(matches or [])
        self._last_universal_match_result_kind = "general"
        self.uni_progress_bar.setValue(100)
        self.uni_match_table.setRowCount(0); src_base = self.uni_match_src_input.text().split('\n')[0]; res_base = self.uni_match_res_input.text().split('\n')[0]
        src_base = src_base if os.path.isdir(src_base) else os.path.dirname(src_base); res_base = res_base if os.path.isdir(res_base) else os.path.dirname(res_base)
        rename_name_counts = {}
        for m in matches:
            try: src_rel = os.path.relpath(m['src'], src_base); res_rel = os.path.relpath(m['res'], res_base)
            except: src_rel = os.path.basename(m['src']); res_rel = os.path.basename(m['res'])
            base_rename_name = self._choose_universal_match_name(
                src_abs=m.get('src', ''),
                res_abs=m.get('res', ''),
                rename_name="",
                mode_override="general"
            ) or os.path.splitext(os.path.basename(m.get('src', '') or src_rel))[0]
            res_ext = os.path.splitext(str(m.get('res', '') or res_rel))[1]
            # 命名去重应当“按目标所在文件夹”独立计数：
            # 否则 A 文件夹里已经出现过 1.mp4，会导致 B 文件夹里第一个 1.mp4 直接变成 1_2.mp4（用户会觉得很怪）。
            # 同时扩展名不同的文件允许同名（1.mp4 与 1.wav 不冲突）。
            try:
                res_dir_key = os.path.dirname(os.path.abspath(str(m.get('res', '') or ''))).lower()
            except Exception:
                res_dir_key = ""
            count_key = (res_dir_key, str(base_rename_name or ""), str(res_ext or "").lower())
            seq = rename_name_counts.get(count_key, 0) + 1
            rename_name_counts[count_key] = seq
            rename_name = base_rename_name if seq == 1 else f"{base_rename_name}_{seq}"
            display_name = f"{rename_name}{res_ext}" if rename_name and res_ext else (rename_name or src_rel)
            tooltip = f"来源：{src_rel}\n目标：{res_rel}"
            self._append_universal_match_row(display_name, res_rel, m.get('score', ''), src_abs=m.get('src', ''), res_abs=m.get('res', ''), rename_name=rename_name, tooltip=tooltip, srt_label="", srt_abs="", txt_label="", txt_abs="")

    def display_video_copy_match_results(self, matches):
        self._last_universal_match_results = list(matches or [])
        self._last_universal_match_result_kind = "audio_text"
        self.uni_progress_bar.setValue(100)
        self.uni_match_table.setRowCount(0)
        res_base = self.uni_match_res_input.text().split('\n')[0]
        res_base = res_base if os.path.isdir(res_base) else os.path.dirname(res_base)
        name_pref = self.get_universal_match_name_source_mode()
        for m in matches:
            try:
                res_rel = os.path.relpath(m['res'], res_base)
            except Exception:
                res_rel = os.path.basename(m['res'])
            srt_abs = str(m.get('srt_path', '') or '').strip()
            if srt_abs:
                try:
                    srt_rel = os.path.relpath(srt_abs, res_base)
                except Exception:
                    srt_rel = os.path.basename(srt_abs)
            else:
                srt_rel = ""
            txt_abs = str(m.get('txt_path', '') or '').strip()
            if txt_abs:
                try:
                    txt_rel = os.path.relpath(txt_abs, res_base)
                except Exception:
                    txt_rel = os.path.basename(txt_abs)
            else:
                txt_rel = ""
            raw_text_name = str(m.get('rename_name', '') or m.get('src_label', '') or '').strip()
            if name_pref == "text" and not srt_abs and not txt_abs and raw_text_name:
                base_rename_name = raw_text_name
            else:
                base_rename_name = self._choose_universal_match_name(
                    src_abs=m.get('src', ''),
                    res_abs=m.get('res', ''),
                    rename_name=raw_text_name,
                    mode_override="audio_text"
                )
            rename_name = base_rename_name or raw_text_name
            res_ext = os.path.splitext(str(m.get('res', '') or res_rel))[1]
            is_rename_preview = bool(rename_name) and not srt_abs and not txt_abs
            display_label = f"{rename_name}{res_ext}" if is_rename_preview and res_ext else (rename_name if is_rename_preview else (m.get('src_label', '') or rename_name))
            tooltip = str(m.get('tooltip', '') or '').strip()
            duplicate_note = str(m.get("duplicate_note", "") or "").strip()
            if duplicate_note and duplicate_note not in tooltip:
                tooltip = f"{duplicate_note}\n\n{tooltip}" if tooltip else duplicate_note
            self._append_universal_match_row(
                display_label,
                res_rel,
                m.get('score', ''),
                src_abs="",
                res_abs=m.get('res', ''),
                rename_name=rename_name,
                tooltip=tooltip,
                srt_label=srt_rel,
                srt_abs=srt_abs,
                txt_label=txt_rel,
                txt_abs=txt_abs
            )

    def _resolve_universal_match_abs_path(self, item, base_input_text=""):
        raw_path = ""
        try:
            raw_path = str(item.data(_UserRole) or "").strip()
        except Exception:
            raw_path = ""
        if raw_path and os.path.exists(raw_path):
            return os.path.abspath(raw_path)

        label = ""
        try:
            label = str(item.text() or "").strip()
        except Exception:
            label = ""
        if not label:
            return raw_path

        candidates = []
        if os.path.isabs(label):
            candidates.append(label)
        else:
            input_paths = [p.strip() for p in str(base_input_text or "").split('\n') if p.strip()]
            for p in input_paths:
                if os.path.isdir(p):
                    candidates.append(os.path.join(p, label))
                else:
                    candidates.append(os.path.join(os.path.dirname(p), label))
            candidates.append(label)

        seen = set()
        for cand in candidates:
            cand_abs = os.path.abspath(cand)
            if cand_abs in seen:
                continue
            seen.add(cand_abs)
            if os.path.exists(cand_abs):
                return cand_abs
        return os.path.abspath(raw_path) if raw_path else label

    def rename_matched_universal(self):
        count = 0
        skipped = 0
        failed = 0
        rows = []

        def _abs(path):
            return os.path.abspath(str(path or "").strip())

        def _find_available_target_path(preferred_path, reserved_paths=None, movable_source_paths=None, collision_source_path="", prefer_text_repeat=False):
            reserved = set(_abs(p) for p in (reserved_paths or set()) if str(p or "").strip())
            movable = set(_abs(p) for p in (movable_source_paths or set()) if str(p or "").strip())
            candidate = _abs(preferred_path)
            if not ((os.path.exists(candidate) and candidate not in movable) or candidate in reserved):
                return candidate
            folder = os.path.dirname(candidate)
            target_stem, ext = os.path.splitext(os.path.basename(candidate))
            collision_stem = ""
            try:
                collision_stem = clean_long_filename(
                    os.path.splitext(os.path.basename(str(collision_source_path or "").strip()))[0],
                    max_len=40
                ).strip()
            except Exception:
                collision_stem = ""
            collision_stem = collision_stem or "原名"
            seq = 1
            while True:
                if prefer_text_repeat:
                    if seq == 1:
                        merged_stem = clean_long_filename(f"重复[{target_stem}]", max_len=120).strip()
                    else:
                        merged_stem = clean_long_filename(f"重复{seq}[{target_stem}]", max_len=120).strip()
                else:
                    if seq == 1:
                        merged_stem = clean_long_filename(f"{target_stem}[{collision_stem}]", max_len=120).strip()
                    else:
                        merged_stem = clean_long_filename(f"{target_stem}[{collision_stem}-{seq}]", max_len=120).strip()
                merged_stem = merged_stem or (f"重复[{target_stem}]" if prefer_text_repeat else f"{target_stem}[{collision_stem}]")
                candidate = os.path.join(folder, f"{merged_stem}{ext}")
                if not ((os.path.exists(candidate) and candidate not in movable) or candidate in reserved):
                    break
                seq += 1
            return candidate

        def _make_temp_path(src_path):
            folder = os.path.dirname(src_path)
            _, ext = os.path.splitext(src_path)
            while True:
                candidate = os.path.join(folder, f".__rename_tmp__{uuid.uuid4().hex}{ext}")
                if not os.path.exists(candidate):
                    return candidate

        for i in range(self.uni_match_table.rowCount()):
            it_src = self.uni_match_table.item(i, 0); it_res = self.uni_match_table.item(i, 1)
            if not it_src or not it_res: continue
            src_abs = self._resolve_universal_match_abs_path(it_src, self.uni_match_src_input.text())
            res_abs = self._resolve_universal_match_abs_path(it_res, self.uni_match_res_input.text())
            if not os.path.exists(res_abs):
                skipped += 1
                self.log(f"[全能对位] 跳过第 {i+1} 行：找不到目标文件 -> {res_abs}", "orange")
                continue
            rename_name = str(it_src.data(_UserRole + 1) or "").strip()
            if not rename_name:
                rename_name = str(it_src.text() or "").strip()
            if not rename_name and src_abs:
                rename_name = os.path.splitext(os.path.basename(str(src_abs)))[0]
            if not rename_name and res_abs:
                rename_name = os.path.splitext(os.path.basename(str(res_abs)))[0]
            src_name = clean_long_filename(rename_name, 120)
            res_dir = os.path.dirname(res_abs); res_ext = os.path.splitext(res_abs)[1]; desired_main = os.path.join(res_dir, f"{src_name}{res_ext}")
            srt_path = str(it_src.data(_UserRole + 2) or "").strip()
            txt_path = str(it_src.data(_UserRole + 3) or "").strip()
            rows.append({
                "row": i,
                "it_src": it_src,
                "it_res": it_res,
                "it_srt": self.uni_match_table.item(i, 3),
                "it_txt": self.uni_match_table.item(i, 4),
                "src_abs": _abs(src_abs),
                "res_abs": _abs(res_abs),
                "desired_main": _abs(desired_main),
                "final_main": "",
                "srt_path": _abs(srt_path) if srt_path and os.path.exists(srt_path) else "",
                "txt_path": _abs(txt_path) if txt_path and os.path.exists(txt_path) else "",
                "final_srt": "",
                "final_txt": "",
            })

        if not rows:
            self.log(f"[全能对位] 重命名完成，成功处理 {count} 个文件；跳过 {skipped} 个；失败 {failed} 个", "green")
            return

        prefer_text_repeat = self.get_universal_match_mode() == "audio_text"
        main_source_paths = {_abs(item["res_abs"]) for item in rows}
        reserved_main_paths = set()
        for item in rows:
            if item["res_abs"] == item["desired_main"]:
                item["final_main"] = item["desired_main"]
                reserved_main_paths.add(item["final_main"])
                skipped += 1
                self.log(f"[全能对位] 第 {item['row']+1} 行无需重命名：{os.path.basename(item['res_abs'])}", "gray")

        planned_main_paths = set(reserved_main_paths)
        for item in rows:
            if item["final_main"]:
                continue
            item["final_main"] = _find_available_target_path(
                item["desired_main"],
                reserved_paths=planned_main_paths,
                movable_source_paths=main_source_paths,
                collision_source_path=item["res_abs"],
                prefer_text_repeat=prefer_text_repeat
            )
            planned_main_paths.add(item["final_main"])

        for support_key, ext in [("srt_path", ".srt"), ("txt_path", ".txt")]:
            source_paths = {_abs(item.get(support_key, "")) for item in rows if item.get(support_key)}
            reserved_paths = set()
            final_key = "final_srt" if support_key == "srt_path" else "final_txt"
            for item in rows:
                src_path = item.get(support_key, "")
                if not src_path:
                    continue
                desired_path = os.path.splitext(item["final_main"])[0] + ext
                if _abs(src_path) == _abs(desired_path):
                    item[final_key] = _abs(desired_path)
                    reserved_paths.add(item[final_key])
            planned_paths = set(reserved_paths)
            for item in rows:
                src_path = item.get(support_key, "")
                if not src_path or item.get(final_key):
                    continue
                desired_path = os.path.splitext(item["final_main"])[0] + ext
                item[final_key] = _find_available_target_path(
                    desired_path,
                    reserved_paths=planned_paths,
                    movable_source_paths=source_paths,
                    collision_source_path=src_path
                )
                planned_paths.add(item[final_key])

        try:
            main_moves = []
            for item in rows:
                if item["res_abs"] == item["final_main"]:
                    continue
                temp_path = _make_temp_path(item["res_abs"])
                os.rename(item["res_abs"], temp_path)
                main_moves.append((item, temp_path))
            for item, temp_path in main_moves:
                os.rename(temp_path, item["final_main"])
                item["it_res"].setText(os.path.basename(item["final_main"]))
                item["it_res"].setData(_UserRole, item["final_main"])
                count += 1
        except Exception as e:
            failed += 1
            self.log(f"主文件重命名失败: {e}", "red")

        for support_key, final_key, role_offset, item_key, label in [
            ("srt_path", "final_srt", 2, "it_srt", "SRT"),
            ("txt_path", "final_txt", 3, "it_txt", "TXT"),
        ]:
            try:
                support_moves = []
                for item in rows:
                    src_path = item.get(support_key, "")
                    final_path = item.get(final_key, "")
                    if not src_path or not final_path or src_path == final_path:
                        continue
                    temp_path = _make_temp_path(src_path)
                    os.rename(src_path, temp_path)
                    support_moves.append((item, temp_path, final_path))
                for item, temp_path, final_path in support_moves:
                    os.rename(temp_path, final_path)
                    item["it_src"].setData(_UserRole + role_offset, final_path)
                    table_item = item.get(item_key)
                    if table_item:
                        table_item.setText(os.path.basename(final_path))
                        table_item.setData(_UserRole, final_path)
                        table_item.setToolTip(final_path)
            except Exception as e:
                failed += 1
                self.log(f"{label} 同步重命名失败: {e}", "orange")
        self.log(f"[全能对位] 重命名完成，成功处理 {count} 个文件；跳过 {skipped} 个；失败 {failed} 个", "green")
