    def creator_parse_quick_input(self):
        """把“快速输入”解析为文件夹名列表并写入表格。"""
        if not hasattr(self, "creator_quick_input") or not hasattr(self, "creator_table"):
            return
        raw = self.creator_quick_input.toPlainText().strip()
        if not raw:
            QMessageBox.information(self, "提示", "快速输入为空：请先粘贴文件夹名（支持 A1-A10 / 多行 / 逗号空格分隔）。")
            return
        try:
            names = self._extract_folder_names_quick(raw)
        except Exception:
            names = []
        if not names:
            QMessageBox.warning(self, "提示", "未识别到任何可用的文件夹名。")
            return
        self.creator_table.blockSignals(True)
        try:
            self.creator_table.setRowCount(max(10, len(names)))
            for i, n in enumerate(names):
                self.creator_table.setItem(i, 0, QTableWidgetItem(str(n)))
        finally:
            self.creator_table.blockSignals(False)
        self.log(f"[批量建文件夹] 已解析 {len(names)} 个名称到表格。", "blue")
        self.trigger_save()

    def creator_daily_import_from_template(self):
        """把上方“子文件夹模板”快速复制到“每日自动模板”。"""
        if not hasattr(self, "creator_template_input") or not hasattr(self, "creator_daily_items_input"):
            return
        text = self.creator_template_input.toPlainText().strip()
        self.creator_daily_items_input.setPlainText(text)
        self.log("[批量建文件夹] 已把上方模板复制到“每日自动模板”。", "blue")
        self.trigger_save()
