    def _normalize_ai_prompt_library(self, items):
        normalized = []
        for raw in items or []:
            if not isinstance(raw, dict):
                continue
            title = str(raw.get("title", "") or "").strip()
            content = str(raw.get("content", "") or "").strip()
            if not title or not content:
                continue
            normalized.append({
                "category": str(raw.get("category", "未分类") or "未分类").strip() or "未分类",
                "title": title,
                "content": content
            })
        return normalized

    def _update_ai_workflow_summary_label(self):
        if not hasattr(self, "chat_workflow_summary_label"):
            return
        profile = self._get_ai_workflow_profile()
        base = profile.get("today_folder") or profile.get("default_work_root") or "未设置工作目录"
        safe_base = str(base or "")
        if safe_base and safe_base != "未设置工作目录":
            safe_base = safe_base.rstrip("/\\")
            safe_base = os.path.basename(safe_base) or safe_base
        label = f"工作流：{safe_base or '未设置工作目录'}"
        extras = []
        if profile.get("prefer_clip_first", True):
            extras.append("CLIP优先")
        if profile.get("confirm_before_run", True):
            extras.append("执行前确认")
        if extras:
            label += " · " + " / ".join(extras)
        self.chat_workflow_summary_label.setText(label)

    def show_ai_workflow_dialog(self):
        dlg = QDialog(self)
        dlg.setWindowTitle("工作流设置")
        dlg.setMinimumSize(620, 260)
        layout = QVBoxLayout(dlg)
        form = QGridLayout()
        form.addWidget(QLabel("默认工作目录"), 0, 0)
        work_root_edit = QLineEdit(self.ai_default_work_root_input.text().strip())
        work_root_edit.setPlaceholderText("默认工作文件夹 / 项目根目录")
        form.addWidget(work_root_edit, 0, 1)
        btn_root = QPushButton("浏览")
        btn_root.clicked.connect(lambda: self.browse_dir(work_root_edit))
        form.addWidget(btn_root, 0, 2)
        form.addWidget(QLabel("今日工作目录"), 1, 0)
        today_edit = QLineEdit(self.ai_today_folder_input.text().strip())
        today_edit.setPlaceholderText("今天要处理的目录，不填则可后续从聊天里指定")
        form.addWidget(today_edit, 1, 1)
        row_btn = QHBoxLayout()
        btn_today = QPushButton("今日目录")
        btn_today.clicked.connect(lambda: today_edit.setText(self._default_today_work_folder()))
        row_btn.addWidget(btn_today)
        btn_attach = QPushButton("附加到对话")
        btn_attach.clicked.connect(lambda: self.add_chat_attachments([today_edit.text().strip() or work_root_edit.text().strip()]) if (today_edit.text().strip() or work_root_edit.text().strip()) else QMessageBox.information(dlg, "提示", "请先填写一个有效目录。"))
        row_btn.addWidget(btn_attach)
        row_btn.addStretch()
        form.addLayout(row_btn, 1, 2)
        layout.addLayout(form)
        clip_check = QCheckBox("批量选图优先 CLIP，不走 API")
        clip_check.setChecked(self.ai_clip_first_check.isChecked())
        layout.addWidget(clip_check)
        confirm_check = QCheckBox("执行自动化前先确认")
        confirm_check.setChecked(self.ai_confirm_before_run_check.isChecked())
        layout.addWidget(confirm_check)
        layout.addStretch()
        if PYQT_VERSION == 6:
            btn_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        else:
            btn_box = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        layout.addWidget(btn_box)

        def _save():
            self.ai_default_work_root_input.setText(work_root_edit.text().strip())
            self.ai_today_folder_input.setText(today_edit.text().strip())
            self.ai_clip_first_check.setChecked(clip_check.isChecked())
            self.ai_confirm_before_run_check.setChecked(confirm_check.isChecked())
            self.ai_workflow_profile = self._get_ai_workflow_profile()
            self._update_ai_workflow_summary_label()
            self.trigger_save()
            dlg.accept()

        btn_box.accepted.connect(_save)
        btn_box.rejected.connect(dlg.reject)
        if PYQT_VERSION == 6:
            dlg.exec()
        else:
            dlg.exec_()

    def _refresh_ai_prompt_library_ui(self):
        if not hasattr(self, "ai_prompt_category_combo") or not hasattr(self, "ai_prompt_item_combo"):
            return
        current_category = self.ai_prompt_category_combo.currentText().strip()
        categories = ["全部"] + sorted({str(item.get("category", "未分类") or "未分类").strip() or "未分类" for item in self.ai_prompt_library})
        self.ai_prompt_category_combo.blockSignals(True)
        self.ai_prompt_category_combo.clear()
        self.ai_prompt_category_combo.addItems(categories)
        idx = self.ai_prompt_category_combo.findText(current_category) if current_category else 0
        self.ai_prompt_category_combo.setCurrentIndex(max(0, idx))
        self.ai_prompt_category_combo.blockSignals(False)
        self._refresh_ai_prompt_items()

    def _refresh_ai_prompt_items(self):
        if not hasattr(self, "ai_prompt_item_combo"):
            return
        current_category = self.ai_prompt_category_combo.currentText().strip() if hasattr(self, "ai_prompt_category_combo") else "全部"
        items = []
        for item in self.ai_prompt_library:
            category = str(item.get("category", "未分类") or "未分类").strip() or "未分类"
            if current_category not in ("", "全部") and category != current_category:
                continue
            items.append(item)
        self.ai_prompt_item_combo.clear()
        for item in items:
            self.ai_prompt_item_combo.addItem(item.get("title", "未命名"), item)

    def _insert_selected_ai_prompt(self):
        if not hasattr(self, "ai_prompt_item_combo") or self.ai_prompt_item_combo.count() <= 0:
            return
        item = self.ai_prompt_item_combo.currentData()
        if not isinstance(item, dict):
            return
        prompt_text = str(item.get("content", "") or "")
        current = self.chat_input.toPlainText()
        if current.strip():
            self.chat_input.setPlainText(prompt_text.rstrip() + "\n\n" + current)
        else:
            self.chat_input.setPlainText(prompt_text)
        self.chat_input.setFocus()

    def _refresh_local_command_library_ui(self):
        if not hasattr(self, "ai_local_cmd_module_combo") or not hasattr(self, "ai_local_cmd_item_combo"):
            return
        self.ai_local_command_library = self._default_local_command_library()
        current_module = self.ai_local_cmd_module_combo.currentText().strip()
        modules = ["全部"] + sorted({str(item.get("module", "未分类") or "未分类").strip() or "未分类" for item in self.ai_local_command_library})
        self.ai_local_cmd_module_combo.blockSignals(True)
        self.ai_local_cmd_module_combo.clear()
        self.ai_local_cmd_module_combo.addItems(modules)
        idx = self.ai_local_cmd_module_combo.findText(current_module) if current_module else 0
        self.ai_local_cmd_module_combo.setCurrentIndex(max(0, idx))
        self.ai_local_cmd_module_combo.blockSignals(False)
        self._refresh_local_command_items()

    def _refresh_local_command_items(self):
        if not hasattr(self, "ai_local_cmd_item_combo"):
            return
        current_module = self.ai_local_cmd_module_combo.currentText().strip() if hasattr(self, "ai_local_cmd_module_combo") else "全部"
        items = []
        for item in getattr(self, "ai_local_command_library", []) or []:
            module = str(item.get("module", "未分类") or "未分类").strip() or "未分类"
            if current_module not in ("", "全部") and module != current_module:
                continue
            items.append(item)
        self.ai_local_cmd_item_combo.clear()
        for item in items:
            self.ai_local_cmd_item_combo.addItem(item.get("title", "未命名"), item)

    def _apply_selected_local_command_to_input(self, replace=False):
        if not hasattr(self, "ai_local_cmd_item_combo") or self.ai_local_cmd_item_combo.count() <= 0:
            return False
        item = self.ai_local_cmd_item_combo.currentData()
        if not isinstance(item, dict):
            return False
        cmd_text = str(item.get("content", "") or "").strip()
        if not cmd_text:
            return False
        current = self.chat_input.toPlainText()
        if replace or not current.strip():
            self.chat_input.setPlainText(cmd_text)
        else:
            self.chat_input.setPlainText(cmd_text.rstrip() + "\n\n" + current)
        self.chat_input.setFocus()
        return True

    def _insert_selected_local_command(self):
        self._apply_selected_local_command_to_input(replace=False)

    def _send_selected_local_command(self):
        if not self._apply_selected_local_command_to_input(replace=True):
            return
        self.send_chat_message()

    def _open_ai_prompt_library_dialog(self):
        dlg = QDialog(self)
        dlg.setWindowTitle("提示词库管理")
        dlg.resize(820, 520)
        layout = QHBoxLayout(dlg)

        left = QVBoxLayout()
        list_widget = QListWidget()
        left.addWidget(list_widget, 1)
        left_btns = QHBoxLayout()
        btn_new = QPushButton("新增")
        btn_delete = QPushButton("删除")
        left_btns.addWidget(btn_new)
        left_btns.addWidget(btn_delete)
        left.addLayout(left_btns)
        layout.addLayout(left, 1)

        right = QVBoxLayout()
        form = QGridLayout()
        form.addWidget(QLabel("分类"), 0, 0)
        category_edit = QLineEdit()
        form.addWidget(category_edit, 0, 1)
        form.addWidget(QLabel("标题"), 1, 0)
        title_edit = QLineEdit()
        form.addWidget(title_edit, 1, 1)
        right.addLayout(form)
        content_edit = QTextEdit()
        content_edit.setPlaceholderText("在这里输入提示词正文")
        right.addWidget(content_edit, 1)
        right_btns = QHBoxLayout()
        btn_save_item = QPushButton("保存当前")
        right_btns.addWidget(btn_save_item)
        right_btns.addStretch()
        right.addLayout(right_btns)
        layout.addLayout(right, 2)

        temp_items = [dict(item) for item in self.ai_prompt_library]
        current_index = {"value": -1}

        def _refresh_list(select_idx=None):
            list_widget.clear()
            for item in temp_items:
                list_widget.addItem(f"[{item.get('category', '未分类')}] {item.get('title', '未命名')}")
            if temp_items:
                final_idx = 0 if select_idx is None else max(0, min(select_idx, len(temp_items) - 1))
                list_widget.setCurrentRow(final_idx)
            else:
                current_index["value"] = -1
                category_edit.clear()
                title_edit.clear()
                content_edit.clear()

        def _load_current():
            idx = list_widget.currentRow()
            current_index["value"] = idx
            if not (0 <= idx < len(temp_items)):
                return
            item = temp_items[idx]
            category_edit.setText(item.get("category", "未分类"))
            title_edit.setText(item.get("title", ""))
            content_edit.setPlainText(item.get("content", ""))

        def _new_item():
            temp_items.append({"category": "未分类", "title": "新提示词", "content": ""})
            _refresh_list(len(temp_items) - 1)
            title_edit.selectAll()
            title_edit.setFocus()

        def _save_item():
            idx = list_widget.currentRow()
            if idx < 0:
                _new_item()
                idx = list_widget.currentRow()
            title = title_edit.text().strip()
            content = content_edit.toPlainText().strip()
            category = category_edit.text().strip() or "未分类"
            if not title:
                QMessageBox.information(dlg, "提示", "标题不能为空。")
                return
            if not content:
                QMessageBox.information(dlg, "提示", "提示词内容不能为空。")
                return
            temp_items[idx] = {"category": category, "title": title, "content": content}
            _refresh_list(idx)

        def _delete_item():
            idx = list_widget.currentRow()
            if not (0 <= idx < len(temp_items)):
                return
            temp_items.pop(idx)
            _refresh_list(min(idx, len(temp_items) - 1))

        btn_new.clicked.connect(_new_item)
        btn_delete.clicked.connect(_delete_item)
        btn_save_item.clicked.connect(_save_item)
        list_widget.currentRowChanged.connect(lambda *_: _load_current())

        if PYQT_VERSION == 6:
            btn_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        else:
            btn_box = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        right.addWidget(btn_box)

        def _accept():
            if title_edit.text().strip() or content_edit.toPlainText().strip():
                idx = list_widget.currentRow()
                if idx >= 0:
                    _save_item()
            self.ai_prompt_library = self._normalize_ai_prompt_library(temp_items)
            if not self.ai_prompt_library:
                self.ai_prompt_library = self._default_ai_prompt_library()
            self._refresh_ai_prompt_library_ui()
            self.trigger_save()
            dlg.accept()

        btn_box.accepted.connect(_accept)
        btn_box.rejected.connect(dlg.reject)
        _refresh_list(0 if temp_items else None)
        if PYQT_VERSION == 6:
            dlg.exec()
        else:
            dlg.exec_()

    def _default_today_work_folder(self):
        try:
            home = os.path.expanduser("~")
            downloads = os.path.join(home, "Downloads")
            return os.path.join(downloads, datetime.now().strftime("%Y-%m-%d"))
        except Exception:
            return datetime.now().strftime("%Y-%m-%d")

    def _get_ai_workflow_profile(self):
        profile = {
            "default_work_root": self.ai_default_work_root_input.text().strip() if hasattr(self, "ai_default_work_root_input") else "",
            "today_folder": self.ai_today_folder_input.text().strip() if hasattr(self, "ai_today_folder_input") else "",
            "prefer_clip_first": self.ai_clip_first_check.isChecked() if hasattr(self, "ai_clip_first_check") else True,
            "confirm_before_run": self.ai_confirm_before_run_check.isChecked() if hasattr(self, "ai_confirm_before_run_check") else True
        }
        self.ai_workflow_profile = profile
        return profile

    def _apply_ai_workflow_profile(self, data):
        data = data or {}
        if hasattr(self, "ai_default_work_root_input"):
            self.ai_default_work_root_input.setText(data.get("default_work_root", ""))
        if hasattr(self, "ai_today_folder_input"):
            self.ai_today_folder_input.setText(data.get("today_folder", ""))
        if hasattr(self, "ai_clip_first_check"):
            self.ai_clip_first_check.setChecked(bool(data.get("prefer_clip_first", True)))
        if hasattr(self, "ai_confirm_before_run_check"):
            self.ai_confirm_before_run_check.setChecked(bool(data.get("confirm_before_run", True)))
        self.ai_workflow_profile = self._get_ai_workflow_profile()
        self._update_ai_workflow_summary_label()

    def _attach_default_workflow_folder(self):
        path = self.ai_today_folder_input.text().strip() or self.ai_default_work_root_input.text().strip()
        if not path:
            QMessageBox.information(self, "提示", "请先在左侧填写默认工作目录或今日工作目录。")
            return
        self.add_chat_attachments([path])

    def _new_chat_session(self, title="新对话"):
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        return {
            "id": uuid.uuid4().hex,
            "title": title,
            "created_at": now,
            "updated_at": now,
            "messages": [],
            "chat_api_name": ""
        }

    def _normalize_chat_attachments(self, attachments):
        result = []
        for att in attachments or []:
            if isinstance(att, str):
                path = att
                kind = "folder" if os.path.isdir(path) else "file"
                result.append({"name": os.path.basename(path) or path, "path": path, "kind": kind})
                continue
            if not isinstance(att, dict):
                continue
            path = str(att.get("path", "") or "").strip()
            if not path:
                continue
            kind = att.get("kind") or ("folder" if os.path.isdir(path) else "file")
            result.append({
                "name": att.get("name") or os.path.basename(path) or path,
                "path": path,
                "kind": kind
            })
        return result

    def _normalize_chat_messages(self, messages):
        normalized = []
        for msg in messages or []:
            if not isinstance(msg, dict):
                continue
            role = msg.get("role", "user")
            if role not in ("user", "assistant"):
                role = "user"
            content = msg.get("content", "")
            if isinstance(content, (dict, list)):
                content = json.dumps(content, ensure_ascii=False)
            normalized.append({
                "id": msg.get("id") or uuid.uuid4().hex,
                "role": role,
                "content": str(content or ""),
                "ts": msg.get("ts", ""),
                "status": msg.get("status", "done"),
                "attachments": self._normalize_chat_attachments(msg.get("attachments", [])),
                "reply_to": msg.get("reply_to"),
                "raw_text": str(msg.get("raw_text", content or "")),
                "render_md": bool(msg.get("render_md", role == "assistant"))
            })
        return normalized

    def _normalize_ai_conversations(self, conversations):
        normalized = []
        for idx, conv in enumerate(conversations or []):
            if not isinstance(conv, dict):
                continue
            conv_id = conv.get("id") or uuid.uuid4().hex
            title = str(conv.get("title") or f"新对话 {idx+1}").strip()
            created_at = conv.get("created_at") or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            updated_at = conv.get("updated_at") or created_at
            normalized.append({
                "id": conv_id,
                "title": title,
                "created_at": created_at,
                "updated_at": updated_at,
                "messages": self._normalize_chat_messages(conv.get("messages", [])),
                "chat_api_name": str(conv.get("chat_api_name", "") or "").strip()
            })
        return normalized

    def _ensure_ai_chat_ready(self):
        self.ai_conversations = self._normalize_ai_conversations(getattr(self, "ai_conversations", []))
        if not self.ai_conversations:
            self.ai_conversations = [self._new_chat_session()]
        chat_ids = {c["id"] for c in self.ai_conversations}
        if self.current_chat_id not in chat_ids:
            self.current_chat_id = self.ai_conversations[0]["id"]
        self.refresh_chat_session_list()
        self.render_current_chat()

    def _get_current_chat(self):
        for conv in getattr(self, "ai_conversations", []):
            if conv.get("id") == getattr(self, "current_chat_id", None):
                return conv
        return None

    def _get_available_chat_api_nodes(self):
        assistant_cfg = self._get_named_ai_config("assistant")
        pool = normalize_api_pool(assistant_cfg)
        enabled = [dict(item) for item in pool if item.get("enabled", True)]
        return enabled or [dict(item) for item in pool]

    def _describe_current_chat_api_route(self, conv=None):
        conv = conv or self._get_current_chat()
        assistant_cfg = self._get_named_ai_config("assistant")
        if str(assistant_cfg.get("mode", "api") or "api").lower() != "api":
            mode = str(assistant_cfg.get("mode", "api") or "api").lower()
            mode_text = {"local": "本地模型", "clip": "CLIP 极速模式"}.get(mode, "当前引擎")
            return f"当前模式：{mode_text}"
        forced_name = str((conv or {}).get("chat_api_name", "") or "").strip()
        if forced_name:
            return f"当前路由：只走 [{forced_name}]"
        global_mode = get_api_source_mode(assistant_cfg, "pool")
        if global_mode == "single":
            active = str(assistant_cfg.get("active_api_name", "") or "").strip()
            return f"当前路由：只走全局固定节点 [{active or '未指定'}]"
        if get_api_provider_strategy(assistant_cfg, "ordered") == "random" or get_api_pool_strategy(assistant_cfg, "ordered") == "random":
            return "当前路由：跟随全局 API 节点池（随机切换）"
        return "当前路由：跟随全局 API 节点池"

    def _refresh_chat_api_selector(self):
        if not hasattr(self, "chat_api_selector"):
            return
        conv = self._get_current_chat()
        current_name = str((conv or {}).get("chat_api_name", "") or "").strip()
        nodes = self._get_available_chat_api_nodes()
        self.chat_api_selector.blockSignals(True)
        self.chat_api_selector.clear()
        self.chat_api_selector.addItem("跟随全局配置", "")
        for item in nodes:
            name = item.get("name", "未命名节点")
            self.chat_api_selector.addItem(f"只走节点：{name}", name)
        idx = self.chat_api_selector.findData(current_name)
        self.chat_api_selector.setCurrentIndex(idx if idx >= 0 else 0)
        assistant_cfg = self._get_named_ai_config("assistant")
        is_api_mode = str(assistant_cfg.get("mode", "api") or "api").lower() == "api"
        self.chat_api_selector.setEnabled(is_api_mode and self.chat_api_selector.count() > 1)
        self.chat_api_selector.blockSignals(False)
        if hasattr(self, "chat_api_route_label"):
            self.chat_api_route_label.setText(self._describe_current_chat_api_route(conv))

    def _on_chat_api_selector_changed(self):
        conv = self._get_current_chat()
        if not conv or not hasattr(self, "chat_api_selector"):
            return
        conv["chat_api_name"] = str(self.chat_api_selector.currentData() or "").strip()
        conv["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self._refresh_chat_api_selector()
        self.trigger_save()

    def _build_chat_ai_config(self, conv=None):
        conv = conv or self._get_current_chat()
        cfg = dict(self._get_named_ai_config("assistant"))
        forced_name = str((conv or {}).get("chat_api_name", "") or "").strip()
        if forced_name and str(cfg.get("mode", "api") or "api").lower() == "api":
            cfg["api_source_mode"] = "single"
            cfg["active_api_name"] = forced_name
        return cfg

    def _find_message(self, conv, message_id):
        if not conv:
            return None, -1
        for idx, msg in enumerate(conv.get("messages", [])):
            if msg.get("id") == message_id:
                return msg, idx
        return None, -1

    def _make_chat_title_from_text(self, text):
        text = " ".join((text or "").split())
        if not text:
            return "新对话"
        return text[:18] + ("..." if len(text) > 18 else "")

    def refresh_chat_session_list(self):
        if not hasattr(self, "chat_session_list"):
            return
        self.chat_session_list.blockSignals(True)
        self.chat_session_list.clear()
        current_row = -1
        for idx, conv in enumerate(self.ai_conversations):
            item = QListWidgetItem(conv.get("title", f"新对话 {idx+1}"))
            item.setData(_UserRole, conv.get("id"))
            preview = ""
            if conv.get("messages"):
                preview = conv["messages"][-1].get("content", "")
            item.setToolTip((preview or "空白对话")[:160])
            self.chat_session_list.addItem(item)
            if conv.get("id") == self.current_chat_id:
                current_row = idx
        if current_row >= 0:
            self.chat_session_list.setCurrentRow(current_row)
        self.chat_session_list.blockSignals(False)

    def switch_chat_session(self, item):
        if not item:
            return
        chat_id = item.data(_UserRole)
        if not chat_id:
            return
        self.current_chat_id = chat_id
        self.render_current_chat()
        self.trigger_save()

    def create_new_chat(self):
        conv = self._new_chat_session(f"新对话 {len(self.ai_conversations) + 1}")
        self.ai_conversations.insert(0, conv)
        self.current_chat_id = conv["id"]
        self.refresh_chat_session_list()
        self.render_current_chat()
        self.chat_input.clear()
        self.chat_editing_message_id = None
        self._clear_pending_attachments()
        self.chat_input.setFocus()
        self.trigger_save()

    def rename_current_chat(self):
        conv = self._get_current_chat()
        if not conv:
            return
        new_title, ok = QInputDialog.getText(self, "重命名对话", "请输入新的对话名称：", text=conv.get("title", ""))
        if not ok:
            return
        new_title = new_title.strip()
        if not new_title:
            return
        conv["title"] = new_title
        conv["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.refresh_chat_session_list()
        self.render_current_chat()
        self.trigger_save()

    def delete_current_chat(self):
        conv = self._get_current_chat()
        if not conv:
            return
        if len(self.ai_conversations) == 1:
            self.ai_conversations = [self._new_chat_session()]
        else:
            self.ai_conversations = [c for c in self.ai_conversations if c.get("id") != conv.get("id")]
        self.current_chat_id = self.ai_conversations[0]["id"]
        self.refresh_chat_session_list()
        self.render_current_chat()
        self.trigger_save()

    def clear_current_chat_messages(self):
        conv = self._get_current_chat()
        if not conv:
            return
        conv["messages"] = []
        conv["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.chat_editing_message_id = None
        self.render_current_chat()
        self.refresh_chat_session_list()
        self.trigger_save()

    def _append_message_to_chat(self, conv, role, content, attachments=None, status="done", reply_to=None, raw_text=None):
        if not conv:
            return None
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        msg = {
            "id": uuid.uuid4().hex,
            "role": role,
            "content": str(content or ""),
            "raw_text": str(raw_text if raw_text is not None else content or ""),
            "ts": now,
            "status": status,
            "attachments": self._normalize_chat_attachments(attachments),
            "reply_to": reply_to,
            "render_md": role == "assistant"
        }
        conv.setdefault("messages", []).append(msg)
        conv["updated_at"] = now
        if role == "user" and len(conv["messages"]) == 1:
            conv["title"] = self._make_chat_title_from_text(msg["content"])
        return msg

    def _compose_message_for_ai(self, msg):
        text = str(msg.get("content", "") or "")
        attachments = self._normalize_chat_attachments(msg.get("attachments", []))
        blocks = [text.strip()]
        attachment_texts = [summarize_attachment_for_ai(att) for att in attachments]
        attachment_texts = [part for part in attachment_texts if part.strip()]
        if attachment_texts:
            blocks.append("【附件上下文】\n" + "\n\n".join(attachment_texts))
        if msg.get("role") == "user":
            note_context = self._build_note_context_for_chat(text)
            if note_context:
                blocks.append(note_context)
        return "\n\n".join([b for b in blocks if b.strip()])

    def _resolve_note_tab_for_chat(self, text):
        if not hasattr(self, "note_widget") or not is_alive(self.note_widget):
            return None, ""
        tabs = getattr(self.note_widget, "tabs", None)
        if not tabs:
            return None, ""
        raw = str(text or "").strip()
        if not raw:
            return None, ""
        if any(k in raw for k in ["当前便签", "这个便签", "本便签"]):
            table = tabs.currentWidget()
            return table, tabs.tabText(tabs.currentIndex()) if table else ""
        m = re.search(r"便签\s*([0-9]+)", raw)
        if m:
            idx = int(m.group(1)) - 1
            if 0 <= idx < tabs.count():
                return tabs.widget(idx), tabs.tabText(idx)
        compact = re.sub(r"\s+", "", raw)
        for i in range(tabs.count()):
            name = tabs.tabText(i)
            if name and (name in raw or re.sub(r"\s+", "", name) in compact):
                return tabs.widget(i), name
        return None, ""

    def _table_to_chat_text(self, table, max_rows=60, max_cols=6):
        if not table:
            return ""
        lines = []
        row_count = min(table.rowCount(), max_rows)
        col_count = min(table.columnCount(), max_cols)
        for row in range(row_count):
            cells = []
            for col in range(col_count):
                item = table.item(row, col)
                val = item.text().strip() if item else ""
                if val:
                    cells.append(val)
            if cells:
                lines.append(" | ".join(cells))
        return "\n".join(lines)

    def _note_page_to_chat_text(self, note_page):
        if not note_page:
            return ""
        table = note_page
        text_edit = None
        if hasattr(self, "note_widget") and is_alive(self.note_widget) and hasattr(self.note_widget, "_get_note_parts"):
            table, text_edit = self.note_widget._get_note_parts(note_page)
        table_text = self._table_to_chat_text(table)
        long_text = ""
        if text_edit and is_alive(text_edit):
            long_text = text_edit.toPlainText().strip()
        blocks = []
        if table_text:
            blocks.append("【表格计划】\n" + table_text)
        if long_text:
            blocks.append("【文本备注】\n" + long_text)
        return "\n\n".join(blocks)

    def _build_note_context_for_chat(self, text):
        if not any(k in str(text or "") for k in ["便签", "计划", "待办", "todo"]):
            return ""
        note_page, tab_name = self._resolve_note_tab_for_chat(text)
        if not note_page:
            return ""
        note_text = self._note_page_to_chat_text(note_page)
        if not note_text:
            return ""
        return f"【便签上下文：{tab_name or '当前便签'}】\n{note_text}"

    def _ensure_note_panel_visible(self):
        if not hasattr(self, "note_widget") or not is_alive(self.note_widget):
            return False
        try:
            if getattr(self.note_widget, "is_floating", False):
                self.note_widget.show()
                self.note_widget.raise_()
                self.note_widget.activateWindow()
            else:
                self.sidebar.show()
                if hasattr(self, "splitter") and is_alive(self.splitter):
                    sizes = self.splitter.sizes()
                    if len(sizes) >= 2 and sizes[1] <= 10:
                        total = max(960, self.width() or 960)
                        self.splitter.setSizes([max(620, total - 320), 320])
        except Exception:
            pass
        return True

    def _get_or_create_note_page_for_command(self, text, create_if_missing=True):
        if not hasattr(self, "note_widget") or not is_alive(self.note_widget):
            return None, ""
        tabs = getattr(self.note_widget, "tabs", None)
        if not tabs:
            return None, ""
        note_page, tab_name = self._resolve_note_tab_for_chat(text)
        if note_page:
            try:
                tabs.setCurrentWidget(note_page)
            except Exception:
                pass
            if not tab_name:
                idx = tabs.indexOf(note_page)
                tab_name = tabs.tabText(idx) if idx >= 0 else ""
            return note_page, tab_name
        current = tabs.currentWidget()
        if current:
            return current, tabs.tabText(tabs.currentIndex())
        if create_if_missing:
            self.note_widget.add_new_tab("今日计划")
            current = tabs.currentWidget()
            if current:
                return current, tabs.tabText(tabs.currentIndex())
        return None, ""

    def _ensure_note_table_columns(self, table, column_count):
        if not table:
            return
        try:
            target_cols = max(3, int(column_count or 3))
        except Exception:
            target_cols = 3
        while table.columnCount() < target_cols:
            table.insertColumn(table.columnCount())
        if hasattr(table, "update_headers"):
            table.update_headers()

    def _append_plan_items_to_note_page(self, note_page, items, source="聊天指令"):
        if not note_page or not items:
            return 0
        table = note_page
        text_edit = None
        if hasattr(self, "note_widget") and is_alive(self.note_widget) and hasattr(self.note_widget, "_get_note_parts"):
            table, text_edit = self.note_widget._get_note_parts(note_page)
        if not is_alive(table):
            return 0
        self._ensure_note_table_columns(table, 5)
        added = 0
        table.blockSignals(True)
        try:
            for item in items:
                content = str(item.get("content", "") or "").strip()
                if not content:
                    continue
                row = table.rowCount()
                table.insertRow(row)
                table.setItem(row, 0, QTableWidgetItem("DONE" if item.get("done") else ""))
                table.setItem(row, 1, QTableWidgetItem(content))
                table.setItem(row, 2, QTableWidgetItem(str(item.get("deadline", "") or "").strip()))
                table.setItem(row, 3, QTableWidgetItem(str(item.get("priority", "中") or "中").strip()))
                table.setItem(row, 4, QTableWidgetItem(str(item.get("source", source) or source).strip()))
                for col in range(5, table.columnCount()):
                    if not table.item(row, col):
                        table.setItem(row, col, QTableWidgetItem(""))
                added += 1
        finally:
            table.blockSignals(False)
        if hasattr(table, "update_headers"):
            table.update_headers()
        return added

    def _append_text_to_note_page(self, note_page, text):
        if not note_page:
            return False
        table = note_page
        text_edit = None
        if hasattr(self, "note_widget") and is_alive(self.note_widget) and hasattr(self.note_widget, "_get_note_parts"):
            table, text_edit = self.note_widget._get_note_parts(note_page)
        if not (text_edit and is_alive(text_edit)):
            return False
        safe_text = str(text or "").strip()
        if not safe_text:
            return False
        existing = text_edit.toPlainText().rstrip()
        text_edit.setPlainText((existing + "\n\n" if existing else "") + safe_text)
        return True

    def _extract_note_command_payload(self, text):
        raw = str(text or "").strip()
        if not raw:
            return ""
        lines = raw.splitlines()
        first_line = lines[0].strip() if lines else ""
        note_cmd_keys = ["写到便签", "写进便签", "记到便签", "记录到便签", "加入便签", "添加到便签", "追加到便签", "保存到便签", "同步到便签"]
        if len(lines) > 1 and any(k in first_line for k in note_cmd_keys):
            payload = "\n".join(lines[1:]).strip()
            if payload:
                return payload
        payload = raw
        payload = re.sub(r"^\s*(请|麻烦你|帮我|帮忙)?\s*", "", payload)
        payload = re.sub(r"^\s*(把|将)\s*", "", payload)
        payload = re.sub(r"\s*(写到|写进|记到|记录到|加入|添加到|追加到|保存到|同步到)(当前|这个|本)?便签(?:\s*[0-9]+)?\s*$", "", payload)
        return payload.strip(" ：:，,。；;")

    # ─────────────────────────────────────────────
    #  深度联动：本地指令路由器（模块调用）
    # ─────────────────────────────────────────────
    def _ai_confirm(self, title, detail, default_yes=True):
        """AI 触发本地执行前的统一确认逻辑（可在工作流设置里关闭确认）。"""
        try:
            if not self._get_ai_workflow_profile().get("confirm_before_run", True):
                return True
        except Exception:
            pass
        try:
            buttons = QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
            default_btn = QMessageBox.StandardButton.Yes if default_yes else QMessageBox.StandardButton.No
            reply = QMessageBox.question(self, title, detail, buttons, default_btn)
            return reply == QMessageBox.StandardButton.Yes
        except Exception:
            return True

    def _normalize_cmd(self, text):
        raw = str(text or "")
        raw = raw.replace("：", ":").replace("＝", "=").replace("，", ",").replace("；", ";")
        return raw.strip()

    def _parse_kv_args(self, text):
        """
        解析简易参数：支持 key=value / key: value / key=多行。
        返回 dict，key 会被归一化到小写英文。
        """
        t = self._normalize_cmd(text)
        args = {}
        if not t:
            return args
        # 多行优先：逐行找 key=...
        for line in t.splitlines():
            s = line.strip()
            if not s:
                continue
            m = re.match(r"^\s*([A-Za-z\u4e00-\u9fff_]{1,12})\s*[:=]\s*(.+?)\s*$", s)
            if not m:
                continue
            k = str(m.group(1) or "").strip().lower()
            v = str(m.group(2) or "").strip()
            if k and v:
                args[k] = v
        # 单行兜底：用空格/分号/逗号切
        if not args:
            parts = re.split(r"[;,\s]+", t)
            for p in parts:
                if "=" in p or ":" in p:
                    kv = re.split(r"[:=]", p, maxsplit=1)
                    if len(kv) == 2:
                        k = kv[0].strip().lower()
                        v = kv[1].strip()
                        if k and v:
                            args[k] = v
        # 中文 key 映射
        key_map = {
            "源": "src", "来源": "src", "源目录": "src", "目录": "src", "路径": "src",
            "目标": "dst", "结果": "dst", "输出": "out", "输出目录": "out",
            "参考": "ref", "参考源": "ref", "参考文件": "ref",
            "待匹配": "dst", "待改名": "dst",
            "位置": "base", "创建位置": "base",
            "规则": "rules", "递归": "recursive",
            "项目": "project", "项目名": "project",
            "csv": "csv"
        }
        normalized = {}
        for k, v in args.items():
            nk = key_map.get(k, k)
            normalized[nk] = v
        return normalized

    def _resolve_quick_base_dir(self, raw_text, args, candidate_paths):
        """
        为“建文件夹”类口令解析创建位置：
        1) 显式参数：base/out/src/dst
        2) 附件里的第一个目录
        3) 口令中出现“下载/下载目录/默认下载目录”→ ~/Downloads
        4) 口令中出现“今日目录/今天”→ 优先用工作流设置里的“今日工作目录”，否则 ~/Downloads/YYYY-MM-DD
        5) 工作流设置：今日目录 / 默认工作目录
        """
        raw = str(raw_text or "")
        compact = re.sub(r"\s+", "", raw).lower()

        base = args.get("base") or args.get("out") or args.get("dst") or args.get("src") or ""
        if not base:
            base = next((p for p in candidate_paths if os.path.isdir(p)), "") or ""
        if base:
            # 允许在口令里写“{date} / ${HOME} / ~”等变量
            return render_path_template(base)

        # 约定俗成的“下载目录”
        def _downloads_dir():
            try:
                home = os.path.expanduser("~")
                return os.path.join(home, "Downloads")
            except Exception:
                return ""

        if any(k in compact for k in ["默认下载目录", "下载目录", "下载文件夹", "downloads", "download"]):
            return _downloads_dir()

        if any(k in compact for k in ["今日目录", "今天目录", "今日文件夹", "今天文件夹", "今天"]):
            try:
                profile = self._get_ai_workflow_profile()
                today = str(profile.get("today_folder", "") or "").strip()
                if today:
                    return today
            except Exception:
                pass
            try:
                home = os.path.expanduser("~")
                downloads = os.path.join(home, "Downloads")
                return os.path.join(downloads, datetime.now().strftime("%Y-%m-%d"))
            except Exception:
                return datetime.now().strftime("%Y-%m-%d")

        # 工作流默认目录兜底
        try:
            profile = self._get_ai_workflow_profile()
            today = str(profile.get("today_folder", "") or "").strip()
            root = str(profile.get("default_work_root", "") or "").strip()
            return today or root or ""
        except Exception:
            return ""

    def _expand_folder_name_range(self, token):
        """
        展开范围写法：
        - A1-A10 / A1~A10 / A1到A10 / A1至A10
        - 01-10（会生成 01..10）
        仅当两端“前缀一致”时展开，如 A1-B10 不展开。
        """
        t = str(token or "").strip()
        if not t:
            return []
        t = t.replace("～", "~").replace("—", "-").replace("－", "-").replace("到", "-").replace("至", "-")
        m = re.match(r"^\s*([A-Za-z\u4e00-\u9fff_]*)(\d+)\s*[-~]\s*([A-Za-z\u4e00-\u9fff_]*)(\d+)\s*$", t)
        if not m:
            return []
        p1, n1, p2, n2 = m.group(1), m.group(2), m.group(3), m.group(4)
        if (p1 or "") != (p2 or ""):
            return []
        try:
            a = int(n1); b = int(n2)
        except Exception:
            return []
        if a == b:
            return [f"{p1}{n1}"]
        step = 1 if b >= a else -1
        width = max(len(n1), len(n2))
        out = []
        for i in range(a, b + step, step):
            out.append(f"{p1}{i:0{width}d}" if width > 1 else f"{p1}{i}")
            if len(out) >= 5000:
                break
        return out

    def _extract_folder_names_quick(self, raw_text):
        """
        从一句话或多行中尽量“宽松地”提取文件夹名：
        - 支持：建A1-A10 / 创建 A1 A2 A3 / 新建 文件夹A,文件夹B
        - 多行时：自动忽略 base= / 位置= 这类参数行
        """
        raw = str(raw_text or "")
        names = []
        for line in raw.splitlines():
            s = line.strip()
            if not s:
                continue
            # 参数行跳过
            if re.match(r"^[A-Za-z\u4e00-\u9fff_]{1,12}\s*[:=]", s):
                continue
            # 带“建/创建/新建/生成/做”动词的行，先去掉前缀动词
            s = re.sub(r"^\s*(在.+?)?(批量)?(新建|创建|建立|生成|建)(文件夹|目录)?\s*", "", s)
            s = s.strip(" ：:，,。；;")
            if not s:
                continue

            # 先按逗号/空格/分号切，再对每个 token 做范围展开
            parts = [p for p in re.split(r"[;,，\s]+", s) if p.strip()]
            for p in parts:
                p = p.strip().strip(" -•*")
                if not p:
                    continue
                expanded = self._expand_folder_name_range(p)
                if expanded:
                    names.extend(expanded)
                else:
                    names.append(p)

        # 去重但保序
        seen = set()
        uniq = []
        for n in names:
            nn = str(n or "").strip()
            if not nn or nn in seen:
                continue
            seen.add(nn)
            uniq.append(nn)
        return uniq[:5000]

    def _match_main_module(self, raw_text):
        raw = str(raw_text or "").strip()
        if not raw:
            return None, ""
        mapping = [
            (["ai助手", "智能助手", "对话助手", "聊天"], getattr(self, "ai_assistant_tab", None), "AI 智能助手"),
            (["素材整理", "汇总预览", "图文审核", "图片库存", "项目"], getattr(self, "heygen_tab", None), "素材整理与汇总预览"),
            (["智能匹配", "全能对位", "匹配名字"], getattr(self, "universal_match_tab", None), "智能匹配 / 视频对位"),
            (["视频对位", "极速对位", "深度匹配"], getattr(self, "universal_match_tab", None), "智能匹配 / 视频对位"),
            (["自动分类", "分类"], getattr(self, "sorter_tab", None), "自动分类"),
            (["建文件夹", "批量建文件夹", "批量创建文件夹"], getattr(self, "creator_tab", None), "批量建文件夹"),
            (["批量重命名", "重命名"], getattr(self, "renamer_tab", None), "批量重命名"),
            (["水印", "视频水印", "批量水印"], getattr(self, "watermark_tab", None), "批量视频水印")
        ]
        compact = re.sub(r"\s+", "", raw).lower()
        for keys, tab, name in mapping:
            for k in keys:
                if k in compact:
                    return tab, name
        return None, ""

    def _parse_sorter_rules_block(self, raw_text):
        """
        解析分类规则块：
        - 每行格式： [模式] 关键词 => 目标文件夹
          例：包含 .jpg => 图片
              结尾是 .mp4 => 视频
              正则 (?i)abc => 命中
        """
        raw = str(raw_text or "")
        if "=>" not in raw and "->" not in raw:
            return []
        rules = []
        for line in raw.splitlines():
            s = line.strip()
            if not s:
                continue
            if "=>" in s:
                left, right = s.split("=>", 1)
            elif "->" in s:
                left, right = s.split("->", 1)
            else:
                continue
            left = left.strip()
            folder = right.strip().strip('"').strip("'")
            if not folder:
                continue
            mode = "包含"
            keyword = left
            m = re.match(r"^(包含|开头是|结尾是|后缀名|正则|正则表达式|精确匹配|完全匹配)\s+(.+)$", left)
            if m:
                mode = m.group(1).strip()
                keyword = m.group(2).strip()
            keyword = keyword.strip().strip('"').strip("'")
            if not keyword:
                continue
            rules.append({"p": keyword, "m": mode, "f": folder})
            if len(rules) >= 60:
                break
        return rules

    def _apply_sorter_rules_to_table(self, rules):
        if not hasattr(self, "sorter_table") or not is_alive(self.sorter_table):
            return 0
        tbl = self.sorter_table
        mode = self._get_sorter_mode()
        is_extension_mode = (self._get_sorter_rule_bucket(mode) == "extension")
        tbl.blockSignals(True)
        try:
            tbl.setHorizontalHeaderLabels(["扩展名", "匹配方式", "目标文件夹名"] if is_extension_mode else ["匹配关键词", "匹配模式", "目标文件夹名"])
            tbl.setRowCount(0)
            mode_items = ["包含", "开头是", "结尾是", "后缀名", "完全匹配", "正则表达式"]
            for idx, r in enumerate(rules or []):
                row = tbl.rowCount()
                tbl.insertRow(row)
                try:
                    if hasattr(tbl, "add_mode_combo"):
                        tbl.add_mode_combo(row)
                except Exception:
                    pass
                tbl.setItem(row, 0, QTableWidgetItem(r.get("p", "")))
                tbl.setItem(row, 2, QTableWidgetItem(r.get("f", "")))
                combo = tbl.cellWidget(row, 1)
                if combo and hasattr(combo, "setCurrentText"):
                    combo.blockSignals(True)
                    combo.clear()
                    combo.addItems(["后缀名"] if is_extension_mode else mode_items)
                    combo.setCurrentText("后缀名" if is_extension_mode else r.get("m", "包含"))
                    combo.setEnabled(not is_extension_mode)
                    combo.blockSignals(False)
            if tbl.rowCount() <= 0:
                for _ in range(5):
                    row = tbl.rowCount()
                    tbl.insertRow(row)
                    try:
                        if hasattr(tbl, "add_mode_combo"):
                            tbl.add_mode_combo(row)
                    except Exception:
                        pass
                    combo = tbl.cellWidget(row, 1)
                    if combo:
                        combo.blockSignals(True)
                        combo.clear()
                        combo.addItems(["后缀名"] if is_extension_mode else mode_items)
                        combo.setCurrentText("后缀名" if is_extension_mode else "包含")
                        combo.setEnabled(not is_extension_mode)
                        combo.blockSignals(False)
        finally:
            tbl.blockSignals(False)
        return len(rules or [])

    def _clone_sorter_rules(self, rules):
        cloned = []
        for rule in rules or []:
            if not isinstance(rule, dict):
                continue
            cloned.append({
                "p": str(rule.get("p", "") or "").strip(),
                "m": str(rule.get("m", "包含") or "包含").strip(),
                "f": str(rule.get("f", "") or "").strip(),
            })
        return cloned

    def _get_sorter_rule_bucket(self, mode=None):
        mode = str(mode or self._get_sorter_mode() or "comprehensive").strip()
        if mode in ("comprehensive", "custom_rule"):
            return "rule"
        if mode == "extension":
            return "extension"
        return ""

    def _sync_sorter_rule_cache_from_table(self, mode=None):
        bucket = self._get_sorter_rule_bucket(mode)
        if not bucket:
            return []
        rules = self._clone_sorter_rules(self._collect_sorter_rules())
        if not hasattr(self, "_sorter_rules_cache") or not isinstance(self._sorter_rules_cache, dict):
            self._sorter_rules_cache = {"rule": [], "extension": []}
        self._sorter_rules_cache[bucket] = rules
        return rules

    def _get_sorter_cached_rules(self, mode=None):
        bucket = self._get_sorter_rule_bucket(mode)
        if not bucket:
            return []
        if not hasattr(self, "_sorter_rules_cache") or not isinstance(self._sorter_rules_cache, dict):
            self._sorter_rules_cache = {"rule": [], "extension": []}
        return self._clone_sorter_rules(self._sorter_rules_cache.get(bucket, []))

    def _get_sorter_mode(self):
        if hasattr(self, "sorter_mode_combo") and is_alive(self.sorter_mode_combo):
            mode = self.sorter_mode_combo.currentData()
            if mode:
                return str(mode)
        return "comprehensive"

    def _get_sorter_mode_label(self, mode=None):
        mode = str(mode or self._get_sorter_mode() or "comprehensive")
        labels = {
            "comprehensive": "综合智能模式",
            "custom_rule": "自定义规则模式",
            "name_existing": "按文件名匹配现有文件夹",
            "filename_group": "按文件名前缀自动分组",
            "extension": "按扩展名自动分类",
            "time": "按时间自动分类",
            "flatten_to_root": "提取子文件夹文件到指定目录",
            "extract_incomplete_pairs": "提取配对检查文件夹（完整/缺失/手动检查）",
        }
        return labels.get(mode, mode)

    def _build_sorter_rules_from_heygen_projects(self):
        project_tabs = getattr(self, "project_tabs", {})
        if not isinstance(project_tabs, dict) or not project_tabs:
            return [], {"project_rule_count": 0, "code_rule_count": 0, "skipped_numeric_code_count": 0, "conflict_keywords": []}

        ordered_names = []
        if hasattr(self, "heygen_project_tabs") and is_alive(self.heygen_project_tabs):
            try:
                for i in range(self.heygen_project_tabs.count()):
                    name = str(self.heygen_project_tabs.tabText(i) or "").strip()
                    if name and name in project_tabs and name not in ordered_names:
                        ordered_names.append(name)
            except Exception:
                pass
        for name in list(project_tabs.keys()):
            pname = str(name or "").strip()
            if pname and pname not in ordered_names:
                ordered_names.append(pname)

        grouped = {}
        skipped_numeric_code_count = 0

        def _add_keyword(keyword, folder, source):
            keyword = str(keyword or "").strip()
            folder = self._sanitize_sort_folder_name(folder, fallback="")
            source = str(source or "").strip() or "code"
            if not keyword or not folder:
                return
            grouped.setdefault(keyword, [])
            key = (folder, source)
            if key in {(item.get("folder", ""), item.get("source", "")) for item in grouped[keyword]}:
                return
            grouped[keyword].append({"folder": folder, "source": source})

        for project_name in ordered_names:
            project_entry = project_tabs.get(project_name) or {}
            folder_name = self._sanitize_sort_folder_name(project_name, fallback="")
            if not folder_name:
                continue
            _add_keyword(project_name, folder_name, "project")

            table = project_entry.get("table")
            if not table or not is_alive(table):
                continue
            seen_codes_in_project = set()
            for row in range(table.rowCount()):
                code_item = table.item(row, 0)
                code_text = code_item.text().strip() if code_item and code_item.text() else ""
                if not code_text or code_text in seen_codes_in_project:
                    continue
                seen_codes_in_project.add(code_text)
                compact_code = re.sub(r"[\s._-]+", "", code_text)
                if compact_code.isdigit():
                    skipped_numeric_code_count += 1
                    continue
                _add_keyword(code_text, folder_name, "code")

        rules = []
        project_rule_count = 0
        code_rule_count = 0
        conflict_keywords = []
        for keyword, entries in grouped.items():
            folders = {str(item.get("folder", "") or "").strip() for item in entries if str(item.get("folder", "") or "").strip()}
            if not folders:
                continue
            chosen = None
            if len(folders) == 1:
                project_entries = [item for item in entries if item.get("source") == "project"]
                chosen = project_entries[0] if project_entries else entries[0]
            else:
                project_entries = [item for item in entries if item.get("source") == "project"]
                project_folders = {str(item.get("folder", "") or "").strip() for item in project_entries if str(item.get("folder", "") or "").strip()}
                if len(project_folders) == 1 and project_entries:
                    chosen = project_entries[0]
                else:
                    conflict_keywords.append({"keyword": keyword, "folders": sorted(folders)})
                    continue

            folder_name = str(chosen.get("folder", "") or "").strip()
            if not folder_name:
                continue
            rules.append({"p": keyword, "m": "开头是", "f": folder_name})
            if chosen.get("source") == "project":
                project_rule_count += 1
            else:
                code_rule_count += 1

        return rules, {
            "project_rule_count": project_rule_count,
            "code_rule_count": code_rule_count,
            "skipped_numeric_code_count": skipped_numeric_code_count,
            "conflict_keywords": conflict_keywords,
        }

    def import_sorter_rules_from_heygen(self):
        rules, stats = self._build_sorter_rules_from_heygen_projects()
        if not rules:
            msg = "素材整理模块里暂时没有可导入的项目名/代码名。请先填写项目，代码列若是纯数字会被自动跳过。"
            self.log(msg, "orange")
            QMessageBox.information(self, "提示", msg)
            return

        if self._get_sorter_mode() == "extension" and hasattr(self, "sorter_mode_combo") and is_alive(self.sorter_mode_combo):
            idx = self.sorter_mode_combo.findData("custom_rule")
            if idx >= 0:
                self.sorter_mode_combo.setCurrentIndex(idx)

        added = self._append_sorter_rules(rules, bucket="rule")
        existed_count = max(0, len(rules) - int(added or 0))
        conflict_keywords = stats.get("conflict_keywords", []) or []

        detail_parts = []
        if stats.get("project_rule_count"):
            detail_parts.append(f"项目名 {int(stats.get('project_rule_count', 0))} 条")
        if stats.get("code_rule_count"):
            detail_parts.append(f"代码名 {int(stats.get('code_rule_count', 0))} 条")
        if stats.get("skipped_numeric_code_count"):
            detail_parts.append(f"跳过纯数字代码 {int(stats.get('skipped_numeric_code_count', 0))} 条")
        if conflict_keywords:
            detail_parts.append(f"跳过冲突关键词 {len(conflict_keywords)} 组")
        if existed_count:
            detail_parts.append(f"已存在未重复追加 {existed_count} 条")
        detail_text = "；".join(detail_parts)

        if added:
            msg = f"已从素材整理导入 {added} 条分类规则。"
            if detail_text:
                msg += f"\n\n{detail_text}"
            if conflict_keywords:
                preview_lines = [f"- {item.get('keyword', '')} => {' / '.join(item.get('folders', []))}" for item in conflict_keywords[:8]]
                if preview_lines:
                    msg += "\n\n以下关键词因会指向多个目标文件夹，已自动跳过：\n" + "\n".join(preview_lines)
                if len(conflict_keywords) > 8:
                    msg += f"\n... 还有 {len(conflict_keywords) - 8} 组未展开"
            self.log(f"已从素材整理导入 {added} 条分类规则", "green")
            QMessageBox.information(self, "导入完成", msg)
            return

        msg = "素材整理里的可导入规则都已经在当前分类规则里了，无需重复追加。"
        if detail_text:
            msg += f"\n\n{detail_text}"
        self.log("素材整理命名已存在于当前分类规则中，无需重复导入。", "blue")
        QMessageBox.information(self, "提示", msg)

    def clear_sorter_rules(self):
        """
        清空当前规则区：
        - 综合智能/自定义规则：清空“关键词规则”
        - 扩展名模式：清空“扩展名映射”
        """
        mode = self._get_sorter_mode()
        bucket = self._get_sorter_rule_bucket(mode)
        if bucket not in ("rule", "extension"):
            msg = "当前模式没有可清空的规则区。请切到“自定义规则模式/综合智能模式/按扩展名自动分类”后再清空。"
            self.log(msg, "orange")
            QMessageBox.information(self, "提示", msg)
            return

        label = "关键词规则" if bucket == "rule" else "扩展名映射"
        reply = QMessageBox.question(
            self,
            "确认清空",
            f"确定要清空当前【{label}】吗？\n此操作会清空规则表格与已保存的规则缓存（下次启动也不会再出现）。",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )
        if reply != QMessageBox.StandardButton.Yes:
            return

        # 先同步一下，保证“清空”前的编辑不会造成怪异状态
        try:
            self._sync_sorter_rule_cache_from_table(mode)
        except Exception:
            pass

        if not hasattr(self, "_sorter_rules_cache") or not isinstance(self._sorter_rules_cache, dict):
            self._sorter_rules_cache = {"rule": [], "extension": []}
        self._sorter_rules_cache[bucket] = []

        # 若当前展示的就是这个 bucket，立即刷新表格为默认空行
        if self._get_sorter_rule_bucket(self._get_sorter_mode()) == bucket:
            self._apply_sorter_rules_to_table([])
        self.trigger_save()
        self.log(f"已清空 {label}", "blue")

