        if hasattr(self, "btn_sorter_clear_rules") and is_alive(self.btn_sorter_clear_rules):
            self.btn_sorter_clear_rules.setVisible(mode in ("comprehensive", "custom_rule", "extension"))
        if show_rule_box:
            self._apply_sorter_rules_to_table(self._get_sorter_cached_rules(mode))
        time_basis_text = self.sorter_time_basis_combo.currentText() if hasattr(self, "sorter_time_basis_combo") and is_alive(self.sorter_time_basis_combo) else "按修改时间"
        time_group_text = self.sorter_time_group_combo.currentText() if hasattr(self, "sorter_time_group_combo") and is_alive(self.sorter_time_group_combo) else "按年月"
        tips = {
            "comprehensive": "一键走多种策略：先规则，再按文件名进现有文件夹，再按文件名前缀成组，最后按扩展名兜底。",
            "custom_rule": "只按你表格里的规则执行，适合完全自定义分类。",
            "name_existing": "根据文件名和同级已存在文件夹名的相似度自动归类，不会先建新文件夹。",
            "filename_group": "自动识别同名前缀文件，开始前会先弹出预览，让你确认要建哪些分组文件夹。",
            "extension": "按文件后缀自动分类，可直接使用内置类型，也可用上方表格覆盖默认映射。",
            "time": f"按文件时间归档，当前设置：{time_basis_text}，{time_group_text}。",
            "flatten_to_root": "把子文件夹里的文件统一提取到你指定的新文件夹；可选提取后自动删除已清空的子文件夹。",
            "extract_incomplete_pairs": "扫描子文件夹中的纯数字 txt/视频配对情况，并把“完整”“缺失”“需手动检查”自动分开提取到目标目录。",
        }
        if hasattr(self, "sorter_mode_tip") and is_alive(self.sorter_mode_tip):
            self.sorter_mode_tip.setText(tips.get(mode, ""))
        if hasattr(self, "sorter_name_folder_check") and is_alive(self.sorter_name_folder_check):
            self.sorter_name_folder_check.blockSignals(True)
            self.sorter_name_folder_check.setChecked(mode in ("comprehensive", "name_existing"))
            self.sorter_name_folder_check.blockSignals(False)
        if hasattr(self, "sorter_filename_group_check") and is_alive(self.sorter_filename_group_check):
            self.sorter_filename_group_check.blockSignals(True)
