    def _collect_sorter_rules(self):
        rules = []
        if not hasattr(self, "sorter_table") or not is_alive(self.sorter_table):
            return rules
        for i in range(self.sorter_table.rowCount()):
            p = self.sorter_table.item(i, 0).text().strip() if self.sorter_table.item(i, 0) else ""
            m = self.sorter_table.cellWidget(i, 1).currentText() if self.sorter_table.cellWidget(i, 1) else "包含"
            f = self.sorter_table.item(i, 2).text().strip() if self.sorter_table.item(i, 2) else ""
            if p and f:
                rules.append({"p": p, "m": m, "f": f})
        return rules

    def _split_sort_extension_tokens(self, text):
        parts = re.split(r'[,，、;\s/|]+', str(text or "").strip())
        tokens = []
        for part in parts:
            token = str(part or "").strip().lower()
            if not token:
                continue
            if not token.startswith("."):
                token = f".{token}"
            if token not in tokens:
                tokens.append(token)
        return tokens

    def _match_sort_rule(self, fname, rule):
        fname = str(fname or "")
        pattern = str(rule.get("p", "") or "").strip()
        mode = str(rule.get("m", "包含") or "包含").strip()
        if not pattern:
            return False
        if mode == "包含":
            return pattern in fname
        if mode == "开头是":
            return fname.startswith(pattern)
        if mode == "结尾是":
            return fname.endswith(pattern)
        if mode == "后缀名":
            return os.path.splitext(fname)[1].lower() in self._split_sort_extension_tokens(pattern)
        if mode in ("正则", "正则表达式"):
            try:
                return bool(re.search(pattern, fname))
            except Exception:
                return False
        if mode in ("完全匹配", "精确匹配"):
            return pattern == fname
        return False

    def _resolve_sort_rule_target_dir(self, src_dir, root, folder_name):
        folder = self._sanitize_sort_folder_name(folder_name, fallback="")
        if not folder:
            return ""
        root_candidate = os.path.join(root, folder)
        if os.path.isdir(root_candidate):
            return root_candidate
        return os.path.join(src_dir, folder)

    def _find_extension_sort_target_dir(self, src_dir, fname, rules=None):
        ext = os.path.splitext(str(fname or ""))[1].lower()
        if rules:
            for rule in rules:
                folder = self._sanitize_sort_folder_name(rule.get("f", ""), fallback="")
                if folder and ext in self._split_sort_extension_tokens(rule.get("p", "")):
                    return os.path.join(src_dir, folder)
        built_in_map = {
            "图片": {".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".tif", ".tiff", ".heic"},
            "视频": {".mp4", ".mov", ".avi", ".mkv", ".wmv", ".flv", ".m4v", ".ts", ".webm"},
            "音频": {".mp3", ".wav", ".aac", ".flac", ".m4a", ".ogg", ".wma"},
            "表格": {".csv", ".xlsx", ".xls", ".xlsm"},
            "文档": {".txt", ".doc", ".docx", ".pdf", ".ppt", ".pptx", ".md", ".rtf"},
            "压缩包": {".zip", ".rar", ".7z", ".tar", ".gz", ".bz2"},
            "代码": {".py", ".pyw", ".js", ".ts", ".json", ".html", ".css", ".java", ".cpp", ".c", ".cs", ".php", ".go", ".rs", ".sql"},
        }
        if not ext:
            return os.path.join(src_dir, "无后缀")
        for folder_name, ext_set in built_in_map.items():
            if ext in ext_set:
                return os.path.join(src_dir, folder_name)
        return os.path.join(src_dir, "其他")

    def _build_time_sort_target_dir(self, src_dir, fpath):
        basis = self.sorter_time_basis_combo.currentData() if hasattr(self, "sorter_time_basis_combo") and is_alive(self.sorter_time_basis_combo) else "mtime"
        granularity = self.sorter_time_group_combo.currentData() if hasattr(self, "sorter_time_group_combo") and is_alive(self.sorter_time_group_combo) else "month"
        try:
            ts = os.path.getctime(fpath) if basis == "ctime" else os.path.getmtime(fpath)
        except Exception:
            ts = time.time()
        dt = datetime.fromtimestamp(ts)
        if granularity == "year":
            folder = dt.strftime("%Y年")
        elif granularity == "day":
            folder = dt.strftime("%Y-%m-%d")
        else:
            folder = dt.strftime("%Y-%m")
        return os.path.join(src_dir, folder)

    def _collect_flatten_sort_files(self, src_dir, recursive=True):
        src_dir = os.path.abspath(str(src_dir or "").strip())
        files_to_move = []
        if not src_dir or not os.path.isdir(src_dir):
            return files_to_move
        if recursive:
            for root, dirs, files in os.walk(src_dir):
                dirs[:] = self._filter_sort_subdirs(root, dirs, src_dir)
                if os.path.abspath(root) == src_dir:
                    continue
                for fname in files:
                    fpath = os.path.join(root, fname)
                    if os.path.isfile(fpath):
                        files_to_move.append(os.path.abspath(fpath))
        else:
            try:
                for name in os.listdir(src_dir):
                    sub_path = os.path.join(src_dir, name)
                    if not os.path.isdir(sub_path):
                        continue
                    if self._is_sorter_auto_managed_dir(sub_path):
                        continue
                    try:
                        for fname in os.listdir(sub_path):
                            fpath = os.path.join(sub_path, fname)
                            if os.path.isfile(fpath):
                                files_to_move.append(os.path.abspath(fpath))
                    except Exception:
                        continue
            except Exception:
                return []
        return files_to_move

    def _resolve_flatten_sort_target_dir(self, src_dir):
        src_dir = os.path.abspath(str(src_dir or "").strip())
        raw_target = ""
        if hasattr(self, "sorter_flatten_target_input") and is_alive(self.sorter_flatten_target_input):
            raw_target = str(self.sorter_flatten_target_input.text() or "").strip()
        if not raw_target:
            raw_target = "提取结果"
        if os.path.isabs(raw_target):
            return os.path.abspath(raw_target)
        folder_name = self._sanitize_sort_folder_name(raw_target, fallback="提取结果")
        return os.path.join(src_dir, folder_name or "提取结果")

    def _resolve_incomplete_pairs_target_dir(self, src_dir):
        """缺素材文件夹提取：自动避免重复套娃，只保留一层结果目录。"""
        src_dir = os.path.abspath(str(src_dir or "").strip())
        raw_target = ""
        if hasattr(self, "sorter_incomplete_target_input") and is_alive(self.sorter_incomplete_target_input):
            raw_target = str(self.sorter_incomplete_target_input.text() or "").strip()
        if raw_target:
            if os.path.isabs(raw_target):
                return os.path.abspath(raw_target)
            folder_name = self._sanitize_sort_folder_name(raw_target, fallback="配对检查结果")
            return os.path.join(src_dir, folder_name or "配对检查结果")
        if self._is_pair_status_bucket_dir(src_dir):
            return os.path.join(os.path.dirname(src_dir), "配对检查结果")
        if self._looks_like_pair_status_root(src_dir):
            return src_dir
        return os.path.join(src_dir, "配对检查结果")

    def _get_pair_status_bucket_names(self):
        return {"完整", "缺失", "需检查", "需手动检查", "手动检查"}

    def _get_pair_status_root_names(self):
        return {"配对检查结果", "配对结果", "配对结果文件夹"}

    def _get_pair_status_bucket_label(self, status):
        mapping = {
            "complete": "完整",
            "incomplete": "缺失",
            "manual_review": "需检查",
        }
        return mapping.get(str(status or "").strip(), str(status or "").strip())

    def _is_pair_status_bucket_dir(self, path):
        try:
            base = os.path.basename(os.path.abspath(str(path or "").strip()))
            return base in self._get_pair_status_bucket_names()
        except Exception:
            return False

    def _looks_like_pair_status_root(self, path):
        try:
            abs_path = os.path.abspath(str(path or "").strip())
            if not abs_path or not os.path.isdir(abs_path):
                return False
            base = os.path.basename(abs_path)
            if base in self._get_pair_status_root_names():
                return True
            for name in os.listdir(abs_path):
                sub_path = os.path.join(abs_path, name)
                if os.path.isdir(sub_path) and name in self._get_pair_status_bucket_names():
                    return True
        except Exception:
            return False
        return False

    def _resolve_pair_status_move_root(self, folder_path, src_dir, output_root=""):
        """
        只按当前命中的文件夹本身处理，不再向上合并到父项目目录。
        这样配对状态只受当前文件夹内的 txt / 视频影响，避免被上层目录或兄弟目录的额外文件干扰。
        """
        current = os.path.abspath(str(folder_path or "").strip())
        if not current or not os.path.isdir(current):
            return folder_path
        return current

    def _merge_pair_status_item(self, old_item, new_item):
        priority = {"complete": 1, "incomplete": 2, "manual_review": 3}
        if not old_item:
            return dict(new_item or {})
        merged = dict(old_item)
        merged["missing_mp4"] = sorted(set((old_item.get("missing_mp4", []) or []) + (new_item.get("missing_mp4", []) or [])), key=lambda x: int(x) if str(x).isdigit() else str(x))
        merged["missing_txt"] = sorted(set((old_item.get("missing_txt", []) or []) + (new_item.get("missing_txt", []) or [])), key=lambda x: int(x) if str(x).isdigit() else str(x))
        merged["paired"] = sorted(set((old_item.get("paired", []) or []) + (new_item.get("paired", []) or [])), key=lambda x: int(x) if str(x).isdigit() else str(x))
        merged["extra_videos"] = sorted(set((old_item.get("extra_videos", []) or []) + (new_item.get("extra_videos", []) or [])))
        old_status = str(old_item.get("status", "") or "")
        new_status = str(new_item.get("status", "") or "")
        if priority.get(new_status, 0) >= priority.get(old_status, 0):
            merged["status"] = new_status or old_status
        return merged

    def _normalize_pair_sort_rel_path(self, rel_path):
        rel_path = str(rel_path or "").replace("\\", "/").strip().strip("/")
        if not rel_path:
            return ""
        strip_heads = {"完整", "缺失", "需手动检查", "手动检查", "需检查", "配对检查结果", "其它文件"}
        parts = [p for p in rel_path.split("/") if p]
        while parts and parts[0] in strip_heads:
            parts.pop(0)
        return "/".join(parts)

    def _collect_pair_status_folders(self, src_dir, recursive=True, check_missing_txt=False, output_root="", force_rescan=False):
        """
        扫描数字 txt/视频配对目录，并区分：
        - complete:      至少存在一组完整配对，且没有缺失，也没有额外未编号视频
        - incomplete:    有缺失配对（例如 2.txt 但没有 2.mp4），且“视频总数量不足以补齐缺失”
        - manual_review: 存在额外未编号视频（如 未匹配-xxx、重复[...]、原始文件名视频）
                          - 若同时存在缺失配对，但视频总数足够（可能需要人工判断“多余视频”是否可补齐缺失），归入“需检查”
        返回：{"incomplete":[...], "complete":[...], "manual_review":[...]}
        """
        src_dir = os.path.abspath(str(src_dir or "").strip())
        output_root = os.path.abspath(str(output_root or "").strip()) if output_root else ""
        results = {"incomplete": [], "complete": [], "manual_review": []}
        if not src_dir or not os.path.isdir(src_dir):
            return results
        num_re = re.compile(r"^\d+$")
        video_exts = {".mp4", ".mov", ".m4v", ".mkv", ".avi", ".wmv", ".flv", ".webm", ".ts", ".mts", ".m2ts"}
        merged_by_path = {}
        allow_pair_status_dirs = True if force_rescan else self._looks_like_pair_status_root(src_dir)
        effective_recursive = True if force_rescan else bool(recursive)
        try:
            for root, dirs, files in os.walk(src_dir):
                root_abs = os.path.abspath(root)
                if root_abs == src_dir:
                    dirs[:] = self._filter_sort_subdirs(
                        root,
                        dirs,
                        src_dir,
                        allow_pair_status_dirs=allow_pair_status_dirs,
                        force_rescan=force_rescan,
                    )
                    continue

                dirs[:] = self._filter_sort_subdirs(
                    root,
                    dirs,
                    src_dir,
                    allow_pair_status_dirs=allow_pair_status_dirs,
                    force_rescan=force_rescan,
                )
                if not effective_recursive:
                    dirs[:] = []
                if output_root:
                    try:
                        same_as_src_root = False
                        try:
                            same_as_src_root = os.path.normcase(os.path.abspath(output_root)) == os.path.normcase(os.path.abspath(src_dir))
                        except Exception:
                            same_as_src_root = False
                        if (not same_as_src_root) and os.path.commonpath([output_root, root_abs]) == output_root:
                            continue
                    except Exception:
                        pass

                txt_nums = set()
                video_nums = set()
                extra_videos = []
                for fname in files or []:
                    stem, ext = os.path.splitext(str(fname or ""))
                    ext = ext.lower().strip()
                    if ext not in ({".txt"} | video_exts):
                        continue
                    stem = str(stem or "").strip()
                    if not stem:
                        continue
                    if ext == ".txt":
                        if not num_re.fullmatch(stem):
                            continue
                        txt_nums.add(stem)
                    else:
                        if num_re.fullmatch(stem):
                            video_nums.add(stem)
                        else:
                            extra_videos.append(str(fname or ""))

                paired_nums = sorted(list(txt_nums & video_nums), key=lambda x: int(x))
                missing_mp4 = sorted(list(txt_nums - video_nums), key=lambda x: int(x))
                missing_txt = sorted(list(video_nums - txt_nums), key=lambda x: int(x)) if check_missing_txt else []

                has_txt = bool(txt_nums)
                has_extra = bool(extra_videos)
                has_missing = bool(missing_mp4 or missing_txt)
                txt_count = len(txt_nums)
                video_total_count = len(video_nums) + len(extra_videos)

                if has_txt and has_extra and (not has_missing):
                    manual_trigger = True
                elif has_txt and has_extra and has_missing and (video_total_count >= txt_count):
                    manual_trigger = True
                else:
                    manual_trigger = False

                if manual_trigger:
                    item = {
                        "path": self._resolve_pair_status_move_root(root_abs, src_dir, output_root),
                        "missing_mp4": missing_mp4,
                        "missing_txt": missing_txt,
                        "paired": paired_nums,
                        "extra_videos": sorted(extra_videos),
                        "status": "manual_review",
                    }
                    merged_by_path[item["path"]] = self._merge_pair_status_item(merged_by_path.get(item["path"]), item)
                    dirs[:] = []
                elif missing_mp4 or missing_txt:
                    item = {
                        "path": self._resolve_pair_status_move_root(root_abs, src_dir, output_root),
                        "missing_mp4": missing_mp4,
                        "missing_txt": missing_txt,
                        "paired": paired_nums,
                        "extra_videos": sorted(extra_videos) if (has_txt and has_extra) else [],
                        "status": "incomplete",
                    }
                    merged_by_path[item["path"]] = self._merge_pair_status_item(merged_by_path.get(item["path"]), item)
                    dirs[:] = []
                elif paired_nums:
                    item = {
                        "path": self._resolve_pair_status_move_root(root_abs, src_dir, output_root),
                        "missing_mp4": [],
                        "missing_txt": [],
                        "paired": paired_nums,
                        "extra_videos": [],
                        "status": "complete",
                    }
                    merged_by_path[item["path"]] = self._merge_pair_status_item(merged_by_path.get(item["path"]), item)
                    dirs[:] = []
        except Exception:
            return {"incomplete": [], "complete": [], "manual_review": []}
        for item in merged_by_path.values():
            status = str(item.get("status", "") or "")
            if status in results:
                results[status].append(item)
        return results

    def _collect_incomplete_pairs_folders(self, src_dir, recursive=True, check_missing_txt=False, output_root="", force_rescan=False):
        """
        扫描“缺素材文件夹”：
        - 只认纯数字文件名：1.txt / 1.mp4
        - 默认只检查：txt 有而 mp4 缺（缺视频素材）
        - 可选：也检查 mp4 有而 txt 缺
        返回：[{path, missing_mp4:[...], missing_txt:[...]}]
        """
        return self._collect_pair_status_folders(
            src_dir,
            recursive=recursive,
            check_missing_txt=check_missing_txt,
            output_root=output_root,
            force_rescan=force_rescan,
        ).get("incomplete", [])

    def _remove_empty_sort_dirs(self, src_dir, keep_dirs=None):
        src_dir = os.path.abspath(str(src_dir or "").strip())
        keep_dirs = [os.path.abspath(str(p or "").strip()) for p in (keep_dirs or []) if str(p or "").strip()]
        removed = []
        if not src_dir or not os.path.isdir(src_dir):
            return removed
        for root, dirs, files in os.walk(src_dir, topdown=False):
            root_abs = os.path.abspath(root)
            if root_abs == src_dir:
                continue
            if root_abs in keep_dirs:
                continue
            try:
                if os.path.isdir(root_abs) and not os.listdir(root_abs):
                    os.rmdir(root_abs)
                    removed.append(root_abs)
            except Exception:
                continue
        return removed

    def _remove_single_empty_sort_dir(self, path, keep_dirs=None):
        path = os.path.abspath(str(path or "").strip())
        keep_dirs = {os.path.abspath(str(p or "").strip()) for p in (keep_dirs or []) if str(p or "").strip()}
        if not path or not os.path.isdir(path) or path in keep_dirs:
            return False
        try:
            if os.listdir(path):
                return False
            os.rmdir(path)
            return True
        except Exception:
            return False
        for root, dirs, files in os.walk(src_dir, topdown=False):
            root_abs = os.path.abspath(root)
            if root_abs == src_dir:
                continue
            if root_abs in keep_dirs:
                continue
            try:
                if os.path.isdir(root_abs) and not os.listdir(root_abs):
                    os.rmdir(root_abs)
                    removed.append(root_abs)
            except Exception:
                continue
        return removed

