                def _find_csv_files(paths):
                    found = []
                    seen = set()
                    for p in paths or []:
                        try:
                            if os.path.isfile(p) and p.lower().endswith(".csv"):
                                key = os.path.normpath(p).lower()
                                if key not in seen:
                                    seen.add(key); found.append(p)
                            elif os.path.isdir(p):
                                for fn in os.listdir(p):
                                    if fn.lower().endswith(".csv"):
                                        fp = os.path.join(p, fn)
                                        key = os.path.normpath(fp).lower()
                                        if key not in seen:
                                            seen.add(key); found.append(fp)
                        except Exception:
                            pass
                    return found

                csv_files = _find_csv_files(candidate_paths)
