            if any(k in raw for k in ["批量配图", "自动配图", "图文匹配", "ai匹配", "自动选图", "选图"]) and "审核" not in raw:
                project_name = self._find_target_project_name(raw)
                if not project_name:
                    self._append_local_assistant_reply(conv, user_msg, "我识别到你要执行 `AI 图文匹配`，但还没定位到项目名。你可以直接说“给 A1 自动配图”，或先切到目标项目再说“给当前项目配图”。")
