    def _get_browse_start_dir(self, line_edit=None):
        """浏览目录/文件时，优先从当前输入框已有路径打开，其次回退到上次浏览位置。"""
        candidates = []
        if line_edit is not None and hasattr(line_edit, "text"):
            txt = str(line_edit.text() or "").strip().strip('"').strip("'")
            if txt:
                candidates.append(txt)
        last_dir = str(getattr(self, "_last_browse_dir", "") or "").strip()
        if last_dir:
            candidates.append(last_dir)
        candidates.append(os.getcwd())

        for raw in candidates:
            try:
                p = os.path.expanduser(raw)
                if os.path.isdir(p):
                    return p
                if os.path.isfile(p):
                    return os.path.dirname(p)
            except Exception:
                pass
        return ""

    def browse_folder(self, line_edit):
        start_dir = self._get_browse_start_dir(line_edit)
        path = QFileDialog.getExistingDirectory(self, "选择目录", start_dir)
        if path:
            self._last_browse_dir = path
            line_edit.setText(path)

    def browse_dir(self, line_edit):
        """browse_folder 的别名，兼容代码中 browse_dir 的调用。"""
        self.browse_folder(line_edit)

    def _render_output_base_dir(self, path_template, project_name=""):
        """
        渲染“整理后存放位置”的变量模板，并返回规范化后的实际路径。

        支持变量：
        - {date} / {yyyy-MM-dd}: 例如 2026-07-29
        - {yyyyMMdd}: 例如 20260729
        - {project}: 当前项目名（会做安全化）
        """
        return render_path_template(path_template, project_name=project_name)

    def _get_heygen_base_output_dir(self, project_name="", project_entry=None):
        """
        获取素材整理模块的实际输出根目录：
        1. 优先使用项目自己的“整理后存放位置”
        2. 若项目未填写，则回退到“全局统一存放位置”
        """
        raw = ""
        p = project_entry if isinstance(project_entry, dict) else None
        if p and is_alive(p.get("out_path")):
            raw = p["out_path"].text().strip()
        if not raw and hasattr(self, "heygen_global_out_input") and is_alive(self.heygen_global_out_input):
            raw = self.heygen_global_out_input.text().strip()
        return self._render_output_base_dir(raw, project_name=project_name)

    def browse_file(self, line_edit, filter_str="所有文件 (*)"):
        start_dir = self._get_browse_start_dir(line_edit)
        path, _ = QFileDialog.getOpenFileName(self, "选择文件", start_dir, filter_str)
        if path:
            self._last_browse_dir = os.path.dirname(path)
            line_edit.setText(path)

    def browse_files_or_dir(self, line_edit):
        # 优先选择目录
        start_dir = self._get_browse_start_dir(line_edit)
        folder_path = QFileDialog.getExistingDirectory(self, "选择文件夹", start_dir)
        if folder_path:
            self._last_browse_dir = folder_path
            line_edit.setText(folder_path)
            return
        # 如果没有选择目录，则允许选择文件
        file_paths, _ = QFileDialog.getOpenFileNames(self, "选择文件", start_dir, "所有文件 (*)")
        if file_paths:
            self._last_browse_dir = os.path.dirname(file_paths[0])
            line_edit.setText("\n".join(file_paths))
    def add_heygen_project(self):
        name = self.new_proj_input.text().strip()
        if not name or name in self.project_tabs: return
        self.create_heygen_project_ui(name); self.new_proj_input.clear(); self.trigger_save()
    def _get_heygen_project_name_by_widget(self, project_widget):
        if not hasattr(self, "heygen_project_tabs") or not is_alive(self.heygen_project_tabs) or not project_widget:
            return ""
        try:
            for i in range(self.heygen_project_tabs.count()):
                if self.heygen_project_tabs.widget(i) is project_widget:
                    return self.heygen_project_tabs.tabText(i)
        except Exception:
            pass
        try:
            return str(project_widget.property("heygen_project_name") or "").strip()
        except Exception:
            return ""
    def rename_current_heygen_project(self):
        idx = self.heygen_project_tabs.currentIndex() if hasattr(self, "heygen_project_tabs") else -1
        if idx < 0:
            return
        old_name = self.heygen_project_tabs.tabText(idx).strip()
        if not old_name:
            return
        new_name, ok = QInputDialog.getText(self, "重命名项目", "请输入新的项目名：", text=old_name)
        new_name = str(new_name or "").strip()
        if not ok or not new_name or new_name == old_name:
            return
        if new_name in self.project_tabs:
            QMessageBox.warning(self, "提示", f"项目名 [{new_name}] 已存在，请换一个名称。")
            return
        project_data = self.project_tabs.get(old_name)
        if not project_data:
            return
        self.project_tabs[new_name] = self.project_tabs.pop(old_name)
        project_widget = self.heygen_project_tabs.widget(idx)
        try:
            if project_widget:
                project_widget.setProperty("heygen_project_name", new_name)
        except Exception:
            pass
        self.heygen_project_tabs.setTabText(idx, new_name)
        self.log(f"项目 [{old_name}] 已重命名为 [{new_name}]", "green")
        self.trigger_save()
    def delete_current_heygen_project(self):
        idx = self.heygen_project_tabs.currentIndex()
        if idx < 0: return
        name = self.heygen_project_tabs.tabText(idx)
        if name in self.project_tabs: del self.project_tabs[name]
        self.heygen_project_tabs.removeTab(idx); self.trigger_save()


    def run_single_heygen_csv_only(self, name):
        if name not in self.project_tabs: return
        p = self.project_tabs[name]
        base_out_dir = self._get_heygen_base_output_dir(name, p)
        table = p["table"]
        if not base_out_dir:
            QMessageBox.warning(self, "提示", f"请设置项目 [{name}] 的存放位置，或填写上方全局统一存放位置")
            return
        
        out_dir = os.path.join(base_out_dir, clean_long_filename(name))
        if not os.path.exists(out_dir): os.makedirs(out_dir)
        
        csv_rows = []
        for i in range(table.rowCount()):
            code = table.item(i, 0).text().strip() if table.item(i, 0) else ""
            cn = table.item(i, 3).text().strip() if table.item(i, 3) else ""
            en = table.item(i, 4).text().strip() if table.item(i, 4) else ""
            if code or cn or en: csv_rows.append([code, cn, en])
        
        if csv_rows:
            csv_path_1 = make_unique_path(out_dir, f"{name}_仅代码英文", ".csv", max_component_len=120, max_full_path=240)
            csv_path_2 = make_unique_path(out_dir, f"{name}_中英对照汇总", ".csv", max_component_len=120, max_full_path=240)
            try:
                with open(csv_path_1, "w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.writer(f)
                    for row in csv_rows: writer.writerow([row[0], row[2]])
                with open(csv_path_2, "w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.writer(f)
                    writer.writerow(["代码", "中文文案", "英文文案"])
                    writer.writerows(csv_rows)
                self.log(f"项目 [{name}] CSV 导出成功", "green")
                QMessageBox.information(self, "完成", f"项目 [{name}] CSV 导出成功！\n\n1. {csv_path_1}\n2. {csv_path_2}")
            except Exception as e: self.log(f"CSV 导出失败: {e}", "red")
        else: self.log(f"项目 [{name}] 没有可导出的数据", "orange")

    def run_single_heygen_split_en(self, name):
        """
        独立的英文分段导出逻辑：按行建文件夹。
        核心规则：
        1. 先追求各段字数尽量平均；
        2. 再尽量保证不断句；
        3. 若单句本身过长，再降级到逗号/单词边界切分。
        """
        if name not in self.project_tabs: return
        p = self.project_tabs[name]
        base_out_dir = self._get_heygen_base_output_dir(name, p)
        table = p["table"]
        if not base_out_dir:
            QMessageBox.warning(self, "提示", f"请设置项目 [{name}] 的存放位置，或填写上方全局统一存放位置")
            return
        
        # 获取用户设置的基础上限
        limit = p.get("split_limit").value() if p.get("split_limit") else 100
        
        out_dir = os.path.join(base_out_dir, clean_long_filename(name))
        
        count = 0
        total_files = 0
        
        for i in range(table.rowCount()):
            code = table.item(i, 0).text().strip() if table.item(i, 0) else ""
            en = table.item(i, 4).text().strip() if table.item(i, 4) else ""
            if not en: continue
            
            # 为每一行创建独立文件夹
            safe_code = clean_long_filename(code, 120) if code else f"item_{i+1}"
            item_dir = os.path.join(out_dir, safe_code)
            if not os.path.exists(item_dir): os.makedirs(item_dir)

            # 直接复用“均衡分桶”算法：
            # - 优先让各段长度尽量接近
            # - 尽量在句子边界切
            # - 超长单句再退化到逗号/单词边界
            wrapped_text = smart_wrap_text(en, limit, merge_single_linebreaks=True)
            final_segments = [seg.strip() for seg in wrapped_text.splitlines() if seg and seg.strip()]
            if not final_segments:
                final_segments = [en.strip()]

            # 写入该行的分段文件
            for idx, content in enumerate(final_segments, 1):
                with open(os.path.join(item_dir, f"{idx}.txt"), "w", encoding="utf-8") as f:
                    f.write(content)
                total_files += 1
            count += 1
        
        if count > 0:
            self.log(f"项目 [{name}] 英文分段导出成功，共处理 {count} 组素材，生成 {total_files} 个分段文件", "green")
            QMessageBox.information(self, "完成", f"英文分段导出完成！\n\n导出路径：{out_dir}\n处理组数：{count}\n总分段数：{total_files}\n每段上限：{limit} 字符")
        else:
            self.log(f"项目 [{name}] 没有可导出的英文文案", "orange")

    def run_single_heygen_project(self, name, write_csv=True):
        if name not in self.project_tabs: return []
        p = self.project_tabs[name]
        base_out_dir = self._get_heygen_base_output_dir(name, p)
        table = p["table"]
        move_mode = p["move_check"].isChecked()
        if not base_out_dir:
            QMessageBox.warning(self, "提示", f"请设置项目 [{name}] 的存放位置，或填写上方全局统一存放位置")
            return []
        # 只有在确实有素材可处理时才创建文件夹
        out_dir = os.path.join(base_out_dir, clean_long_filename(name))
        count = 0; history = []; csv_rows = []
        for i in range(table.rowCount()):
            # 修正列索引：0=代码, 1=图片路径, 2=评分, 3=中文文案, 4=英文文案, 5=备注
            code = table.item(i, 0).text().strip() if table.item(i, 0) else ""
            img_p = table.item(i, 1).text().strip() if table.item(i, 1) else ""
            # 注意：第2列是评分，文案在第3列(中)和第4列(英)
            cn = table.item(i, 3).text().strip() if table.item(i, 3) else ""
            en = table.item(i, 4).text().strip() if table.item(i, 4) else ""
            if not img_p or not os.path.exists(img_p): continue
            
            # 确定有素材，此时才创建项目总文件夹
            if not os.path.exists(out_dir): os.makedirs(out_dir)
            
            ext = os.path.splitext(img_p)[1]; safe_code = clean_long_filename(code, 120) if code else f"item_{i+1}"
            item_dir = make_unique_path(out_dir, safe_code, "", max_component_len=120, max_full_path=240)
            target_img = make_unique_path(item_dir, safe_code, ext, max_component_len=120, max_full_path=240)
            cn_txt = make_unique_path(item_dir, cn if cn else "中文文案", ".txt", max_component_len=180, max_full_path=240)
            en_txt = make_unique_path(item_dir, en if en else "英文文案", ".txt", max_component_len=180, max_full_path=240)
            if os.path.abspath(en_txt) == os.path.abspath(cn_txt):
                en_txt = make_unique_path(item_dir, f"{en if en else '英文文案'}_英文", ".txt", max_component_len=180, max_full_path=240)
            try:
                if not os.path.exists(item_dir): os.makedirs(item_dir)
                if move_mode: shutil.move(img_p, target_img); history.append({"type": "move", "src": img_p, "dst": target_img})
                else: shutil.copy2(img_p, target_img); history.append({"type": "copy", "src": img_p, "dst": target_img})
                with open(cn_txt, "w", encoding="utf-8") as f: f.write(cn)
                history.append({"type": "file", "path": cn_txt})
                # 导出时自动对英文文案进行智能断行（默认60字符）
                wrapped_en = smart_wrap_text(en, 60, merge_single_linebreaks=True)
                with open(en_txt, "w", encoding="utf-8") as f: f.write(wrapped_en)
                history.append({"type": "file", "path": en_txt})
                # 为了总表，返回完整的三列数据：[代码, 中文文案, 英文文案]
                csv_rows.append([code, cn, en]); count += 1
            except Exception as e: self.log(f"处理失败 {img_p}: {e}", "red")
        
        if write_csv and csv_rows:
            # 1. 导出 CSV 1：无标题、仅包含 [代码, 英文文案]
            csv_path_1 = make_unique_path(out_dir, f"{name}_仅代码英文", ".csv", max_component_len=120, max_full_path=240)
            # 2. 导出 CSV 2：带标题、包含 [代码, 中文文案, 英文文案]
            csv_path_2 = make_unique_path(out_dir, f"{name}_中英对照汇总", ".csv", max_component_len=120, max_full_path=240)
            try:
                with open(csv_path_1, "w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.writer(f)
                    for row in csv_rows:
                        writer.writerow([row[0], row[2]])
                history.append({"type": "file", "path": csv_path_1})
                
                with open(csv_path_2, "w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.writer(f)
                    writer.writerow(["代码", "中文文案", "英文文案"])
                    writer.writerows(csv_rows)
                history.append({"type": "file", "path": csv_path_2})
            except Exception as e: self.log(f"CSV写入失败: {e}", "red")
            
        if count > 0: self.last_heygen_history = history; self.log(f"项目 [{name}] 整理完成，共 {count} 组素材", "green")
        else: self.log(f"项目 [{name}] 没有可处理的素材", "orange")
        return csv_rows
    def run_all_heygen_projects(self):
        try:
            import pandas as pd
        except ImportError:
            QMessageBox.critical(self, "缺少依赖",
                "运行此功能需要安装 pandas 和 openpyxl 库。\n\n"
                "请在命令行执行以下命令后重启程序：\n"
                "    pip install pandas openpyxl")
            return
        first_base_out_dir = ""
        project_data = {} # {project_name: rows}
        
        for name in list(self.project_tabs.keys()):
            if not first_base_out_dir and name in self.project_tabs:
                first_base_out_dir = self._get_heygen_base_output_dir(name, self.project_tabs[name])
            
            # 修改：调用 run_single_heygen_project 时 write_csv 设为 True
            # 这样每个项目会自动在自己的文件夹下生成一份独立的 CSV
            project_rows = self.run_single_heygen_project(name, write_csv=True)
            if project_rows:
                project_data[name] = project_rows

        if project_data and first_base_out_dir:
            try:
                os.makedirs(first_base_out_dir, exist_ok=True)
            except Exception:
                pass
            # 1. 生成 Excel 分页汇总（包含中英文）
            xlsx_path = make_unique_path(first_base_out_dir, "全部项目汇总_中英对照", ".xlsx", max_component_len=120, max_full_path=240)
            # 2. 生成 CSV 总汇总（包含中英文）
            csv_all_path = make_unique_path(first_base_out_dir, "全部项目汇总_中英对照", ".csv", max_component_len=120, max_full_path=240)
            
            all_combined_rows = []
            try:
                with pd.ExcelWriter(xlsx_path, engine='openpyxl') as writer:
                    for name, rows in project_data.items():
                        sheet_name = re.sub(r'[\\/*?:\\[\\]]', '', name)[:31]
                        # rows 结构：[代码, 中文文案, 英文文案]
                        df = pd.DataFrame(rows, columns=["代码", "中文文案", "英文文案"])
                        df.to_excel(writer, sheet_name=sheet_name, index=False)
                        all_combined_rows.extend(rows)
                
                # 写入 CSV 总汇总
                with open(csv_all_path, "w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.writer(f)
                    writer.writerow(["代码", "中文文案", "英文文案"]) # 总汇总保留标题
                    writer.writerows(all_combined_rows)

                self.last_heygen_history.append({"type": "file", "path": xlsx_path})
                self.last_heygen_history.append({"type": "file", "path": csv_all_path})
                self.log(f"✅ 全部项目汇总(Excel/CSV)已生成", "green")
                split_stats = None
                auto_split_enabled = hasattr(self, "heygen_auto_split_en_check") and self.heygen_auto_split_en_check.isChecked()
                if auto_split_enabled:
                    self.log("✂️ 已启用“整理后自动导出分段英文”，开始批量导出...", "blue")
                    split_stats = self.run_all_heygen_split_en(show_dialog=False)
                msg = (
                    f"已成功整理全部项目！\n\n"
                    f"1. 汇总表（中英对照）：{xlsx_path}\n"
                    f"2. 独立分项 CSV（仅英无标）：已存入各项目文件夹"
                )
                if auto_split_enabled:
                    if split_stats and split_stats.get("projects", 0) > 0:
                        msg += (
                            f"\n3. 已自动导出分段英文："
                            f"{split_stats.get('projects', 0)} 个项目，"
                            f"{split_stats.get('groups', 0)} 组，"
                            f"{split_stats.get('files', 0)} 个分段文件"
                        )
                    else:
                        msg += "\n3. 已尝试自动导出分段英文，但本次没有可导出的英文文案"
                QMessageBox.information(self, "完成", msg)
            except Exception as e:
                self.log(f"❌ 汇总表生成失败: {e}", "red")
                # 如果 Excel 写入失败，降级到原有的 CSV 逻辑（可选）
    def run_undo_heygen(self):
        if not self.last_heygen_history: self.log("没有可撤销的记录", "orange"); return
        count = 0
        for item in reversed(self.last_heygen_history):
            try:
                if item["type"] == "move":
                    if os.path.exists(item["dst"]):
                        os.makedirs(os.path.dirname(item["src"]), exist_ok=True); shutil.move(item["dst"], item["src"]); count += 1
                elif item["type"] == "copy":
                    if os.path.exists(item["dst"]): os.remove(item["dst"]); count += 1
                elif item["type"] == "file":
                    if os.path.exists(item["path"]): os.remove(item["path"])
            except: pass
        self.last_heygen_history = []; self.log(f"已撤销 {count} 个文件的操作", "blue")
    def _normalize_sort_name(self, name_text):
        raw = os.path.splitext(os.path.basename(str(name_text or "")))[0].lower()
        raw = re.sub(r'[\s_\-—【】\[\]\(\)（）{}]+', '', raw)
        raw = re.sub(r'[^0-9a-z\u4e00-\u9fff]+', '', raw)
        return raw
    def _extract_sort_tokens(self, name_text):
        raw = os.path.splitext(os.path.basename(str(name_text or "")))[0].lower()
        parts = re.split(r'[\s_\-—【】\[\]\(\)（）{}·,，。、]+', raw)
        tokens = []
        for part in parts:
            part = (part or "").strip()
            if not part:
                continue
            chunks = re.findall(r'[a-z]+|\d+|[\u4e00-\u9fff]+', part) or [part]
            for chunk in chunks:
                chunk = (chunk or "").strip()
                if len(chunk) < 2:
                    continue
                if chunk not in tokens:
                    tokens.append(chunk)
        return tokens
    def _sanitize_sort_folder_name(self, name_text, fallback="未命名分组"):
        text = str(name_text or "").strip()
        text = re.sub(r'[\\/:*?"<>|\r\n\t]+', ' ', text)
        text = re.sub(r'\s+', ' ', text).strip(" .")
        return text[:80] if text else fallback
    def _strip_sort_variant_suffix(self, name_text):
        stem = os.path.splitext(os.path.basename(str(name_text or "")))[0].strip()
        if not stem:
            return ""
        for pat in [
            r'^(.*?)(?:[_\- ]+\d+)$',
            r'^(.*?)(?:\(\d+\))$',
            r'^(.*?)(?:（\d+）)$',
        ]:
            m = re.match(pat, stem, flags=re.IGNORECASE)
            if not m:
                continue
            prefix = (m.group(1) or "").strip(" _-（）()")
            if len(self._normalize_sort_name(prefix)) >= 2:
                return prefix
        return stem
    def _get_sort_name_variants(self, name_text):
        stem = os.path.splitext(os.path.basename(str(name_text or "")))[0].strip()
        candidates = [stem]
        base_variant = self._strip_sort_variant_suffix(name_text)
        if base_variant and base_variant != stem:
            candidates.insert(0, base_variant)
        result = []
        seen = set()
        for cand in candidates:
            norm = self._normalize_sort_name(cand)
            if len(norm) < 2 or norm in seen:
                continue
            seen.add(norm)
            result.append((cand, norm))
        return result
    def _split_sort_name_parts(self, name_text, strip_variant=True):
        stem = os.path.splitext(os.path.basename(str(name_text or "")))[0].strip()
        if strip_variant:
            stem = self._strip_sort_variant_suffix(stem)
        raw = str(stem or "").lower().strip()
        if not raw:
            return []
        parts = []
        for part in re.split(r'[\s_\-—【】\[\]\(\)（）{}·,，。、]+', raw):
            part = (part or "").strip()
            if not part:
                continue
            chunks = re.findall(r'[a-z]+|\d+|[\u4e00-\u9fff]+', part) or [part]
            for chunk in chunks:
                chunk = (chunk or "").strip()
                if chunk:
                    parts.append(chunk)
        return parts
    def _has_sort_structured_mismatch(self, filename, folder_name):
        # 这里不能 strip_variant=True：
        # 对于类似 “0720-C-11” 这类结构化编号，去掉尾号会导致 11/12/13 都被误判成同一类，
        # 从而把很多文件错误归到同一个已存在文件夹（例如都归到 0720-C-10）。
        file_parts = self._split_sort_name_parts(filename, strip_variant=False)
        folder_parts = self._split_sort_name_parts(folder_name, strip_variant=False)
        if not file_parts or not folder_parts:
            return False
        if file_parts == folder_parts:
            return False
        file_text = [p for p in file_parts if not p.isdigit()]
        folder_text = [p for p in folder_parts if not p.isdigit()]
        file_nums = [p for p in file_parts if p.isdigit()]
        folder_nums = [p for p in folder_parts if p.isdigit()]
        if file_text and folder_text and file_text == folder_text and file_nums and folder_nums and file_nums != folder_nums:
            return True
        if len(file_parts) == len(folder_parts):
            same_kind = all(a.isdigit() == b.isdigit() for a, b in zip(file_parts, folder_parts))
            same_text_slots = all((a == b) for a, b in zip(file_parts, folder_parts) if not a.isdigit() and not b.isdigit())
            numeric_diff = any((a != b) for a, b in zip(file_parts, folder_parts) if a.isdigit() and b.isdigit())
            if same_kind and same_text_slots and numeric_diff:
                return True
        return False
    def _derive_filename_group_key(self, filename):
        stem = os.path.splitext(os.path.basename(str(filename or "")))[0].strip()
        if not stem:
            return ""
        candidates = []
        base_variant = self._strip_sort_variant_suffix(filename)
        if base_variant and base_variant != stem:
            candidates.append(base_variant)
        for pat in [
            r'^(.*?)(?:[_\- ]+\d+)$',
            r'^(.*?)(?:\(\d+\))$',
            r'^(.*?)(?:（\d+）)$',
            r'^(.*?)(?:第\d+[集章节期篇部])$',
            r'^(.*?)(?:[ _\-]?[A-Za-z]?\d{1,3})$'
        ]:
            m = re.match(pat, stem, flags=re.IGNORECASE)
            if m:
                prefix = (m.group(1) or "").strip(" _-（）()")
                if len(self._normalize_sort_name(prefix)) >= 2:
                    candidates.append(prefix)
        tokens = [t for t in self._extract_sort_tokens(stem) if not re.fullmatch(r'\d+', t or "")]
        if tokens:
            if len(tokens) >= 2:
                combo = "".join(tokens[:2]).strip()
                if len(self._normalize_sort_name(combo)) >= 2:
                    candidates.append(combo)
            candidates.append(tokens[0])
        seen = set()
        for cand in candidates:
            norm = self._normalize_sort_name(cand)
            if len(norm) < 2 or norm in seen:
                continue
            seen.add(norm)
            return self._sanitize_sort_folder_name(cand)
        return ""
    def _collect_filename_auto_groups(self, src_dir, recursive=False):
        groups = {}
        try:
            src_dir = os.path.abspath(src_dir)
            for root, dirs, files in os.walk(src_dir):
                dirs[:] = self._filter_sort_subdirs(root, dirs, src_dir)
                existing_dirs = {d.lower() for d in dirs if os.path.isdir(os.path.join(root, d))}
                for fname in files:
                    key = self._derive_filename_group_key(fname)
                    if not key:
                        continue
                    norm_key = self._normalize_sort_name(key)
                    if len(norm_key) < 2:
                        continue
                    if norm_key in existing_dirs:
                        continue
                    gkey = (os.path.abspath(root), norm_key)
                    if gkey not in groups:
                        groups[gkey] = {"root": os.path.abspath(root), "folder": self._sanitize_sort_folder_name(key), "files": []}
                    groups[gkey]["files"].append(os.path.join(root, fname))
                if not recursive:
                    break
        except Exception:
            return []
        result = []
        for item in groups.values():
            files = sorted(item.get("files", []) or [])
            if len(files) < 2:
                continue
            item["files"] = files
            result.append(item)
        result.sort(key=lambda x: (x.get("root", ""), x.get("folder", "")))
        return result
    def _preview_filename_auto_groups(self, src_dir):
        recursive = self.recursive_check.isChecked() if hasattr(self, "recursive_check") and is_alive(self.recursive_check) else False
        groups = self._collect_filename_auto_groups(src_dir, recursive=recursive)
        if not groups:
            QMessageBox.information(self, "提示", "没有识别到可自动成组的文件名模式。\n至少需要 2 个文件名能归到同一组，才会出现在预览里。")
            return []
        dlg = FilenameGroupPreviewDialog(groups, src_dir=src_dir, parent=self)
        if PYQT_VERSION == 6:
            accepted = (dlg.exec() == QDialog.DialogCode.Accepted)
        else:
            accepted = (dlg.exec_() == QDialog.Accepted)
        if not accepted:
            return None
        confirmed = dlg.get_confirmed_groups()
        if not confirmed:
            QMessageBox.information(self, "提示", "你没有勾选任何自动分组项，本次不会按文件名自动建文件夹。")
            return []
        return confirmed
    def _calc_longest_common_substring_len(self, a, b):
        if not a or not b: return 0
        try:
            match = SequenceMatcher(None, a, b).find_longest_match(0, len(a), 0, len(b))
            return int(match.size or 0)
        except Exception:
            return 0
    def _is_sort_numeric_suffix_conflict(self, name_a, name_b):
        def _parts(text):
            raw = os.path.splitext(os.path.basename(str(text or "")))[0].lower().strip()
            if not raw:
                return []
            parts = []
            for part in re.split(r'[\s_\-—【】\[\]\(\)（）{}·,，。、]+', raw):
                part = (part or "").strip()
                if not part:
                    continue
                chunks = re.findall(r'[a-z]+|\d+|[\u4e00-\u9fff]+', part) or [part]
                for chunk in chunks:
                    chunk = (chunk or "").strip()
                    if chunk:
                        parts.append(chunk)
            return parts
        a_parts = _parts(name_a)
        b_parts = _parts(name_b)
        if not a_parts or not b_parts or a_parts == b_parts:
            return False
        if len(a_parts) != len(b_parts):
            return False
        if len(a_parts) < 1 or a_parts[:-1] != b_parts[:-1]:
            return False
        last_a = a_parts[-1]
        last_b = b_parts[-1]
        if not (last_a.isdigit() and last_b.isdigit()) or last_a == last_b:
            return False
        short_last, long_last = (last_a, last_b) if len(last_a) <= len(last_b) else (last_b, last_a)
        return len(short_last) < len(long_last) and long_last.startswith(short_last)
    def _calc_auto_sort_match_score(self, filename, folder_name):
        file_norm = self._normalize_sort_name(filename)
        folder_norm = self._normalize_sort_name(folder_name)
        if len(file_norm) < 2 or len(folder_norm) < 2:
            return 0.0
        if self._is_sort_numeric_suffix_conflict(filename, folder_name):
            return 0.0
        if self._has_sort_structured_mismatch(filename, folder_name):
            return 0.0
        score = 0.0
        file_variants = self._get_sort_name_variants(filename)
        folder_variants = self._get_sort_name_variants(folder_name)
        if not file_variants or not folder_variants:
            return 0.0
        if any(f_norm == d_norm for _, f_norm in file_variants for _, d_norm in folder_variants):
            same_as_original = any(f_norm == folder_norm for _, f_norm in file_variants) and any(d_norm == file_norm for _, d_norm in folder_variants)
            score = max(score, 1.0 if same_as_original else 0.98)
        for _, file_var_norm in file_variants:
            for _, folder_var_norm in folder_variants:
                if folder_var_norm in file_var_norm:
                    if len(folder_var_norm) >= 3 or re.fullmatch(r'[\u4e00-\u9fff]{2}', folder_var_norm or ""):
                        score = max(score, 1.0)
                elif file_var_norm in folder_var_norm and len(file_var_norm) >= 3:
                    score = max(score, 0.82)
                lcs = self._calc_longest_common_substring_len(file_var_norm, folder_var_norm)
                seq_ratio = SequenceMatcher(None, file_var_norm, folder_var_norm).ratio()
                cover_ratio = lcs / max(len(folder_var_norm), 1)
                short_ratio = lcs / max(min(len(file_var_norm), len(folder_var_norm)), 1)
                if lcs >= 3 and (cover_ratio >= 0.6 or short_ratio >= 0.75):
                    score = max(score, 0.72 + min(0.18, seq_ratio * 0.18))
                elif seq_ratio >= 0.76 and lcs >= 2:
                    score = max(score, seq_ratio)
        file_tokens = set()
        for cand, _ in file_variants:
            file_tokens.update(self._extract_sort_tokens(cand))
        folder_tokens = set()
        for cand, _ in folder_variants:
            folder_tokens.update(self._extract_sort_tokens(cand))
        shared_tokens = sorted(file_tokens & folder_tokens, key=len, reverse=True)
        if shared_tokens:
            shared_text_tokens = [tok for tok in shared_tokens if not str(tok).isdigit()]
            shared_number_tokens = [tok for tok in shared_tokens if str(tok).isdigit()]
            longest_shared = len((shared_text_tokens or shared_tokens)[0])
            shared_len = sum(len(tok) for tok in shared_tokens)
            folder_cover = shared_len / max(len(folder_norm), 1)
            if shared_text_tokens and (longest_shared >= 2 or len(shared_tokens) >= 2 or folder_cover >= 0.55):
                token_score = 0.74 + min(0.18, folder_cover * 0.18 + (0.04 if len(shared_tokens) >= 2 else 0.0))
                score = max(score, token_score)
            elif len(shared_number_tokens) >= 2 and len(shared_tokens) >= 2:
                token_score = 0.68 + min(0.1, folder_cover * 0.1)
                score = max(score, token_score)
        return min(score, 1.0)
    def _find_auto_sort_folder_for_file(self, filename, folder_names, return_detail=False):
        # 规则增强（可配置）：编号前缀优先命中
        # 例如 prefix=0720-C- 时：
        # - 文件名 0720-C-12_3_2 / 0720-C-12-2 / 0720-C-12(3) 都应归到文件夹 0720-C-12
        try:
            prefix = ""
            if hasattr(self, "sorter_code_prefix_input") and is_alive(self.sorter_code_prefix_input):
                prefix = str(self.sorter_code_prefix_input.text() or "").strip()
            if prefix:
                stem = os.path.splitext(os.path.basename(str(filename or "")))[0].strip()
                m = re.match(rf"^{re.escape(prefix)}(\d+)", stem, flags=re.IGNORECASE)
                if m:
                    code_folder = f"{prefix}{m.group(1)}"
                    # 优先找同级完全同名文件夹（不做模糊）
                    for folder_name in folder_names or []:
                        if str(folder_name or "").strip().lower() == code_folder.lower():
                            return (folder_name, 1.0, 0.0) if return_detail else folder_name
        except Exception:
            pass

        # 规则增强：优先“最长前缀文件夹”命中，用于处理类似：
        # 文件夹：0720-C-19
        # 文件名：0720-C-19-2 / 0720-C-19_3 / 0720-C-19(2)
        # 这种情况必须归到 0720-C-19，而不能被误判为 0720-C-1 / 0720-C 等更短前缀。
        try:
            file_stem = os.path.splitext(os.path.basename(str(filename or "")))[0].strip()
            file_stem_l = file_stem.lower()
            best_prefix_folder = ""
            best_prefix_len = 0
            boundary_chars = set("-_ (（[【{")  # 文件夹名后允许出现的分隔符
            for folder_name in folder_names or []:
                fstem = str(folder_name or "").strip()
                if not fstem:
                    continue
                fstem_l = fstem.lower()
                if file_stem_l == fstem_l:
                    # 完全同名：直接命中
                    return (fstem, 1.0, 0.0) if return_detail else fstem
                if not file_stem_l.startswith(fstem_l):
                    continue
                # 边界判断：避免 0720-C-19-2 错命中 0720-C-1（后面紧跟的是 9，不是分隔符）
                if len(file_stem_l) > len(fstem_l):
                    nxt = file_stem_l[len(fstem_l):len(fstem_l) + 1]
                    if nxt and (nxt not in boundary_chars):
                        continue
                if len(fstem_l) > best_prefix_len:
                    best_prefix_folder = fstem
                    best_prefix_len = len(fstem_l)
            if best_prefix_folder:
                return (best_prefix_folder, 1.0, 0.0) if return_detail else best_prefix_folder
        except Exception:
            pass

        file_norm = self._normalize_sort_name(filename)
        if len(file_norm) < 2:
            return ("", 0.0, 0.0) if return_detail else ""
        best_folder = ""; best_score = 0.0; second_best = 0.0
        for folder_name in folder_names or []:
            score = self._calc_auto_sort_match_score(filename, folder_name)
            if score > best_score:
                second_best = best_score
                best_folder = folder_name
                best_score = score
            elif score > second_best:
                second_best = score
        # 强化歧义过滤：如果次高分与最高分几乎相同（尤其是都=1.00），则视为不确定，直接放弃自动归类。
        if best_score > 0 and (best_score - second_best) <= 1e-6:
            return ("", best_score, second_best) if return_detail else ""
        if best_score < 0.72:
            return ("", best_score, second_best) if return_detail else ""
        if best_score < 0.9 and (best_score - second_best) < 0.08:
            return ("", best_score, second_best) if return_detail else ""
        return (best_folder, best_score, second_best) if return_detail else best_folder
    def _append_sorter_rules(self, rules, bucket="rule"):
        bucket = str(bucket or "rule").strip() or "rule"
        if not rules:
            return 0
        if not hasattr(self, "_sorter_rules_cache") or not isinstance(self._sorter_rules_cache, dict):
            self._sorter_rules_cache = {"rule": [], "extension": []}
        existing = self._clone_sorter_rules(self._sorter_rules_cache.get(bucket, []))
        seen = {(r.get("p", ""), r.get("m", ""), r.get("f", "")) for r in existing}
        added = 0
        for rule in rules or []:
            if not isinstance(rule, dict):
                continue
            p = str(rule.get("p", "") or "").strip()
            m = str(rule.get("m", "开头是") or "开头是").strip()
            f = self._sanitize_sort_folder_name(rule.get("f", ""), fallback="")
            if not p or not f:
                continue
            key = (p, m, f)
            if key in seen:
                continue
            seen.add(key)
            existing.append({"p": p, "m": m, "f": f})
            added += 1
        self._sorter_rules_cache[bucket] = existing
        if self._get_sorter_rule_bucket(self._get_sorter_mode()) == bucket:
            self._apply_sorter_rules_to_table(existing)
        if added:
            self.trigger_save()
        return added
    def _normalize_sort_dir_path(self, path):
        try:
            return os.path.normcase(os.path.abspath(str(path or "").strip()))
        except Exception:
            return os.path.normcase(str(path or "").strip())
    def _get_sorter_auto_managed_dir_cache(self):
        cache = getattr(self, "_sorter_auto_managed_dirs", None)
        if not isinstance(cache, set):
            cache = set()
            try:
                self._sorter_auto_managed_dirs = cache
            except Exception:
                pass
        return cache
    def _is_sorter_auto_managed_dir(self, path):
        try:
            if not path or not os.path.isdir(path):
                return False
            norm = self._normalize_sort_dir_path(path)
            if norm and norm in self._get_sorter_auto_managed_dir_cache():
                return True
            return os.path.exists(os.path.join(path, SORTER_AUTO_DIR_MARKER))
        except Exception:
            return False
    def _mark_sorter_auto_managed_dir(self, path):
        try:
            if not path or not os.path.isdir(path):
                return False
            norm = self._normalize_sort_dir_path(path)
            if norm:
                self._get_sorter_auto_managed_dir_cache().add(norm)
            return True
        except Exception:
            return False
    def _clear_sorter_auto_managed_marker(self, path):
        try:
            if not path or not os.path.isdir(path):
                return False
            mark_path = os.path.join(path, SORTER_AUTO_DIR_MARKER)
            if os.path.exists(mark_path):
                os.remove(mark_path)
            return True
        except Exception:
            return False
    def _import_and_cleanup_sorter_markers(self, src_dir):
        cleaned = 0
        src_dir = os.path.abspath(str(src_dir or "").strip())
        if not src_dir or not os.path.isdir(src_dir):
            return cleaned
        try:
            for root, dirs, files in os.walk(src_dir):
                if SORTER_AUTO_DIR_MARKER in (files or []):
                    norm = self._normalize_sort_dir_path(root)
                    if norm:
                        self._get_sorter_auto_managed_dir_cache().add(norm)
                    try:
                        os.remove(os.path.join(root, SORTER_AUTO_DIR_MARKER))
                        cleaned += 1
                    except Exception:
                        pass
        except Exception:
            return cleaned
        return cleaned
    def _cleanup_sorter_markers_for_paths(self, paths):
        cleaned = 0
        seen = set()
        for path in paths or []:
            norm = self._normalize_sort_dir_path(path)
            if not norm or norm in seen:
                continue
            seen.add(norm)
            try:
                if self._clear_sorter_auto_managed_marker(path):
                    cleaned += 1
            except Exception:
                pass
        return cleaned
    def _filter_sort_subdirs(self, root, dirs, src_dir="", allow_pair_status_dirs=False, force_rescan=False):
        kept = []
        for d in dirs or []:
            cand = os.path.join(root, d)
            if self._is_sorter_auto_managed_dir(cand):
                if force_rescan:
                    kept.append(d)
                    continue
                if allow_pair_status_dirs and self._is_pair_status_bucket_dir(cand):
                    kept.append(d)
                    continue
                continue
            kept.append(d)
        return kept
    def _hash_file_for_sort_compare(self, path, chunk_size=1024 * 1024):
        md5 = hashlib.md5()
        with open(path, "rb") as f:
            while True:
                chunk = f.read(max(4096, int(chunk_size or 1024 * 1024)))
                if not chunk:
                    break
                md5.update(chunk)
        return md5.hexdigest()
    def _are_sort_files_equivalent(self, src_path, dst_path):
        try:
            if not (src_path and dst_path and os.path.exists(src_path) and os.path.exists(dst_path)):
                return False
            if os.path.getsize(src_path) != os.path.getsize(dst_path):
                return False
            return self._hash_file_for_sort_compare(src_path) == self._hash_file_for_sort_compare(dst_path)
        except Exception:
            return False
    def _build_name_existing_match_items(self, src_dir):
        result = []
        recursive = self.recursive_check.isChecked() if hasattr(self, "recursive_check") and is_alive(self.recursive_check) else False
        try:
            for root, dirs, files in os.walk(src_dir):
                dirs[:] = self._filter_sort_subdirs(root, dirs, src_dir)
                sibling_dirs = [d for d in dirs if os.path.isdir(os.path.join(root, d))]
                for fname in files:
                    best_folder, best_score, second_best = self._find_auto_sort_folder_for_file(fname, sibling_dirs, return_detail=True)
                    if not best_folder:
                        continue
                    stem = os.path.splitext(os.path.basename(str(fname or "")))[0].strip()
                    base_variant = self._strip_sort_variant_suffix(fname)
                    note_parts = []
                    if base_variant and base_variant != stem:
                        note_parts.append(f"编号后缀识别：{base_variant}")
                    if second_best > 0:
                        note_parts.append(f"次高分 {second_best:.2f}")
                    result.append({
                        "root": os.path.abspath(root),
                        "file_path": os.path.join(root, fname),
                        "file_name": fname,
                        "folder": best_folder,
                        "score": float(best_score or 0.0),
                        "rule_keyword": base_variant or stem,
                        "note": "；".join(note_parts) if note_parts else "高匹配已有文件夹",
                    })
                if not recursive:
                    break
        except Exception:
            return []
        result.sort(key=lambda x: (x.get("root", ""), x.get("file_name", "")))
        return result
    def _preview_name_existing_matches(self, src_dir, quiet=False):
        items = self._build_name_existing_match_items(src_dir)
        if not items:
            if not quiet:
                QMessageBox.information(self, "提示", "没有识别到可放入已有文件夹的高匹配结果。")
            return ({}, [])
        dlg = NameExistingMatchPreviewDialog(items, src_dir=src_dir, parent=self)
        if PYQT_VERSION == 6:
            accepted = (dlg.exec() == QDialog.DialogCode.Accepted)
        else:
            accepted = (dlg.exec_() == QDialog.Accepted)
        if not accepted:
            return None
        confirmed = dlg.get_confirmed_matches()
        quick_rules = dlg.get_generated_rules()
        match_map = {}
        for item in confirmed:
            fpath = os.path.abspath(item.get("file_path", "") or "")
            root = os.path.abspath(item.get("root", "") or "")
            folder = self._sanitize_sort_folder_name(item.get("folder", "") or "", fallback="")
            if not fpath or not root or not folder:
                continue
            match_map[fpath] = os.path.join(root, folder)
        if not match_map and not quick_rules and not quiet:
            QMessageBox.information(self, "提示", "你没有保留任何匹配项，本次不会按“已有文件夹匹配”移动文件。")
        return (match_map, quick_rules)
    def run_sorting(self):
        src_dir = self.sorter_path_input.text().strip()
        if not src_dir or not os.path.exists(src_dir): QMessageBox.warning(self, "提示", "源目录不存在"); return
        try:
            cleaned_marker_count = self._import_and_cleanup_sorter_markers(src_dir)
            if cleaned_marker_count:
                self.log(f"已自动清理 {cleaned_marker_count} 个旧的分类标记文件。", "blue")
        except Exception:
            pass
        mode = self._get_sorter_mode()
        if mode == "flatten_to_root":
            flatten_files = self._collect_flatten_sort_files(src_dir, recursive=self.recursive_check.isChecked())
            if not flatten_files:
                self.log(f"当前模式【{self._get_sorter_mode_label(mode)}】下没有找到可提取的子文件夹文件", "orange")
                return
            target_dir = self._resolve_flatten_sort_target_dir(src_dir)
            delete_empty_dirs = self.sorter_flatten_delete_empty_check.isChecked() if hasattr(self, "sorter_flatten_delete_empty_check") and is_alive(self.sorter_flatten_delete_empty_check) else True
            scope_text = "所有层级子文件夹" if self.recursive_check.isChecked() else "直接子文件夹"
            confirm = QMessageBox.question(
                self,
                "确认提取文件",
                f"即将把 {len(flatten_files)} 个文件从{scope_text}提取到：\n{target_dir}\n\n是否继续？"
            )
            accepted_yes = QMessageBox.StandardButton.Yes if PYQT_VERSION == 6 else QMessageBox.Yes
            if confirm != accepted_yes:
                self.log("已取消提取子文件夹文件。", "orange")
                return
            try:
                os.makedirs(target_dir, exist_ok=True)
            except Exception as e:
                QMessageBox.warning(self, "提示", f"无法创建目标目录：\n{target_dir}\n\n{e}")
                return
            count = 0
            history = []
            skipped_existing_count = 0
            conflict_rename_count = 0
            failures = []
            for fpath in flatten_files:
                if not fpath or not os.path.exists(fpath):
                    continue
                fname = os.path.basename(fpath)
                target_path = os.path.join(target_dir, fname)
                if os.path.abspath(target_path) == os.path.abspath(fpath):
                    continue
                try:
                    if os.path.exists(target_path) and self._are_sort_files_equivalent(fpath, target_path):
                        skipped_existing_count += 1
                        continue
                    resolved_target_path = _pick_nonconflict_path(target_path)
                    if os.path.abspath(resolved_target_path) != os.path.abspath(target_path):
                        conflict_rename_count += 1
                    target_path = resolved_target_path
                    shutil.move(fpath, target_path)
                    history.append((fpath, target_path))
                    count += 1
                except Exception as e:
                    failures.append((fpath, target_path, str(e)))
            removed_empty_dirs = []
            if count > 0 and delete_empty_dirs:
                removed_empty_dirs = self._remove_empty_sort_dirs(src_dir, keep_dirs=[target_dir])
            if count > 0:
                self.last_sort_history = history
                self.btn_undo_sort.setEnabled(True)
                detail_parts = [f"提取文件 {count}"]
                if skipped_existing_count:
                    detail_parts.append(f"已存在同内容跳过 {skipped_existing_count}")
                if conflict_rename_count:
                    detail_parts.append(f"冲突自动改名 {conflict_rename_count}")
                if removed_empty_dirs:
                    detail_parts.append(f"删除空文件夹 {len(removed_empty_dirs)}")
                self.log(f"分类完成，模式：{self._get_sorter_mode_label(mode)}（{'，'.join(detail_parts)}）", "green")
                if failures:
                    self.log(f"⚠️ 另有 {len(failures)} 个文件提取失败（常见原因：文件被占用/无权限）。", "orange")
                    msg_lines = ["以下文件未能提取到目标目录："]
                    for fp, tp, err in failures[:10]:
                        msg_lines.append(f"- {os.path.basename(fp)}")
                    if len(failures) > 10:
                        msg_lines.append(f"... 还有 {len(failures) - 10} 个未展示")
                    try:
                        QMessageBox.warning(self, "部分文件未提取", "\n".join(msg_lines))
                    except Exception:
                        pass
            else:
                self.log(f"当前模式【{self._get_sorter_mode_label(mode)}】下未发现可移动的文件", "orange")
            return
        if mode == "extract_incomplete_pairs":
            recursive = True
            keep_structure = self.sorter_incomplete_keep_structure_check.isChecked() if hasattr(self, "sorter_incomplete_keep_structure_check") and is_alive(self.sorter_incomplete_keep_structure_check) else True
            check_missing_txt = self.sorter_incomplete_check_missing_txt_check.isChecked() if hasattr(self, "sorter_incomplete_check_missing_txt_check") and is_alive(self.sorter_incomplete_check_missing_txt_check) else False
            force_rescan = True
            target_dir = self._resolve_incomplete_pairs_target_dir(src_dir)
            pair_groups = self._collect_pair_status_folders(
                src_dir,
                recursive=recursive,
                check_missing_txt=check_missing_txt,
                output_root=target_dir,
                force_rescan=force_rescan,
            )
            incomplete_items = pair_groups.get("incomplete", []) or []
            complete_items = pair_groups.get("complete", []) or []
            manual_review_items = pair_groups.get("manual_review", []) or []
            if not incomplete_items and not complete_items and not manual_review_items:
                self.log(f"当前模式【{self._get_sorter_mode_label(mode)}】已强制重扫当前范围，但没有发现可归类的配对文件夹", "orange")
                return

            # 预览提示：展示前若干项
            preview_lines = []
            preview_items = (
                [dict(it, _preview_status="缺失") for it in incomplete_items[:6]]
                + [dict(it, _preview_status="需检查") for it in manual_review_items[:6]]
                + [dict(it, _preview_status="完整") for it in complete_items[:6]]
            )
            for it in preview_items:
                rel = ""
                try:
                    rel = os.path.relpath(it.get("path", ""), src_dir)
                except Exception:
                    rel = os.path.basename(it.get("path", "") or "")
                m_mp4 = it.get("missing_mp4", []) or []
                m_txt = it.get("missing_txt", []) or []
                extra_videos = it.get("extra_videos", []) or []
                note_parts = []
                if m_mp4:
                    note_parts.append(f"缺视频:{','.join(m_mp4[:8])}{'...' if len(m_mp4) > 8 else ''}")
                if m_txt:
                    note_parts.append(f"缺文本:{','.join(m_txt[:8])}{'...' if len(m_txt) > 8 else ''}")
                if extra_videos:
                    note_parts.append(f"额外视频:{','.join(extra_videos[:4])}{'...' if len(extra_videos) > 4 else ''}")
                if not note_parts:
                    paired = it.get("paired", []) or []
                    note_parts.append(f"完整配对:{len(paired)} 组")
                preview_lines.append(f"- [{it.get('_preview_status', '缺失')}] {rel}（{'；'.join(note_parts)}）")
            total_items = len(incomplete_items) + len(complete_items) + len(manual_review_items)
            more_hint = f"\n... 还有 {total_items - len(preview_items)} 个未展示" if total_items > len(preview_items) else ""
            scope_text = "所有层级子文件夹（强制重扫）" if force_rescan else ("所有层级子文件夹" if recursive else "直接子文件夹")
            keep_text = "保持原结构" if keep_structure else "仅保留文件夹名"
            incomplete_dir = os.path.join(target_dir, "缺失")
            manual_review_dir = os.path.join(target_dir, "需检查")
            complete_dir = os.path.join(target_dir, "完整")
            confirm = QMessageBox.question(
                self,
                "确认提取配对文件夹",
                f"将从{scope_text}中整理 {total_items} 个文件夹：\n"
                f"- 缺失：{len(incomplete_items)} 个 → {incomplete_dir}\n"
                f"- 需检查：{len(manual_review_items)} 个 → {manual_review_dir}\n"
                f"- 完整：{len(complete_items)} 个 → {complete_dir}\n\n方式：{keep_text}\n\n示例：\n"
                + "\n".join(preview_lines)
                + more_hint
                + "\n\n每次执行都会把当前范围内已有的“完整 / 缺失 / 需检查”结果重新洗牌归并，最终只保留一层结果目录，不会再出现里面套一层同名目录。\n\n是否继续？"
            )
            accepted_yes = QMessageBox.StandardButton.Yes if PYQT_VERSION == 6 else QMessageBox.Yes
            if confirm != accepted_yes:
                self.log("已取消提取配对文件夹。", "orange")
                return

            try:
                os.makedirs(target_dir, exist_ok=True)
                if incomplete_items:
                    os.makedirs(incomplete_dir, exist_ok=True)
                if manual_review_items:
                    os.makedirs(manual_review_dir, exist_ok=True)
                if complete_items:
                    os.makedirs(complete_dir, exist_ok=True)
                try:
                    self._mark_sorter_auto_managed_dir(target_dir)
                    if incomplete_items:
                        self._mark_sorter_auto_managed_dir(incomplete_dir)
                    if manual_review_items:
                        self._mark_sorter_auto_managed_dir(manual_review_dir)
                    if complete_items:
                        self._mark_sorter_auto_managed_dir(complete_dir)
                except Exception:
                    pass
            except Exception as e:
                QMessageBox.warning(self, "提示", f"无法创建目标目录：\n{target_dir}\n\n{e}")
                return

            count = 0
            stable_count = 0
            history = []
            failures = []
            skipped = 0
            moved_incomplete = 0
            moved_manual_review = 0
            moved_complete = 0
            for status_key, bucket_dir, items in (
                ("缺失", incomplete_dir, incomplete_items),
                ("需检查", manual_review_dir, manual_review_items),
                ("完整", complete_dir, complete_items),
            ):
                for it in items:
                    folder_path = os.path.abspath(it.get("path", "") or "")
                    if not folder_path or not os.path.isdir(folder_path):
                        continue
                    try:
                        # 防止把“输出目录”本身/其上级目录再次搬走导致递归错乱
                        if target_dir and os.path.commonpath([folder_path, target_dir]) == folder_path:
                            skipped += 1
                            continue
                        # 如果目标桶目录在源目录里，避免把桶目录搬走
                        if os.path.commonpath([folder_path, bucket_dir]) == folder_path:
                            skipped += 1
                            continue
                    except Exception:
                        pass

                    try:
                        rel = os.path.relpath(folder_path, src_dir) if keep_structure else os.path.basename(folder_path)
                    except Exception:
                        rel = os.path.basename(folder_path)
                    rel = self._normalize_pair_sort_rel_path(rel)
                    rel = rel.strip().lstrip("\\/") if rel else os.path.basename(folder_path)
                    target_path = os.path.join(bucket_dir, rel)
                    try:
                        os.makedirs(os.path.dirname(target_path), exist_ok=True)
                    except Exception:
                        pass
                    same_target = False
                    try:
                        same_target = os.path.abspath(target_path) == os.path.abspath(folder_path)
                    except Exception:
                        same_target = False
                    if same_target:
                        stable_count += 1
                        if status_key == "缺失":
                            moved_incomplete += 1
                        elif status_key == "需检查":
                            moved_manual_review += 1
                        else:
                            moved_complete += 1
                        continue
                    target_path = _pick_nonconflict_path(target_path)
                    try:
                        shutil.move(folder_path, target_path)
                        history.append((folder_path, target_path))
                        count += 1
                        if status_key == "缺失":
                            moved_incomplete += 1
                        elif status_key == "需检查":
                            moved_manual_review += 1
                        else:
                            moved_complete += 1
                    except Exception as e:
                        failures.append((folder_path, target_path, f"{status_key}: {e}"))

            removed_empty_dirs = []
            removed_source_root = False
            if count > 0:
                try:
                    removed_empty_dirs = self._remove_empty_sort_dirs(
                        src_dir,
                        keep_dirs=[target_dir, incomplete_dir, manual_review_dir, complete_dir],
                    )
                except Exception:
                    removed_empty_dirs = []
                try:
                    removed_source_root = self._remove_single_empty_sort_dir(
                        src_dir,
                        keep_dirs=[target_dir, incomplete_dir, manual_review_dir, complete_dir],
                    )
                except Exception:
                    removed_source_root = False

            if count > 0 or stable_count > 0:
                if history:
                    self.last_sort_history = history
                    self.btn_undo_sort.setEnabled(True)
                detail_parts = [f"处理文件夹 {count + stable_count}", f"缺失 {moved_incomplete}", f"需检查 {moved_manual_review}", f"完整 {moved_complete}"]
                if stable_count:
                    detail_parts.append(f"原位保留 {stable_count}")
                if skipped:
                    detail_parts.append(f"跳过 {skipped}")
                if removed_empty_dirs:
                    detail_parts.append(f"删除空文件夹 {len(removed_empty_dirs)}")
                if removed_source_root:
                    detail_parts.append("删除旧结果根目录 1")
                self.log(f"分类完成，模式：{self._get_sorter_mode_label(mode)}（{'，'.join(detail_parts)}）", "green")
                if failures:
                    self.log(f"⚠️ 另有 {len(failures)} 个项目移动失败（常见原因：文件被占用/无权限）。", "orange")
                    msg_lines = ["以下项目未能移动（常见原因：文件被占用/无权限）。请先关闭占用程序后重试："]
                    for fp, tp, err in failures[:10]:
                        msg_lines.append(f"- {os.path.basename(fp)}")
                    if len(failures) > 10:
                        msg_lines.append(f"... 还有 {len(failures) - 10} 个未展示")
                    try:
                        QMessageBox.warning(self, "部分项目未移动", "\n".join(msg_lines))
                    except Exception:
                        pass
            else:
                self.log(f"当前模式【{self._get_sorter_mode_label(mode)}】下未发现可处理的文件夹", "orange")
            return
        rules = self._collect_sorter_rules()
        if mode == "custom_rule" and not rules:
            QMessageBox.warning(self, "提示", "当前是“自定义规则模式”，请至少设置一条有效的分类规则。")
            return
        filename_groups = []
        if mode in ("comprehensive", "filename_group"):
            preview_result = self._preview_filename_auto_groups(src_dir)
            if preview_result is None:
                self.log("已取消按文件名前缀自动分组。", "orange")
                return
            filename_groups = preview_result or []
            if mode == "filename_group" and not filename_groups:
                self.log("当前模式下没有可自动成组的文件。", "orange")
                return
        filename_group_map = {}
        for group in filename_groups:
            root = os.path.abspath(group.get("root", "") or "")
            folder = self._sanitize_sort_folder_name(group.get("folder", "") or "")
            if not root or not folder:
                continue
            for fpath in group.get("files", []) or []:
                filename_group_map[os.path.abspath(fpath)] = os.path.join(root, folder)
        # 先计算“按文件名匹配现有文件夹”的候选（不在这里弹窗；统一在“分类前预览”里编辑）
        name_existing_items = []
        name_existing_item_by_path = {}
        if mode in ("comprehensive", "name_existing"):
            name_existing_items = self._build_name_existing_match_items(src_dir)
            for it in name_existing_items:
                try:
                    p = os.path.abspath(it.get("file_path", "") or "")
                except Exception:
                    p = ""
                if p:
                    name_existing_item_by_path[p] = it

        # ── 统一生成分类计划（预览 + 快速编辑 + 写规则）──
        plan_items = []
        for root, dirs, files in os.walk(src_dir):
            dirs[:] = self._filter_sort_subdirs(root, dirs, src_dir)
            for fname in files:
                fpath = os.path.join(root, fname)
                abs_fpath = os.path.abspath(fpath)
                matched_by = ""
                folder_name = ""
                match_info = ""
                note = ""
                rule_keyword = ""
                rule_mode = ""

                # 1) 自定义规则（优先级最高）
                if mode in ("comprehensive", "custom_rule"):
                    for r in rules:
                        if self._match_sort_rule(fname, r):
                            folder_name = self._sanitize_sort_folder_name(r.get("f", ""), fallback="")
                            if folder_name:
                                matched_by = "rule"
                                rule_keyword = str(r.get("p", "") or "").strip()
                                rule_mode = str(r.get("m", "") or "包含").strip() or "包含"
                                if rule_mode == "正则":
                                    rule_mode = "正则表达式"
                                match_info = f"{rule_mode} {rule_keyword}".strip()
                                note = f"命中规则：{rule_mode} {rule_keyword} => {folder_name}".strip()
                            break

                # 2) 文件名匹配现有文件夹（同级目录）
                if not folder_name and mode in ("comprehensive", "name_existing"):
                    info = name_existing_item_by_path.get(abs_fpath)
                    if info:
                        folder_name = self._sanitize_sort_folder_name(info.get("folder", ""), fallback="")
                        if folder_name:
                            matched_by = "auto"
                            try:
                                match_info = f"{float(info.get('score', 0.0) or 0.0):.2f}"
                            except Exception:
                                match_info = str(info.get("score", "") or "")
                            note = str(info.get("note", "") or "文件名匹配已有文件夹")
                            # “名称归类”命中的目标通常是带编号的文件夹（如 0720-C-12）。
                            # 若继续沿用旧的 base_variant（例如 0720-C）会导致写规则时出现大量冲突（同一个关键词指向多个文件夹）。
                            # 这里默认把规则关键词设为目标文件夹名，避免冲突，用户也更容易理解。
                            rule_keyword = str(folder_name or "").strip()
                            rule_mode = "开头是"

                # 3) 文件名前缀自动分组（预览已确认）
                if not folder_name and mode in ("comprehensive", "filename_group") and filename_group_map:
                    target_dir = filename_group_map.get(abs_fpath, "")
                    if target_dir:
                        folder_name = self._sanitize_sort_folder_name(os.path.basename(target_dir), fallback="")
                        if folder_name:
                            matched_by = "filename_group"
                            match_info = ""
                            note = "文件名前缀自动分组"
                            rule_keyword = os.path.splitext(os.path.basename(fname))[0]
                            rule_mode = "开头是"

                # 4) 扩展名分类
                if not folder_name and mode in ("comprehensive", "extension"):
                    target_dir = self._find_extension_sort_target_dir(src_dir, fname, rules if mode == "extension" else None)
                    if target_dir:
                        folder_name = self._sanitize_sort_folder_name(os.path.basename(target_dir), fallback="")
                        if folder_name:
                            matched_by = "extension"
                            ext = os.path.splitext(str(fname or ""))[1].lower()
                            match_info = ext or "无后缀"
                            note = "按扩展名分类"
                            rule_keyword = ext or ""
                            rule_mode = "后缀名"

                # 5) 时间分类
                if not folder_name and mode == "time":
                    target_dir = self._build_time_sort_target_dir(src_dir, fpath)
                    if target_dir:
                        folder_name = self._sanitize_sort_folder_name(os.path.basename(target_dir), fallback="")
                        if folder_name:
                            matched_by = "time"
                            match_info = ""
                            note = "按时间归档"
                            rule_keyword = ""
                            rule_mode = "包含"

                if folder_name:
                    plan_items.append({
                        "matched_by": matched_by,
                        "root": os.path.abspath(root),
                        "file_path": abs_fpath,
                        "file_name": fname,
                        "folder": folder_name,
                        "match_info": match_info,
                        "rule_keyword": rule_keyword,
                        "rule_mode": rule_mode,
                        "note": note,
                    })
            if not self.recursive_check.isChecked():
                break

        if not plan_items:
            self.log(f"当前模式【{self._get_sorter_mode_label(mode)}】下未发现可移动的文件", "orange")
            return

        # 分类前预览：可改目标/跳过/批量改/写规则
        dlg = NameExistingMatchPreviewDialog(plan_items, src_dir=src_dir, parent=self, title="分类前预览匹配结果")
        if PYQT_VERSION == 6:
            accepted = (dlg.exec() == QDialog.DialogCode.Accepted)
        else:
            accepted = (dlg.exec_() == QDialog.Accepted)
        if not accepted:
            self.log("已取消本次分类（预览窗口已关闭）。", "orange")
            return

        confirmed = dlg.get_confirmed_matches()
        quick_rules = dlg.get_generated_rules()
        added_rule_count = self._append_sorter_rules(quick_rules, bucket="rule") if quick_rules else 0
        if added_rule_count:
            self.log(f"已从预览勾选项写入 {added_rule_count} 条规则，可在规则区继续编辑。", "blue")

        # ── 执行移动 ──
        count = 0; history = []; rule_count = 0; auto_count = 0; filename_group_count = 0; extension_count = 0; time_count = 0
        skipped_existing_count = 0; conflict_rename_count = 0
        failures = []
        created_dirs = []
        created_dir_seen = set()
        for item in confirmed or []:
            fpath = os.path.abspath(item.get("file_path", "") or "")
            if not fpath or not os.path.exists(fpath):
                continue
            fname = str(item.get("file_name", "") or os.path.basename(fpath))
            root = os.path.abspath(item.get("root", "") or os.path.dirname(fpath))
            folder = self._sanitize_sort_folder_name(item.get("folder", "") or "", fallback="")
            matched_by = str(item.get("matched_by", "") or "").strip()
            if not folder:
                continue

            target_dir = ""
            if matched_by == "rule":
                target_dir = self._resolve_sort_rule_target_dir(src_dir, root, folder)
            elif matched_by in ("auto", "name_existing", "filename_group"):
                target_dir = os.path.join(root, folder)
            elif matched_by in ("extension", "time"):
                target_dir = os.path.join(src_dir, folder)
            else:
                target_dir = os.path.join(src_dir, folder)
            if not target_dir:
                continue
            target_dir_created_now = False
            try:
                if not os.path.exists(target_dir):
                    os.makedirs(target_dir)
                    target_dir_created_now = True
                    norm_target_dir = self._normalize_sort_dir_path(target_dir)
                    if norm_target_dir and norm_target_dir not in created_dir_seen:
                        created_dir_seen.add(norm_target_dir)
                        created_dirs.append(os.path.abspath(target_dir))
            except Exception:
                continue
            try:
                if target_dir_created_now or matched_by in ("rule", "extension", "time", "filename_group"):
                    self._mark_sorter_auto_managed_dir(target_dir)
            except Exception:
                pass

            target_path = os.path.join(target_dir, fname)
            if os.path.abspath(target_path) == os.path.abspath(fpath):
                continue
            try:
                if os.path.exists(target_path) and self._are_sort_files_equivalent(fpath, target_path):
                    skipped_existing_count += 1
                    continue
                resolved_target_path = _pick_nonconflict_path(target_path)
                if os.path.abspath(resolved_target_path) != os.path.abspath(target_path):
                    conflict_rename_count += 1
                target_path = resolved_target_path
                shutil.move(fpath, target_path)
                history.append((fpath, target_path))
                count += 1
                if matched_by == "rule": rule_count += 1
                elif matched_by in ("auto", "name_existing"): auto_count += 1
                elif matched_by == "filename_group": filename_group_count += 1
                elif matched_by == "extension": extension_count += 1
                elif matched_by == "time": time_count += 1
            except Exception as e:
                # 不尝试“删源文件”兜底：用户明确不希望在存在同名/多份时通过删除来解决。
                failures.append((fpath, target_path, str(e)))
        if count > 0:
            self.last_sort_history = history; self.btn_undo_sort.setEnabled(True)
            detail_parts = []
            if rule_count: detail_parts.append(f"规则 {rule_count}")
            if auto_count: detail_parts.append(f"文件名匹配现有文件夹 {auto_count}")
            if filename_group_count: detail_parts.append(f"文件名前缀分组 {filename_group_count}")
            if extension_count: detail_parts.append(f"扩展名分类 {extension_count}")
            if time_count: detail_parts.append(f"时间分类 {time_count}")
            if skipped_existing_count: detail_parts.append(f"已存在同内容跳过 {skipped_existing_count}")
            if conflict_rename_count: detail_parts.append(f"冲突自动改名 {conflict_rename_count}")
            if created_dirs: detail_parts.append(f"新建目录 {len(created_dirs)}")
            detail_text = f"（{'，'.join(detail_parts)}）" if detail_parts else ""
            self.log(f"分类完成，模式：{self._get_sorter_mode_label(mode)}，共移动 {count} 个文件{detail_text}", "green")
            if failures:
                self.log(f"⚠️ 另有 {len(failures)} 个文件移动失败（常见原因：文件被占用/无权限）。可先关闭占用程序后重试。", "orange")
                msg_lines = ["以下文件未能移动（常见原因：文件被占用/无权限）。请先关闭正在播放/编辑该文件的程序后重试："]
                for fp, tp, err in failures[:10]:
                    msg_lines.append(f"- {os.path.basename(fp)}")
                if len(failures) > 10:
                    msg_lines.append(f"... 还有 {len(failures) - 10} 个未展示")
                try:
                    QMessageBox.warning(self, "部分文件未移动", "\n".join(msg_lines))
                except Exception:
                    pass
        else:
            self.log(f"当前模式【{self._get_sorter_mode_label(mode)}】下未发现可移动的文件", "orange")
    def run_undo_sorting(self):
        if not self.last_sort_history: return
        count = 0
        for src, dst in reversed(self.last_sort_history):
            try:
                if os.path.exists(dst):
                    os.makedirs(os.path.dirname(src), exist_ok=True); shutil.move(dst, src); count += 1
            except: pass
        self.last_sort_history = []; self.btn_undo_sort.setEnabled(False); self.log(f"已撤销 {count} 个文件的移动", "blue")
    def sanitize_filename(self, filename, max_len=120):
        """清理文件名中的 Windows 非法字符并限制长度"""
        # Windows 非法字符: \ / : * ? " < > |
        invalid_chars = r'[\\/:*?"<>|\r\n\t]'
        import re
        # 替换非法字符为空格
        clean_name = re.sub(invalid_chars, ' ', filename)
        # 压缩连续空格
        clean_name = ' '.join(clean_name.split())
        # 限制长度 (截取前 max_len 个字符)
        if len(clean_name) > max_len:
            clean_name = clean_name[:max_len].strip()
        return clean_name

    def _resolve_renamer_name_ext(self, name_text, original_ext):
        """
        解析“包含后缀名”模式下的输入。
        默认优先保留原后缀，只有当用户输入的是明确且常见的扩展名时，才允许覆盖。
        这样主文件名里出现句点时，不会把内容误判为新后缀。
        """
        raw_name = (name_text or "").strip()
        original_ext = (original_ext or "").strip()
        if not raw_name:
            return "", original_ext

        base_part, typed_ext = os.path.splitext(raw_name)
        if not typed_ext:
            return raw_name, original_ext

        known_exts = {
            ".mp4", ".mov", ".avi", ".mkv", ".wmv", ".flv", ".m4v", ".webm",
            ".mp3", ".wav", ".aac", ".flac", ".m4a",
            ".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp", ".tiff",
            ".txt", ".csv", ".xlsx", ".xls", ".doc", ".docx", ".ppt", ".pptx",
            ".pdf", ".zip", ".rar", ".7z", ".json", ".md"
        }
        typed_ext_lower = typed_ext.lower()
        original_ext_lower = original_ext.lower()

        if typed_ext_lower == original_ext_lower:
            return base_part, original_ext

        if re.fullmatch(r'\.[a-z0-9]{1,8}', typed_ext_lower) and (typed_ext_lower in known_exts or not original_ext):
            return base_part, typed_ext

        return raw_name, original_ext

    def parse_csv_for_rename(self, csv_path):
        """解析 CSV 或 Excel 文件，提取代码和中文文案，返回 {代码: 中文文案} 字典。"""
        mapping = {}
        if not os.path.exists(csv_path):
            self.log(f"[智能改名] 错误：文件不存在: {csv_path}", "red")
            return mapping
        
        try:
            # 判断是否为 Excel 文件
            if csv_path.lower().endswith(('.xlsx', '.xls')):
                try:
                    import pandas as pd
                    # 读取所有分页 (sheet_name=None 会返回一个字典 {sheet_name: dataframe})
                    all_sheets = pd.read_excel(csv_path, sheet_name=None)
                    total_count = 0
                    for sheet_name, df in all_sheets.items():
                        df.columns = [str(c).strip() for c in df.columns]
                        if "代码" in df.columns and "中文文案" in df.columns:
                            sheet_count = 0
                            for _, row in df.iterrows():
                                code = str(row["代码"]).strip()
                                cn_text = str(row["中文文案"]).strip()
                                if code and code != 'nan' and code != 'None':
                                    mapping[code] = cn_text
                                    sheet_count += 1
                            total_count += sheet_count
                            self.log(f"[智能改名] 分页 '{sheet_name}' 加载了 {sheet_count} 条规则", "blue")
                    
                    if total_count > 0:
                        self.log(f"[智能改名] 成功从所有分页加载共 {len(mapping)} 条唯一映射规则", "green")
                    else:
                        self.log("[智能改名] 错误：Excel 任何分页中都未找到『代码』和『中文文案』列", "red")
                except Exception as e:
                    self.log(f"[智能改名] Excel 多分页解析失败: {str(e)}", "red")
            else:
                # 采用二进制读取并尝试多种编码读取 CSV
                data = open(csv_path, 'rb').read()
                text = None
                for enc in ['utf-8-sig', 'gbk', 'utf-8', 'gb18030']:
                    try:
                        text = data.decode(enc)
                        break
                    except: continue
                
                if text is None: raise Exception("无法识别文件编码")

                import io
                import csv
                f = io.StringIO(text)
                reader = csv.reader(f)
                header = [h.strip() for h in next(reader)]
                
                try:
                    code_col_idx = header.index("代码")
                    cn_text_col_idx = header.index("中文文案")
                    for i, row in enumerate(reader):
                        if len(row) > max(code_col_idx, cn_text_col_idx):
                            code = row[code_col_idx].strip()
                            cn_text = row[cn_text_col_idx].strip()
                            if code: mapping[code] = cn_text
                        else:
                            self.log(f"[智能改名] 警告：CSV 第 {i+2} 行数据不完整，已跳过", "orange")
                    self.log(f"[智能改名] 成功加载 {len(mapping)} 条 CSV 映射规则", "green")
                except ValueError:
                    self.log("[智能改名] 错误：CSV 必须包含『代码』和『中文文案』列", "red")
        except Exception as e:
            self.log(f"[智能改名] 错误：解析文件失败: {str(e)}", "red")
        return mapping

    def _compose_renamer_stem(self, prefix_text, main_text):
        """组合前缀和主文件名：两者都存在时默认使用连字符分隔。"""
        prefix = (prefix_text or "").strip()
        main = (main_text or "").strip()
        if prefix and main:
            return f"{prefix}-{main}"
        return prefix or main

    def _find_best_rename_code_match(self, name_without_ext, csv_mapping):
        """
        从文件名中寻找最合适的代码匹配：
        1. 优先匹配更长的代码，避免 11/12 被 1 抢先命中；
        2. 先尝试“边界匹配”，再退回普通包含匹配。
        """
        raw_name = str(name_without_ext or "").strip()
        if not raw_name or not csv_mapping:
            return None

        codes = sorted(
            {str(code).strip() for code in csv_mapping.keys() if str(code).strip()},
            key=lambda x: (-len(x), x)
        )
        if not codes:
            return None

        boundary_chars = r"A-Za-z0-9\u4e00-\u9fff"

        for code in codes:
            pat = rf"(?<![{boundary_chars}]){re.escape(code)}(?![{boundary_chars}])"
            if re.search(pat, raw_name, re.IGNORECASE):
                return code

        raw_name_lower = raw_name.lower()
        for code in codes:
            if code.lower() in raw_name_lower:
                return code

        return None

    def renamer_smart_rename_preview(self):
        if not hasattr(self, "is_smart_rename_mode"): self.is_smart_rename_mode = False
        csv_path = self.renamer_csv_input.text().strip()
        files_to_rename_str = self.renamer_files_input.text().strip()

        if not csv_path:
            QMessageBox.warning(self, "提示", "请拖入 CSV 文件")
            return
        
        csv_mapping = self.parse_csv_for_rename(csv_path)
        if not csv_mapping:
            return

        all_files_to_process = []

        if files_to_rename_str:
            # 有指定待改名文件夹/文件：按原逻辑处理
            if "\n" in files_to_rename_str:
                all_files_to_process = [f.strip() for f in files_to_rename_str.split("\n") if f.strip()]
            else:
                input_path = files_to_rename_str
                if os.path.isfile(input_path):
                    all_files_to_process.append(input_path)
                elif os.path.isdir(input_path):
                    for root, _, files in os.walk(input_path):
                        for f in files:
                            all_files_to_process.append(os.path.join(root, f))
                else:
                    self.log(f"[智能改名] 错误：无效的待改名路径: {input_path}", "red")
                    return
        else:
            # 待改名文件夹为空：直接使用已在表格中的文件（拖拽文件场景）
            if self.rename_table.rowCount() == 0:
                QMessageBox.warning(self, "提示", "请先拖拽文件到表格，或设置待改名文件夹")
                return
            for row in range(self.rename_table.rowCount()):
                item = self.rename_table.item(row, 0)
                if item:
                    p = item.text().strip()
                    if p and os.path.exists(p):
                        all_files_to_process.append(p)
            self.log(f"[智能改名] 待改名文件夹为空，直接匹配表格中 {len(all_files_to_process)} 个文件", "blue")

        self.rename_table.setRowCount(0)  # 清空旧的重命名列表
        self.is_smart_rename_mode = True  # 标记当前为智能改名模式

        if not all_files_to_process:
            self.log("[智能改名] 未找到任何待处理的文件", "orange")
            return

        renamed_count = 0
        for original_path in all_files_to_process:
            if not os.path.exists(original_path): continue

            basename = os.path.basename(original_path)
            name_without_ext, ext = os.path.splitext(basename)
            new_name_without_ext = name_without_ext
            
            matched_code = self._find_best_rename_code_match(name_without_ext, csv_mapping)
            matched = bool(matched_code)
            if matched:
                cn_text = str(csv_mapping.get(matched_code, "") or "").strip()
                new_name_without_ext = self._compose_renamer_stem(matched_code, cn_text)
            
            if matched:
                new_full_name = f"{new_name_without_ext}{ext}"
                # 确保新文件名合法且不为空
                if new_full_name and new_full_name != basename:
                    row = self.rename_table.rowCount()
                    self.rename_table.insertRow(row)
                    self.rename_table.setItem(row, 0, QTableWidgetItem(original_path))
                    self.rename_table.setItem(row, 1, QTableWidgetItem(new_name_without_ext)) # 预览时显示新文件名（不含后缀）
                    self.rename_table.setItem(row, 2, QTableWidgetItem(ext.lstrip("."))) # 显示后缀
                    renamed_count += 1
            else:
                self.log(f"[智能改名] 未找到匹配的代码，跳过文件: {basename}", "orange")

        if renamed_count > 0:
            self.log(f"[智能改名] 预览完成，共 {renamed_count} 个文件可智能改名", "green")
        else:
            self.log("[智能改名] 未找到任何可智能改名的文件", "orange")

    # ─────────────────────────────────────────────
    #  批量建文件夹：增强版（预览/模板/冲突处理/撤销）
    # ─────────────────────────────────────────────
    def _creator_collect_table_names(self):
        names = []
        if not hasattr(self, "creator_table") or not is_alive(self.creator_table):
            return names
        for i in range(self.creator_table.rowCount()):
            it = self.creator_table.item(i, 0)
            val = it.text().strip() if (it and it.text()) else ""
            if val:
                names.append(val)
        return names

    def _creator_get_template_names(self):
        if not getattr(self, "creator_use_template_check", None) or not is_alive(self.creator_use_template_check):
            return []
        if not self.creator_use_template_check.isChecked():
            return []
        raw = ""
        if hasattr(self, "creator_template_input") and is_alive(self.creator_template_input):
            raw = self.creator_template_input.toPlainText()
        items = []
        for line in str(raw or "").splitlines():
            s = line.strip().strip('"').strip("'")
            if not s:
                continue
            # 模板默认只允许单层名称；用户真要层级可以直接在表格里用 A1/素材 这种形式
            s = s.replace("\\", "/").replace("/", "_")
            s = self.sanitize_filename(s, max_len=80)
            if s:
                items.append(s)
        # 去重保序
        seen = set()
        out = []
        for x in items:
            if x in seen:
                continue
            seen.add(x)
            out.append(x)
        return out[:200]

    def _creator_sanitize_rel_path(self, raw_name, allow_nested=True):
        """
        返回“相对路径”：
        - allow_nested=True：允许 A1/素材/成片
        - 会屏蔽绝对路径、..、空段
        """
        s = str(raw_name or "").strip().strip('"').strip("'")
        if not s:
            return ""

        # 先把范围写法展开（允许在表格里直接填 A1-A10）
        try:
            expanded = self._expand_folder_name_range(s)
            if expanded and len(expanded) == 1:
                s = expanded[0]
        except Exception:
            pass

        # 屏蔽绝对路径/盘符路径
        if os.path.isabs(s) or re.match(r"^[A-Za-z]:[\\/]", s):
            return ""

        s = s.replace("\\", "/")
        if allow_nested:
            parts = [p for p in s.split("/") if p not in ("", ".", " ")]
            safe_parts = []
            for p in parts:
                if p == "..":
                    return ""
                p = self.sanitize_filename(p, max_len=120)
                if not p:
                    continue
                safe_parts.append(p)
            if not safe_parts:
                return ""
            try:
                return os.path.join(*safe_parts)
            except Exception:
                return ""
        # 不允许层级：斜杠改成下划线
        s = s.replace("/", "_")
        return self.sanitize_filename(s, max_len=160)

    def _creator_apply_prefix_suffix(self, rel_path, prefix="", suffix=""):
        prefix = str(prefix or "").strip()
        suffix = str(suffix or "").strip()
        if not (prefix or suffix):
            return rel_path

        # 只对“最后一级文件夹名”加前后缀，避免 A1/素材 这种被整体包裹
        try:
            parts = rel_path.split(os.sep)
        except Exception:
            parts = [rel_path]
        if not parts:
            return rel_path
        leaf = parts[-1]
        leaf = self.sanitize_filename(f"{prefix}{leaf}{suffix}", max_len=160)
        parts[-1] = leaf
        return os.sep.join([p for p in parts if p])

    def _creator_make_unique_dir_path(self, abs_path):
        """当目录已存在时，自动追加 _2/_3... 找到可用目录名。"""
        if not os.path.exists(abs_path):
            return abs_path
        base = abs_path.rstrip("\\/ ")
        n = 2
        while n <= 9999:
            cand = f"{base}_{n}"
            if not os.path.exists(cand):
                return cand
            n += 1
        return ""

    def _creator_get_daily_rule_config(self):
        data = {
            "enabled": self.creator_daily_enable_check.isChecked() if hasattr(self, "creator_daily_enable_check") and is_alive(self.creator_daily_enable_check) else False,
            "root": self.creator_daily_root_input.text().strip() if hasattr(self, "creator_daily_root_input") and is_alive(self.creator_daily_root_input) else "",
            "use_date_folder": self.creator_daily_use_date_folder_check.isChecked() if hasattr(self, "creator_daily_use_date_folder_check") and is_alive(self.creator_daily_use_date_folder_check) else True,
            "date_format": self.creator_daily_date_format_input.text().strip() if hasattr(self, "creator_daily_date_format_input") and is_alive(self.creator_daily_date_format_input) else "%Y-%m-%d",
            "items_text": self.creator_daily_items_input.toPlainText() if hasattr(self, "creator_daily_items_input") and is_alive(self.creator_daily_items_input) else "",
            "last_run": str(getattr(self, "creator_daily_last_run", "") or ""),
            "last_target": str(getattr(self, "creator_daily_last_target", "") or ""),
        }
        return data

    def _apply_creator_daily_rule_config(self, data):
        data = data or {}
        if hasattr(self, "creator_daily_enable_check") and is_alive(self.creator_daily_enable_check):
            self.creator_daily_enable_check.setChecked(bool(data.get("enabled", False)))
        if hasattr(self, "creator_daily_root_input") and is_alive(self.creator_daily_root_input):
            self.creator_daily_root_input.setText(str(data.get("root", "") or ""))
        if hasattr(self, "creator_daily_use_date_folder_check") and is_alive(self.creator_daily_use_date_folder_check):
            self.creator_daily_use_date_folder_check.setChecked(bool(data.get("use_date_folder", True)))
        if hasattr(self, "creator_daily_date_format_input") and is_alive(self.creator_daily_date_format_input):
            self.creator_daily_date_format_input.setText(str(data.get("date_format", "%Y-%m-%d") or "%Y-%m-%d"))
        if hasattr(self, "creator_daily_items_input") and is_alive(self.creator_daily_items_input):
            self.creator_daily_items_input.setPlainText(str(data.get("items_text", "") or ""))
        self.creator_daily_last_run = str(data.get("last_run", "") or "")
        self.creator_daily_last_target = str(data.get("last_target", "") or "")
        self._creator_update_daily_status_label()

    def _creator_update_daily_status_label(self, msg=""):
        if not hasattr(self, "creator_daily_status_label") or not is_alive(self.creator_daily_status_label):
            return
        if msg:
            self.creator_daily_status_label.setText(msg)
            return
        last_run = str(getattr(self, "creator_daily_last_run", "") or "").strip()
        last_target = str(getattr(self, "creator_daily_last_target", "") or "").strip()
        if last_run:
            txt = f"今日自动模板：上次 {last_run}"
            if last_target:
                txt += f" -> {last_target}"
            self.creator_daily_status_label.setText(txt)
        else:
            self.creator_daily_status_label.setText("今日自动模板：未执行")

    def _creator_get_daily_items(self):
        raw = self.creator_daily_items_input.toPlainText() if hasattr(self, "creator_daily_items_input") and is_alive(self.creator_daily_items_input) else ""
        items = []
        for line in str(raw or "").splitlines():
            s = line.strip().strip('"').strip("'")
            if not s:
                continue
            rel = self._creator_sanitize_rel_path(s, allow_nested=True)
            if rel:
                items.append(rel)
        # 去重保序
        seen = set()
        out = []
        for x in items:
            if x in seen:
                continue
            seen.add(x)
            out.append(x)
        return out[:500]

    def _creator_build_daily_plan(self):
        cfg = self._creator_get_daily_rule_config()
        root = cfg.get("root", "").strip()
        if not root:
            return {"ok": False, "error": "每日模板根目录为空。"}
        if os.path.isabs(root) is False and re.match(r"^[A-Za-z]:[\\/]", root) is None and not root.startswith(os.sep):
            # 相对路径也允许，但最终转绝对路径更稳
            root = os.path.abspath(root)
        date_format = cfg.get("date_format", "%Y-%m-%d").strip() or "%Y-%m-%d"
        try:
            date_name = datetime.now().strftime(date_format)
        except Exception:
            date_format = "%Y-%m-%d"
            date_name = datetime.now().strftime(date_format)
        base = os.path.join(root, date_name) if cfg.get("use_date_folder", True) else root
        items = self._creator_get_daily_items()
        if not items:
            return {"ok": False, "error": "每日模板列表为空。"}
        abs_items = [os.path.join(base, x) for x in items]
        return {
            "ok": True,
            "root": root,
            "base": base,
            "items": items,
            "abs_items": abs_items,
            "date_name": date_name,
            "use_date_folder": bool(cfg.get("use_date_folder", True)),
            "date_format": date_format,
            "last_run": str(cfg.get("last_run", "") or ""),
        }

    def creator_daily_preview_plan(self):
        plan = self._creator_build_daily_plan()
        if not plan.get("ok"):
            QMessageBox.warning(self, "提示", plan.get("error", "预览失败"))
            return
        base = plan.get("base", "")
        items = plan.get("items", [])
        show = "\n- ".join(items[:30])
        QMessageBox.information(
            self,
            "今日模板预览",
            f"今日目标位置：{base}\n"
            f"将创建 {len(items)} 个常见文件夹：\n- {show}"
            + ("\n- ..." if len(items) > 30 else "")
        )

    def _creator_run_daily_auto_if_needed(self, force=False):
        cfg = self._creator_get_daily_rule_config()
        if not cfg.get("enabled") and not force:
            self._creator_update_daily_status_label()
            return False

        plan = self._creator_build_daily_plan()
        if not plan.get("ok"):
            self._creator_update_daily_status_label(f"今日自动模板：{plan.get('error', '未就绪')}")
            return False

        today_key = datetime.now().strftime("%Y-%m-%d")
        if (not force) and str(getattr(self, "creator_daily_last_run", "") or "").strip() == today_key:
            self._creator_update_daily_status_label()
            return False

        created = 0
        try:
            os.makedirs(plan.get("base", ""), exist_ok=True)
        except Exception as e:
            self.log(f"[批量建文件夹] 每日模板基础目录创建失败：{e}", "red")
            self._creator_update_daily_status_label("今日自动模板：基础目录创建失败")
            return False

        for p in plan.get("abs_items", []):
            try:
                if not os.path.exists(p):
                    os.makedirs(p, exist_ok=True)
                    created += 1
            except Exception as e:
                self.log(f"[批量建文件夹] 每日模板创建失败：{p} -> {e}", "red")

        self.creator_daily_last_run = today_key
        self.creator_daily_last_target = plan.get("base", "")
        self._creator_update_daily_status_label()
        self.log(f"[批量建文件夹] 每日自动模板已执行：目标 {plan.get('base', '')}，新建 {created} 个常见文件夹。", "green")
        try:
            self.save_config(force=True)
        except Exception:
            pass
        return True

    def _creator_build_create_plan(self):
        base = self.creator_path_input.text().strip() if hasattr(self, "creator_path_input") else ""
        if not base:
            return {"ok": False, "error": "创建位置为空。"}

        # 名称来源：表格优先；表格为空就尝试解析“快速输入”
        names = self._creator_collect_table_names()
        if not names and hasattr(self, "creator_quick_input") and is_alive(self.creator_quick_input):
            raw = self.creator_quick_input.toPlainText().strip()
            if raw:
                try:
                    names = self._extract_folder_names_quick(raw)
                except Exception:
                    names = []

        if not names:
            return {"ok": False, "error": "未提供任何文件夹名称（可在表格里填，或在“快速输入”里粘贴后点解析）。"}

        prefix = self.creator_prefix_input.text().strip() if hasattr(self, "creator_prefix_input") else ""
        suffix = self.creator_suffix_input.text().strip() if hasattr(self, "creator_suffix_input") else ""
        allow_nested = bool(self.creator_allow_nested_check.isChecked()) if hasattr(self, "creator_allow_nested_check") else True
        conflict_policy = 0
        if hasattr(self, "creator_conflict_combo") and is_alive(self.creator_conflict_combo):
            conflict_policy = int(self.creator_conflict_combo.currentIndex())

        template = self._creator_get_template_names()
        fill_existing = bool(self.creator_fill_template_for_existing_check.isChecked()) if hasattr(self, "creator_fill_template_for_existing_check") else False

        items = []
        invalid = []
        skipped_exists = []
        resolved = []

        for raw_name in names[:5000]:
            rel = self._creator_sanitize_rel_path(raw_name, allow_nested=allow_nested)
            if not rel:
                invalid.append(str(raw_name))
                continue
            rel = self._creator_apply_prefix_suffix(rel, prefix, suffix)
            if not rel:
                invalid.append(str(raw_name))
                continue

            abs_path = os.path.join(base, rel)
            if os.path.exists(abs_path):
                if conflict_policy == 0:
                    skipped_exists.append(rel)
                    continue
                unique = self._creator_make_unique_dir_path(abs_path)
                if not unique:
                    skipped_exists.append(rel)
                    continue
                try:
                    resolved.append(f"{rel} -> {os.path.relpath(unique, base)}")
                except Exception:
                    resolved.append(f"{rel} -> {unique}")
                abs_path = unique

            items.append({"rel": rel, "abs": abs_path})

        # 去重（按 abs 路径）
        seen = set()
        uniq_items = []
        for it in items:
            ap = os.path.abspath(it.get("abs", ""))
            if not ap or ap in seen:
                continue
            seen.add(ap)
            uniq_items.append(it)

        return {
            "ok": True,
            "base": base,
            "items": uniq_items,
            "invalid": invalid[:200],
            "skipped_exists": skipped_exists[:200],
            "resolved": resolved[:200],
            "template": template,
            "fill_existing": fill_existing,
        }

    def creator_preview_plan(self):
        plan = self._creator_build_create_plan()
        if not plan.get("ok"):
            QMessageBox.warning(self, "提示", plan.get("error", "预览失败"))
            return
        base = plan.get("base", "")
        items = plan.get("items", [])
        invalid = plan.get("invalid", [])
        skipped = plan.get("skipped_exists", [])
        resolved = plan.get("resolved", [])
        template = plan.get("template", [])

        preview_paths = []
        for it in items[:25]:
            try:
                preview_paths.append(os.path.relpath(it.get("abs", ""), base))
            except Exception:
                preview_paths.append(it.get("abs", ""))

        msg = (
            f"创建位置：{base}\n"
            f"将创建：{len(items)} 个\n"
            f"已存在跳过：{len(skipped)} 个\n"
            f"无效名称：{len(invalid)} 个\n"
            f"模板子文件夹：{('、'.join(template) if template else '（无）')}\n\n"
            f"前 25 个预览：\n- " + "\n- ".join(preview_paths)
        )
        if resolved:
            msg += "\n\n冲突自动改名示例：\n- " + "\n- ".join(resolved[:10])
        QMessageBox.information(self, "批量建文件夹预览", msg)

    def creator_undo_last(self):
        history = list(getattr(self, "last_creator_history", []) or [])
        if not history:
            self.log("[批量建文件夹] 没有可撤销的创建记录。", "orange")
            return
        removed = 0
        skipped = 0
        # 先删最深层
        history_sorted = sorted(history, key=lambda p: (len(str(p).split(os.sep)), len(str(p))), reverse=True)
        for p in history_sorted:
            try:
                if os.path.isdir(p):
                    os.rmdir(p)  # 仅能删除空文件夹
                    removed += 1
                else:
                    skipped += 1
            except Exception:
                skipped += 1
        self.last_creator_history = []
        if hasattr(self, "btn_creator_undo") and is_alive(self.btn_creator_undo):
            self.btn_creator_undo.setEnabled(False)
        self.log(f"[批量建文件夹] 已撤销：成功删除 {removed} 个空文件夹；跳过 {skipped} 个（非空/不存在/删除失败）。", "blue")

    def run_batch_create(self):
        plan = self._creator_build_create_plan()
        if not plan.get("ok"):
            QMessageBox.warning(self, "提示", plan.get("error", "创建失败"))
            return

        base = plan.get("base", "").strip()
        items = plan.get("items", [])
        template = plan.get("template", [])
        fill_existing = bool(plan.get("fill_existing", False))
        skipped_exists = plan.get("skipped_exists", [])
        invalid = plan.get("invalid", [])

        # 友好处理：如果目录不存在，尝试自动创建（尤其是“下载/今日目录”这类快捷口令推导出的路径）
        if not os.path.exists(base):
            try:
                os.makedirs(base, exist_ok=True)
            except Exception:
                QMessageBox.warning(self, "提示", "创建位置无效（无法创建基础目录）")
                return

        created_dirs = 0
        created_template = 0
        created_history = []
        already_exists = 0

        for it in items:
            abs_path = it.get("abs", "")
            if not abs_path:
                continue
            parent_existed = os.path.exists(abs_path)
            try:
                if not parent_existed:
                    os.makedirs(abs_path, exist_ok=True)
                    created_dirs += 1
                    created_history.append(abs_path)
                else:
                    already_exists += 1
            except Exception as e:
                self.log(f"[批量建文件夹] 创建失败：{abs_path} -> {e}", "red")
                continue

            # 子文件夹模板
            if template and (fill_existing or (not parent_existed)):
                for sub in template:
                    sub_path = os.path.join(abs_path, sub)
                    if os.path.exists(sub_path):
                        continue
                    try:
                        os.makedirs(sub_path, exist_ok=True)
                        created_template += 1
                        created_history.append(sub_path)
                    except Exception:
                        pass

        self.last_creator_history = created_history
        if hasattr(self, "btn_creator_undo") and is_alive(self.btn_creator_undo):
            self.btn_creator_undo.setEnabled(bool(created_history))

        self.log(
            f"[批量建文件夹] 完成：新建 {created_dirs} 个；"
            f"模板子目录新增 {created_template} 个；"
            f"已存在跳过 {len(skipped_exists)} 个；"
            f"无效名称 {len(invalid)} 个。",
            "green"
        )
    def renamer_add_file(self, fpath):
        row = self.rename_table.rowCount(); self.rename_table.insertRow(row)
        self.rename_table.setItem(row, 0, QTableWidgetItem(fpath))
        self.rename_table.setItem(row, 1, QTableWidgetItem(""))
        fname = os.path.basename(fpath)
        if not self.ext_check.isChecked(): fname = os.path.splitext(fname)[0]
        self.rename_table.setItem(row, 2, QTableWidgetItem(fname))
    def renamer_toggle_ext(self, checked):
        if not hasattr(self, "rename_table") or self.rename_table.rowCount() == 0: return
        for i in range(self.rename_table.rowCount()):
            fpath = self.rename_table.item(i, 0).text(); fname = os.path.basename(fpath)
            if not checked: fname = os.path.splitext(fname)[0]
            self.rename_table.setItem(i, 2, QTableWidgetItem(fname))
    def renamer_batch_replace(self):
        f = self.find_input.text(); r = self.replace_input.text(); is_re = self.regex_check.isChecked()
        for i in range(self.rename_table.rowCount()):
            for col in (1, 2):
                item = self.rename_table.item(i, col)
                if not item:
                    continue
                old = item.text()
                try:
                    new = re.sub(f, r, old) if is_re else old.replace(f, r)
                    self.rename_table.setItem(i, col, QTableWidgetItem(new))
                except:
                    pass
    def renamer_del_front(self):
        n = self.del_front_spin.value()
        for i in range(self.rename_table.rowCount()):
            old = self.rename_table.item(i, 2).text(); self.rename_table.setItem(i, 2, QTableWidgetItem(old[n:]))
    def renamer_del_back(self):
        n = self.del_back_spin.value()
        for i in range(self.rename_table.rowCount()):
            old = self.rename_table.item(i, 2).text()
            if n > 0: self.rename_table.setItem(i, 2, QTableWidgetItem(old[:-n]))
    def renamer_auto_number(self):
        for i in range(self.rename_table.rowCount()):
            old = self.rename_table.item(i, 2).text(); self.rename_table.setItem(i, 2, QTableWidgetItem(f"{i+1:02d}_{old}"))
    def renamer_restore_original(self):
        checked = self.ext_check.isChecked()
        for i in range(self.rename_table.rowCount()):
            fpath = self.rename_table.item(i, 0).text(); fname = os.path.basename(fpath)
            if not checked: fname = os.path.splitext(fname)[0]
            self.rename_table.setItem(i, 1, QTableWidgetItem("")); self.rename_table.setItem(i, 2, QTableWidgetItem(fname))
    def renamer_clear(self): self.rename_table.setRowCount(0)
    # detach_chat_panel / restore_chat_panel 已移除（浮动模式已删除）

    def renamer_execute(self):
        count = 0
        history = []
        is_smart_mode = getattr(self, "is_smart_rename_mode", False)
        
        for i in range(self.rename_table.rowCount()):
            item_path = self.rename_table.item(i, 0)
            item_col1 = self.rename_table.item(i, 1) # 智能模式下是新名(无后缀)，普通模式下是前缀
            item_col2 = self.rename_table.item(i, 2) # 智能模式下是后缀，普通模式下是主文件名
            
            if not item_path: continue
            old_p = item_path.text().strip()
            if not old_p or not os.path.exists(old_p): continue
            
            val1 = item_col1.text().strip() if item_col1 else ""
            val2 = item_col2.text().strip() if item_col2 else ""
            
            dname = os.path.dirname(old_p)
            original_ext = os.path.splitext(old_p)[1]
            
            # 自动判定模式：如果 val2 看起来像后缀(mp4, jpg等)且没有勾选"包含后缀名"，或者显式标记了智能模式
            # 但最稳妥的是直接根据 val1 和 val2 是否能组合出有效名字
            
            if is_smart_mode:
                # 智能改名模式：val1 是新名，val2 是后缀
                new_base = self.sanitize_filename(val1)
                new_ext = val2
                if new_ext and not new_ext.startswith("."):
                    new_ext = "." + new_ext
                # 如果 val2 为空，尝试保留原后缀
                if not new_ext:
                    new_ext = original_ext
                new_name = new_base + new_ext
            else:
                # 传统改名模式
                if not self.ext_check.isChecked():
                    # val1=前缀, val2=主文件名
                    new_name = self._compose_renamer_stem(val1, val2) + original_ext
                else:
                    # 勾选了包含后缀名：仅当检测到明确、有效的新扩展名时才允许覆盖原后缀
                    merged_name = self._compose_renamer_stem(val1, val2).strip()
                    base_name, final_ext = self._resolve_renamer_name_ext(merged_name, original_ext)
                    fallback_base = self._compose_renamer_stem(val1, val2)
                    new_name = f"{base_name}{final_ext}" if base_name else f"{fallback_base}{original_ext}"

            # 清理非法字符
            new_name = re.sub(r'[\\/:*?"<>|：]', '_', new_name).strip()
            
            # 最终检查：如果名字没变或者为空，跳过
            if not new_name or new_name == os.path.basename(old_p):
                continue
                
            new_p = os.path.join(dname, new_name)
            # 文件名冲突时自动追加序号 _2, _3, ...
            if os.path.exists(new_p) and os.path.abspath(new_p) != os.path.abspath(old_p):
                base_no_ext, final_ext = os.path.splitext(new_name)
                n = 2
                while True:
                    candidate = os.path.join(dname, f"{base_no_ext}_{n}{final_ext}")
                    if not os.path.exists(candidate):
                        new_p = candidate
                        break
                    n += 1
            try:
                os.rename(old_p, new_p)
                self.rename_table.setItem(i, 0, QTableWidgetItem(new_p))
                history.append({"src": old_p, "dst": new_p})
                count += 1
            except Exception as e:
                self.log(f"重命名失败 ({os.path.basename(old_p)}): {e}", "red")
                
        if count > 0:
            self.last_rename_history = history
            if hasattr(self, "btn_undo_rename"):
                self.btn_undo_rename.setEnabled(True)
        self.log(f"重命名执行完毕，成功处理 {count} 个文件", "green")
        # 执行完后重置模式标记
        self.is_smart_rename_mode = False

    def run_undo_rename(self):
        if not self.last_rename_history:
            self.log("没有可撤销的改名记录", "orange")
            return

        count = 0
        for item in reversed(self.last_rename_history):
            src = item.get("src", "")
            dst = item.get("dst", "")
            if not src or not dst:
                continue
            try:
                if not os.path.exists(dst):
                    continue
                if os.path.exists(src) and os.path.abspath(src) != os.path.abspath(dst):
                    self.log(f"撤回跳过：原文件名已被占用 -> {os.path.basename(src)}", "orange")
                    continue
                os.makedirs(os.path.dirname(src), exist_ok=True)
                os.rename(dst, src)
                for row in range(self.rename_table.rowCount()):
                    item_path = self.rename_table.item(row, 0)
                    if item_path and os.path.abspath(item_path.text().strip()) == os.path.abspath(dst):
                        self.rename_table.setItem(row, 0, QTableWidgetItem(src))
                        break
                count += 1
            except Exception as e:
                self.log(f"撤回改名失败 ({os.path.basename(dst)}): {e}", "red")

        self.last_rename_history = []
        if hasattr(self, "btn_undo_rename"):
            self.btn_undo_rename.setEnabled(False)
        self.log(f"已撤销 {count} 个文件的改名", "blue")

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            # 智能识别：如果在 AI 聊天面板区域，则优先接受
            if hasattr(self, "chat_panel") and self.chat_panel.isVisible():
                pos_in_chat = self.chat_panel.mapFromGlobal(_globalPos(event))
                if self.chat_panel.rect().contains(pos_in_chat):
                    event.accept()
                    return
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        # 智能识别拖拽范围：如果在 AI 聊天面板区域，则转发给它
        if hasattr(self, "chat_panel") and self.chat_panel.isVisible():
            # 将全局坐标转换为聊天面板的局部坐标
            pos_in_chat = self.chat_panel.mapFromGlobal(_globalPos(event))
            if self.chat_panel.rect().contains(pos_in_chat):
                urls = event.mimeData().urls() if event.mimeData() and event.mimeData().hasUrls() else []
                files = []
                for u in urls:
                    p = u.toLocalFile()
                    if p and os.path.exists(p):
                        files.append(os.path.normpath(p))
                if files and hasattr(self, "add_chat_attachments"):
                    self.add_chat_attachments(files)
                    event.acceptProposedAction()
                return

        urls = event.mimeData().urls()
        files = []
        for u in urls:
            f = u.toLocalFile()
            if not f:
                path = u.path()
                if sys.platform == 'win32':
                    if path.startswith('/'): path = path[1:]
                    import urllib.parse
                    f = urllib.parse.unquote(path)
                else:
                    f = path
            if f:
                f = os.path.normpath(f)
                if os.path.exists(f): files.append(f)
                else:
                    # 兜底处理可能带协议头的字符串
                    raw = u.toString()
                    if raw.startswith("file:///"):
                        clean_p = raw[8:]
                        if sys.platform == 'win32' and clean_p[1:2] == ':': pass
                        elif sys.platform == 'win32' and clean_p.startswith('/'): clean_p = clean_p[1:]
                        import urllib.parse
                        clean_p = urllib.parse.unquote(clean_p)
                        clean_p = os.path.normpath(clean_p)
                        if os.path.exists(clean_p): files.append(clean_p)
        
        if not files: return
        # 重要：不要再用固定 tab index 判断（新增/调整 tab 会导致拖拽路由错位）
        curr_widget = self.tabs.currentWidget()
        if curr_widget is getattr(self, "heygen_tab", None):
            curr_heygen_idx = self.heygen_project_tabs.currentIndex()
            if curr_heygen_idx >= 0:
                name = self.heygen_project_tabs.tabText(curr_heygen_idx); table = self.project_tabs[name]["table"]
                # 修复坐标转换错位问题：拖拽事件的坐标是相对于主窗口的，
                # 需要将主窗口坐标转换为全局坐标，再映射到 table.viewport() 局部坐标
                if PYQT_VERSION == 6:
                    event_global_pos = event.position().toPoint()
                    # position() 返回的是相对于接收窗厣的坐标，需转为全局
                    event_global_pos = self.mapToGlobal(event_global_pos)
                else:
                    event_global_pos = self.mapToGlobal(event.pos())
                table_pos = table.viewport().mapFromGlobal(event_global_pos)
                row_at = table.rowAt(table_pos.y())
                start_row = row_at if row_at >= 0 else table.rowCount()
                
                for i, f in enumerate(files):
                    if os.path.isfile(f):
                        curr_r = start_row + i
                        # 如果行数不够，自动增加行
                        while curr_r >= table.rowCount():
                            table.insertRow(table.rowCount())
                        # 仅填充图片路径列 (索引为 1)
                        table.setItem(curr_r, 1, QTableWidgetItem(f))
            self.trigger_save()
        elif curr_widget is getattr(self, "universal_match_tab", None):
            # 全能极速对位拖拽支持
            if PYQT_VERSION == 6: event_global_pos = self.mapToGlobal(event.position().toPoint())
            else: event_global_pos = self.mapToGlobal(event.pos())
            u_src_rect = QRect(self.uni_match_src_input.mapToGlobal(self.uni_match_src_input.rect().topLeft()), self.uni_match_src_input.mapToGlobal(self.uni_match_src_input.rect().bottomRight()))
            u_res_rect = QRect(self.uni_match_res_input.mapToGlobal(self.uni_match_res_input.rect().topLeft()), self.uni_match_res_input.mapToGlobal(self.uni_match_res_input.rect().bottomRight()))
            if u_res_rect.contains(event_global_pos): self.uni_match_res_input.setText("\n".join(files))
            else: self.uni_match_src_input.setText("\n".join(files))
        elif curr_widget is getattr(self, "sorter_tab", None):
            if os.path.isdir(files[0]): self.sorter_path_input.setText(files[0])
        elif curr_widget is getattr(self, "renamer_tab", None):
            new_file_paths = []
            for f in files:
                if os.path.isfile(f):
                    new_file_paths.append(f)
                elif os.path.isdir(f):
                    dir_files = []
                    for root, _, filenames in os.walk(f):
                        for fname in filenames:
                            dir_files.append(os.path.join(root, fname))
                    dir_files.sort(key=lambda x: [int(c) if c.isdigit() else c.lower() for c in re.split(r'(\d+)', os.path.basename(x))])
                    new_file_paths.extend(dir_files)
            # 对本次拖入的所有文件按文件名自然顺序排序后再添加
            new_file_paths.sort(key=lambda x: [int(c) if c.isdigit() else c.lower() for c in re.split(r'(\d+)', os.path.basename(x))])
            for f in new_file_paths:
                self.renamer_add_file(f)
        elif curr_widget is getattr(self, "watermark_tab", None):
            existing = self.watermark_tab.video_list_edit.toPlainText().strip()
            new_paths = []
            video_exts = ('.mp4', '.mkv', '.avi', '.mov', '.flv', '.wmv', '.m4v', '.ts', '.webm')
            for f in files:
                if os.path.isfile(f):
                    if f.lower().endswith(video_exts):
                        new_paths.append(f)
                elif os.path.isdir(f):
                    # 递归扫描子文件夹中的视频文件
                    for root, _, filenames in os.walk(f):
                        for fname in sorted(filenames):
                            if fname.lower().endswith(video_exts):
                                new_paths.append(os.path.join(root, fname))
            if new_paths:
                combined = f"{existing}\n" if existing else ""
                combined = combined + "\n".join(new_paths)
                self.watermark_tab.video_list_edit.setPlainText(combined)
        elif curr_widget is getattr(self, "video_concat_tab", None):
            existing = self.video_concat_tab.video_list_edit.toPlainText().strip()
            new_paths = []
            video_exts = VideoConcatTab.VIDEO_EXTS
            for f in files:
                if os.path.isfile(f):
                    if f.lower().endswith(video_exts):
                        new_paths.append(f)
                elif os.path.isdir(f):
                    for root, _, filenames in os.walk(f):
                        for fname in sorted(filenames):
                            if fname.lower().endswith(video_exts):
                                new_paths.append(os.path.join(root, fname))
            if new_paths:
                combined = f"{existing}\n" if existing else ""
                combined = combined + "\n".join(new_paths)
                self.video_concat_tab.video_list_edit.setPlainText(combined)
    def log(self, msg, color="black"):
        # 核心：UI 日志展示，不再反向调用 write_debug 以防递归
        c_map = {"red": "red", "green": "green", "orange": "orange", "blue": "blue", "black": "black"}
        c_hex = c_map.get(color, color)
        self.log_display.append(f'<span style="color:{c_hex}">[{datetime.now().strftime("%H:%M:%S")}] {msg}</span>')
        self.log_display.moveCursor(QTextCursor.MoveOperation.End)
    def load_config(self):
        if not os.path.exists(CONFIG_FILE): return
        self._is_loading = True
        try:
            with open(CONFIG_FILE, "r", encoding="utf-8") as f: cfg = json.load(f)
            if not isinstance(cfg, dict): return
            rules = self._clone_sorter_rules(cfg.get("rules", []))
            extension_rules = self._clone_sorter_rules(cfg.get("sorter_extension_rules", []))
            if not hasattr(self, "_sorter_rules_cache") or not isinstance(self._sorter_rules_cache, dict):
                self._sorter_rules_cache = {"rule": [], "extension": []}
            self._sorter_rules_cache["rule"] = rules
            self._sorter_rules_cache["extension"] = extension_rules
            if hasattr(self, "sorter_path_input") and self.sorter_path_input: self.sorter_path_input.setText(cfg.get("sorter_path", ""))
            if hasattr(self, "sorter_code_prefix_input") and is_alive(self.sorter_code_prefix_input):
                self.sorter_code_prefix_input.setText(str(cfg.get("sorter_code_prefix", "") or ""))
            if hasattr(self, "auto_root_input") and self.auto_root_input: self.auto_root_input.setText(cfg.get("auto_root_path", ""))
            if hasattr(self, "heygen_global_out_input") and self.heygen_global_out_input:
                self.heygen_global_out_input.setText(cfg.get("heygen_global_out_path", ""))
            self.recursive_check.setChecked(cfg.get("recursive", False))
            if hasattr(self, "sorter_name_folder_check") and is_alive(self.sorter_name_folder_check):
                self.sorter_name_folder_check.setChecked(bool(cfg.get("sorter_name_folder_enabled", True)))
            if hasattr(self, "sorter_filename_group_check") and is_alive(self.sorter_filename_group_check):
                self.sorter_filename_group_check.setChecked(bool(cfg.get("sorter_filename_group_enabled", True)))
            sorter_mode = str(cfg.get("sorter_mode", "") or "").strip()
            if not sorter_mode:
                legacy_name_mode = bool(cfg.get("sorter_name_folder_enabled", True))
                legacy_filename_group_mode = bool(cfg.get("sorter_filename_group_enabled", True))
                if legacy_name_mode and legacy_filename_group_mode:
                    sorter_mode = "comprehensive"
                elif legacy_filename_group_mode:
                    sorter_mode = "filename_group"
                elif legacy_name_mode:
                    sorter_mode = "name_existing"
                elif rules:
                    sorter_mode = "custom_rule"
                else:
                    sorter_mode = "extension"
            if hasattr(self, "sorter_mode_combo") and is_alive(self.sorter_mode_combo):
                idx = self.sorter_mode_combo.findData(sorter_mode)
                self.sorter_mode_combo.setCurrentIndex(idx if idx >= 0 else 0)
            if hasattr(self, "sorter_time_basis_combo") and is_alive(self.sorter_time_basis_combo):
                basis_val = str(cfg.get("sorter_time_basis", "mtime") or "mtime")
                idx = self.sorter_time_basis_combo.findData(basis_val)
                self.sorter_time_basis_combo.setCurrentIndex(idx if idx >= 0 else 0)
            if hasattr(self, "sorter_time_group_combo") and is_alive(self.sorter_time_group_combo):
                group_val = str(cfg.get("sorter_time_granularity", "month") or "month")
                idx = self.sorter_time_group_combo.findData(group_val)
                self.sorter_time_group_combo.setCurrentIndex(idx if idx >= 0 else 0)
            if hasattr(self, "sorter_flatten_target_input") and is_alive(self.sorter_flatten_target_input):
                self.sorter_flatten_target_input.setText(str(cfg.get("sorter_flatten_target", "") or ""))
            if hasattr(self, "sorter_flatten_delete_empty_check") and is_alive(self.sorter_flatten_delete_empty_check):
                self.sorter_flatten_delete_empty_check.setChecked(bool(cfg.get("sorter_flatten_delete_empty", True)))
            if hasattr(self, "sorter_incomplete_target_input") and is_alive(self.sorter_incomplete_target_input):
                self.sorter_incomplete_target_input.setText(str(cfg.get("sorter_incomplete_target", "") or ""))
            if hasattr(self, "sorter_incomplete_keep_structure_check") and is_alive(self.sorter_incomplete_keep_structure_check):
                self.sorter_incomplete_keep_structure_check.setChecked(bool(cfg.get("sorter_incomplete_keep_structure", True)))
            if hasattr(self, "sorter_incomplete_check_missing_txt_check") and is_alive(self.sorter_incomplete_check_missing_txt_check):
                self.sorter_incomplete_check_missing_txt_check.setChecked(bool(cfg.get("sorter_incomplete_check_missing_txt", False)))
            if hasattr(self, "_on_sorter_mode_changed"):
                self._on_sorter_mode_changed()
            if hasattr(self, "heygen_auto_split_en_check") and is_alive(self.heygen_auto_split_en_check):
                self.heygen_auto_split_en_check.setChecked(bool(cfg.get("heygen_auto_split_en_after_sort", False)))
            creator_cfg = cfg.get("creator_config", {})
            if isinstance(creator_cfg, dict):
                if hasattr(self, "creator_path_input") and is_alive(self.creator_path_input):
                    self.creator_path_input.setText(creator_cfg.get("base_path", ""))
                if hasattr(self, "creator_quick_input") and is_alive(self.creator_quick_input):
                    self.creator_quick_input.setPlainText(creator_cfg.get("quick_input", ""))
                if hasattr(self, "creator_prefix_input") and is_alive(self.creator_prefix_input):
                    self.creator_prefix_input.setText(creator_cfg.get("prefix", ""))
                if hasattr(self, "creator_suffix_input") and is_alive(self.creator_suffix_input):
                    self.creator_suffix_input.setText(creator_cfg.get("suffix", ""))
                if hasattr(self, "creator_allow_nested_check") and is_alive(self.creator_allow_nested_check):
                    self.creator_allow_nested_check.setChecked(bool(creator_cfg.get("allow_nested", True)))
                if hasattr(self, "creator_conflict_combo") and is_alive(self.creator_conflict_combo):
                    try:
                        self.creator_conflict_combo.setCurrentIndex(int(creator_cfg.get("conflict_mode", 0) or 0))
                    except Exception:
                        self.creator_conflict_combo.setCurrentIndex(0)
                if hasattr(self, "creator_use_template_check") and is_alive(self.creator_use_template_check):
                    self.creator_use_template_check.setChecked(bool(creator_cfg.get("use_template", False)))
                if hasattr(self, "creator_fill_template_for_existing_check") and is_alive(self.creator_fill_template_for_existing_check):
                    self.creator_fill_template_for_existing_check.setChecked(bool(creator_cfg.get("fill_template_for_existing", False)))
                if hasattr(self, "creator_template_input") and is_alive(self.creator_template_input):
                    self.creator_template_input.setPlainText(creator_cfg.get("template_text", ""))
                if hasattr(self, "creator_table") and is_alive(self.creator_table):
                    names = creator_cfg.get("table_names", [])
                    if isinstance(names, list) and names:
                        self.creator_table.setRowCount(max(10, len(names)))
                        for i, name in enumerate(names):
                            self.creator_table.setItem(i, 0, QTableWidgetItem(str(name)))
                daily_cfg = creator_cfg.get("daily_rule", {})
                if isinstance(daily_cfg, dict):
                    self._apply_creator_daily_rule_config(daily_cfg)
            if hasattr(self, "uni_match_name_source_combo") and is_alive(self.uni_match_name_source_combo):
                try:
                    name_source = str(cfg.get("universal_match_name_source", "auto") or "auto")
                    idx = self.uni_match_name_source_combo.findData(name_source)
                    self.uni_match_name_source_combo.setCurrentIndex(idx if idx >= 0 else 0)
                except Exception:
                    self.uni_match_name_source_combo.setCurrentIndex(0)
            if hasattr(self, "uni_match_skip_existing_pairs_check") and is_alive(self.uni_match_skip_existing_pairs_check):
                self.uni_match_skip_existing_pairs_check.setChecked(bool(cfg.get("universal_match_skip_existing_pairs", True)))
            # 核心改进：按照保存的顺序恢复标签页
            heygen_data = cfg.get("heygen_projects", {})
            heygen_order = cfg.get("heygen_projects_order", list(heygen_data.keys()))
            for name in heygen_order:
                if name in heygen_data:
                    data = heygen_data[name]
                    self.create_heygen_project_ui(
                        name,
                        data.get("out_path", ""),
                        data.get("src_path", ""),
                        data.get("table_data"),
                        data.get("split_limit", cfg.get("heygen_default_split_limit", 100))
                    )
                    if "move_mode" in data: self.project_tabs[name]["move_check"].setChecked(data["move_mode"])
            self._last_heygen_split_limit = int(cfg.get("heygen_default_split_limit", getattr(self, "_last_heygen_split_limit", 100)) or 100)
            self._last_browse_dir = str(cfg.get("last_browse_dir", getattr(self, "_last_browse_dir", "")) or "")
            note_projects = cfg.get("note_projects", [])
            if note_projects:
                for proj in note_projects:
                    self.note_widget.add_new_tab(
                        proj.get("name", "未命名"),
                        proj.get("data", []),
                        headers=proj.get("column_count", proj.get("headers")),
                        note_text=proj.get("note_text", "")
                    )
            else:
                self.note_widget.add_new_tab("今日计划")
            if cfg.get("note_is_floating"): self.handle_note_mode_change(True)
            n_pos = cfg.get("note_pos")
            if n_pos and n_pos[0] >= 0 and n_pos[1] >= 0: self.note_widget.move(n_pos[0], n_pos[1])
            n_size = cfg.get("note_size")
            if n_size and n_size[0] > 100 and n_size[1] > 100: self.note_widget.resize(n_size[0], n_size[1])
            s_sizes = cfg.get("splitter_sizes")
            if s_sizes:
                # 兼容逻辑：确保 sizes 长度与当前 splitter 组件数一致
                # 移除旧版三栏尺寸兼容
                if len(s_sizes) == self.splitter.count():
                    self.splitter.setSizes(s_sizes)
            else:
                self.splitter.setSizes([1000, 300])
            
            # 恢复侧边栏显示状态
            note_visible = cfg.get("note_visible", True)
            if not note_visible:
                self.sidebar.hide()

            if cfg.get("global_pin"): self.global_pin_check.setChecked(True)
            m_geom = cfg.get("main_window_geom")
            if m_geom and len(m_geom) == 4:
                self.move(m_geom[0], m_geom[1])
                self.resize(m_geom[2], m_geom[3])
            try:
                wm_cfg = cfg.get("watermark_config")
                if wm_cfg: self.watermark_tab.load_config(wm_cfg)
                concat_cfg = cfg.get("video_concat_config")
                if concat_cfg and hasattr(self, "video_concat_tab"):
                    self.video_concat_tab.load_config(concat_cfg)
                
                ai_cfg = cfg.get("ai_config")
                if ai_cfg:
                    self.ai_config.update(ai_cfg)
                review_ai_cfg = cfg.get("review_ai_config")
                self.assistant_ai_config = self._normalize_module_ai_config(self.ai_config)
                self.review_ai_config = self._normalize_module_ai_config(review_ai_cfg or self.ai_config)
                # 恢复审核问题库
                lib = cfg.get("review_issue_library")
                if isinstance(lib, list):
                    self.review_issue_library = self._normalize_keyword_dict_list(lib, default_level="⚠️ 有问题")
                # 恢复图片审核规则
                img_rules = cfg.get("review_image_rules")
                if isinstance(img_rules, list):
                    self.review_image_rules = self._normalize_keyword_dict_list(img_rules)
                # 万能自动化模块已移除，旧配置项不再加载
            except: pass
        except: pass
        finally:
            self._is_loading = False
            try:
                self._creator_run_daily_auto_if_needed(force=False)
            except Exception:
                pass
    def _get_heygen_save_data(self):
        res = {}
        if not hasattr(self, "project_tabs"): return res
        for name, v in self.project_tabs.items():
            table = v["table"]; table_data = []
            if is_alive(table):
                for i in range(table.rowCount()): 
                    table_data.append({
                        "code": table.item(i, 0).text() if table.item(i, 0) else "", 
                        "img": table.item(i, 1).text() if table.item(i, 1) else "", 
                        "score": table.item(i, 2).text() if table.item(i, 2) else "",
                        "script_cn": table.item(i, 3).text() if table.item(i, 3) else "", 
                        "script_en": table.item(i, 4).text() if table.item(i, 4) else "",
                        "remark": table.item(i, 5).text() if table.item(i, 5) else ""
                    })
            res[name] = {
                "out_path": v["out_path"].text() if is_alive(v["out_path"]) else "",
                "src_path": v["source_input"].text() if is_alive(v["source_input"]) else "",
                "move_mode": v["move_check"].isChecked() if is_alive(v["move_check"]) else True,
                "split_limit": v["split_limit"].value() if is_alive(v.get("split_limit")) else getattr(self, "_last_heygen_split_limit", 100),
                "table_data": table_data
            }
        return res
    def save_config(self, force=False):
        if getattr(self, "_is_loading", False): return
        
        # 优化：检查当前是否有表格正在编辑。如果有，则推迟保存，避免卡顿。
        if not force:
            focus_w = QApplication.focusWidget()
            # 仅在“长文本输入”场景推迟保存：避免打字卡顿。
            # 不再对 QTableWidget 一律推迟，否则便签表格的内容非常容易因退出过快而未落盘。
            if focus_w and (isinstance(focus_w, QTextEdit) or isinstance(focus_w, QLineEdit)):
                self.save_timer.start(3000) # 还在输入中，推迟 3 秒
                return

        try:
            if force:
                try:
                    fw = QApplication.focusWidget()
                    if fw:
                        fw.clearFocus()
                        QApplication.processEvents()
                except Exception:
                    pass
            self._sync_sorter_rule_cache_from_table(self._get_sorter_mode() if hasattr(self, "_get_sorter_mode") else "comprehensive")
            sorter_rules_cache = getattr(self, "_sorter_rules_cache", {})
            if not isinstance(sorter_rules_cache, dict):
                sorter_rules_cache = {"rule": [], "extension": []}
            rules = self._clone_sorter_rules(sorter_rules_cache.get("rule", []))
            extension_rules = self._clone_sorter_rules(sorter_rules_cache.get("extension", []))
            
            note_projects = []
            if hasattr(self, "note_widget") and is_alive(self.note_widget):
                tabs = self.note_widget.tabs
                for idx in range(tabs.count()):
                    page = tabs.widget(idx)
                    table, text_edit = self.note_widget._get_note_parts(page) if hasattr(self.note_widget, "_get_note_parts") else (page, None)
                    if is_alive(table):
                        t_data = []
                        row_count = table.rowCount()
                        col_count = table.columnCount()
                        # 按照视觉顺序保存数据，确保拖拽重排后能持久化
                        for v_r in range(row_count):
                            r = table.verticalHeader().logicalIndex(v_r)
                            row_cells = []
                            for v_c in range(col_count):
                                c = table.horizontalHeader().logicalIndex(v_c)
                                it = table.item(r, c)
                                row_cells.append(it.text() if it else "")
                            t_data.append({"cells": row_cells})
                        note_projects.append({
                            "name": tabs.tabText(idx),
                            "data": t_data,
                            "column_count": col_count,
                            "note_text": text_edit.toPlainText() if (text_edit and is_alive(text_edit)) else ""
                        })

            ai_cfg = getattr(self, "ai_config", {})
            review_ai_cfg = getattr(self, "review_ai_config", self._normalize_module_ai_config(ai_cfg))
            review_issue_library = self._normalize_keyword_dict_list(getattr(self, "review_issue_library", []), default_level="⚠️ 有问题")
            review_image_rules = self._normalize_keyword_dict_list(getattr(self, "review_image_rules", []))

            cfg = {
                "rules": rules,
                "sorter_extension_rules": extension_rules,
                "creator_config": {
                    "base_path": self.creator_path_input.text().strip() if hasattr(self, "creator_path_input") and is_alive(self.creator_path_input) else "",
                    "quick_input": self.creator_quick_input.toPlainText() if hasattr(self, "creator_quick_input") and is_alive(self.creator_quick_input) else "",
                    "prefix": self.creator_prefix_input.text().strip() if hasattr(self, "creator_prefix_input") and is_alive(self.creator_prefix_input) else "",
                    "suffix": self.creator_suffix_input.text().strip() if hasattr(self, "creator_suffix_input") and is_alive(self.creator_suffix_input) else "",
                    "allow_nested": self.creator_allow_nested_check.isChecked() if hasattr(self, "creator_allow_nested_check") and is_alive(self.creator_allow_nested_check) else True,
                    "conflict_mode": self.creator_conflict_combo.currentIndex() if hasattr(self, "creator_conflict_combo") and is_alive(self.creator_conflict_combo) else 0,
                    "use_template": self.creator_use_template_check.isChecked() if hasattr(self, "creator_use_template_check") and is_alive(self.creator_use_template_check) else False,
                    "fill_template_for_existing": self.creator_fill_template_for_existing_check.isChecked() if hasattr(self, "creator_fill_template_for_existing_check") and is_alive(self.creator_fill_template_for_existing_check) else False,
                    "template_text": self.creator_template_input.toPlainText() if hasattr(self, "creator_template_input") and is_alive(self.creator_template_input) else "",
                    "table_names": self._creator_collect_table_names() if hasattr(self, "_creator_collect_table_names") else [],
                    "daily_rule": self._creator_get_daily_rule_config() if hasattr(self, "_creator_get_daily_rule_config") else {},
                },
                "heygen_projects": self._get_heygen_save_data(),
                "heygen_projects_order": [self.heygen_project_tabs.tabText(i) for i in range(self.heygen_project_tabs.count())],
                "heygen_default_split_limit": int(getattr(self, "_last_heygen_split_limit", 100) or 100),
                "heygen_auto_split_en_after_sort": self.heygen_auto_split_en_check.isChecked() if hasattr(self, "heygen_auto_split_en_check") and is_alive(self.heygen_auto_split_en_check) else False,
                "last_browse_dir": str(getattr(self, "_last_browse_dir", "") or ""),
                "sorter_path": self.sorter_path_input.text() if hasattr(self, "sorter_path_input") and is_alive(self.sorter_path_input) else "",
                "sorter_code_prefix": self.sorter_code_prefix_input.text().strip() if hasattr(self, "sorter_code_prefix_input") and is_alive(self.sorter_code_prefix_input) else "",
                "auto_root_path": self.auto_root_input.text() if hasattr(self, "auto_root_input") and is_alive(self.auto_root_input) else "",
                "heygen_global_out_path": self.heygen_global_out_input.text() if hasattr(self, "heygen_global_out_input") and is_alive(self.heygen_global_out_input) else "",
                "recursive": self.recursive_check.isChecked() if hasattr(self, "recursive_check") and is_alive(self.recursive_check) else False,
                "sorter_mode": self._get_sorter_mode() if hasattr(self, "_get_sorter_mode") else "comprehensive",
                "sorter_time_basis": self.sorter_time_basis_combo.currentData() if hasattr(self, "sorter_time_basis_combo") and is_alive(self.sorter_time_basis_combo) else "mtime",
                "sorter_time_granularity": self.sorter_time_group_combo.currentData() if hasattr(self, "sorter_time_group_combo") and is_alive(self.sorter_time_group_combo) else "month",
                "sorter_flatten_target": self.sorter_flatten_target_input.text().strip() if hasattr(self, "sorter_flatten_target_input") and is_alive(self.sorter_flatten_target_input) else "",
                "sorter_flatten_delete_empty": self.sorter_flatten_delete_empty_check.isChecked() if hasattr(self, "sorter_flatten_delete_empty_check") and is_alive(self.sorter_flatten_delete_empty_check) else True,
                "sorter_incomplete_target": self.sorter_incomplete_target_input.text().strip() if hasattr(self, "sorter_incomplete_target_input") and is_alive(self.sorter_incomplete_target_input) else "",
                "sorter_incomplete_keep_structure": self.sorter_incomplete_keep_structure_check.isChecked() if hasattr(self, "sorter_incomplete_keep_structure_check") and is_alive(self.sorter_incomplete_keep_structure_check) else True,
                "sorter_incomplete_check_missing_txt": self.sorter_incomplete_check_missing_txt_check.isChecked() if hasattr(self, "sorter_incomplete_check_missing_txt_check") and is_alive(self.sorter_incomplete_check_missing_txt_check) else False,
                "sorter_name_folder_enabled": self.sorter_name_folder_check.isChecked() if hasattr(self, "sorter_name_folder_check") and is_alive(self.sorter_name_folder_check) else True,
                "sorter_filename_group_enabled": self.sorter_filename_group_check.isChecked() if hasattr(self, "sorter_filename_group_check") and is_alive(self.sorter_filename_group_check) else True,
                "note_projects": note_projects,
                "note_is_floating": getattr(self.note_widget, "is_floating", False),
                "note_pos": [self.note_widget.pos().x(), self.note_widget.pos().y()] if is_alive(self.note_widget) else [0,0],
                "note_size": [self.note_widget.width(), self.note_widget.height()] if is_alive(self.note_widget) else [400,600],
                "splitter_sizes": self.splitter.sizes() if hasattr(self, "splitter") and is_alive(self.splitter) else [],
                "main_window_geom": [self.pos().x(), self.pos().y(), self.width(), self.height()],
                "global_pin": self.global_pin_check.isChecked() if hasattr(self, "global_pin_check") and is_alive(self.global_pin_check) else False,
                "note_visible": self.sidebar.isVisible() if hasattr(self, "sidebar") and is_alive(self.sidebar) else True,
                "watermark_config": self.watermark_tab.get_config() if hasattr(self.watermark_tab, "get_config") and is_alive(self.watermark_tab) else {},
                "video_concat_config": self.video_concat_tab.get_config() if hasattr(self, "video_concat_tab") and is_alive(self.video_concat_tab) else {},
                "universal_match_name_source": self.get_universal_match_name_source_mode() if hasattr(self, "get_universal_match_name_source_mode") else "auto",
                "universal_match_skip_existing_pairs": self.get_universal_match_skip_existing_pairs() if hasattr(self, "get_universal_match_skip_existing_pairs") else True,
                "ai_config": ai_cfg,
                "review_ai_config": review_ai_cfg,
                "review_issue_library": review_issue_library,
                "review_image_rules": review_image_rules
            }
            with open(CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(cfg, f, ensure_ascii=False, indent=4)
        except Exception as e:
            write_debug(f"Save Config Error: {e}")

    def show_ai_config_dialog(self, config_target="pipeline"):
        """弹出独立的 AI 配置对话框，支持按模块分别配置。"""
        config_target = str(config_target or "pipeline").strip().lower()
        target_cfg = self._get_named_ai_config(config_target)
        title_map = {
            "assistant": "⚙️ AI 引擎配置 - 智能助手",
            "review": "⚙️ AI 引擎配置 - 汇总预览审核",
            "pipeline": "⚙️ AI 引擎配置 - 批量匹配/流水线"
        }
        dlg = QDialog(self)
        dlg.setWindowTitle(title_map.get(config_target, "⚙️ AI 引擎配置"))
        dlg.setMinimumSize(760, 620)
        layout = QVBoxLayout(dlg)

        tip = QLabel("💡 当前窗口保存的是该模块自己的 AI 配置。智能助手、批量匹配/流水线、汇总预览审核现在彼此独立，不再互相覆盖。")
        tip.setStyleSheet("color: #1d4ed8; background: #eff6ff; padding: 8px; border-radius: 4px; font-size: 12px;")
        tip.setWordWrap(True)
        layout.addWidget(tip)

        engine_tabs = QTabWidget()

        api_widget = QWidget()
        api_layout = QVBoxLayout(api_widget)
        api_form = QGridLayout()
        api_form.setHorizontalSpacing(10)
        api_form.setVerticalSpacing(8)

        api_pool_cache = normalize_api_pool(target_cfg)
        legacy_keys_cache = sanitize_api_keys(target_cfg.get("api_keys", []))
        if not legacy_keys_cache and target_cfg.get("api_key"):
            legacy_keys_cache = [target_cfg.get("api_key", "")]

        source_mode_combo = QComboBox()
        source_mode_combo.addItem("指定 API 节点", "single")
        source_mode_combo.addItem("API 池自动切换", "pool")
        idx_mode = source_mode_combo.findData(get_api_source_mode(target_cfg, "pool"))
        source_mode_combo.setCurrentIndex(idx_mode if idx_mode >= 0 else 1)

        provider_strategy_combo = QComboBox()
        provider_strategy_combo.addItem("顺序切换", "ordered")
        provider_strategy_combo.addItem("随机切换", "random")
        idx_provider = provider_strategy_combo.findData(get_api_provider_strategy(target_cfg, "ordered"))
        provider_strategy_combo.setCurrentIndex(idx_provider if idx_provider >= 0 else 0)

        pool_strategy_combo = QComboBox()
        pool_strategy_combo.addItem("顺序切换", "ordered")
        pool_strategy_combo.addItem("随机切换", "random")
        current_strategy = get_api_pool_strategy(target_cfg)
        current_idx = pool_strategy_combo.findData(current_strategy)
        pool_strategy_combo.setCurrentIndex(current_idx if current_idx >= 0 else 0)

        random_api_check = QCheckBox("启用随机 API 模式（随机节点 + 随机 Key）")
        random_api_check.setChecked(bool(target_cfg.get("api_random_enabled", False)))
        random_api_check.setToolTip("开启后，会优先按随机顺序选择 API 节点，并随机打散节点内 Key，适合多节点随机调换。")

        active_api_combo = QComboBox()
        active_api_combo.setToolTip("在“指定 API 节点”模式下，这里决定固定使用哪个节点；在“API 池自动切换”模式下，这里决定优先起始节点。")

        pool_status_label = QLabel("")
        pool_status_label.setStyleSheet("color: #7c3aed; font-weight: bold;")

        btn_manage_api_pool = QPushButton("🌐 管理 API 节点池")
        btn_manage_api_pool.setMinimumHeight(38)
        btn_manage_api_pool.setStyleSheet("background-color: #7c3aed; color: white; border-radius: 4px;")

        saved_models = target_cfg.get("api_models_list", [])
        model_combo = QComboBox()
        if saved_models:
            model_combo.addItems(saved_models)
        last_model = target_cfg.get("api_model", "")
        if last_model and last_model not in saved_models:
            model_combo.addItem(last_model)
        model_combo.setEditable(True)
        model_combo.setCurrentText(last_model or (saved_models[0] if saved_models else "gpt-4o-mini"))

        btn_refresh_models = QPushButton("🔄 刷新列表")
        btn_refresh_models.setToolTip("从当前使用来源获取可用模型")

        self.api_base_edit_obj = QLineEdit(target_cfg.get("api_base", ""))
        api_base_edit = self.api_base_edit_obj
        api_base_edit.setPlaceholderText("留空则使用官方 OpenAI；谷歌直连填 https://generativelanguage.googleapis.com")

        interval_spin = QSpinBox()
        interval_spin.setRange(0, 60)
        interval_spin.setValue(target_cfg.get("api_interval", 5))
        interval_spin.setToolTip("仅在收到 429 时作为冷却参考使用，不再做每次请求前的强制等待。")
        max_retries_spin = QSpinBox()
        max_retries_spin.setRange(1, 10)
        max_retries_spin.setValue(target_cfg.get("api_max_retries", 3))
        max_retries_spin.setToolTip("遇到 429 时自动重试的最大次数。")
        max_concurrency_spin = QSpinBox()
        max_concurrency_spin.setRange(0, 64)
        max_concurrency_spin.setValue(target_cfg.get("api_max_concurrency", 0))
        max_concurrency_spin.setToolTip("0 表示自动按 Key 数量并发。")

        def _refresh_status_labels():
            enabled_nodes = len([x for x in api_pool_cache if x.get("enabled", True)])
            pool_status_label.setText(f"API 节点池共 {len(api_pool_cache)} 个节点，启用 {enabled_nodes} 个")

        def _refresh_active_combo():
            current_name = str(target_cfg.get("active_api_name", "") or "")
            active_api_combo.blockSignals(True)
            active_api_combo.clear()
            for item in api_pool_cache:
                label = item.get("name", "未命名节点")
                if not item.get("enabled", True):
                    label += " [停用]"
                active_api_combo.addItem(label, item.get("name", ""))
            if active_api_combo.count() > 0:
                idx = active_api_combo.findData(current_name)
                if idx < 0:
                    idx = 0
                active_api_combo.setCurrentIndex(idx)
            active_api_combo.blockSignals(False)

        def _sync_active_name_from_combo():
            name = active_api_combo.currentData() or ""
            target_cfg["active_api_name"] = name

        def _build_preview_ai_config():
            preview = dict(target_cfg)
            preview.update({
                "api_keys": list(legacy_keys_cache),
                "api_base": api_base_edit.text().strip(),
                "api_model": model_combo.currentText().strip(),
                "api_source_mode": source_mode_combo.currentData(),
                "api_provider_strategy": provider_strategy_combo.currentData(),
                "active_api_name": active_api_combo.currentData() or "",
                "api_pool": [dict(item) for item in api_pool_cache],
                "api_pool_strategy": pool_strategy_combo.currentData(),
                "api_random_enabled": random_api_check.isChecked(),
                "api_interval": interval_spin.value(),
                "api_max_retries": max_retries_spin.value(),
                "api_max_concurrency": max_concurrency_spin.value(),
            })
            return preview

        def _collect_profiles_for_runtime():
            preview = _build_preview_ai_config()
            return get_runtime_api_profiles(preview)

        def _update_mode_ui():
            mode = source_mode_combo.currentData()
            use_pool = mode in ("single", "pool")
            active_api_combo.setEnabled(use_pool and active_api_combo.count() > 0)
            provider_strategy_combo.setEnabled(mode == "pool")

        def _open_api_pool_manager():
            nonlocal api_pool_cache
            mgr = ApiPoolManagerDialog(dlg, api_pool_cache)
            accepted = (mgr.exec() == QDialog.DialogCode.Accepted) if PYQT_VERSION == 6 else (mgr.exec_() == QDialog.Accepted)
            if accepted:
                api_pool_cache = mgr.get_pool()
                if api_pool_cache and not any(x.get("name") == target_cfg.get("active_api_name", "") for x in api_pool_cache):
                    target_cfg["active_api_name"] = api_pool_cache[0].get("name", "")
                _refresh_status_labels()
                _refresh_active_combo()
                _update_mode_ui()
                self.log(f"✅ 已同步 {len(api_pool_cache)} 个 API 节点到内存", "green")

        btn_manage_api_pool.clicked.connect(_open_api_pool_manager)
        active_api_combo.currentIndexChanged.connect(lambda *_: _sync_active_name_from_combo())
        source_mode_combo.currentIndexChanged.connect(lambda *_: _update_mode_ui())

        api_form.addWidget(QLabel("API 节点池:"), 0, 0)
        pool_row = QHBoxLayout()
        pool_row.addWidget(pool_status_label)
        pool_row.addWidget(btn_manage_api_pool)
        api_form.addLayout(pool_row, 0, 1, 1, 2)

        api_form.addWidget(QLabel("使用方式:"), 1, 0)
        api_form.addWidget(source_mode_combo, 1, 1)
        api_form.addWidget(QLabel("指定/优先节点:"), 1, 2)
        api_form.addWidget(active_api_combo, 1, 3)

        api_form.addWidget(QLabel("API 节点策略:"), 2, 0)
        provider_strategy_combo.setToolTip("仅在“API 池自动切换”模式下生效，决定多个 API 节点之间的切换顺序。")
        api_form.addWidget(provider_strategy_combo, 2, 1)
        api_form.addWidget(QLabel("节点内 Key 策略:"), 2, 2)
        pool_strategy_combo.setToolTip("决定每个 API 节点自己的 Key 池如何切换。")
        api_form.addWidget(pool_strategy_combo, 2, 3)

        api_form.addWidget(QLabel("模型名称（兼容旧配置）:"), 3, 0)
        api_form.addWidget(model_combo, 3, 1, 1, 2)
        api_form.addWidget(btn_refresh_models, 3, 3)

        api_form.addWidget(QLabel("默认接口地址（兼容旧配置）:"), 4, 0)
        api_form.addWidget(api_base_edit, 4, 1, 1, 3)

        api_form.addWidget(QLabel("429 冷却参考 (秒):"), 5, 0)
        api_form.addWidget(interval_spin, 5, 1)
        api_form.addWidget(QLabel("最大重试次数:"), 5, 2)
        api_form.addWidget(max_retries_spin, 5, 3)

        api_form.addWidget(QLabel("最大并发数:"), 6, 0)
        api_form.addWidget(max_concurrency_spin, 6, 1)

        def _refresh_models():
            profiles = _collect_profiles_for_runtime()
            if not profiles:
                QMessageBox.warning(None, "缺少配置", "当前没有可用的 API 节点。请先在 API 节点池里至少启用一个带 Key 的节点。")
                return
            btn_refresh_models.setEnabled(False)
            btn_refresh_models.setText("⏳ 获取中...")
            self.log("🔄 [1/5] 启动模型刷新流程...", "blue")
            QApplication.processEvents()
            self.worker = ApiWorker("refresh_models", {
                "api_profiles": profiles,
                "pool_strategy": pool_strategy_combo.currentData(),
                "provider_strategy": provider_strategy_combo.currentData()
            })
            self.worker.log_signal.connect(self.log)
            def on_finished(success, msg, models):
                btn_refresh_models.setEnabled(True)
                if success:
                    current = model_combo.currentText()
                    model_combo.clear()
                    model_combo.addItems(models)
                    if current in models:
                        model_combo.setCurrentText(current)
                    btn_refresh_models.setText("✅ 已更新")
                    self.log(msg, "green")
                    QMessageBox.information(None, "获取成功", msg)
                else:
                    btn_refresh_models.setText("❌ 获取失败")
                    self.log(f"❌ 获取失败: {msg}", "red")
                    QMessageBox.critical(None, "获取失败", f"错误详情:\n{msg}")
            self.worker.finished_signal.connect(on_finished)
            self.worker.start()

        btn_refresh_models.clicked.connect(_refresh_models)
        api_layout.addLayout(api_form)
        api_layout.addWidget(random_api_check)
        api_layout.addWidget(QLabel("💡 远程调用统一走 API 节点池。随机 API 模式开启后，会优先随机调换节点与 Key；未触发真实限流时不会再强制插入预等待。"))

        def _test_api():
            profiles = _collect_profiles_for_runtime()
            if not profiles:
                QMessageBox.warning(None, "缺少配置", "当前使用来源没有可用 Key。请先补齐配置后再测试。")
                return
            btn_test.setEnabled(False)
            btn_test.setText("⏳ 测试中...")
            self.log("⚡ [1/5] 启动 API 测试...", "blue")
            QApplication.processEvents()
            self.test_worker = ApiWorker("test_api", {
                "api_profiles": profiles,
                "pool_strategy": pool_strategy_combo.currentData(),
                "provider_strategy": provider_strategy_combo.currentData()
            })
            self.test_worker.log_signal.connect(self.log)
            def on_test_finished(success, msg, data):
                btn_test.setEnabled(True)
                if success:
                    btn_test.setText("✅ 连接成功！")
                    btn_test.setStyleSheet("color: green;")
                    self.log(msg, "green")
                    QMessageBox.information(None, "测试成功", "当前配置可用。")
                else:
                    btn_test.setText("❌ 失败")
                    btn_test.setStyleSheet("color: red;")
                    self.log(f"❌ 测试失败: {msg}", "red")
                    QMessageBox.critical(None, "测试失败", f"错误详情:\n{msg}")
            self.test_worker.finished_signal.connect(on_test_finished)
            self.test_worker.start()

        btn_test = QPushButton("⚡ 测试当前来源")
        btn_test.clicked.connect(_test_api)
        api_layout.addWidget(btn_test)
        api_layout.addStretch()
        _refresh_status_labels()
        _refresh_active_combo()
        _update_mode_ui()
        engine_tabs.addTab(api_widget, "🌐 远程 API / API 池")

        # ―― 模式 2：本地大模型 ――
        local_widget = QWidget()
        local_layout = QVBoxLayout(local_widget)
        local_form = QGridLayout()
        local_form.addWidget(QLabel("模型目录:"), 0, 0)
        local_path_edit = QLineEdit(target_cfg.get("local_model_path", ""))
        local_path_edit.setPlaceholderText("选择包含 .gguf 文件或 Transformers 模型的文件夹")
        local_form.addWidget(local_path_edit, 0, 1)
        btn_browse_model = QPushButton("📁 浏览")
        def _browse_model():
            p = QFileDialog.getExistingDirectory(dlg, "选择本地模型目录")
            if p: local_path_edit.setText(p)
        btn_browse_model.clicked.connect(_browse_model)
        local_form.addWidget(btn_browse_model, 0, 2)
        local_btn_row = QHBoxLayout()
        btn_preload_local = QPushButton("⚡ 立即加载")
        btn_unload_local = QPushButton("🧹 卸载")
        local_status_label = QLabel("")
        local_status_label.setWordWrap(True)
        def _refresh_local_status():
            target_path = str(local_path_edit.text() or "").strip()
            current_engine = getattr(self, "local_engine", None)
            current_loaded = str(getattr(current_engine, "current_model_path", "") or "").strip()
            try:
                same_model = bool(target_path and current_loaded and os.path.normpath(target_path) == os.path.normpath(current_loaded))
            except Exception:
                same_model = bool(target_path and current_loaded and target_path == current_loaded)
            if same_model:
                local_status_label.setText(f"✅ 已预加载：{os.path.basename(current_loaded)}")
                local_status_label.setStyleSheet("color: #15803d;")
            elif current_loaded:
                local_status_label.setText(f"ℹ️ 当前内存中已加载：{os.path.basename(current_loaded)}")
                local_status_label.setStyleSheet("color: #1d4ed8;")
            else:
                local_status_label.setText("未预加载本地模型")
                local_status_label.setStyleSheet("color: #6b7280;")
        def _preload_local_from_dialog():
            target_path = str(local_path_edit.text() or "").strip()
            if not target_path:
                QMessageBox.warning(dlg, "缺少模型路径", "请先选择本地模型目录。")
                return
            target_cfg["local_model_path"] = target_path
            QApplication.processEvents()
            if self._load_shared_local_engine(target_path, parent=dlg):
                _refresh_local_status()
                QMessageBox.information(dlg, "加载成功", "本地模型已经预加载完成。之后切到本地模式时无需先发消息触发加载。")
        def _unload_local_from_dialog():
            if self._unload_shared_local_engine(parent=dlg, quiet=False):
                _refresh_local_status()
        btn_preload_local.clicked.connect(_preload_local_from_dialog)
        btn_unload_local.clicked.connect(_unload_local_from_dialog)
        local_path_edit.textChanged.connect(lambda *_: _refresh_local_status())
        local_btn_row.addWidget(btn_preload_local)
        local_btn_row.addWidget(btn_unload_local)
        local_btn_row.addWidget(local_status_label, 1)
        local_layout.addLayout(local_btn_row)
        _refresh_local_status()
        local_layout.addLayout(local_form)
        local_layout.addWidget(QLabel(
            "💡 本地模型推荐：\n"
            "  1. Qwen2-VL-2B-Instruct （约 4GB，速度快）\n"
            "  2. InternVL2-2B （轻量且精准）\n"
            "  3. 任意 GGUF 格式模型（需配合 llama-cpp-python）\n"
            "⚠️ 模型路径严禁包含中文字符。"
        ))
        local_layout.addStretch()
        engine_tabs.addTab(local_widget, "💻 本地大模型")

        # ―― 模式 3： CLIP 极速模式 ――
        clip_widget = QWidget()
        clip_layout = QVBoxLayout(clip_widget)
        clip_intro = QLabel(
            "⚡ <b>CLIP 极速模式</b>：无需大模型，通过图文语义相似度匹配。"
            "显存仅约 300MB，速度比大模型快 10-50 倍。"
            "首次运行需下载模型（约 600MB）。"
        )
        clip_intro.setWordWrap(True)
        clip_intro.setStyleSheet("color: #0055cc; padding: 6px; background: #e8f0fe; border-radius: 4px;")
        clip_layout.addWidget(clip_intro)
        clip_form = QGridLayout()
        clip_form.addWidget(QLabel("🤖 CLIP 模型:"), 0, 0)
        clip_combo = QComboBox()
        clip_combo.addItems([
            "OFA-Sys/chinese-clip-vit-large-patch14",
            "OFA-Sys/chinese-clip-vit-base-patch16",
            "clip-ViT-L-14",
            "clip-ViT-B-16",
            "clip-ViT-B-32",
        ])
        clip_combo.setEditable(True)
        clip_combo.setCurrentText(target_cfg.get("clip_model", "OFA-Sys/chinese-clip-vit-large-patch14"))
        clip_form.addWidget(clip_combo, 0, 1)
        clip_layout.addLayout(clip_form)
        clip_layout.addWidget(QLabel(
            "💡 中文增强版 (OFA-Sys/chinese-clip-*) 推荐中文场景；\n"
            "clip-ViT-* 适用于英文文案场景。"
        ))
        clip_layout.addStretch()
        engine_tabs.addTab(clip_widget, "⚡ CLIP 极速模式 (推荐)")

        layout.addWidget(engine_tabs)
        
        # ―― 调试选项 ――
        debug_row = QHBoxLayout()
        debug_check = QCheckBox("🐞 开启 AI 调试日志 (在后台显示详细请求与返回内容)")
        debug_check.setChecked(target_cfg.get("debug_mode", False))
        debug_row.addWidget(debug_check)
        debug_row.addStretch()
        layout.addLayout(debug_row)

        # ―― 预设模式切换 ――
        mode_map = {"api": 0, "local": 1, "clip": 2}
        engine_tabs.setCurrentIndex(mode_map.get(target_cfg.get("mode", "clip"), 2))

        # ―― 底部按钮 ――
        if PYQT_VERSION == 6:
            btn_box = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        else:
            btn_box = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        layout.addWidget(btn_box)

        def _save():
            idx = engine_tabs.currentIndex()
            mode = ["api", "local", "clip"][idx]
            all_models = [model_combo.itemText(i) for i in range(model_combo.count())]
            target_cfg.update({
                "mode": mode,
                "api_keys": list(legacy_keys_cache),
                "api_base": self.api_base_edit_obj.text().strip(),
                "api_model": model_combo.currentText().strip(),
                "api_source_mode": source_mode_combo.currentData(),
                "api_provider_strategy": provider_strategy_combo.currentData(),
                "active_api_name": active_api_combo.currentData() or "",
                "api_pool": [dict(item) for item in api_pool_cache],
                "api_pool_strategy": get_api_pool_strategy({"api_pool_strategy": pool_strategy_combo.currentData()}),
                "api_random_enabled": random_api_check.isChecked(),
                "api_models_list": all_models,
                "api_interval": interval_spin.value(),
                "api_max_retries": max_retries_spin.value(),
                "api_max_concurrency": max_concurrency_spin.value(),
                "local_model_path": local_path_edit.text().strip(),
                "clip_model": clip_combo.currentText().strip(),
                "debug_mode": debug_check.isChecked(),
            })
            self._set_named_ai_config(config_target, target_cfg)
            if config_target == "assistant":
                valid_names = {item.get("name", "") for item in normalize_api_pool(target_cfg)}
                for conv in getattr(self, "ai_conversations", []):
                    if str(conv.get("chat_api_name", "") or "").strip() not in valid_names:
                        conv["chat_api_name"] = ""
            if mode == "local":
                target_path = target_cfg.get("local_model_path", "")
                if target_path and not self._load_shared_local_engine(target_path, parent=dlg, quiet=False):
                    return
            self.trigger_save()
            if config_target == "assistant":
                self._refresh_chat_api_selector()
            elif config_target == "pipeline" and hasattr(self, "btn_ai_config"):
                mode_labels = {"api": "🌐 API", "local": "💻 本地", "clip": "⚡ CLIP"}
                self.btn_ai_config.setText(f"⚙️ AI 配置 [{mode_labels.get(mode, mode)}]")
            dlg.accept()

        btn_box.accepted.connect(_save)
        btn_box.rejected.connect(dlg.reject)

        if PYQT_VERSION == 6:
            dlg.exec()
        else:
            dlg.exec_()

    def setup_heygen_tab(self):
        layout = QVBoxLayout(self.heygen_tab)
        
        # --- 批量自动化流水线控制区 ---
        auto_group = QGroupBox("🤖 批量自动化流水线")
        auto_group.setStyleSheet("QGroupBox { border: 2px solid #3b82f6; border-radius: 8px; margin-top: 10px; padding-top: 10px; font-weight: bold; }")
        auto_layout = QVBoxLayout(auto_group)
        
        path_row = QHBoxLayout()
        path_row.addWidget(QLabel("监控总素材根目录 (A):"))
        self.auto_root_input = PathDropLineEdit(accept_dirs=True, accept_files=False)
        self.auto_root_input.setPlaceholderText("可直接拖入总目录（包含 A1, A2... 子文件夹）")
        self.auto_root_input.textChanged.connect(self.trigger_save)
        path_row.addWidget(self.auto_root_input)
        btn_browse = QPushButton("浏览")
        btn_browse.clicked.connect(lambda: self.browse_dir(self.auto_root_input))
        path_row.addWidget(btn_browse)
        auto_layout.addLayout(path_row)

        global_out_row = QHBoxLayout()
        global_out_row.addWidget(QLabel("全局统一存放位置:"))
        self.heygen_global_out_input = PathDropLineEdit(accept_dirs=True, accept_files=False)
        self.heygen_global_out_input.setPlaceholderText("所有项目可共用这里；项目里留空时自动使用本路径")
        self.heygen_global_out_input.setToolTip("支持变量：{date} / {yyyy-MM-dd} / {yyyyMMdd} / {project}\n例如：D:\\输出\\{date}")
        self.heygen_global_out_input.textChanged.connect(self.trigger_save)
        global_out_row.addWidget(self.heygen_global_out_input)
        btn_browse_global_out = QPushButton("浏览")
        btn_browse_global_out.clicked.connect(lambda: self.browse_dir(self.heygen_global_out_input))
        global_out_row.addWidget(btn_browse_global_out)
        auto_layout.addLayout(global_out_row)

        global_out_hint = QLabel("说明：这里是所有项目共用的默认输出目录。项目自己的“整理后存放位置”如果留空，就自动走这里。支持变量：`{date}`、`{yyyy-MM-dd}`、`{yyyyMMdd}`、`{project}`。")
        global_out_hint.setWordWrap(True)
        global_out_hint.setStyleSheet("color:#64748b; padding:0 0 4px 2px;")
        auto_layout.addWidget(global_out_hint)
        
