    def _shutdown_thread_if_running(self, thread_obj, wait_ms=2500):
        t = thread_obj
        if not t:
            return
        try:
            is_running = t.isRunning() if hasattr(t, "isRunning") else False
        except Exception:
            is_running = False
        if not is_running:
            return
        try:
            if hasattr(t, "stop"):
                t.stop()
        except Exception:
            pass
        try:
            if hasattr(t, "requestInterruption"):
                t.requestInterruption()
        except Exception:
            pass
        try:
            if hasattr(t, "quit"):
                t.quit()
        except Exception:
            pass
        try:
            if hasattr(t, "wait"):
                t.wait(wait_ms)
        except Exception:
            pass

    def _shutdown_background_workers(self):
        thread_names = [
            "gpu_monitor",
            "engine",
            "project_match_thread",
            "_review_thread",
            "uni_match_thread",
            "chat_thread",
            "worker",
            "test_worker",
        ]
        for name in thread_names:
            self._shutdown_thread_if_running(getattr(self, name, None))
        try:
            vtab = getattr(self, "video_concat_tab", None)
            if vtab:
                for name in ["concat_thread", "scene_thread", "speed_thread", "trim_thread", "format_thread"]:
                    self._shutdown_thread_if_running(getattr(vtab, name, None))
        except Exception:
            pass
        try:
            wtab = getattr(self, "watermark_tab", None)
            if wtab:
                self._shutdown_thread_if_running(getattr(wtab, "wm_thread", None))
        except Exception:
            pass

    def closeEvent(self, event):
        try:
            if hasattr(self, "save_timer") and self.save_timer.isActive():
                self.save_timer.stop()
        except Exception:
            pass
        try:
            focus_w = QApplication.focusWidget()
            if focus_w:
                focus_w.clearFocus()
                QApplication.processEvents()
        except Exception:
            pass
        try:
            self.save_config(force=True)
        except Exception:
            pass
        try:
            self._shutdown_background_workers()
        except Exception:
            pass
        try:
            return super().closeEvent(event)
        except Exception:
            event.accept()







